            const rx: f64 = @floatFromInt(r.x);
            const ry: f64 = @floatFromInt(r.y);
            if (x_px >= rx and x_px < rx + @as(f64, @floatFromInt(r.w)) and
                y_px >= ry and y_px < ry + @as(f64, @floatFromInt(r.h)))
            {
                self.toggleSidebarCollapsed();
                return;
            }
        }
        // 사이드바 우측 경계 down → 폭 조절 드래그 시작(사이드바 슬롯/터미널보다 먼저 — 경계는 둘 사이 밴드). 접힘이면
        // 사이드바가 없어(폭 0) 경계 드래그 비활성(onResizeEdge가 x=0 근처를 잡아 의도치 않게 트리거되는 것 방지).
        if (kind == 1 and !self.sidebar_collapsed and chrome.components.sidebar.onResizeEdge(x_px, self.sidebar_width_px, if (self.cell_width_px > 0) self.cell_width_px else placeholder_cell_width_px)) {
            self.sidebar_resize_active = true;
            self.sidebar_resize_start_pt = self.sidebar_width_pt; // up에서 실제 변화 여부 판정 기준(write-back 가드)
            self.drag_autoscroll = 0;
            self.mouse_drag_selecting = false;
            return;
        }
        // 사이드바 영역 클릭은 Maru UI다(터미널 선택/리포팅 아님). down(1)에서 슬롯을 hit-test한다 —
        // 슬롯 우측 ✕ zone이고 그 슬롯이 호버 중(✕가 보임)이면 그 탭을 닫고, 아니면 그 탭으로 전환하고
        // 드래그 재정렬을 시작한다(이어지는 drag가 순서를 바꾼다 — 안 움직이면 그냥 클릭=전환). 슬롯 밖
        // (빈 영역)은 무시. 진행 중이던 터미널 드래그 선택은 멈춘다. 사이드바 클릭은 터미널에 안 닿는다.
        if (self.inSidebar(x_px)) {
            if (kind == 1) {
                // 상단 헤더: 새 워크스페이스 아이콘 → 새 탭(하단 "+"를 헤더로 이동), view options 아이콘 → 메뉴(P4),
                // 검색 영역 → 검색 활성(P3). 헤더 밖(none)이면 카드 슬롯 hit-test(✕ 닫기 / 전환 + 드래그 재정렬).
                const header_region = chrome.components.sidebar.headerHit(x_px, y_px, self.sidebar_width_px, self.cell_width_px, self.cell_height_px, self.sidebar_header_height_px);
                switch (header_region) {
                    .new_workspace => _ = self.newTab() catch {},
                    .toggle_sidebar => self.toggleSidebarCollapsed(), // ◧ → 사이드바 접기(좌상단 펼치기 버튼만 남음)
                    .view_options => {
                        // ⚙ 클릭 → 사이드바 표시 토글 메뉴(브랜치·폴더)를 ⚙ 아이콘 아래에 띄운다(체크박스 패널).
                        // 다시 ⚙(메뉴 박스 밖)를 클릭하면 닫힌다(아래 context_menu.open 분기의 바깥-클릭 경로).
                        self.view_options_menu = true;
                        const items = self.buildViewOptionsMenuItems();
                        const anchor_x: i32 = @intCast(self.sidebar_width_px -| 4 * self.cell_width_px); // ⚙ 아이콘 col
                        const anchor_y: i32 = @intCast(self.cell_height_px); // 아이콘 줄(0) 바로 아래
                        self.chrome_host.context_menu.show(anchor_x, anchor_y, items.len);
                        self.metal_dirty = true;
                    },
                    .search => {
                        self.sidebar_search_active = true; // 검색바 클릭 → 활성(키/IME가 검색으로 라우팅)
                        self.rebuildSidebar() catch {}; // 보존된 검색어가 있으면 필터를 즉시 재개(blur 중 일시정지됐던 것)
                        self.resetCursorBlink();
                        self.metal_dirty = true;
                    },
                    .notifications => self.openNotificationPanel(), // 종 클릭 → 인앱 알림 센터 패널(앵커는 단일 출처 헬퍼)
                    .none => if (self.sidebarSlotAt(y_px)) |slot| if (self.visibleTab(slot)) |tab_idx| {
                        // slot=표시 슬롯, tab_idx=원본 탭(검색 필터 역매핑). 닫기/전환/드래그는 원본 인덱스로 한다.
                        const on_close = chrome.components.sidebar.closeButton(x_px, self.sidebar_width_px, self.cell_width_px) and
                            self.hovered_slot != null and self.hovered_slot.? == slot;
                        if (on_close) {
                            self.requestClose(.{ .tab_index = tab_idx }); // 실행 중 명령 있으면 확인 모달(없으면 즉시 closeTab)
                        } else {
                            self.hovered_slot = null; // 드래그 중엔 stale 호버 밴드/✕를 안 보이게
                            _ = self.switchTab(tab_idx);
                            // 검색 필터 중엔 드래그 재정렬을 비활성(부분 목록 재정렬은 의미 모호). 비활성/빈 검색이면 visible=전체라
                            // 정상 동작. 고정 탭도 arm — moveTab/드래그 타겟이 같은 그룹으로 clamp(고정/비고정 영역 안 넘음).
                            if (!self.sidebar_search_active and tab_idx < self.tabs.items.len) {
                                self.sidebar_drag_active = true;
                                self.sidebar_drag_index = tab_idx;
                            }
                        }
                    },
                }
                // 검색 영역이 아닌 곳(카드·아이콘·빈 영역)을 클릭하면 검색을 blur한다 — 키 포커스를 터미널로 되돌려
                // '검색 활성 중 터미널 입력 불가'를 푼다(검색어는 보존). 카드 클릭의 visibleTab 역매핑은 위에서 이미
                // 끝나 매핑이 안 깨진다. .search 분기는 방금 active=true로 켠 참이라 제외한다.
                if (kind == 1 and header_region != .search and self.sidebar_search_active) self.blurSidebarSearch();
            }
            // 사이드바 더블클릭(kind 4) rename은 위 통합 kind==4 핸들러(renameTargetAt)가 이미 처리했다.
            self.drag_autoscroll = 0;
            self.mouse_drag_selecting = false;
            return;
        }
        // 사이드바 '밖'(터미널·pane·탭 바)을 클릭하면 검색을 blur한다 — 같은 이유(키를 터미널로 되돌림, 검색어 보존).
        // 사이드바 밖은 visibleTab 의존이 없어 여기서 바로 blur해도 안전하다.
        if (kind == 1 and self.sidebar_search_active) self.blurSidebarSearch();
        // down(1)에서 pane/탭 바 클릭을 hit-test한다(kind!=1이면 단락 평가로 self.tabs를 안 건드린다 — 최소-셋업
        // 드래그 테스트는 kind 2/3만 보낸다). 활성 탭 leaf rect를 한 번 펴 ① 탭 바 클릭(어느 pane의 상단 바면 그
        // pane 포커스 + 클릭한 Term 탭 전환) ② 다른 panel의 터미널 영역 클릭(그 pane 포커스)을 차례로 본다. 둘 다
        // 클릭을 소비한다 — 터미널 선택은 활성 panel의 '바 아래' 클릭에서만 시작한다. 활성 panel의 활성 탭/터미널
        // 클릭은 무전환으로 아래 일반 선택 경로로 흐른다.
        if (kind == 1) {
            var leaf_rects: std.ArrayList(PaneTree.LeafRect) = .empty;
            defer leaf_rects.deinit(self.allocator);
            if (self.activeTabLeafRects(self.allocator, self.termRect(), &leaf_rects)) |_| {
                // ① 탭 바 클릭 → pane 포커스 + Term 탭 전환. 클릭이 호버된 탭의 ✕ zone이면 그 Term을 닫는다
                //    (focusPaneByPtr+focusTerm로 그 탭을 활성으로 만든 뒤 closeActiveTermOrPane cascade). 단일 panel도
                //    Term이 여럿이면 전환/닫기 된다. ✕는 호버 중일 때만 보이므로 hovered_tab과 일치할 때만 닫는다.
                for (leaf_rects.items) |lr| {
                    const pb = self.paneBar(lr.rect, lr.leaf) orelse continue;
                    if (layout_math.pointInRect(x_px, y_px, pb.full)) {
                        // 좌측 grip+라벨 세그먼트 클릭 → 그 pane 포커스 + **pane 통째 드래그 arm**(이어지는 drag(2)가
                        // floating 미리보기, up(3)이 사이드바면 분리/합치기 — 안 끌면 그냥 포커스). 탭 hit-test는 그 뒤
                        // 영역(pb.tabs)만 대상이라, 좌측 영역 x가 tabIndex의 좌측 clamp로 탭0을 잘못 잡는 걸 막는다.
                        // 더블클릭·우클릭 rename은 같은 영역에서 renameTargetAt이 따로 처리(kind 4/우클릭은 위에서 분기).
                        if ((pb.grip_cols > 0 or pb.label_cols > 0) and x_px < @as(f64, @floatFromInt(pb.tabs.x))) {
                            _ = self.focusPaneByPtr(lr.leaf);
                            self.pane_drag_active = true;
                            self.pane_drag_pane = lr.leaf;
                            self.pane_drag_x = x_px;
                            self.pane_drag_y = y_px;
                            self.drag_autoscroll = 0;
                            self.mouse_drag_selecting = false;
                            return;
                        }
                        const count = lr.leaf.terms.items.len;
                        const m = barMetrics(pb.tabs, self.cell_width_px, count, self.buildChromeTokens().space.tab_width_cols, lr.leaf.tab_scroll_cols);
                        // 바 우측 ‹›(가로 스크롤) 버튼 클릭 → 그 pane의 tab_scroll_cols를 ±tab_w(한 탭). 넘침 범위로 clamp. "+"·탭보다 먼저.
                        if (m) |bm| if (bm.inScrollLeftZone(x_px)) {
                            _ = self.focusPaneByPtr(lr.leaf);
                            lr.leaf.tab_scroll_cols = bm.scroll_cols -| bm.tab_w; // ‹ 이전 탭 — bm.scroll_cols(=clamp된 eff) 기준이라 stale 자동 정정
                            self.metal_dirty = true;
                            return;
                        };
                        if (m) |bm| if (bm.inScrollRightZone(x_px)) {
                            _ = self.focusPaneByPtr(lr.leaf);
                            lr.leaf.tab_scroll_cols = bm.scroll_cols + bm.tab_w; // › 다음 탭 — 다음 렌더의 tabLayout이 [0,max]로 clamp
                            self.metal_dirty = true;
                            return;
                        };
                        // 바 우측 "+" 버튼 클릭 → 그 pane을 포커스하고 새 Term을 띄운다(⌘T의 마우스 버전). 탭/✕보다 먼저.
                        if (m) |bm| if (bm.inPlusZone(x_px)) {
                            _ = self.focusPaneByPtr(lr.leaf);
                            self.newTermInActivePane() catch {};
                            self.drag_autoscroll = 0;
                            self.mouse_drag_selecting = false;
                            return;
                        };
                        const tab = if (m) |bm| bm.tabIndex(count, x_px) else 0;
                        const on_close = m != null and self.hovered_tab != null and self.hovered_tab.?.pane == lr.leaf and
                            self.hovered_tab.?.tab == tab and
                            m.?.inCloseZone(tab, x_px);
                        _ = self.focusPaneByPtr(lr.leaf); // 다른 pane이면 포커스 이동(같으면 무동작)
                        self.focusTerm(tab); // 그 pane의 클릭한 Term으로(같으면 무동작)
                        if (on_close) {
                            self.hovered_tab = null; // 닫으면 Pane/Term이 바뀔 수 있으니 stale 호버 비움
                            // 위에서 focusPaneByPtr+focusTerm로 클릭한 Term을 활성으로 만든 뒤라, 활성 cascade로 닫는다.
                            self.requestClose(.term_or_pane); // 실행 중 명령 있으면 확인 모달(없으면 즉시 닫음)
                        } else {
                            // ✕가 아니면 탭 드래그를 arm한다(이어지는 drag(2)가 pane 내 재정렬). 안 끌면 그냥 전환.
                            self.tab_drag_active = true;
                            self.tab_drag_pane = lr.leaf;
                            self.tab_drag_index = tab;
                        }
                        self.drag_autoscroll = 0;
                        self.mouse_drag_selecting = false;
                        return;
                    }
                }
                // ⓐ divider 클릭 → 리사이즈 드래그 시작(PR6). 탭 바(①)보다 뒤·pane 선택(②)보다 앞 — 탭 바는
                //    seam에 붙어 있어 우선권을 주고, divider는 terminal 영역 seam에서 잡는다. drag(2)/up(3)은 위
                //    divider 캡처가 받는다. split일 때만(dividerAtPoint가 단일 panel이면 null).
                if (self.dividerAtPoint(x_px, y_px)) |hit| {
                    self.divider_drag = hit.split;
                    self.divider_drag_seg = hit.seg; // neutral seg 직접(재변환 없음 — 드래그 중 dragRatio가 쓴다)
                    self.drag_autoscroll = 0;
                    self.mouse_drag_selecting = false;
                    return;
                }
                // ② split에서 다른 panel의 터미널 영역 클릭 → 그 pane 포커스(활성 panel이면 아래 선택 경로로).
                if (Model.paneAtPoint(leaf_rects.items, x_px, y_px)) |pane| {
                    if (pane != self.activePane() and self.focusPaneByPtr(pane)) {
                        self.drag_autoscroll = 0;
                        self.mouse_drag_selecting = false;
                        return;
                    }
                }
            } else |_| {}
        }
        // 스크롤바 thumb/트랙 down(활성 pane 우측, 스크롤백 있을 때) → thumb 드래그 시작. 터미널 선택/리포팅
        // 보다 먼저 가로챈다 — 우측 가장자리 얇은 띠라 평소 셀 선택을 거의 안 가린다(스크롤백 없으면 스크롤바
        // 자체가 없어 이 분기도 안 탄다). 트랙(thumb 밖) 클릭은 즉시 그 지점으로 점프하고 이어서 드래그한다.
        if (kind == 1) {
            if (self.scrollbarGrabAt(x_px, y_px)) |grab| {
                self.scrollbar_drag_grab = grab;
                self.drag_autoscroll = 0;
                self.mouse_drag_selecting = false;
                self.dragScrollbarTo(y_px);
                return;
            }
        }
        const cell = self.pxToCell(x_px, y_px) orelse {
            // 비유한(NaN/Inf) 좌표 — 셀로 못 바꾼다. up(3)/down(1)이면 드래그 자동 스크롤을
            // 멈춘다(안 그러면 mouseUp이 좌표 손상으로 와도 autoscroll이 frame-loop로 영원히 돈다).
            if (kind == 1 or kind == 3) {
                self.drag_autoscroll = 0;
                self.mouse_drag_selecting = false;
            }
            return;
        };
        const col = cell.col;
        const row = cell.row;
        const click_surface = self.activeSurface();
        const core = &click_surface.core;
        // mouse reporting: 트래킹 모드(DECSET 1000~1003)고 shift·option 미포함이면 셀렉션 대신 앱에 리포트한다 —
        // shift+click은 선형 셀렉션 override, option+click은 블록 override(iTerm2 관례). mods: shift=4·option=8.
        // mouse_tracking 읽기 + reportMouse(코어 response 생성)는 락 아래(리더 core.write와 response 경합 방지,
        // docs/io-render-threading.md PR3). reporting 모드면 진행 중 셀렉션 autoscroll도 멈춘다. writeInput은 락 밖.
        // mouse_tracking 읽기는 메인 락-아래(읽기는 위임 안 함 — §9.1). reportMouse(코어 mutate + PTY 응답)는
        // full (a)(P3-4)로 reader에 위임 — reader가 적용 후 pendingResponse를 PTY로 흘린다(메인 직접 mutate 0).
        click_surface.lockCore(self.io);
        const do_report = core.mouse_tracking != .none and (mods & 4) == 0 and (mods & 8) == 0;
        click_surface.unlockCore(self.io);
        if (do_report) {
            self.drag_autoscroll = 0;
            self.mouse_drag_selecting = false;
            self.runtime.enqueueCoreCommand(click_surface.id, .{ .report_mouse = .{
                .button = @intCast(button),
                .col = col,
                .row = row,
                .x_px = cell.term_x_px,
                .y_px = cell.term_y_px,
                .pressed = kind != 3,
                .motion = kind == 2,
                .mods = @intCast(mods),
            } }, self.io) catch {};
            return;
        }
        // 셀렉션은 left 버튼(0)만 시작한다 — tracking 아닌 상태의 right/middle 클릭은 무시(셀렉션·context 메뉴 없음).
        if (button != 0) return;
        const ch: f64 = @floatFromInt(if (self.cell_height_px > 0) self.cell_height_px else placeholder_cell_height_px);
        // 선택 코어 mutate(selectionStart/Extend/Clear/Word/Line)는 full (a)(docs/io-render-threading.md §9 P3-4)로
        // reader에 위임한다 — read-modify-decide(kind 3 "이동 없는 클릭=해제")는 `select_extend_or_collapse` 명령으로
        // reader가 락 아래 **원자 실행**(메인이 위임 후 옛 상태를 읽어 오판하던 문제 제거). 메인은 UI 상태
        // (mouse_drag_selecting·drag_autoscroll·last_drag_col)만 만지고 코어는 안 만진다.
        switch (kind) {
            1 => {
                self.mouse_drag_selecting = true;
                self.drag_autoscroll = 0;
                self.runtime.enqueueCoreCommand(click_surface.id, .{ .select_start = .{ .row = row, .col = col, .block = (mods & 8) != 0 } }, self.io) catch {};
            },
            2 => {
                // 드래그가 활성 panel grid 위/아래 밖으로 나가면 자동 스크롤을 건다(tick이 수행). grid 높이용 rows는
                // 코어 read(메인 락-아래 — 읽기는 위임 안 함, §9.1). panel은 active_pane_rect.y에서 시작.
                const pane_top: f64 = @floatFromInt(self.active_pane_rect.y);
                const rows: u16 = blk: {
                    click_surface.lockCore(self.io);
                    defer click_surface.unlockCore(self.io);
                    break :blk core.size.rows;
                };
                const grid_height: f64 = @as(f64, @floatFromInt(rows)) * ch;
                self.drag_autoscroll = if (y_px < pane_top) 1 else if (y_px > pane_top + grid_height) -1 else 0;
                self.last_drag_col = col;
                self.runtime.enqueueCoreCommand(click_surface.id, .{ .select_extend = .{ .row = row, .col = col } }, self.io) catch {};
            },
            3 => {
                self.drag_autoscroll = 0;
                // 더블/트리플클릭 직후의 up은 그 선택을 건드리면 안 된다(단어가 1칸이면 "이동 없는 클릭" 판정에 걸려 즉시 해제).
                if (!self.mouse_drag_selecting) return;
                self.mouse_drag_selecting = false;
                self.runtime.enqueueCoreCommand(click_surface.id, .{ .select_extend_or_collapse = .{ .row = row, .col = col } }, self.io) catch {};
            },
            4 => {
                self.mouse_drag_selecting = false;
                // 더블클릭 단어 선택: config input.word-separators를 명령에 **복사**해 실어 보낸다(borrowed slice의
                // reload 수명 문제 회피 — 코어는 구분자 상태를 안 들고 매 선택에 현재 config를 받는다, 항상 reload-safe). F2-8.
                // 버퍼 크기(64)는 SelectWord.separators와 일치해야 한다 — 어긋나면 아래 .separators 대입이 컴파일 에러.
                var sep_buf: [64]u8 = undefined;
                const sep = self.loaded_config.config.input.word_separators;
                // 64바이트 상한으로 자르되 **codepoint 경계**에서 자른다(width.truncateToBoundary 단일 출처) — 멀티바이트
                // 구분자가 64바이트 중간에서 쪼개지면 코어의 Utf8View.init이 슬라이스 전체를 거부해 **모든** 구분자가 조용히
                // 무시되기 때문이다(F2-8). 반환은 ≤ sep_buf.len(64)이라 u8 안전.
                const n: u8 = @intCast(terminal.width.truncateToBoundary(sep, sep_buf.len));
                @memcpy(sep_buf[0..n], sep[0..n]);
                self.runtime.enqueueCoreCommand(click_surface.id, .{ .select_word = .{ .row = row, .col = col, .separators = sep_buf, .sep_len = n } }, self.io) catch {};
            },
            5 => {
                self.mouse_drag_selecting = false;
                self.runtime.enqueueCoreCommand(click_surface.id, .{ .select_line = row }, self.io) catch {};
            },
            else => return,
        }
        self.metal_dirty = true;
    }

    pub fn configuredFrameRateHz(self: *const AppSession) u32 {
        return clampFrameRateHz(self.loaded_config.config.render_frame_rate);
    }

    pub fn setFrameLoopRateHz(self: *AppSession, hz: u32) void {
        self.frame_loop_rate_hz = clampFrameRateHz(hz);
    }

    pub fn frameRateHz(self: *const AppSession) u32 {
        return clampFrameRateHz(self.frame_loop_rate_hz);
    }

    fn ticksForMs(self: *const AppSession, ms: u32) u32 {
        return ticksForMsAtRate(ms, self.frameRateHz());
    }

    // 한 tick의 실제 경과 시간(ms) = round(1000 / 실제 cadence). frameRateHz는 #1117에서 Swift가 주입한
    // frame_loop_rate_hz(실제 NSTimer cadence)를 반환하므로, 이 값은 호스트 타이머 기준 tick 간격이다. 드래그
    // 자동 스크롤이 tick당 경과 ms를 누적해 frame rate 무관 속도를 내는 데 쓴다(ticksForMs의 역방향).
    fn msPerTick(self: *const AppSession) u32 {
        const hz = self.frameRateHz();
        return @max(1, (1000 + hz / 2) / hz);
    }

    fn bellFlashTotalTicks(self: *const AppSession) u32 {
        return self.ticksForMs(bell_flash_total_ms);
    }

    fn scrollbarVisibleTicks(self: *const AppSession) u32 {
        return self.ticksForMs(scrollbar_visible_ms);
    }

    fn scrollbarFadeTicks(self: *const AppSession) u32 {
        return self.ticksForMs(scrollbar_fade_ms);
    }

    fn scrollbarFadeCompleteTicks(self: *const AppSession) u32 {
        return self.scrollbarVisibleTicks() + self.scrollbarFadeTicks();
    }

    fn agentPollIntervalTicks(self: *const AppSession) u32 {
        return self.ticksForMs(agent_poll_interval_ms);
    }

    fn agentSpinIntervalTicks(self: *const AppSession) u32 {
        return self.ticksForMs(agent_spin_interval_ms);
    }

    fn syncTimeoutTicks(self: *const AppSession) u32 {
        return self.ticksForMs(sync_timeout_ms);
    }

    /// 커서 깜빡임 반주기를 현재 host frame-loop cadence tick으로 환산한다(config `cursor.blink-interval-ms` → 틱).
    /// ticks = round(ms × frame_loop_rate_hz / 1000)이고, 최소 1틱(0틱이면 토글이 멈춰 영구 visible로 굳음).
    /// 한 반주기 = on 또는 off 한 단계라 사용자가 적은 ms가 곧 깜빡임 속도다. blink=false는 updateCursorBlink
    /// 가드가 호출 전에 걸러낸다.
    fn blinkIntervalTicks(self: *const AppSession) u32 {
        return self.ticksForMs(self.appearance.cursor.blink_interval_ms);
    }

    /// 커서/오버레이 caret 깜빡임 한 스텝(frame-loop tick마다). 깜빡일 대상이 없으면(steady 커서 + 오버레이 닫힘) 보이는
    /// 위상으로 고정한다 — 토글 없으니 idle 재투영도 없다. 오버레이(find·palette)가 열렸으면 커서 blink 설정과 무관
    /// 하게 caret이 깜빡인다(텍스트 입력 caret 관용). 터미널 커서의 기존 메커니즘(틱-카운터 + suffix-trim)을 그대로 탄다.
    fn updateCursorBlink(self: *AppSession) void {
        const surface = self.activeSurface();
        const core = &surface.core;
        // 코어 읽기(cursor 상태 + viewportHasBlink는 셀 스캔)는 락 아래(docs/io-render-threading.md PR3 —
        // 리더 core.write와 경합 방지). 커서/blink 조건을 먼저 다 읽고 락을 푼다.
        surface.lockCore(self.io);
        // 커서 자체가 깜빡이는 조건(DECSCUSR blink·표시·조합 아님).
        // 모달(anyOverlayOpen)이 열리면 터미널 커서 blink를 멈춘다 — 포커스를 잃은 터미널 커서가 모달 뒤에서 계속
        // 깜빡이지 않게(find/palette의 입력 caret은 아래 overlay_open이 따로 진행한다). 커서 모양은 unfocusedCursorMode가 hollow로.
        const cursor_blinks = core.cursor_blink and core.cursor_visible and core.preedit == null and !self.anyOverlayOpen();
        // 텍스트 blink(SGR 5): config text.blink가 켜졌고 보이는 뷰포트에 blink 셀이 있을 때만 위상을 진행한다
        // (없으면 idle 재투영 없음). blink 글자는 커서/caret과 달리 suffix-trim으로 못 숨겨 full rebuild가 필요하다.
        const text_blinks = self.appearance.blink_text and core.viewportHasBlink();
        surface.unlockCore(self.io);
        const overlay_open = self.chrome_host.find.open or self.chrome_host.palette.open;
        // 인라인 rename 편집 caret도 깜빡인다 — 사이드바/탭/라벨 셀 스트림의 '|' 글자라(터미널 커서처럼 suffix-trim
        // 으로 못 숨김) text-blink와 같이 full rebuild가 필요하다(renameEditText가 blink_visible로 '|'↔공백 토글).
        const rename_active = self.rename != null;
        // running 스피너: 사이드바에 **실제로 보이는** 카드(접힘 아님 + 검색 필터 통과) 중 running 에이전트가 있을 때만
        // 위상을 진행한다 — 접힘·필터아웃이면 스피너가 화면에 없으니 매 틱 full-grid 재셰이프는 낭비다(code-review high #1).
        const spinner_visible = self.anyAgentRunning();
        // 사이드바 검색 caret도 깜빡인다 — 헤더 frame의 '|' 글자라(rename과 동형) full rebuild가 필요하다.
        // 검색 caret이 '실제로 그려질' 때만 blink로 재투영한다(buildSidebarHeaderDrawList이 caret을 그리는 조건과 동일:
        // 활성 + 접힘 아님 + cols≥10). 안 그러면 활성인 채 사이드바를 10칸 미만으로 드래그하면 안 보이는 caret 때문에 매
        // 틱 전체 grid가 CoreText 재셰이프된다(idle 못 듦). (접힘은 toggleSidebarCollapsed가 search_active를 끄지만 방어적으로 포함.)
        const sidebar_search = self.sidebar_search_active and !self.sidebar_collapsed and
            self.cell_width_px > 0 and self.sidebar_width_px / self.cell_width_px >= 10;
        // IME 조합 중에는 커서를 **고정**한다(깜빡이면 커서가 덮은 조합 글자가 깜빡 사라짐). 터미널은 cursor_blinks가
        // core.preedit로 이미 막지만, 오버레이/rename/검색은 imeComposingActive로 막아야 한다(단일 출처).
        if ((!cursor_blinks and !overlay_open and !text_blinks and !rename_active and !spinner_visible and !sidebar_search) or self.imeComposingActive()) {
            self.resetCursorBlink(); // 깜빡일 게 없거나 조합 중 — 보이는 위상 고정
            return;
        }
        // running 스피너: blink(500ms)보다 빠른 별도 위상 — 약 133ms마다 프레임 진행 + 사이드바 재투영(회전 보임).
        if (spinner_visible) {
            self.agent_spin_ticks += 1;
            if (self.agent_spin_ticks >= self.agentSpinIntervalTicks()) {
                self.agent_spin_ticks = 0;
                // 파형 길이로 wrap — u8 자연 wrap(256%14≠0)이면 255→0 경계에서 파형이 튀므로 주기 안에서 순환한다.
                self.agent_spin_frame = (self.agent_spin_frame + 1) % @as(u8, @intCast(spinner_wave.len));
                self.metal_dirty = true;
            }
        }
        self.blink_ticks += 1;
        if (self.blink_ticks >= self.blinkIntervalTicks()) {
            self.blink_ticks = 0;
            self.blink_visible = !self.blink_visible;
            // suffix-trim 토글(재빌드 없음). 오버레이가 열렸으면 suffix=오버레이 caret이라 caret을, 닫혔으면 suffix=
            // 터미널 커서라 커서를 깜빡인다 — 같은 코드(generation↑만, idle에 full-grid reshape 안 함).
            self.metal_buffer.setCursorVisible(self.blink_visible);
            // 텍스트 blink·rename caret·검색 caret은 셀/사이드바 glyph라 full rebuild가 필요하다(suffix-trim으로 못 숨김).
            // 에이전트 스피너는 위 자기 위상(약 133ms)에서 따로 dirty하므로 여기엔 안 넣는다(옛 펄스 폐기 후 500ms 재투영은 byte-identical 낭비, #3).
            if (text_blinks or rename_active or sidebar_search) self.metal_dirty = true;
        }
    }

    /// 사이드바에 **실제로 보이는** 워크스페이스 카드 중 running 에이전트가 있으면 true — 스피너 위상을 진행할지/사이드바를
    /// 재투영할지 결정한다. 접힘이면 스피너가 안 보이고(false), 검색 필터로 숨은 탭은 카드가 없으므로(스피너 미표시) 제외해야
    /// 한다 — 그래서 `tabs` 전체가 아니라 `sidebar_visible_tabs`(필터 통과 = 표시 카드)만 본다(code-review high #1: 옛 전체-스캔이
    /// 접힘·필터아웃에도 130ms 재투영을 돌리던 회귀). 빈 검색이면 visible_tabs=전체라 평소와 동일.
    fn anyAgentRunning(self: *AppSession) bool {
        if (self.sidebar_collapsed) return false; // 접힘 = 스피너 화면에 없음
        for (self.sidebar_visible_tabs.items) |i| {
            if (i < self.tabs.items.len and self.tabs.items[i].activePane().activeTerm().agent_state == .running) return true;
        }
        return false;
    }

    /// 깜빡임을 보이는 위상으로 리셋한다(입력/출력 직후 — caret이 항상 보이며 새 주기를 시작).
    fn resetCursorBlink(self: *AppSession) void {
        self.blink_ticks = 0;
        if (!self.blink_visible) {
            self.blink_visible = true;
            self.metal_buffer.setCursorVisible(true);
        }
    }

    /// 드래그 자동 스크롤 한 스텝(frame-loop tick마다). 드래그가 grid 밖에 머무는 동안 한 줄씩
    /// 스크롤하며 선택을 가장자리 행으로 확장한다 — 화면보다 긴 내용을 드래그로 선택하는 표준 UX.
    fn applyDragAutoscroll(self: *AppSession) void {
        if (self.drag_autoscroll == 0) {
            self.drag_autoscroll_accum_ms = 0; // 드래그가 grid 안으로 돌아옴 — 다음 진입이 새로 누적 시작
            return;
        }
        // **frame rate 무관 속도**: 옛날엔 tick마다 한 줄이라 기본이 30→60Hz로 오르며 자동 스크롤이 2배(120Hz면
        // 4배) 빨라졌다. tick 수가 아니라 경과 ms로 게이트해 항상 ≈30줄/s를 유지한다 — msPerTick 누적이 step_ms를
        // 넘을 때만 한 줄. frame-rate_min=30이라 msPerTick≤step_ms → tick당 최대 한 줄(저rate에서도 과속 없음).
        self.drag_autoscroll_accum_ms += self.msPerTick();
        if (self.drag_autoscroll_accum_ms < drag_autoscroll_step_ms) return;
        self.drag_autoscroll_accum_ms -= drag_autoscroll_step_ms;
        const surface = self.activeSurface();
        const core = &surface.core;
        // selection_anchor/view_offset/selection_head 읽기 + scrollViewport/selectionExtend(코어 변경)는 리더
        // core.write와 경합 — 메서드 전체를 락 아래(docs/io-render-threading.md PR3). 짧은 메서드라 락 비용 무시 가능;
        // 함수가 metal_dirty 직후 끝나므로 함수-스코프 defer로 풀어 early return도 안전히 unlock.
        // 게이트("확장할 선택이 있는가") + grid rows는 코어 read(메인 락-아래 — 읽기는 위임 안 함, §9.1).
        // mouse_drag_selecting로 걸면 더블/트리플클릭(4/5)으로 시작한 선택을 드래그로 화면 밖까지 늘릴 때 자동
        // 스크롤이 영원히 안 걸린다.
        const rows: u16 = blk: {
            surface.lockCore(self.io);
            defer surface.unlockCore(self.io);
            if (core.selection_anchor == null) return; // 확장할 선택 없음
            break :blk core.size.rows;
        };
        const row: u16 = if (self.drag_autoscroll > 0) 0 else rows - 1;
        // scroll+extend는 full (a)(docs/io-render-threading.md §9 P3-4)로 reader에 위임 — **kind-2 드래그 extend와
        // 같은 명령 큐를 타 순서 보존**(둘이 다른 스레드면 선택이 어긋날 수 있다). 원래의 "변화 시만 재투영" 최적화는
        // reader 렌더 트리거로 대체한다(스크롤백 끝에서 포인터를 grid 밖에 둘 때 cheap render tick 몇 개 — §9 trade-off).
        self.runtime.enqueueCoreCommand(surface.id, .{ .scroll_and_extend = .{ .delta = @as(isize, self.drag_autoscroll), .row = row, .col = self.last_drag_col } }, self.io) catch {};
    }

    /// 입력(키·IME)이 지금 어디로 가는가 — **단일 출처**. 모달은 배타적(show가 서로 닫는다 — showNotice/toggleFind/
    /// togglePalette가 나머지를 닫아 한 번에 하나만 열린다)이다. notice는 텍스트 입력 대상이 아니지만(dismiss만) IME가
    /// 뒤(터미널/find)로 새지 않게 **최우선**으로 잡아 무시한다. 모든 IME 연산(preedit set·조합 판정·caret)이 이걸로
    /// 분기해, 라우팅이 콜백마다 흩어져 일부를 누락하던 단일-출처 위반을 없앤다.
    const InputFocus = enum { terminal, confirm, notice, settings, rename, sidebar_search, find, palette };
    fn inputFocus(self: *const AppSession) InputFocus {
        if (self.chrome_host.confirm.open) return .confirm; // 닫기 확인 — 파괴적 동작 게이트라 최우선(notice와 동형: IME 비대상)
        if (self.chrome_host.notice.open) return .notice; // 최우선 모달 — 텍스트/IME를 받지 않고 무시(뒤로 안 샘)
        // 세팅 모달(전체 화면 오버레이) — 열려 있으면 그 안 검색줄이 IME/확정 텍스트를 받는다. macOS는 평범한 글자
        // 입력을 IME(NSTextInputClient) 확정 텍스트로 처리하므로, 여기 없으면 검색어가 뒤의 터미널로 새 검색이 안 됐다
        // (find/palette가 되던 것과 달리 settings만 누락돼 있던 버그). 검색 중이 아니어도 모달이라 뒤 터미널로 안 흘린다.
        if (self.chrome_host.settings.open) return .settings;
        if (self.rename != null) return .rename; // 인라인 rename(find/palette와 배타적 — startRename이 닫음)
        if (self.sidebar_search_active) return .sidebar_search; // 사이드바 검색바(상주 — 활성이면 키/IME를 받는다)
        if (self.chrome_host.find.open) return .find;
        if (self.chrome_host.palette.open) return .palette;
        return .terminal;
    }

    /// 활성 입력 대상의 IME 조합(marked) 텍스트를 교체한다(빈 bytes=해제). inputFocus 단일 출처로 분기 — exhaustive
    /// switch라 입력 대상 추가 시 컴파일러가 누락을 막는다.
    fn imeSetPreedit(self: *AppSession, bytes: []const u8) void {
        switch (self.inputFocus()) {
            .confirm, .notice => {}, // 확인/notice 모달은 조합을 표시하지 않는다(텍스트 입력 대상 아님)
            .settings => self.chrome_host.settings.setSearchPreedit(bytes), // 세팅 검색줄 조합(고정 버퍼 — OverlayInput과 별개)
            .rename => self.rename_input.setPreedit(self.allocator, bytes) catch {},
            .sidebar_search => self.sidebar_search_input.setPreedit(self.allocator, bytes) catch {},
            .find => self.chrome_host.find.input.setPreedit(self.allocator, bytes) catch {},
            .palette => self.chrome_host.palette.input.setPreedit(self.allocator, bytes) catch {},
            .terminal => {
                // Phase 3 위임(docs/io-render-threading.md §9 P3-2): setPreedit는 코어 mutate라 메인이 직접 하지
                // 않고 reader로 위임한다 — IME 조합 확정 중 포커스 상실 재진입 데드락(#700)을 구조적으로 없앤다.
                // 빈 bytes=조합 해제(clear_preedit). interactive면 명령 큐로 enqueue+wake, non-interactive(테스트/
                // smoke, reader 없음)면 runtime이 호출 스레드에서 직접 적용 폴백한다(enqueueCoreCommand 내부 분기).
                const cmd: app.CoreCommand = if (bytes.len > 0) .{ .set_preedit = bytes } else .clear_preedit;
                self.runtime.enqueueCoreCommand(self.activeSurface().id, cmd, self.io) catch {};
            },
        }
    }

    /// 활성 입력 대상이 조합 중(preedit 있음)인가 — imeBegin/imeEnd가 조합 판정에 쓴다. 예전엔 core.preedit만 봐서
    /// find/palette 조합을 놓쳤다(단일-출처 위반 → 조합 보호·표시 버그). inputFocus로 통일.
    fn imeComposingActive(self: *const AppSession) bool {
        return switch (self.inputFocus()) {
            .confirm, .notice => false, // 확인/notice 모달은 조합 상태가 없다
            .settings => self.chrome_host.settings.searchPreedit().len > 0,
            .rename => self.rename_input.preedit.items.len > 0,
            .sidebar_search => self.sidebar_search_input.preedit.items.len > 0,
            .find => self.chrome_host.find.input.preedit.items.len > 0,
            .palette => self.chrome_host.palette.input.preedit.items.len > 0,
            .terminal => self.activeSurfaceConst().core.preedit != null,
        };
    }

    /// IME 키 트랜잭션 시작(Swift keyDown 진입 — 수정자 없는 키). 이번 키에서 입력기가 만들
    /// 텍스트/조합 변화를 모으기 시작한다.
    pub fn imeBegin(self: *AppSession) void {
        if (!self.surface_initialized) return;
        // 조합도 타이핑이다 — 과거를 보는 중이면 바닥으로 스냅해 preedit이 보이게 한다
        // (handleKeyEvent의 "입력하면 live 복귀"와 같은 동작; 조합 키는 그 경로를 안 타므로 여기서).
        // **터미널 입력일 때만** — find/palette에서 조합하면 뒤 터미널 스크롤백을 건드리면 안 된다(조합은
        // 오버레이 입력칸으로 가지 터미널로 안 간다; inputFocus 단일 출처로 판정).
        if (self.inputFocus() == .terminal) {
            // viewOffset 읽기는 메인 락-아래(§9.1), scrollToBottom mutate는 reader로 위임(full (a), §9 P3-4).
            const surface = self.activeSurface();
            const scrolled = blk: {
                surface.lockCore(self.io);
                defer surface.unlockCore(self.io);
                break :blk surface.core.viewOffset() != 0;
            };
            if (scrolled) {
                self.runtime.enqueueCoreCommand(surface.id, .scroll_to_bottom, self.io) catch {};
                self.metal_dirty = true;
            }
        }
        self.ime_active = true;
        self.ime_inserted.clearRetainingCapacity();
        self.ime_marked_changed = false;
        self.ime_did_delete = false;
        self.ime_insert_failed = false;
        self.ime_had_marked = self.imeComposingActive(); // 단일 출처(터미널/find/palette) — core.preedit만 보던 누락 수정
    }

    /// 입력기가 확정한 텍스트(insertText). 즉시 보내지 않고 누적한다 — 전송 여부·시점은
    /// imeEnd가 일괄 판정한다(이중 전송 차단). 트랜잭션 밖(드물게 입력기가 keyDown 없이 직접
    /// 커밋 — 포커스 전환 등)이면 그대로 확정 전송한다.
    pub fn imeInsert(self: *AppSession, bytes: []const u8) void {
        if (!self.surface_initialized) return;
        if (!self.ime_active) {
            // 트랜잭션 밖 직접 커밋(입력기가 keyDown 없이 직접 — 포커스 전환 등 windowLostKey와 같은
            // AppKit 동기 콜백 클래스)도 현재 입력 대상으로 라우팅한다(#10 후속) — 터미널이면 non-blocking
            // PTY, find/palette 입력칸이면 기존 키 경로(routeCommittedText 참조).
            self.routeCommittedText(bytes);
            return;
        }
        self.ime_inserted.appendSlice(self.allocator, bytes) catch {
            self.ime_insert_failed = true; // imeEnd가 잘린 커밋을 보내지 않게
        };
    }

    /// 입력기의 조합 중(marked) 텍스트 갱신(빈 입력 = 조합 해제). 활성 입력 대상(inputFocus 단일 출처)에 보여준다 —
    /// find/palette 열림이면 그 입력에, 아니면 터미널 core. 조합 상태가 그 자리에 즉시 보이고 뒤로 새지 않는다.
    pub fn imeMarked(self: *AppSession, bytes: []const u8) void {
        if (!self.surface_initialized) return;
        self.imeSetPreedit(bytes);
        self.metal_dirty = true; // 조합 글자는 즉시 보여야 한다
        if (self.ime_active) self.ime_marked_changed = true;
    }

    /// 입력기의 deleteBackward 편집 명령(doCommand). 트랜잭션에 기록만 하고 판정은 imeEnd가 한다.
    pub fn imeDeleteBackward(self: *AppSession) void {
        if (self.ime_active) self.ime_did_delete = true;
    }

    // ImeDecision·imeDecide·dropLastCodepoint는 session core로 추출(src/session/ime.zig). 위 file-scope alias
    // (imeDecide=ime.decide)로 imeEnd가 bare 이름 그대로 호출한다. 정의·단위 테스트는 ime.zig.

    /// IME 키 트랜잭션 종료(Swift keyDown이 interpretKeyEvents 직후 호출) — 일괄 판정.
    /// 규칙(위에서부터 첫 일치):
    /// 1. 확정 텍스트가 쌓였으면 그것만 보낸다(키 자체는 입력기가 소비). 단 조합 중 단일
    ///    C0(예: 조합 조작용 Ctrl+H)는 입력기 소유라 버린다(Ghostty와 같은 보호).
    /// 2. 텍스트는 없지만 조합이 변했으면(자모 삭제 등) 키를 보내지 않는다 — 안 막으면 조합
    ///    중 Backspace가 자모도 줄이고 셸 글자까지 지운다(라이브에서 발생).
    /// 3. 둘 다 아니면 일반 키 — 기존 인코딩 경로(Enter/Backspace/기능키).
    /// IME 키 트랜잭션 종료. event가 null이면(정규화 불가 키 — 정의되지 않은 codepoint/keyCode)
    /// 트랜잭션은 그래도 닫고(누적 텍스트 커밋/조합 무시 판정), 일반 키 인코딩만 건너뛴다 —
    /// ime_begin 후 ime_end를 영영 안 닫아 ime_active가 박히고 누적 텍스트가 유실되던 누수를
    /// 막는다(라이브 회귀 클래스).
    pub fn imeEnd(self: *AppSession, event: ?terminal.KeyEvent) void {
        if (!self.surface_initialized) return;
        const composing = self.imeComposingActive() or self.ime_had_marked; // 단일 출처(find/palette도) — core만 보던 누락 수정
        defer {
            self.ime_active = false;
            self.ime_inserted.clearRetainingCapacity();
            self.ime_marked_changed = false;
            self.ime_did_delete = false;
            self.ime_insert_failed = false;
        }
        // OOM으로 누적이 잘렸으면 통째로 버린다 — 반쪽 문자열을 PTY에 보내지 않는다(#14).
        if (self.ime_insert_failed) return;
        switch (imeDecide(composing, self.ime_inserted.items, self.ime_marked_changed, self.ime_did_delete)) {
            .commit_text => |text| {
                // #10 후속: 확정 텍스트를 현재 입력 대상으로 라우팅한다 — imeEnd는 keyDown(interpretKeyEvents
                // 직후) 동기 콜백이라, 터미널 PTY로 blocking enqueue하면 write_queue 포화 시 tick을 멈춰
                // commitComposition과 같은 backpressure 데드락이 된다(#10이 그쪽만 되돌렸다). 터미널이면
                // non-blocking, find/palette 입력칸이면 기존 키 경로(routeCommittedText 참조). 아래 replay(화살표·Enter)는
                // 인코딩이 필요해 그대로 키 경로(handleKeyEvent)를 쓴다 — 버퍼 포화 시 순서/blocking 한계는 그 블록 주석 참조.
                self.routeCommittedText(text);
                // 한글 후보를 화살표로 확정하는 경우(insertText('안') + 화살표): 텍스트만 보내고
                // 화살표를 버리면 커서가 안 움직인다. 확정 후 그 화살표를 다시 보낸다(Ghostty
                // shouldReplayCommittedPreeditKey와 같은 의미론 — 위/오른/아래는 항상, 왼쪽은
                // 수정자 있을 때만; plain 왼쪽은 AppKit이 이미 커서를 제자리에 둬 중복 이동 방지).
                // Enter는 config(input.ime-enter=newline, 기본)면 함께 replay해 조합 확정과 개행을 한 번에
                // 처리한다(브라우저 동작). replay되는 Enter는 handleKeyEvent를 거쳐 일반 Enter=`\r`,
                // Shift+Enter=Meta 변형(`\x1b\r`)으로 인코딩된다(shift→meta 변환·kitty 인코딩·find_nav 등 부작용 유지).
                // **알려진 한계(드묾)**: 확정 텍스트는 non-blocking pending_paste FIFO(#10 데드락 회피)지만 이 replay는
                // blocking writeInput(키 경로)이라 '다른 스트림'이다. PTY 쓰기 버퍼가 포화면(자식이 stdin을 안 읽는 중)
                // 확정 문자는 FIFO에 남고 '\r'가 fd에 먼저 써져 글자가 다음 줄로 밀릴 수 있고, 동기 콜백에서 blocking
                // write가 잠깐 막힐 수도 있다. 대화형 셸은 키 입력을 즉시 읽어 버퍼가 차는 일이 거의 없어 실사용 트리거는
                // 희박하다. 근본 해결은 키 경로도 pending_paste FIFO로 통합(키·paste·IME가 한 순서 스트림)하는 구조
                // 변경이라, IME 트랜잭션(부작용)을 안 깨게 별도 작업으로 둔다([document-basis-and-decision]).
                if (event) |ev| if (shouldReplayAfterCommit(ev, self.ime_enter_newline)) {
                    _ = self.handleKeyEvent(ev) catch {};
                };
            },
            .ignore => {}, // 조합 조작 키(자모 삭제) 또는 조합 중 단일 C0 — 입력기 소유
            .encode_key => if (event) |ev| {
                _ = self.handleKeyEvent(ev) catch {};
            },
        }
    }

    /// 한글 후보를 확정시키며 함께 온 키를 확정 후 다시 보낼지(Ghostty 정책 동작 비교). 화살표는 커서
    /// 이동이라 항상(왼쪽만 수정자 조건), Enter는 enter_newline(config input.ime-enter=newline)일 때만 —
    /// 브라우저처럼 조합 확정과 개행을 한 번에. commit-only면 false라 조합만 확정되고 Enter는 입력기가 소유.
    fn shouldReplayAfterCommit(event: terminal.KeyEvent, enter_newline: bool) bool {
        return switch (event.key) {
            .arrow_up, .arrow_right, .arrow_down => true,
            .arrow_left => event.modifiers.shift or event.modifiers.control or
                event.modifiers.option or event.modifiers.command,
            .enter => enter_newline,
            else => false,
        };
    }

    /// IME 후보창 배치용 커서 셀 사각형(backing px, 좌상단 원점 — 마우스 좌표와 같은 규약).
    /// 입력기가 firstRect로 물어보면 Swift가 이 값을 화면 좌표로 바꿔 후보창을 커서 위치에
    /// 띄운다. 조합 중에는 커서가 preedit 시작(core.screen.cursor)에 있어 후보창이 조합 글자 옆에 뜬다.
    /// 반환: row*cell_h, col*cell_w, cell_w, cell_h.
    // self는 *AppSession(비-const) — rename caret 위치(renameCaretRect)가 leaf-rects 레이아웃을 펴는 *AppSession
    // 헬퍼를 거치기 때문(읽기 전용 계산이지만 activeTabLeafRects 체인이 비-const). ABI·테스트 호출자는 모두 mutable.
    pub fn imeCursorRect(self: *AppSession) struct { x: f64, y: f64, w: f64, h: f64 } {
        const cw: f64 = @floatFromInt(if (self.cell_width_px > 0) self.cell_width_px else placeholder_cell_width_px);
        const ch: f64 = @floatFromInt(if (self.cell_height_px > 0) self.cell_height_px else placeholder_cell_height_px);
        if (!self.surface_initialized) return .{ .x = 0, .y = 0, .w = cw, .h = ch };
        // 활성 입력 대상(inputFocus 단일 출처)의 입력 caret 옆에 후보창을 띄운다 — caretRect가 위치 단일 출처.
        // null(패널 밖)이거나 터미널이면 아래 터미널 커서로 폴백.
        const props = self.buildChromeProps();
        const overlay_caret: ?chrome.draw.Rect = switch (self.inputFocus()) {
            .confirm, .notice => null, // 조합을 안 받으므로 후보창 위치 무의미 — 아래 터미널 커서로 폴백(실제론 안 뜸)
            // rename 인라인 편집기의 caret(사이드바 슬롯/탭/라벨)에 후보창을 띄운다 — renameCaretRect가 대상별 위치를
            // 잡는다(사이드바 y는 slot 기준 근사). null이면 아래 터미널 커서로 폴백.
            .rename => self.renameCaretRect(),
            // 세팅 검색줄 caret — buildChromeOverlayPrep이 캐시한 rect(검색 중이 아니면 null → 터미널 커서 폴백).
            .settings => self.settings_search_caret,
            .sidebar_search => self.sidebarSearchCaretRect(),
            .find => chrome.components.find.caretRect(&self.chrome_host.find, props),
            .palette => chrome.components.palette.caretRect(&self.chrome_host.palette, props),
            .terminal => null,
        };
        if (overlay_caret) |r| {
            return .{ .x = @floatFromInt(r.x), .y = @floatFromInt(r.y), .w = @floatFromInt(r.w), .h = @floatFromInt(r.h) };
        }
        const cursor = self.activeSurfaceConst().core.screen.cursor;
        return .{
            // 활성 panel은 자기 rect origin(active_pane_rect.x/y)에서 그려지므로 커서의 스크린 좌표도 그 origin을
            // 더해야 한다 — 안 더하면 후보창이 실제 커서보다 origin만큼 왼쪽/위에 뜬다(pxToCell의 역변환:
            // pxToCell은 빼고, 셀→스크린인 여기선 더한다). 단일 panel이면 origin = (사이드바 폭+padding_x, padding_y).
            .x = @as(f64, @floatFromInt(self.active_pane_rect.x)) + @as(f64, @floatFromInt(cursor.col)) * cw,
            .y = @as(f64, @floatFromInt(self.active_pane_rect.y)) + @as(f64, @floatFromInt(cursor.row)) * ch,
            .w = cw,
            .h = ch,
        };
    }

    /// 진행 중인 IME 조합(preedit)을 확정(커밋)한다 — 조합 글자를 대상에 보내고 preedit을 비운다. 포커스 상실
    /// (setFocused)과, IME를 우회하는 특수키/단축키(PageUp 등) '직전'에 호출해 Swift marked text와 화면이 어긋나지
    /// 않게 한다. 활성 입력 대상(inputFocus 단일 출처)으로 분기 — 터미널은 PTY로, find/palette는 검색어/명령어로 확정.
    pub fn commitComposition(self: *AppSession) void {
        if (!self.surface_initialized) return;
        switch (self.inputFocus()) {
            .confirm, .notice => {}, // 확인/notice 모달은 확정할 조합이 없다
            .settings => if (self.chrome_host.settings.commitSearchPreedit()) {
                self.refreshSettingsFieldCount(); // 확정 글자로 검색 필터 재적용(setFieldCount가 selected clamp)
                self.metal_dirty = true;
            },
            .rename => if (self.rename_input.commitPreedit(self.allocator)) {
                self.metal_dirty = true; // 조합 글자가 편집 텍스트로 확정됨(렌더 갱신)
            },
            .sidebar_search => if (self.sidebar_search_input.commitPreedit(self.allocator)) {
                self.rebuildSidebar() catch {}; // 확정 글자로 필터 재적용
                self.metal_dirty = true;
            },
            .terminal => {
                // preedit 읽기 + setPreedit("") 변경은 코어 mutate — 락 아래(docs/io-render-threading.md PR3,
                // 리더 경합 방지). 단 확정 텍스트 전송(sendTextAsKeys)은 락을 푼 뒤에 한다:
                // sendTextAsKeys→handleKeyEvent가 같은 core_mutex를 재취득하므로 락 보유 중 호출하면
                // self-deadlock이다(std.Io.Mutex는 비재진입). 과거 PTY 직접 쓰기(sendCommittedText)는 락
                // 안에서 안전했지만 sendTextAsKeys 공유(#2, bd5fd14)로 그 가정이 깨졌다 — 한글 조합 중
                // 창 포커스 상실 시 메인 스레드가 ulock_wait에 박혀 hang으로 드러난 회귀.
                const s = self.activeSurface();
                const core = &s.core;
                var committed: ?[]u8 = null;
                {
                    s.lockCore(self.io);
                    defer s.unlockCore(self.io);
                    if (core.preedit) |pending| {
                        // setPreedit가 버퍼를 해제하므로 먼저 사본을 뜬다. dupe 실패(OOM)면 비우지 않고
                        // 그대로 둔다(반쪽 커밋 방지 — 기존 동작 보존).
                        committed = self.allocator.dupe(u8, pending) catch return;
                        core.setPreedit("") catch {};
                        self.metal_dirty = true;
                    }
                }
                // 락 밖 + non-blocking 전송(sendCommittedText) — windowLostKey(AppKit 동기 콜백)에서
                // 호출돼도 메인 run loop(tick)를 막지 않아 #10 write_queue backpressure 데드락을 피한다
                // (과거 sendTextAsKeys→handleKeyEvent의 enqueueBlocking이 tick을 멈춰 hang했다).
                if (committed) |copy| {
                    defer self.allocator.free(copy);
                    self.sendCommittedText(copy);
                }
            },
            .find => if (self.chrome_host.find.input.commitPreedit(self.allocator)) {
                self.recomputeFind(); // 검색어가 바뀜
                self.metal_dirty = true;
            },
            .palette => if (self.chrome_host.palette.input.commitPreedit(self.allocator)) {
                self.recomputePalette(); // 필터가 바뀜
                self.metal_dirty = true;
            },
        }
    }

    /// 포커스 변화. 잃으면 조합 중 텍스트를 버리지 않고 확정(커밋)한다 — 버리면 글자가
    /// 사라졌다가 재포커스 후 입력 위치가 어긋나는 사용감(라이브 제보)이 된다.
    /// Terminal.app/Ghostty와 같은 의미론.
    pub fn setFocused(self: *AppSession, focused: bool) void {
        if (!self.surface_initialized) return;
        if (focused) return;
        // 인라인 rename 중 포커스 상실 = 확정(docs/tabs-splits-layout.md "포커스 상실=확정"). 앱-내 클릭은 mouse()
        // down이 이미 commit하지만, 앱-간 전환(window resign)은 이 경로뿐이라 여기서 확정한다. commitRename이 조합
        // preedit도 먼저 query로 확정하므로 commitComposition을 따로 부를 필요 없다(rename은 find/palette와 배타적).
        if (self.rename != null) {
            self.commitRename();
            return;
        }
        self.commitComposition();
    }

    /// **IME 확정 텍스트 전용** — 코드포인트 단위로 기존 key event 경로(handleKeyEvent)에 태운다. 인코딩 단일 출처
    /// (encodeKey)·입력 회계(terminal_input)·IME preedit 정리 등 부작용을 유지한다(IME 트랜잭션이 이것에 의존). 개행은
    /// .enter(\r)로 정규화. bracketed paste 없음. 드래그앤드롭은 paste 경로(pasteText→encodePaste)로 별도다 — TUI([Image]) 인식을 위해 DECSET 2004가 켜졌을 때 bracketed paste로 감싸야 하므로.
    /// **불변식: 호출 시 surface.core_mutex를 보유하면 안 된다** — handleKeyEvent가 인코딩 중 core_mutex를 재취득하는데
    /// std.Io.Mutex는 비재진입이라 같은 스레드가 이미 보유 중이면 자기 데드락(ulock_wait)이다. imeEnd의 .terminal 확정
    /// 경로는 preedit를 락 아래 복사한 뒤 락을 풀고 이 함수를 호출한다(아래 imeEnd 참조). 신규 호출처도 이 규율을 지킬 것.
    pub fn sendTextAsKeys(self: *AppSession, bytes: []const u8) void {
        const view = std.unicode.Utf8View.init(bytes) catch return;
        var it = view.iterator();
        while (it.nextCodepoint()) |cp| {
            // 개행은 .enter로 보낸다(\r로 인코딩) — 멀티라인 insertText가 LF를 그대로 PTY에 넣으면 셸 line discipline이 어긋난다.
            const key: terminal.input.Key = if (cp == '\n' or cp == '\r')
                .enter
            else
                (terminal.input.charKeyFromCodepoint(cp) catch continue);
            _ = self.handleKeyEvent(.{ .key = key, .modifiers = .{} }) catch return;
        }
    }

    /// IME 확정 텍스트를 **non-blocking**으로 PTY에 보낸다 — paste와 같은 pending 큐 패턴
    /// (`pending_paste` FIFO + `flushPendingPaste`의 `writeInputNonBlocking`). `windowLostKey` 등
    /// AppKit 동기 콜백 안에서 호출돼도 blocking enqueue로 메인 run loop(=tick)를 멈추지 않아 #10
    /// write_queue backpressure 데드락을 피한다(설계 전제 "입력 전송은 tick 안"에 코드를 맞춤 —
    /// P2-3b write_queue 구조는 그대로). 확정 텍스트는 완성된 평문이라 키 인코딩(handleKeyEvent)
    /// 없이 바이트로 보내되 개행만 \r로 정규화한다(sendTextAsKeys와 동일 규약; bracketed 감싸기는
    /// paste 전용이라 IME 확정엔 안 쓴다). pending_paste FIFO는 paste와 공유해 전송 순서를 지킨다.
    fn sendCommittedText(self: *AppSession, bytes: []const u8) void {
        if (!self.surface_initialized or bytes.len == 0) return;
        self.pendingPasteRetarget();
        self.pending_paste.ensureUnusedCapacity(self.allocator, bytes.len) catch return;
        for (bytes) |b| self.pending_paste.appendAssumeCapacity(if (b == '\n') '\r' else b);
        // handleKeyEvent를 우회하므로 terminal input 회계를 여기서 직접 한다(\n→\r는 1:1이라 byte 수 동일).
        self.total_terminal_input_events += 1;
        self.total_terminal_input_bytes += bytes.len;
        self.flushPendingPaste();
    }

    /// IME 확정 텍스트를 현재 입력 대상(inputFocus 단일 출처)으로 라우팅한다. 터미널이면 non-blocking PTY
    /// 전송(sendCommittedText — AppKit 동기 콜백에서 write_queue backpressure 데드락 회피, #10 후속). find/
    /// palette 입력칸이면 그 입력은 메모리 조작이라 write_queue를 안 거쳐 데드락과 무관하므로, inputFocus
    /// 분기를 흡수하는 기존 키 경로(sendTextAsKeys→handleKeyEvent)로 보내 검색어/명령어에 글자가 들어가게
    /// 한다(이 분기를 빼면 find 조합 확정이 PTY로 새 입력칸이 빈다 — 회귀 테스트가 고정). 터미널 타이핑은
    /// "검색 종료(find_nav)"도 함께 처리한다(handleKeyEvent 3478과 동일 의미).
    fn routeCommittedText(self: *AppSession, bytes: []const u8) void {
        if (self.inputFocus() == .terminal) {
            if (self.find_nav) self.find_nav = false;
            // 타이핑(글자 입력) 중 마우스 숨김(config). IME 확정 텍스트가 터미널로 갈 때 = 실제 글자 타이핑(ASCII·한글·
            // CJK 모두 이 경로 — macOS NSTextInputClient가 평범한 키 입력을 여기로 커밋, handleKeyEvent 우회). find/
            // palette 입력칸(else 분기)은 chrome 타이핑이라 안 숨긴다. Swift가 takeMouseHide로 drain → setHiddenUntilMouseMoves.
            // 베이스: Ghostty mouse-hide-while-typing(press+utf8.len>0) — utf8 텍스트 produce가 곧 IME 확정이다(F1-6).
            if (self.loaded_config.config.input.mouse_hide_while_typing and bytes.len > 0) self.mouse_hide_pending = true;
            self.sendCommittedText(bytes);
        } else {
            self.sendTextAsKeys(bytes);
        }
    }

    /// 셸 메타문자 — 셸이 공백/특수문자에서 단어를 쪼개거나 글롭·치환으로 해석하지 않게 앞에
    /// 백슬래시를 붙일 대상. POSIX 셸 기준이고 동작은 Ghostty Shell.escape와 같다(동작 비교만 —
    /// 코드 표현은 옮기지 않음). 메타문자는 전부 ASCII라 UTF-8 바이트 단위로 안전하다(ASCII
    /// 바이트는 멀티바이트 문자 중간에 안 나타난다 — UTF-8 self-synchronizing).
    fn isShellMetachar(b: u8) bool {
        return switch (b) {
            '\\', ' ', '\t', '(', ')', '[', ']', '{', '}', '<', '>', '"', '\'', '`', '!', '#', '$', '&', ';', '|', '*', '?' => true,
            else => false,
        };
    }

    /// NUL('\0')로 구분된 토큰들을 각각 셸 이스케이프해 공백으로 join한다(토큰 1개면 그 토큰만
    /// 이스케이프). 드래그된 파일 경로/URL을 셸 버퍼에 안전히 넣기 위한 paste 전처리다 — 이전엔
    /// Swift host(MaruAppHost.shellEscape)에 있던 순수 문자열 로직을, 단위 테스트(std.testing)·
    /// 이식성을 위해 Zig로 옮겼다(네이티브 레이어 최소화 정책 — macos-app-host-boundary.md).
    /// 무엇을 이스케이프할지(pasteboard 타입)는 host가 정하고, 메커니즘만 여기 둔다. 호출자가 free한다.
    fn shellEscapeJoin(alloc: std.mem.Allocator, tokens: []const u8) ![]u8 {
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(alloc);
        var it = std.mem.splitScalar(u8, tokens, 0);
        var first = true;
        while (it.next()) |tok| {
            if (!first) try out.append(alloc, ' ');
            first = false;
            for (tok) |b| {
                if (isShellMetachar(b)) try out.append(alloc, '\\');
                try out.append(alloc, b);
            }
        }
        return try out.toOwnedSlice(alloc);
    }

    /// 클립보드 텍스트 붙여넣기(Cmd+V)·드래그앤드롭. 인코딩(개행 정규화 + bracketed paste 감싸기)은
    /// core가 하고, 여기선 한 번의 writeInput으로 보낸다(부분 쓰기 실패로 감싸기가 깨지지 않게).
    /// `escape_each`가 true면 bytes를 NUL('\0') 구분 토큰으로 보고 각 토큰을 셸 이스케이프한 뒤 공백으로
    /// join한다(드래그된 파일 경로·URL — 셸이 공백 등 메타문자에서 단어를 쪼개지 않게). 평문·Cmd+V 웹
    /// URL은 false로 raw 전송한다(이스케이프하면 ?,&,= 등이 깨진다). 무엇을 이스케이프할지는 pasteboard
    /// 타입에 묶여 host(Swift)가 정하고, 이스케이프 '메커니즘'은 여기(Zig)가 단일 출처로 한다.
    pub fn pasteText(self: *AppSession, bytes: []const u8, escape_each: bool) void {
        if (!self.surface_initialized or bytes.len == 0) return;
        // escape면 NUL 구분 토큰을 각각 셸 이스케이프 후 공백 join한 임시 버퍼를 encodePaste에 넘긴다.
        const payload: []const u8 = if (escape_each)
            shellEscapeJoin(self.allocator, bytes) catch return
        else
            bytes;
        defer if (escape_each) self.allocator.free(payload);
        const encoded = self.activeSurface().core.encodePaste(self.allocator, payload) catch return;
        defer self.allocator.free(encoded);
        // 큐에 쌓고 즉시 flush를 시도한다. 자식이 읽는 중이면 보통 이 자리에서 다 들어가고,
        // 안 읽으면(vim 다이얼로그 등) 잔여가 tick마다 흘러나간다 — blocking 단일 write로 UI가
        // 동결되던 것을 없앤다. 큐는 FIFO라 bracketed paste 감싸기 순서는 깨지지 않는다.
        self.pendingPasteRetarget();
        self.pending_paste.appendSlice(self.allocator, encoded) catch return;
        self.flushPendingPaste();
    }

    // 드롭 업로드 백그라운드 스레드에 넘기는 작업 묶음(모두 owned — 워커가 해제). io를 안 싣는다:
    // 파일 읽기는 메인(startUpload)에서 끝내고, 워커는 io 없는 ssh 자식 프로세스 실행만 한다.
    const UploadJob = struct {
        session: *AppSession,
        ctl: []u8,
        dest: []u8,
        name: []u8,
        bytes: []u8,
    };

    /// 드롭한 파일들(NUL 구분 경로)을 처리한다. maru ssh 원격 세션이면 각 파일을 control socket으로
    /// 백그라운드 업로드하고(완료 시 원격 경로 paste), 로컬 세션이면 기존처럼 경로를 셸 이스케이프해
    /// paste한다. Swift 드롭 핸들러(3d ABI)가 fileURL 드롭 시 부른다. 설계: docs/ssh-integration.md §4.
    pub fn handleDroppedFiles(self: *AppSession, paths_nul: []const u8) void {
        if (!self.surface_initialized or paths_nul.len == 0) return;
        const rup = self.remoteUploadContext() orelse {
            self.pasteText(paths_nul, true); // 로컬 세션(또는 dest/ctl 못 구함): 기존 경로 paste
            return;
        };
        defer rup.deinit(self.allocator);

        var it = std.mem.splitScalar(u8, paths_nul, 0);
        var started: usize = 0;
        while (it.next()) |path| {
            if (path.len == 0) continue;
            self.startUpload(rup.ctl, rup.dest, path) catch continue; // 읽기/크기/spawn 실패는 그 파일만 스킵
            started += 1;
        }
        // 한 파일도 못 올렸으면 사용자가 빈손이 되지 않게 로컬 경로라도 paste(graceful).
        if (started == 0) self.pasteText(paths_nul, true);
    }

    /// 클립보드 이미지(Cmd+V)를 처리한다. maru ssh 원격 세션이면 control socket으로 업로드하고 완료 시
    /// 원격 경로를 paste한 뒤 true를 돌려준다(Swift는 더 안 함). 로컬이거나 업로드를 시작 못 하면 false
    /// (Swift가 기존 텍스트·URL paste 진행 — 로컬은 Claude 등이 OS 클립보드를 직접 읽으므로 maru 불개입).
    /// 파일 드롭과 달리 경로가 없어 바이트를 직접 받고 "pasted-<pid>-<N>.png" 이름을 붙인다 — pid로 앱 재시작 후
    /// cross-session 덮어쓰기를 막는다(카운터는 재시작 시 0이라 pid 없이는 다른 세션과 충돌). docs/ssh-integration.md §4.
    pub fn handleDroppedImage(self: *AppSession, bytes: []const u8) bool {
        if (!self.surface_initialized or bytes.len == 0) return false;
        if (bytes.len > maru.cli.ssh.max_upload_bytes) return false; // 16MB 초과 — 로컬 처리로 폴백
        const rup = self.remoteUploadContext() orelse return false; // 로컬 세션 — Swift가 기존 처리
        defer rup.deinit(self.allocator);

        // 클립보드 이미지엔 파일명이 없으므로 카운터로 고유 이름을 만든다(시간 API는 코어 결정성 위해 회피).
        self.upload_counter += 1;
        const name = std.fmt.allocPrint(self.allocator, "pasted-{d}-{d}.png", .{ std.c.getpid(), self.upload_counter }) catch return false;
        const bytes_owned = self.allocator.dupe(u8, bytes) catch {
            self.allocator.free(name);
            return false;
        };
        // name/bytes 소유를 startUploadBytes로 넘긴다(성공/실패 무관 그쪽이 책임).
        self.startUploadBytes(rup.ctl, rup.dest, name, bytes_owned) catch return false;
        return true;
    }

    /// maru ssh 원격 세션의 업로드 컨텍스트(목적지 + control socket 경로). 드롭(handleDroppedFiles)과
    /// paste(handleDroppedImage) 핸들러가 공유한다 — 둘 다 "activeSurface의 sshRemoteDest를 core_mutex(lockCore)
    /// 하에 복사 + HOME으로 controlSocketPath 계산"이 똑같이 필요해서 한 곳으로 모은다. 로컬 세션(sshRemoteDest
    /// 없음)·HOME 없음/빈 문자열·경로 계산 실패면 null(호출자가 각자 폴백). dest/ctl은 owned라 호출자가 deinit으로
    /// 해제한다(startUpload/startUploadBytes는 빌려 dupe한다).
    const RemoteUpload = struct {
        dest: []u8,
        ctl: []u8,
        fn deinit(self: RemoteUpload, allocator: std.mem.Allocator) void {
            allocator.free(self.dest);
            allocator.free(self.ctl);
        }
    };

    fn remoteUploadContext(self: *AppSession) ?RemoteUpload {
        const surface = self.activeSurface();
        surface.lockCore(self.io);
        const dest: ?[]u8 = if (surface.core.sshRemoteDest()) |d|
            (self.allocator.dupe(u8, d) catch null)
        else
            null;
        surface.unlockCore(self.io);
        const remote_dest = dest orelse return null; // 로컬 세션(또는 dupe OOM)

        // getenv는 HOME=""(빈 문자열)도 non-null로 주므로 빈 값을 가드한다(코드베이스 컨벤션) — 빈 HOME이면
        // controlSocketPath가 `/.cache/...` 같은 잘못된 경로를 만든다. optional 반환이라 errdefer가 안 먹어 명시 free.
        const home = std.c.getenv("HOME") orelse {
            self.allocator.free(remote_dest);
            return null;
        };
        const home_span = std.mem.span(home);
        if (home_span.len == 0) {
            self.allocator.free(remote_dest);
            return null;
        }
        const ctl = maru.cli.ssh.controlSocketPath(self.allocator, home_span, remote_dest) catch {
            self.allocator.free(remote_dest);
            return null;
        };
        return .{ .dest = remote_dest, .ctl = ctl };
    }

    /// 드롭 파일을 메인 스레드에서 읽고(io 필요) 크기를 검사한 뒤, 업로드는 startUploadBytes에 넘긴다.
    fn startUpload(self: *AppSession, ctl: []const u8, dest: []const u8, path: []const u8) !void {
        const file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        defer file.close(self.io);
        var rbuf: [64 * 1024]u8 = undefined;
        var reader = file.reader(self.io, &rbuf);
        const size = reader.getSize() catch return error.ReadFailed;
        if (size > maru.cli.ssh.max_upload_bytes) return error.FileTooLarge;
        const bytes = try reader.interface.allocRemaining(self.allocator, .limited(maru.cli.ssh.max_upload_bytes));
        const name = maru.cli.ssh.sanitizeDropFilename(self.allocator, path) catch |e| {
            self.allocator.free(bytes);
            return e;
        };
        try self.startUploadBytes(ctl, dest, name, bytes); // name/bytes 소유 이전
    }

    /// 업로드(ssh 자식 프로세스)를 백그라운드 스레드에 맡긴다. name/bytes는 호출자가 소유를 넘긴 owned
    /// 슬라이스다(이 함수가 책임 — 성공 시 job으로, 실패 시 free). ctl/dest는 빌려와 여기서 dupe한다.
    fn startUploadBytes(self: *AppSession, ctl: []const u8, dest: []const u8, name: []u8, bytes: []u8) !void {
        errdefer self.allocator.free(name);
        errdefer self.allocator.free(bytes);
        const ctl_owned = try self.allocator.dupe(u8, ctl);
        errdefer self.allocator.free(ctl_owned);
        const dest_owned = try self.allocator.dupe(u8, dest);
        errdefer self.allocator.free(dest_owned);

        const job = try self.allocator.create(UploadJob);
        errdefer self.allocator.destroy(job);
        job.* = .{ .session = self, .ctl = ctl_owned, .dest = dest_owned, .name = name, .bytes = bytes };

        self.upload_mutex.lockUncancelable(self.io);
        self.upload_inflight += 1;
        self.upload_mutex.unlock(self.io);

        const thread = std.Thread.spawn(.{}, uploadWorker, .{job}) catch {
            self.upload_mutex.lockUncancelable(self.io);
            self.upload_inflight -= 1;
            self.upload_mutex.unlock(self.io);
            return error.SpawnFailed; // job·owned는 위 errdefer들이 해제
        };
        thread.detach();
    }

    /// 백그라운드 스레드 엔트리: bytes를 ssh로 업로드하고 결과(원격 경로)를 mutex 하에 큐에 넣는다. job과
    /// owned 입력을 전부 해제한다(소유권을 넘겨받았다). io를 안 만지므로(ssh_upload는 posix fork+pipe만 씀 —
    /// std.process.Child가 0.16에서 io 기반이라 회피) 스레드 안전하다.
    fn uploadWorker(job: *UploadJob) void {
        const self = job.session;
        const result: ?[]u8 = ssh_upload.uploadBytes(self.allocator, job.ctl, job.dest, job.name, job.bytes) catch null;
        self.allocator.free(job.ctl);
        self.allocator.free(job.dest);
        self.allocator.free(job.name);
        self.allocator.free(job.bytes);
        self.upload_mutex.lockUncancelable(self.io);
        if (result) |r| {
            self.upload_results.append(self.allocator, r) catch self.allocator.free(r);
        }
        self.upload_inflight -= 1;
        self.upload_mutex.unlock(self.io);
        self.allocator.destroy(job);
    }

    /// 메인 tick: 완료된 업로드의 원격 경로를 paste 큐로 흘려보낸다(core 접근=메인 전용이라 여기서 paste).
    fn drainUploadResults(self: *AppSession) void {
        self.upload_mutex.lockUncancelable(self.io);
        const results = self.upload_results.toOwnedSlice(self.allocator) catch {
            self.upload_mutex.unlock(self.io);
            return;
        };
        self.upload_mutex.unlock(self.io);
        defer self.allocator.free(results);
        for (results) |path| {
            self.pasteText(path, false); // 원격 절대경로(sanitize되어 공백 없음) raw paste
            self.allocator.free(path);
        }
    }

    /// 첫 tick에서 1회: 인앱 새 버전 안내 백그라운드 체크를 띄운다(config notifications.update-check로 끔).
    /// UI를 안 멈추게 별도 스레드에서 GitHub releases/latest를 받는다. upload 패턴과 동일하게 inflight를
    /// 올리고 detach하며, deinit이 0까지 기다린다(self use-after-free 가드).
    fn startUpdateCheck(self: *AppSession) void {
        if (builtin.is_test) return; // 계약 테스트(tick 구동)가 네트워크(curl)를 타지 않게 한다 — 순수 로직은 update_check.zig 단위 테스트가 검증
        if (!self.loaded_config.config.notifications.update_check) return;
        // build.zig.zon .version이 0.0.0 placeholder인 빌드는 모든 실제 release보다 낮아 매 실행 거짓 알림을
        // 낸다(isNewer("0.0.0", any real tag)=true). 버전이 박힌 릴리스 빌드에서만 체크한다(distribution.md 버전 정책).
        if (std.mem.eql(u8, build_options.version, "0.0.0")) return;
        // handle을 보관해 deinit이 join한다(busy-spin 제거 — CPU 0, OS 대기). spawn 실패면 null로 둔다.
        self.update_thread = std.Thread.spawn(.{}, updateCheckWorker, .{self}) catch null;
    }

    /// 백그라운드 스레드: latest tag를 받아 현재 버전(build_options.version)보다 높으면 mutex 하에 태그를
    /// 슬롯에 담는다. self.allocator는 메인과 경합하므로 쓰지 않고 page_allocator(thread-safe)로 받는다.
    /// core/알림은 건드리지 않는다(메인 전용) — 결과 전달은 메인 tick의 drainUpdateCheck가 한다.
    fn updateCheckWorker(self: *AppSession) void {
        // self.allocator는 smp_allocator(thread-safe, app_host_abi.zig)라 백그라운드에서 그대로 쓴다
        // — uploadWorker도 동일. (이전 page_allocator 특수화는 "self.allocator가 메인과 경합"이라는 잘못된 전제였다.)
        const tag = update_check.fetchLatestTagAlloc(self.allocator, update_repo) orelse {
            self.update_ready.store(true, .release); // 결과 없음(네트워크 실패 등)도 '처리 완료' 신호 — 메인이 무동작 판정
            return;
        };
        defer self.allocator.free(tag);
        if (update_check.isNewer(build_options.version, tag)) {
            const n = @min(tag.len, self.update_tag_buf.len);
            @memcpy(self.update_tag_buf[0..n], tag[0..n]); // ready store(release) 전에 채워 publish
            self.update_tag_len = n;
        }
        self.update_ready.store(true, .release); // 메인 tick의 acquire load와 happens-before — 슬롯을 락 없이 안전 공개
    }

    /// 메인 tick: 새 버전 태그가 잡혔으면(백그라운드가 채움) 1회 알림을 띄운다. brew 배포라 업그레이드는
    /// 자동 실행하지 않고 안내만 한다(distribution.md). pushNotificationHistory는 메인 전용이라 여기서 호출.
    fn drainUpdateCheck(self: *AppSession) void {
        if (self.update_notified) return;
        if (!self.update_ready.load(.acquire)) return; // 결과 전엔 atomic load만 — 매 tick mutex lock 회피
        // ready(release) 이후라 worker가 채운 슬롯을 락 없이 안전하게 읽는다(happens-before; worker는 store 후 수렴).
        const len = self.update_tag_len;
        if (len == 0) { // 새 버전 없음/체크 실패 — 한 번만 처리하고 끝낸다
            self.update_notified = true;
            return;
        }
        var title_buf: [160]u8 = undefined;
        const title = std.fmt.bufPrint(&title_buf, "새 버전 {s} 사용 가능", .{self.update_tag_buf[0..len]}) catch "새 버전 사용 가능";
        // push가 성공했을 때만 처리 완료로 표시한다 — 일시적 할당 실패면 update_notified를 남겨 다음 tick에
        // 재시도(알림 유실 방지). 안내 문구는 설치 출처에 맞춘다(아래 updateUpgradeHint).
        if (self.pushNotificationHistory(title, self.updateUpgradeHint(), 0, false)) self.update_notified = true;
    }

    /// 설치 출처별 업그레이드 안내 문구(distribution.md). 실행 파일 경로가 brew(Cellar/homebrew)면 brew
    /// 명령을, 그 외(소스 빌드·~/.local/bin·직접 다운로드)면 일반 안내를 준다 — 비-brew 설치에 brew 명령을
    /// 보이지 않는다(distribution.md "brew가 아닌데 brew 명령을 채워주면 안 된다"). 경로 해석 실패면 일반 안내.
    fn updateUpgradeHint(self: *AppSession) []const u8 {
        const path = std.process.executablePathAlloc(self.io, self.allocator) catch return "GitHub 릴리스에서 최신 버전을 받으세요";
        defer self.allocator.free(path);
        if (std.mem.indexOf(u8, path, "/Cellar/") != null or std.mem.indexOf(u8, path, "/homebrew/") != null)
            return "brew upgrade maru 로 업데이트하세요";
        return "GitHub 릴리스에서 최신 버전을 받으세요";
    }

    /// pending_paste가 다 빠진 뒤 새로 쌓기 시작할 때만 대상 surface를 현재 활성으로 다시 고정한다.
    /// 잔여가 남아 있으면 대상을 바꾸지 않아, 이미 어떤 surface로 가던 paste/IME 확정 바이트가 탭/pane
    /// 전환으로 다른 surface에 섞여 들어가지 않는다(원래 대상 우선; flushPendingPaste가 이 대상으로 쓴다).
    fn pendingPasteRetarget(self: *AppSession) void {
        if (self.pending_paste_offset >= self.pending_paste.items.len) {
            self.pending_paste.clearRetainingCapacity();
            self.pending_paste_offset = 0;
            self.pending_paste_target = self.activeSurface().id;
        }
    }

    /// pending paste를 지금 쓸 수 있는 만큼 non-blocking으로 흘려보낸다(0이 나오면 다음 tick).
    fn flushPendingPaste(self: *AppSession) void {
        while (self.pending_paste_offset < self.pending_paste.items.len) {
            const remaining = self.pending_paste.items[self.pending_paste_offset..];
            const written = self.runtime.writeInputNonBlocking(self.pending_paste_target, remaining) catch {
                // 세션 종료 등 — 잔여는 버린다(다시 쓸 수 없는 대상).
                self.pending_paste.clearRetainingCapacity();
                self.pending_paste_offset = 0;
                return;
            };
            if (written == 0) return; // PTY 버퍼가 찼다 — 다음 tick에 이어서
            self.pending_paste_offset += written;
        }
        self.pending_paste.clearRetainingCapacity();
        self.pending_paste_offset = 0;
    }

    /// Cmd+hover 갱신. cmd_held가 아니거나 URL이 아니면 hover를 해제한다. URL 위면 밑줄 범위를
    /// 저장하고 true를 돌려준다 — Swift가 이 값으로 마우스 커서(pointingHand)를 정한다.
    /// 마우스 호버 위치의 커서 종류를 판정하고(Swift가 NSCursor로 세움), 부수적으로 사이드바 슬롯·pane 탭 호버·
    /// Cmd+hover URL 밑줄을 갱신한다. 영역 우선순위는 마우스 클릭(mouse down)과 같다: 사이드바 → 탭 바 → divider
    /// → 터미널. 사이드바·탭 바=arrow(default), divider=resize(좌우 split=↔, 상하 split=↕), 터미널=iBeam(text),
    /// Cmd+hover URL=pointingHand(link). 창 밖 sentinel(-1,-1)이면 inSidebar=false→터미널 경로로 호버 해제.
    /// 마우스 수식키 비트(xterm 규약: shift=4, alt/meta=8, ctrl=16, command=32)가 config `input.url-click-modifier`와
    /// 일치하는지 — URL hover 밑줄·클릭 열기의 **단일 판정**(Swift는 NSEvent 수식키를 이 비트로 변환만 한다). modifier
    /// 정책을 Zig가 소유해 이식(Linux/Win)·테스트가 한 곳에서 된다. command 비트(32)는 hover/url_at 전용 인코딩이다
    /// (mouse reporting ABI는 command를 안 싣지만 — 터미널 앱엔 Cmd를 리포트 안 함 — URL 판정엔 필요).
    fn urlModifierHeld(self: *const AppSession, mods: i32) bool {
        const mask: i32 = switch (self.loaded_config.config.input.url_click_modifier) {
            .command => 32,
            .control => 16,
            .alt => 8,
            .shift => 4,
        };
        return (mods & mask) != 0;
    }

    /// config `input.link-detection`을 자동 감지 범위(scopes)로 변환한다. osc8-only=자동 감지 끔(OSC 8 명시 링크만),
    /// web=http(s)만(이전 동작), full=추가 스킴+절대/홈/상대/bare 경로. hover·클릭이 매 호출 현재 config를 넘겨
    /// reload-safe(코어는 토글 상태를 안 든다 — word_separators 주입과 동형). 단일 출처: docs/link-detection.md.
    fn linkScopesFromConfig(self: *const AppSession) terminal.LinkScopes {
        return switch (self.loaded_config.config.input.link_detection) {
            .osc8_only => terminal.link_scopes_none,
            .web => terminal.link_scopes_web,
            .full => terminal.link_scopes_full,
        };
    }

    pub fn hoverCursor(self: *AppSession, x_px: f64, y_px: f64, mods: i32) CursorKind {
        if (!self.surface_initialized) return .text;
        // 닫기 확인 모달 중엔 호버 부수효과(사이드바/탭/◧ 호버 강조·스크롤바 hover·URL 밑줄)를 멈추고 화살표 커서만
        // 둔다 — 안 그러면 모달 뒤 버튼/슬롯이 호버에 반응해 강조되며(모달 위로 비침) UI가 깨져 보인다(모달 게이트).
        if (self.chrome_host.confirm.open) return .default;
        // 알림 센터 패널이 열려 있으면 호버를 패널에 라우팅한다(최상위 모달 — 사이드바/탭/divider/터미널보다 먼저, 클릭
        // 라우팅 mouse()의 게이트와 짝). 카드/✕ 위면 그 카드를 hovered로 강조(tab_hover_bg) + pointingHand, 헤더 액션
        // 버튼은 강조 없이 pointingHand, 그 외(제목·빈 여백·패널 밖)는 hovered 해제 + default. 모달이라 뒤 사이드바/탭/
        // 스크롤바/URL 호버는 모두 끈다(stale 강조가 패널 뒤로 비치지 않게 — confirm 게이트와 같은 규율, clearAllHover 단일 출처).
        if (self.chrome_host.notifications.open) {
            self.clearAllHover();
            // coarse 게이트: 직전 프레임 패널 rect 밖이면(대부분의 이동) 무거운 item 빌드 없이 바로 호버 해제. rect는
            // hitTest의 bounds와 같은 content rect라 "밖 ⇒ hitTest=null ⇒ hovered=null/default"와 동치다. rect 미캐시
            // (오픈 직후 첫 이동)면 게이트를 건너뛰고 아래 정확 판정으로 떨어진다(빌드).
            if (self.notif_panel_rect) |pr| {
                const inside = x_px >= @as(f64, @floatFromInt(pr.x)) and x_px < @as(f64, @floatFromInt(pr.x + @as(i32, @intCast(pr.w)))) and
                    y_px >= @as(f64, @floatFromInt(pr.y)) and y_px < @as(f64, @floatFromInt(pr.y + @as(i32, @intCast(pr.h))));
                if (!inside) {
                    self.setHoveredNotification(null);
                    return .default;
                }
            }
            const hit = self.notificationHitAt(x_px, y_px); // 빌드+hitTest 단일 출처(클릭 경로와 공유)
            const hovered_card: ?usize = if (hit) |h| switch (h) {
                .card => |idx| idx,
                .close => |idx| idx, // ✕ 위에서도 같은 행이라 그 카드 강조를 유지
                else => null,
            } else null;
            self.setHoveredNotification(hovered_card);
            return switch (hit orelse .background) {
                .card, .close, .mark_all_read, .clear_all => .link, // 클릭 가능 → pointingHand
                .background => .default, // 제목·빈 여백·패널 밖
            };
        }
        // 스크롤바 hover 강조를 매 이동 갱신한다(어느 zone이든 — 아래 early return 전에 항상). scrollbarGrabAt이
        // 영역+스크롤백 유무를 본다(우측 얇은 띠). 커서 종류는 안 바꾼다(얇은 띠라 iBeam 깜빡임 방지) — 강조만.
        self.setScrollbarHovered(self.scrollbarGrabAt(x_px, y_px) != null);
        // 접힘 펼치기 토글(◧, 신호등 옆) 호버 — 접힘 시 사이드바 폭 0이라 아래 inSidebar(헤더 아이콘) 경로가 안 타고,
        // resize-edge가 x≈0을 잘못 잡을 수 있어 **먼저** 본다. 토글 위면 호버 배경을 켜고 pointingHand(클릭 가능).
        // 토글 밖이면 끄고 아래 일반 경로로 흐른다. mouse down hit-test(collapsedToggleRect)와 같은 rect로 일치.
        if (self.sidebar_collapsed) {
            // 접힘 알림 종(◧ 오른쪽) 호버 — 클릭 가능(알림 패널). ◧보다 먼저(별개 영역, 클릭 우선순위와 일치).
            if (self.collapsedNotificationRect()) |r| {
                const rx: f64 = @floatFromInt(r.x);
                if (x_px >= rx and x_px < rx + @as(f64, @floatFromInt(r.w)) and
                    y_px >= 0 and y_px < @as(f64, @floatFromInt(r.h)))
                {
                    self.setHoveredCollapsedToggle(false); // 종 위면 ◧ 호버는 끈다
                    self.setHoveredSlot(null);
                    self.setHoveredTab(null);
                    self.clearHoverUrlAnchor();
                    return .link;
                }
            }
            if (self.collapsedToggleRect()) |r| {
                const rx: f64 = @floatFromInt(r.x);
                const ry: f64 = @floatFromInt(r.y);
                if (x_px >= rx and x_px < rx + @as(f64, @floatFromInt(r.w)) and
                    y_px >= ry and y_px < ry + @as(f64, @floatFromInt(r.h)))
                {
                    self.setHoveredCollapsedToggle(true);
                    self.setHoveredSlot(null);
                    self.setHoveredTab(null);
                    self.clearHoverUrlAnchor();
                    return .link;
                }
            }
            self.setHoveredCollapsedToggle(false);
        }
        // 사이드바 우측 경계(폭 조절) 위면 리사이즈 커서 — 사이드바/터미널보다 먼저(경계는 둘 사이 밴드).
        if (chrome.components.sidebar.onResizeEdge(x_px, self.sidebar_width_px, if (self.cell_width_px > 0) self.cell_width_px else placeholder_cell_width_px)) {
            self.setHoveredSlot(null);
            self.setHoveredTab(null);
            self.setHoveredHeaderRegion(.none);
            self.clearHoverUrlAnchor();
            return .resize_h; // 좌우로 끄는 세로 경계 ↔
        }
        // 사이드바 영역 호버는 슬롯(또는 상단 헤더)을 추적한다(터미널 URL 호버 아님).
        if (self.inSidebar(x_px)) {
            // 상단 헤더(검색바·아이콘) 영역이면 슬롯 호버 해제 + 아이콘은 pointingHand·검색 영역은 I-beam.
            const region = chrome.components.sidebar.headerHit(x_px, y_px, self.sidebar_width_px, self.cell_width_px, self.cell_height_px, self.sidebar_header_height_px);
            self.setHoveredHeaderRegion(region); // 아이콘이면 뒤에 호버 배경(검색·none이면 지움)
            if (region != .none) {
                self.setHoveredSlot(null);
                self.setHoveredTab(null);
                self.clearHoverUrlAnchor();
                return if (region == .search) .text else .link;
            }
            self.setHoveredSlot(self.sidebarSlotAt(y_px));
            self.setHoveredTab(null); // 사이드바로 가면 pane 탭 호버 해제(stale ✕ 방지)
            self.clearHoverUrlAnchor();
            return if (self.hovered_slot != null) .link else .default; // 워크스페이스 슬롯은 클릭(전환) → pointingHand, 빈 영역은 arrow
        }
        self.setHoveredSlot(null); // 터미널 영역으로 나가면 사이드바 호버 해제
        self.setHoveredHeaderRegion(.none); // 사이드바 밖 → 헤더 아이콘 호버 배경 지움
        // 어느 pane의 탭 바 위면 호버 탭을 갱신(✕ 표시). 바 위면 URL/divider 아니므로 밑줄 해제하고 arrow.
        const bar_hover = self.updateHoveredTab(x_px, y_px);
        if (bar_hover != .none) {
            self.clearHoverUrlAnchor();
            // 좌측 grip+라벨 = 드래그 손잡이 → openHand(grab), 그 외 탭/‹›/+/pane 포커스 = 클릭 가능 → pointingHand.
            return if (bar_hover == .grip) .grab else .link;
        }
        // divider 밴드 위면 리사이즈 커서(클릭과 같은 dividerAtPoint — 탭 바 다음 순서). 단일 panel이면 null.
        if (self.dividerAtPoint(x_px, y_px)) |hit| {
            self.clearHoverUrlAnchor();
            return switch (hit.seg.orientation) {
                .vertical_line => .resize_h, // 세로 divider — 좌우로 끈다
                .horizontal_line => .resize_v, // 가로 divider — 위아래로 끈다
            };
        }
        // 터미널 영역: (config 수식키)+hover URL이면 link(pointingHand), 아니면 text(iBeam).
        var next: ?terminal.SelectionPoint = null;
        if (self.urlModifierHeld(mods)) {
            if (self.pxToCell(x_px, y_px)) |cell| {
                const s = self.activeSurface();
                // URL이면 그 시작 셀의 절대 좌표를 저장한다(뷰포트 좌표가 아님) — 스크롤/출력으로
                // 내용이 움직여도 밑줄이 내용을 따라가고, 좁아진 폭에서도 매 frame 뷰포트로 다시
                // 클립(아래 hoverLinkSpan)되므로 stale·OOB가 안 생긴다. 분류(wordIsUrl)가 스크롤백을 읽으므로
                // 락 아래에서 한다 — urlAt 클릭 경로와 대칭(reader의 evict/realloc race 방지). hover는 매
                // mouse-move라 클릭보다 빈번해 노출이 더 크다(focusedTermCwd/copyText와 같은 규율).
                s.lockCore(self.io);
                const anchor = s.core.urlAnchorAt(cell.row, cell.col, self.linkScopesFromConfig());
                s.unlockCore(self.io);
                if (anchor) |a| next = a;
            }
        }
        const changed = !pointEql(self.hover_url_anchor, next);
        self.hover_url_anchor = next;
        if (changed) self.metal_dirty = true; // 밑줄이 생기거나 사라지면 다시 그린다
        return if (next != null) .link else .text;
    }

    /// 떠 있던 Cmd+hover URL 밑줄 anchor를 해제하고 변경 시 redraw 표시. hoverCursor의 여러 분기(사이드바/탭
    /// 바/divider)가 터미널 URL이 아닌 영역으로 갈 때 공유한다.
    fn clearHoverUrlAnchor(self: *AppSession) void {
        if (self.hover_url_anchor != null) {
            self.hover_url_anchor = null;
            self.metal_dirty = true;
        }
    }

    /// hover URL의 현재 뷰포트 밑줄 범위. 매 frame 절대 좌표 anchor에서 다시 계산해 클립하므로
    /// 스크롤·출력·resize 후에도 항상 현재 폭/위치에 맞는다(stale 좌표 OOB 차단).
    pub fn hoverLinkSpan(self: *AppSession) ?terminal.SelectionSpan {
        const anchor = self.hover_url_anchor orelse return null;
        return self.activeSurface().core.urlSpanAtAbs(anchor);
    }

    fn pointEql(a: ?terminal.SelectionPoint, b: ?terminal.SelectionPoint) bool {
        if (a == null and b == null) return true;
        if (a == null or b == null) return false;
        return std.meta.eql(a.?, b.?);
    }

    /// Cmd+클릭 위치의 링크(없으면 빈 슬라이스). Swift가 NSWorkspace로 연다 — 링크 인식(단어 경계, soft-wrap
    /// 이어 붙임, 스킴/파일 경로 분류, 끝 문장부호 다듬기, file_path resolve+존재검증)은 core가 소유한다.
    pub fn urlAt(self: *AppSession, x_px: f64, y_px: f64, mods: i32) []const u8 {
        self.url_kind = .url; // 빈 반환 경로에서 이전 클릭의 kind가 남지 않게 리셋(ABI out_kind는 len>0일 때만 유효하나 방어)
        if (!self.surface_initialized) return &.{};
        // config 수식키가 안 눌렸으면 URL을 안 연다(빈 슬라이스 → Swift는 일반 클릭으로 처리). hover 밑줄과 같은
        // urlModifierHeld 단일 판정이라 "밑줄 보이는 키 = 열리는 키"가 항상 일치한다.
        if (!self.urlModifierHeld(mods)) return &.{};
        // 스크린→셀 변환은 pxToCell 단일 출처를 쓴다(사이드바 offset 차감 포함) — 별도 변환을 두면
        // 사이드바 폭만큼 어긋난 셀에서 URL을 찾는다(직접 x/cw로 계산하던 버그를 여기로 일원화해 고침).
        const cell = self.pxToCell(x_px, y_px) orelse return &.{};
        if (self.url_buffer.len > 0) {
            self.allocator.free(self.url_buffer);
            self.url_buffer = &.{};
        }
        // url=웹/스킴(Swift가 URL(string:)으로), file_path=resolve된 절대 경로(URL(fileURLWithPath:)). kind는 url_kind에
        // 저장해 ABI url_at이 out_kind로 Swift에 넘긴다. file_path 미존재/cwd 불명이면 extractUrlAt이 null(빈 클릭).
        //
        // **락**: extractUrlAt은 스크롤백을 읽고, file_path resolve(resolveClickedPath)는 core.cwd(currentCwd)를
        // 읽는다 — 둘 다 reader 스레드가 core_mutex 아래 mutate한다(OSC 7로 cwd free+realloc, 스크롤백 evict). 락
        // 없이 읽으면 torn read·use-after-free(focusedTermCwd가 같은 cwd 위험을 락으로 고친 선례 — copyText도 동일).
        // 그래서 lockCore 아래에서 추출하고, 결과 텍스트는 owned라 unlock 후 안전. 존재검증 access(F_OK)는 빠른
        // syscall이라 락 아래 허용한다(copyText가 무거운 extractSelection을 락 아래 하는 것과 같은 트레이드오프).
        const s = self.activeSurface();
        s.lockCore(self.io);
        const ext = s.core.extractUrlAt(self.allocator, cell.row, cell.col, self.linkScopesFromConfig()) catch null;
        s.unlockCore(self.io);
        const e = ext orelse return &.{};
        self.url_buffer = e.text;
        self.url_kind = e.kind;
        return self.url_buffer;
    }

    /// 선택 텍스트를 추출해 내부 버퍼로 돌려준다(없으면 빈 슬라이스). Swift가 NSPasteboard에 쓴다.
    pub fn copyText(self: *AppSession) []const u8 {
        if (!self.surface_initialized) return &.{};
        if (self.copy_buffer.len > 0) {
            self.allocator.free(self.copy_buffer);
            self.copy_buffer = &.{};
        }
        // extractSelection은 선택 + 스크롤백을 읽는다 — 락 아래(docs/io-render-threading.md §9.1). full (a)에서 선택이
        // 이제 reader 스레드가 async로 mutate하므로, 락 없이 읽으면 드래그-선택 직후 Cmd+C가 torn/stale 선택을 본다
        // (렌더 경로는 이미 락 아래 selectionViewportSpan을 읽는다 — copyText만 노출됐던 갭). 추출 바이트는 owned이라 unlock 후 안전.
        const s = self.activeSurface();
        s.lockCore(self.io);
        const extracted = s.core.extractSelection(self.allocator) catch null;
        s.unlockCore(self.io);
        self.copy_buffer = extracted orelse return &.{};
        return self.copy_buffer;
    }

    /// OSC 52 클립보드 쓰기 요청을 내부 버퍼로 돌려준다(없으면 빈 슬라이스). Swift가 NSPasteboard에 쓴다.
    /// **정책**(terminal-compatibility-policy.md §OSC52, 사용자 결정 2026-06-20): write는 기본 `allow` — 로컬
    /// 단일 사용자 데스크톱 터미널이라 트래킹 앱의 드래그 복사를 시스템 클립보드에 반영한다(iTerm2/Ghostty도 유사).
    /// **read**는 클립보드 탈취 방지로 계속 deny한다 — core가 `?` 쿼리에 응답하지 않아 read 요청은 여기 안 온다.
    /// 코어 pending을 비워(한 번 쓰고 소비) 같은 데이터가 다음 tick에 또 쓰이지 않게 한다. ask(요청별 확인 UI)는 후속.
    pub fn pendingClipboard(self: *AppSession) []const u8 {
        if (!self.surface_initialized) return &.{};
        const pending = self.activeSurface().core.pendingClipboardWrite();
        if (pending.len == 0) return &.{};
        if (self.clipboard_out_buffer.len > 0) {
            self.allocator.free(self.clipboard_out_buffer);
            self.clipboard_out_buffer = &.{};
        }
        self.clipboard_out_buffer = self.allocator.dupe(u8, pending) catch return &.{};
        self.activeSurface().core.clearClipboardWrite();
        return self.clipboard_out_buffer;
    }

    /// OSC 52 읽기(`?` 쿼리)가 대기 중이고 정책(osc52.read)이 allow면 true — Swift가 시스템 클립보드를 읽어
    /// provideClipboardRead로 돌려준다. **정책 게이트는 여기**다(write의 platform 게이트와 대칭): 코어는 쿼리만
    /// 파싱하고 pending을 세우며, deny여도 pending을 소비(clear)하되 클립보드는 읽지 않는다(allow일 때만 Swift가 읽음
    /// = 탈취 방지). target(Pc)은 응답 echo용으로 캡처한다. 코어 읽기·clear는 락 아래(리더 경합 방지). (F2-6)
    pub fn takeClipboardReadRequest(self: *AppSession) bool {
        if (!self.surface_initialized) return false;
        const s = self.activeSurface();
        s.lockCore(self.io);
        const pending = s.core.clipboardReadPending();
        if (pending) {
            self.clipboard_read_target_buf.clearRetainingCapacity();
            self.clipboard_read_target_buf.appendSlice(self.allocator, s.core.clipboardReadTarget()) catch {};
            s.core.clearClipboardRead(); // 소비(allow/deny 무관) — 다음 tick에 또 트리거되지 않게
        }
        s.unlockCore(self.io);
        if (!pending) return false;
        return self.loaded_config.config.osc52.read == .allow; // deny면 클립보드 안 읽음
    }

    /// Swift가 읽은 시스템 클립보드 바이트를 base64 OSC 52 응답(`ESC ] 52 ; <Pc> ; <base64> ST`)으로 만들어 요청한
    /// surface의 PTY로 비차단 전송한다(paste FIFO 재사용 — 전송 순서·#10 데드락 회피). target은 직전
    /// takeClipboardReadRequest가 캡처한 Pc(빈 값은 `c`). 과대 클립보드는 거부한다(폭주 방어선, write 상한과 동일). (F2-6)
    pub fn provideClipboardRead(self: *AppSession, bytes: []const u8) void {
        if (!self.surface_initialized) return;
        if (bytes.len > max_clipboard_read_bytes) return; // 과대 거부(폭주 방어선)
        const resp = self.formatOsc52ReadResponse(self.clipboard_read_target_buf.items, bytes) orelse return;
        defer self.allocator.free(resp);
        // 요청 surface PTY로 비차단 전송(paste FIFO 재사용 — 순서·#10 데드락 회피). 응답은 program stdin에서 읽힌다.
        self.pendingPasteRetarget();
        self.pending_paste.appendSlice(self.allocator, resp) catch return;
        self.flushPendingPaste();
    }

    /// 클립보드 바이트를 OSC 52 읽기 응답(`ESC ] 52 ; <Pc> ; <base64> ST`)으로 인코딩한다(owned, 호출자 free).
    /// target(Pc) 빈 값은 `c`(클립보드)로 채운다. 실패(OOM) 시 null. 순수 함수라 포맷을 단위 테스트로 고정(F2-6).
    fn formatOsc52ReadResponse(self: *AppSession, target: []const u8, bytes: []const u8) ?[]u8 {
        const tgt: []const u8 = if (target.len == 0) "c" else target;
        const enc = std.base64.standard.Encoder;
        const b64_len = enc.calcSize(bytes.len);
        const resp_len = 2 + 3 + tgt.len + 1 + b64_len + 2; // ESC ] | "52;" | Pc | ";" | base64 | ESC \
        const buf = self.allocator.alloc(u8, resp_len) catch return null;
        var i: usize = 0;
        buf[i] = 0x1b;
        i += 1;
        buf[i] = ']';
        i += 1;
        @memcpy(buf[i..][0..3], "52;");
        i += 3;
        @memcpy(buf[i..][0..tgt.len], tgt);
        i += tgt.len;
        buf[i] = ';';
        i += 1;
        _ = enc.encode(buf[i..][0..b64_len], bytes);
        i += b64_len;
        buf[i] = 0x1b;
        i += 1;
        buf[i] = '\\';
        i += 1;
        return buf;
    }

    /// OSC 9/777 데스크톱 알림 pending(title, body)을 내부 버퍼로 돌려준다(없으면 null). Swift가
    /// UNUserNotificationCenter로 띄운다. 코어 pending을 비워(한 번 쓰고 소비) 다음 tick에 같은 알림이 또
    /// 뜨지 않게 한다. 알림은 OS 리소스라 native(Swift)만 띄우고 코어/여기는 데이터만 넘긴다(경계). 클립보드와
    /// 달리 env 게이트 없음 — 알림은 OS authorization이 게이트하는 저위험 표면(iTerm2/Ghostty도 기본 허용).
    /// foreground_banner: 앱이 전면(willPresent 호출)일 때도 OS 배너로 띄울지. 에이전트 완료는 "지금 안 보는 탭"
    /// (enqueue 게이트 !is_current)이라 true — 전면이어도 배너로 알려야 유용. OSC 9/777은 활성(보이는) surface가
    /// 보낸 것이라 사용자가 이미 그 화면을 보고 있을 가능성이 커 false — 전면이면 배너 없이 알림 센터 목록에만 남긴다
    /// (자기 화면 알림 노이즈 억제). "전면에서 배너를 띄울지"는 알림 종류가 결정하는 정책이라 Zig가 정하고, 실제
    /// 표시 스타일 적용은 Swift willPresent(OS 표면)가 한다(경계).
    /// pendingNotification/drainOscNotificationFrom 공유 반환 타입 — Zig는 동일 필드 익명 struct도 서로 다른 타입으로
    /// 봐서 두 함수가 같은 익명 struct를 못 쓰므로 named로 둔다. surface_id로 클릭 점프(activateSurfaceById), foreground_banner는
    /// 전면 배너 여부(에이전트=1, OSC=0). Swift ABI 래퍼(app_host_abi.zig)가 필드를 out 인자로 꺼낸다.
    pub const PendingNotification = struct { title: []const u8, body: []const u8, surface_id: u64, foreground_banner: bool };

    pub fn pendingNotification(self: *AppSession) ?PendingNotification {
        // 에이전트 완료 알림(running→idle)을 OSC 9/777보다 먼저 드레인한다 — 큐의 owned 버퍼를 그대로 반환하고
        // 직전 반환 버퍼는 여기서 해제(다음 pendingNotification/destroy까지 유효 규약은 동일).
        if (self.agent_notifications.items.len > 0) {
            const n = self.agent_notifications.orderedRemove(0);
            if (self.notification_title_out.len > 0) self.allocator.free(self.notification_title_out);
            if (self.notification_body_out.len > 0) self.allocator.free(self.notification_body_out);
            self.notification_title_out = n.title;
            self.notification_body_out = n.body;
            // 인앱 히스토리에도 보관(dupe — 위 버퍼는 OS 배너용으로 move됐다). 에이전트 완료라 is_agent=true.
            _ = self.pushNotificationHistory(self.notification_title_out, self.notification_body_out, n.surface_id, true);
            return .{ .title = self.notification_title_out, .body = self.notification_body_out, .surface_id = n.surface_id, .foreground_banner = true };
        }
        if (!self.surface_initialized) return null;
        // OSC 9/777: 발신 surface의 코어가 자기 시퀀스를 파싱한다(reader 스레드가 core_mutex 아래 적용). 예전엔
        // activeSurface().core만 drain해 **비활성 pane/Term이 보낸 OSC 알림이 영영 안 나왔다** — 모든 Term의 코어를
        // 훑어 첫 pending을 그 surface.id로 실어 보낸다(클릭이 발신 Term으로 점프, activateSurfaceById). 한 호출에
        // 하나씩 drain하므로 여러 surface가 동시에 pending이면 다음 tick들에 이어 나온다(에이전트 큐 drain과 같은 결).
        // 전면 배너 결정용: 사용자가 지금 그 안에 있는 Term(포커스 창의 활성 탭·pane·Term). 발신 Term이 이것이면 OSC
        // 배너를 전면에서 억제(목록만), 그 외 background pane/가로탭/비활성 탭이면 전면에서도 배너(에이전트 is_current 대칭).
        const focused_term: ?*Term = if (self.window_focused) self.activeTab().activePane().activeTerm() else null;
        for (self.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (!term.rt.live_initialized or term.rt.terminated) continue; // 종료(미reap) Term은 건너뜀(dispatchBell과 동형)
                    if (self.drainOscNotificationFrom(term, focused_term)) |n| return n;
                }
            }
        }
        return null;
    }

    /// 한 Term의 코어에 쌓인 OSC 9/777 데스크톱 알림을 drain한다(있으면 그 알림, 없으면 null). reader 스레드가
    /// core_mutex 아래 notification_pending/title/body를 세우므로 **lockCore 아래에서 읽고 owned 버퍼로 복사**한다
    /// (pendingNotification 반환 슬라이스는 코어 메모리를 가리켜, 락 없이 들고 dupe하면 reader가 clearNotification으로
    /// 비우는 사이 torn read가 난다 — focusedTermCwd와 같은 함정). 반환 슬라이스는 self.notification_*_out 소유라
    /// 락 밖에서도 유효하다. config notifications.osc=false면 pending만 비우고(다음 tick 재발화 방지) null — 호출 루프가
    /// 다음 surface로 넘어가 모든 pending을 정리한다(종류별 on/off를 발화 지점에서 단일하게 막는 정책, 에이전트와 대칭).
    /// dupe 실패도 pending을 비우고 null(best-effort). 인앱 히스토리에도 dupe 보관한다(OSC라 is_agent=false).
    /// `focused_term`=지금 보고 있는 그 Term(없으면 null=창 비포커스) — 발신 Term이 이것이면 foreground_banner=false
    /// (전면에서 자기 화면 노이즈 억제, 목록만), 그 외면 true(전면이어도 배너). 에이전트 완료 is_current 게이트와 대칭.
    fn drainOscNotificationFrom(self: *AppSession, term: *Term, focused_term: ?*Term) ?PendingNotification {
        term.surface.lockCore(self.io);
        defer term.surface.unlockCore(self.io);
        const pending = term.surface.core.pendingNotification() orelse return null;
        if (!self.loaded_config.config.notifications.osc) {
            term.surface.core.clearNotification();
            return null;
        }
        if (self.notification_title_out.len > 0) {
            self.allocator.free(self.notification_title_out);
            self.notification_title_out = &.{};
        }
        if (self.notification_body_out.len > 0) {
            self.allocator.free(self.notification_body_out);
            self.notification_body_out = &.{};
        }
        // title은 빈 문자열일 수 있다(OSC 9). dupe가 실패하면 그 알림은 버린다(best-effort, 코어 pending은 비운다).
        self.notification_title_out = self.allocator.dupe(u8, pending.title) catch {
            term.surface.core.clearNotification();
            return null;
        };
        self.notification_body_out = self.allocator.dupe(u8, pending.body) catch {
            self.allocator.free(self.notification_title_out);
            self.notification_title_out = &.{};
            term.surface.core.clearNotification();
            return null;
        };
        term.surface.core.clearNotification();
        const osc_surface_id = term.surface.id;
        // 발신 Term이 지금 보고 있는 그 Term이면 전면 배너 억제(목록만), 그 외(background pane/가로탭/비활성 탭)면 배너.
        const fg_banner = !(focused_term != null and term == focused_term.?);
        // 코어 락을 든 채지만 pushNotificationHistory는 코어를 안 만져(히스토리 ring + alloc) 데드락이 없다.
        _ = self.pushNotificationHistory(self.notification_title_out, self.notification_body_out, osc_surface_id, false);
        return .{ .title = self.notification_title_out, .body = self.notification_body_out, .surface_id = osc_surface_id, .foreground_banner = fg_banner };
    }

    /// 인앱 알림 센터 히스토리에 한 건 보관한다(title/body dupe — pendingNotification이 드레인하는 owned 버퍼와
    /// 소유권이 겹치지 않게 복사한다). 상한(config notifications.history-limit) 초과면 가장 오래된 걸 버리고, 그게 안
    /// 읽음이면 unread를 보정한다. dupe/append 실패는 best-effort로 버린다(알림 보관은 부가 기능 — enqueueAgentCompletion 규율).
    /// 알림을 인앱 센터에 추가하고 성공하면 true. 할당 실패(title/body dup·append)면 false를 돌려준다 —
    /// drainUpdateCheck가 이 결과로 "성공했을 때만" 1회 가드를 닫아 일시적 실패 시 재시도하게 한다.
    fn pushNotificationHistory(self: *AppSession, title: []const u8, body: []const u8, surface_id: u64, is_agent: bool) bool {
        const title_dup = self.allocator.dupe(u8, title) catch return false;
        const body_dup = self.allocator.dupe(u8, body) catch {
            self.allocator.free(title_dup);
            return false;
        };
        if (self.notification_history.items.len >= @as(usize, self.loaded_config.config.notifications.history_limit)) {
            const dropped = self.notification_history.orderedRemove(0);
            if (!dropped.is_read) self.notification_unread -|= 1;
            self.allocator.free(dropped.title);
            self.allocator.free(dropped.body);
        }
        self.notification_history.append(self.allocator, .{
            .title = title_dup,
            .body = body_dup,
            .surface_id = surface_id,
            .timestamp_ns = @as(i128, std.Io.Clock.awake.now(self.io).nanoseconds),
            .is_read = false,
            .is_agent = is_agent,
        }) catch {
            self.allocator.free(title_dup);
            self.allocator.free(body_dup);
            return false;
        };
        self.notification_unread += 1;
        self.metal_dirty = true; // 배지 갱신 재렌더
        return true;
    }

    /// 히스토리 항목 index를 읽음 처리한다(안 읽음이었으면 unread 1 감소). 범위 밖/이미 읽음이면 무동작.
    fn markNotificationRead(self: *AppSession, index: usize) void {
        if (index >= self.notification_history.items.len) return;
        if (self.notification_history.items[index].is_read) return;
        self.notification_history.items[index].is_read = true;
        self.notification_unread -|= 1;
    }

    /// 알림 센터 목록의 list_index(역순: 0=최신)에 해당하는 히스토리 항목을 삭제한다(owned title/body free). 안 읽음
    /// 이었으면 unread 보정. 목록이 줄었으니 패널 selected를 clamp한다(다음 collect의 setItemCount와 같은 단일 출처).
    fn deleteNotification(self: *AppSession, list_index: usize) void {
        const len = self.notification_history.items.len;
        if (len == 0 or list_index >= len) return;
        const history_index = len - 1 - list_index; // 역순 매핑(목록 0 = 최신 = 히스토리 끝)
        const removed = self.notification_history.orderedRemove(history_index);
        if (!removed.is_read) self.notification_unread -|= 1;
        self.allocator.free(removed.title);
        self.allocator.free(removed.body);
        self.chrome_host.notifications.setItemCount(self.notification_history.items.len);
        self.metal_dirty = true;
    }

    /// 모든 알림을 읽음 처리한다(배지 0). 히스토리 항목은 유지 — 목록엔 남고 안읽음 점(●)만 사라진다.
    fn markAllNotificationsRead(self: *AppSession) void {
        for (self.notification_history.items) |*it| it.is_read = true;
        self.notification_unread = 0;
        self.metal_dirty = true;
    }

    /// 그 surface를 봤으니(데스크톱 배너 클릭 또는 인앱 카드 클릭) 그 surface_id의 안 읽은 히스토리 항목을 모두 읽음
    /// 처리한다(배너↔인앱 센터 읽음 동기화). 같은 surface가 여러 번 알림했으면 다 읽음 — 그 터미널을 봤다는 의미라 일관.
    /// 한 항목 읽음 회계는 markNotificationRead 단일 출처를 재사용한다(이미 읽음이면 내부에서 무동작). dirty는 형제
    /// 알림 mutator(push·delete·markAll·clear)와 같이 무조건 세운다 — 배너/카드 클릭은 cold path라 조건부 절약 불필요.
    pub fn markNotificationsReadBySurface(self: *AppSession, surface_id: u64) void {
        for (self.notification_history.items, 0..) |*it, i| {
            if (it.surface_id == surface_id) self.markNotificationRead(i);
        }
        self.metal_dirty = true;
    }

    /// 모든 알림을 히스토리에서 삭제한다(owned 전부 free). 패널은 빈 목록("알림 없음")으로 유지된다.
    fn clearNotifications(self: *AppSession) void {
        for (self.notification_history.items) |it| {
            self.allocator.free(it.title);
            self.allocator.free(it.body);
        }
        self.notification_history.clearRetainingCapacity();
        self.notification_unread = 0;
        self.chrome_host.notifications.setItemCount(0);
        self.metal_dirty = true;
    }

    /// G12 BEL: 활성 surface에 pending 벨이 있으면 true(코어 플래그를 비운다). Swift가 시스템 벨(NSSound.beep)을
    /// 울린다 — 코어는 OS 소리를 직접 내지 않는다(OSC 52/9·777과 같은 경계). 한 tick 1회로 합쳐져 벨 폭주 방지.
    /// 활성 surface의 BEL 1회를 drain해 config에 따라 분배한다(audible 소리·visual flash·dock 배지). 매 tick frame
    /// build 직전에 호출 — 코어 플래그를 **단일 drain**하므로 takeBell/take_bell_badge는 여기서 세운 신호만 본다.
    /// 코어 플래그는 audible/visual 무관하게 항상 비운다(음소거·미설정에도 누적 방지). (F2-4)
    fn dispatchBell(self: *AppSession) void {
        if (!self.surface_initialized) return;
        // **모든 live term core**의 BEL을 drain(OR) — 배경 탭/pane/term의 BEL도 잡는다(active surface만 보던 한계, 리뷰 D).
        // Dock 배지는 애초에 "언포커스(=배경) 벨"을 알리는 용도라 active만 보면 그 핵심 케이스를 놓친다. bell_pending은
        // 단일 writer(리더 스레드)가 세우는 bool이라 active-surface 때와 같은 무잠금 읽기다(bool torn read 없음 — benign
        // racy flag, docs/io-render-threading.md). **모든** core에 takeBell을 호출해 비워야 다음 tick 재트리거를 막는다(단락 금지).
        var rang = false;
        for (self.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (!term.rt.live_initialized or term.rt.terminated) continue;
                    if (term.surface.core.takeBell()) rang = true; // 매 live core drain(클리어) — OR로 누적
                }
            }
        }
        if (rang) { // BEL 1회 이상 — config에 따라 분배
            if (self.audible_bell) self.bell_audible_pending = true; // Swift take_bell이 NSSound.beep
            if (self.bell_visual) self.bell_flash_ticks = self.bellFlashTotalTicks(); // 시각 flash 시작
            if (self.bell_dock_badge and !self.window_focused) self.bell_badge_pending = true; // 언포커스 시 Dock 배지
        }
        // 시각 flash가 진행 중이면 매 tick 재빌드해 페이드를 그린다(appendBellFlashQuad가 alpha를 줄이고 1 감소).
        if (self.bell_flash_ticks > 0) self.metal_dirty = true;
    }

    pub fn takeBell(self: *AppSession) bool {
        const p = self.bell_audible_pending; // dispatchBell이 BEL+audible 시 세움
        self.bell_audible_pending = false;
        return p;
    }

    /// Dock 배지 1회성 신호 drain — pending이면 true(비움). Swift가 tick마다 호출해 NSApp.dockTile.badgeLabel을 세운다. (F2-4)
    pub fn takeBellBadge(self: *AppSession) bool {
        const p = self.bell_badge_pending;
        self.bell_badge_pending = false;
        return p;
    }

    /// 세팅 GUI에서 데스크톱 알림 토글을 켠 경우 macOS 알림 권한 요청을 Swift에 맡기는 1회성 신호 drain.
    /// Swift가 tick마다 호출해 true면 UNUserNotificationCenter.requestAuthorization을 시도한다.
    pub fn takeNotificationAuthorizationRequest(self: *AppSession) bool {
        const pending = self.notification_authorization_pending;
        self.notification_authorization_pending = false;
        return pending;
    }

    /// 타이핑 중 마우스 숨김 1회성 신호 drain(config input.mouse-hide-while-typing). pending이면 true + 비운다.
    /// Swift가 tick마다 호출해 true면 NSCursor.setHiddenUntilMouseMoves(true) — 복원은 다음 마우스 이동에서 AppKit이
    /// 자동(별도 unhide 불요). take_bell과 같은 1회성 패턴이라 한 tick에 여러 글자를 쳐도 hide 호출은 한 번이다.
    pub fn takeMouseHide(self: *AppSession) bool {
        const pending = self.mouse_hide_pending;
        self.mouse_hide_pending = false;
        return pending;
    }

    /// 세팅 window.background-image 행 활성으로 파일 선택창 요청이 대기 중인지 — 1회성 drain(Swift가 매 tick 호출,
    /// 1이면 NSOpenPanel을 연다). take_bell과 같은 패턴. (배경 이미지 파일 선택 — 사용자 요청)
    pub fn takeFilePickRequest(self: *AppSession) bool {
        const pending = self.file_pick_pending;
        self.file_pick_pending = false;
        return pending;
    }

    /// Swift NSOpenPanel이 고른 파일의 절대경로를 받아 window.background-image에 적용한다 — config arena에 dupe해 setText,
    /// 라이브 반영(reapplyLoadedConfig가 metal_dirty → 다음 frame ensureBackgroundImage가 새 경로 디코드) + 영속 예약
    /// (markConfigKeyDirty). 빈 경로(취소 등)면 무동작 — 지우기는 행 Backspace가 담당. (배경 이미지 파일 선택)
    pub fn providePickedFile(self: *AppSession, path: []const u8) void {
        if (path.len == 0) return;
        const owned = self.loaded_config.arena.allocator().dupe(u8, path) catch return;
        if (config_mod.schema.setText(&self.loaded_config.config, "window.background-image", owned)) {
            self.reapplyLoadedConfig();
            self.markConfigKeyDirty("window.background-image");
        }
    }

    /// HSV picker `i`(스포이드)로 화면 색 추출 요청이 대기 중인지 — 1회성 drain(Swift가 매 tick 호출, 1이면
    /// NSColorSampler를 연다). take_bell과 같은 패턴. (picker eyedropper)
    pub fn takeColorSampleRequest(self: *AppSession) bool {
        const pending = self.color_sample_pending;
        self.color_sample_pending = false;
        return pending;
    }

    /// Swift NSColorSampler가 추출한 화면 픽셀 색(r,g,b)을 picker 선택값에 반영한다(비동기 콜백 — 사용자가 화면을 고른 뒤).
    /// picker가 아직 열려 있을 때만(닫혔으면 무시). setPickerRgb가 picking·non-editing 가드를 본다. metal_dirty로 즉시 반영.
    pub fn provideSampledColor(self: *AppSession, rgb: maru.color.Rgb) void {
        self.chrome_host.settings.setPickerRgb(rgb);
        self.metal_dirty = true;
    }

    /// 세팅 GUI에서 바뀐 config 키를 write-back 예약 집합에 넣는다(중복은 무시 — 한 번만). 키는 스키마 정적 리터럴.
    fn markConfigKeyDirty(self: *AppSession, key: []const u8) void {
        for (self.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, key)) return;
        self.config_dirty_keys.append(self.allocator, key) catch {};
    }

    /// 반영할 config 키가 있으면 true(앱→파일 write-back 예약 — 사이드바 view options·세팅 화면 공용). 여기선 비우지
    /// 않는다 — serializeConfig가 성공적으로 직렬화한 뒤 비운다(실패 시 키 유지→다음 tick 재시도). Swift가 매 tick
    /// take_sidebar_config_dirty(ABI 이름 유지)로 drain해 1이면 serialize→atomic write한다.
    pub fn takeConfigDirty(self: *AppSession) bool {
        inline for (pending_writeback_lists) |n| if (@field(self, n).items.len > 0) return true;
        return self.theme_preset_persist != null; // 리스트가 아닌 optional이라 registry 밖 — 따로 본다
    }

    /// OSC 7로 셸이 보고한 현재 cwd(percent-decode된 경로). 한 번도 안 받았으면 빈 슬라이스.
    /// 반환은 core 소유로 다음 OSC 7/RIS/destroy까지 유효하다(별도 복사 없음 — native 최소).
    /// Swift가 창 제목에 쓴다.
    pub fn currentCwd(self: *AppSession) []const u8 {
        if (!self.surface_initialized) return &.{};
        return self.activeSurface().core.currentCwd();
    }

    /// term의 git 브랜치(owned 캐시). 그 surface의 cwd(OSC 7)가 바뀌었을 때만 .git/HEAD를 walk-up해 재계산한다
    /// (사이드바는 매 프레임 빌드되므로 fs 읽기를 cwd 변경으로 게이트). 없으면 null. 반환은 term 소유(다음 cwd 변경/
    /// teardown까지 유효). 파생값이라 영속 안 함 — restore가 cwd에서 재도출.
    fn termGitBranch(self: *AppSession, term: *Term) ?[]const u8 {
        const cwd = term.surface.core.currentCwd();
        if (cwd.len == 0) return null;
        if (term.git_branch_cwd) |c| {
            if (std.mem.eql(u8, c, cwd)) return term.git_branch; // 캐시 적중(cwd 불변)
        }
        // cwd 변경 → 재계산(옛 캐시 해제 후 갱신).
        if (term.git_branch) |b| self.allocator.free(b);
        if (term.git_branch_cwd) |c| self.allocator.free(c);
        term.git_branch = readGitBranch(self.io, self.allocator, cwd);
        term.git_branch_cwd = self.allocator.dupe(u8, cwd) catch null;
        if (diag_gate.maruDebugEnabled()) std.log.scoped(.git).info("branch: cwd={s} -> {?s}", .{ cwd, term.git_branch });
        return term.git_branch;
    }

    /// config 파일 경로(Open Config 메뉴용). loader.defaultConfigPath(MARU_CONFIG override·$HOME/.config/maru/
    /// config)가 단일 출처 — 한 번 계산해 세션 소유 버퍼에 캐시한다(다음 호출은 캐시, destroy까지 유효).
    /// HOME 없음·OOM이면 빈 슬라이스(Swift가 무동작). 경로 계산만 — 파일 생성/열기는 platform(Swift) OS 동작.
    pub fn configPath(self: *AppSession) []const u8 {
        if (self.config_path_buffer) |b| return b;
        const path = (config_mod.defaultConfigPath(self.allocator) catch null) orelse return &.{};
        self.config_path_buffer = path; // owned 슬라이스 — 세션이 소유(deinit이 해제)
        return path;
    }

    /// **config 파일을 실제로 쓰는 경로**가 대상 경로를 얻을 때 쓰는 안전 chokepoint(configPath는 resolve+캐시 read 전용).
    /// 테스트에서 config_path_buffer를 tmp로 명시 redirect하지 않았으면 빈 경로를 돌려줘 쓰기를 스킵시킨다 — zig build
    /// test(macOS)가 실제 사용자 config($HOME/.config/maru/config)를 절대 못 건드리게 한다. 과거 reset 테스트가 tmp 가드를
    /// 빠뜨려 실 config를 헤더만 남기고 날린 footgun을 **개별 테스트 가드 누락과 무관하게 원천 차단**한다(새 config-쓰기
    /// 테스트가 가드를 잊어도 안전). 프로덕션(is_test=false)은 configPath() 그대로. 새 config-파일 writer는 이걸 거쳐야 한다.
    fn configWritePath(self: *AppSession) []const u8 {
        if (builtin.is_test and self.config_path_buffer == null) return &.{};
        return self.configPath();
    }

    /// 창 제목으로 보여줄 문자열(OSC 0/2 제목 우선, 없으면 cwd basename, 둘 다 없으면 빈 슬라이스).
    /// 우선순위 로직은 core가 소유한다(native 최소) — Swift는 받아서 빈값이면 앱 이름으로 폴백만.
    /// 반환은 core 소유로 다음 OSC 0/2/7·RIS·destroy까지 유효하다(별도 복사 없음).
    pub fn windowTitle(self: *AppSession) []const u8 {
        if (!self.surface_initialized) return &.{};
        return self.activeSurface().core.windowTitle();
    }

    /// 전역(OS) 단축키 기술자 목록(global_hotkeys)을 loaded_config.global_bindings에서 다시 빌드한다. init이 한 번 부르고,
    /// 라이브 변경(rebindGlobalEntry/unbindGlobalEntry/reloadConfig/resetAllSettings)이 부른다 — 기존 목록을 비우고 각
    /// 바인딩을 descriptorFor로 매핑해 채운다(가상 키코드로 매핑 안 되는 chord는 null → 스킵, 등록 불가라 init과 같은 동작).
    /// descriptor는 POD라 self.allocator로 복사(arena 무관 — global_bindings arena가 reload에서 갈려도 안전). dirty는
    /// 여기서 세우지 않는다(앱 시작 1회 vs 라이브 재등록을 호출자가 가른다 — init은 false 유지, 라이브 경로는 true로 세움).
    fn rebuildGlobalHotkeys(self: *AppSession) !void {
        self.global_hotkeys.clearRetainingCapacity();
        for (self.loaded_config.global_bindings) |gb| {
            if (global_hotkey.descriptorFor(gb)) |d| {
                try self.global_hotkeys.append(self.allocator, .{
                    .virtual_key_code = d.virtual_key_code,
                    .carbon_modifiers = d.carbon_modifiers,
                    .action = @intFromEnum(d.action),
                });
            }
        }
    }

    /// 전역(OS) 단축키 등록 기술자 목록(가상 키코드 + Carbon modifier + action). config에서 만들어 Swift가
    /// 읽어 RegisterEventHotKey로 등록한다(시작 시 1회 + 라이브 변경 시 takeGlobalHotkeysDirty drain → 재등록). 매핑 가능한 chord만.
    pub fn globalHotkeys(self: *const AppSession) []const GlobalHotkey {
        return self.global_hotkeys.items;
    }

    /// 전역 단축키가 라이브로 바뀌어 OS 재등록이 필요한지(take_bell류 1회성). dirty면 true 반환하고 false로 리셋 —
    /// Swift가 tick마다 호출해 1이면 unregisterGlobalHotkeys 후 registerGlobalHotkeys로 새 global_hotkeys를 OS에 다시 깐다.
    pub fn takeGlobalHotkeysDirty(self: *AppSession) bool {
        const was = self.global_hotkeys_dirty;
        self.global_hotkeys_dirty = false;
        return was;
    }

    /// 커맨드 카탈로그가 런타임에 재빌드돼 메뉴바 재빌드가 필요한지(take_global_hotkeys_dirty류 1회성). dirty면 true 반환 후
    /// false 리셋 — Swift가 tick마다 호출해 1이면 buildMainMenu로 NSMenu keyEquivalent를 새 카탈로그로 다시 깐다.
    pub fn takeCommandCatalogDirty(self: *AppSession) bool {
        const was = self.command_catalog_dirty;
        self.command_catalog_dirty = false;
        return was;
    }

    /// 커맨드 카탈로그를 빌드한다(init 1회). 각 정적 엔트리에 대해 현재 바인딩 chord를 역스캔해 표시 문자열을
    /// 만들고(안 묶였으면 빈 문자열), 그걸 owned로 보관한 뒤 CommandEntry(action_key/title=정적 리터럴 포인터,
    /// key_display=owned 포인터)를 append한다. OOM이면 에러를 올려 init이 정리하게 한다(errdefer deinit).
    fn buildCommandCatalog(self: *AppSession) !void {
        const resolver = self.loaded_config.keyBindingResolver();
        for (command_catalog.entries) |entry| {
            const chord = command_catalog.chordForAction(resolver, entry.action);
            // 표시용 chord("⌘T")와 NSMenuItem keyEquivalent("t"+mask)를 둘 다 만든다(안 묶였으면 빈 문자열·mask 0).
            var disp_scratch: [command_catalog.max_chord_display_len]u8 = undefined;
            const display: []const u8 = if (chord) |c| command_catalog.formatChord(c, &disp_scratch) else "";
            var equiv_scratch: [8]u8 = undefined;
            const equiv: []const u8 = if (chord) |c| command_catalog.keyEquivalent(c, &equiv_scratch) else "";
            const modifiers: u32 = if (chord) |c| command_catalog.modifierMask(c) else 0;

            const owned_display = try self.allocator.dupeZ(u8, display);
            errdefer self.allocator.free(owned_display);
            const owned_equiv = try self.allocator.dupeZ(u8, equiv);
            errdefer self.allocator.free(owned_equiv);
            // 세 리스트 capacity를 먼저 확보한 뒤 한꺼번에 무오류 append한다. append 중간에 OOM이 나면 이미 리스트에 든
            // owned_display를 errdefer가 다시 free해 dangling/이중-free(다음 rebuild·deinit의 free 루프)가 되던 버그를
            // 막는다 — capacity 확보 전(append 전)에만 errdefer가 발화하므로, 적재된 포인터는 errdefer가 건드리지 않는다.
            try self.command_key_displays.ensureUnusedCapacity(self.allocator, 1);
            try self.command_key_equivalents.ensureUnusedCapacity(self.allocator, 1);
            try self.command_entries.ensureUnusedCapacity(self.allocator, 1);
            self.command_key_displays.appendAssumeCapacity(owned_display);
            self.command_key_equivalents.appendAssumeCapacity(owned_equiv);
            self.command_entries.appendAssumeCapacity(.{
                .action_key = entry.key.ptr,
                .title = entry.title.ptr,
                .key_display = owned_display.ptr,
                .key_equivalent = owned_equiv.ptr,
                .key_modifiers = modifiers,
            });
        }
    }

    /// 카탈로그를 비우고 다시 빌드한다(리바인딩 후 — 메뉴바·팝업의 단축키 표시 갱신). buildCommandCatalog가 append-only라
    /// 먼저 owned 표시/equiv를 해제하고 비운다. command_catalog_dirty를 세워 Swift tick이 메뉴바를 다시 빌드하게 한다
    /// (모든 keybind 변경 경로 — rebind/unbind·reload·reset — 의 단일 출처). Zig-side 팔레트는 라이브라 즉시 갱신.
    fn rebuildCommandCatalog(self: *AppSession) void {
        for (self.command_key_displays.items) |s| self.allocator.free(s);
        self.command_key_displays.clearRetainingCapacity();
        for (self.command_key_equivalents.items) |s| self.allocator.free(s);
        self.command_key_equivalents.clearRetainingCapacity();
        self.command_entries.clearRetainingCapacity();
        self.buildCommandCatalog() catch {};
        self.command_catalog_dirty = true; // Swift가 tick마다 drain해 메뉴바 keyEquivalent 재빌드(reset 모달-확정·인앱 rebind 포함)
    }

    /// 액션을 새 chord로 다시 묶는다(keybind recorder). loaded_config.keybindings를 새 슬라이스로 교체(그 액션 줄을 새
    /// chord로, 없으면 추가 — resolver가 매 키 이벤트마다 이 슬라이스를 읽으므로 즉시 반영), 카탈로그 재빌드, write-back
    /// 예약(updateKeybindLines가 `keybind = chord = action` 줄로 영속). 옛 슬라이스는 미참조로 남아 reload/deinit에 해제.
    /// 한계(v1): 옛 chord가 빌트인이면 그 chord도 계속 액션을 발동한다(새 chord를 **추가**하는 셈 — unbind는 후속).
    /// 한 액션의 **빌트인 chord(들)**(default_app_bindings)를 unbind한다 — loaded_config.unbinds에 넣어(라이브 ignored)
    /// `keybind = chord = unbind`로 영속한다. `except`가 주어지면 그 chord는 안 죽인다(완전 교체에서 새 chord가 빌트인과
    /// 같을 때 그 키를 살린다 — 사용자 바인딩이 resolver 우선이라 동작은 같지만 파일에 중복 unbind 줄을 안 남긴다). 이미
    /// unbinds에 있으면 스킵(중복 누적 방지). 다중-chord 빌트인(next/previous_tab·increase/decrease_font_size=2개)은 전부
    /// 처리(리뷰 #840). 카탈로그 재빌드는 호출자가 한다. **rebind(완전 교체)·unbind(완전 해제)가 공유하는 단일 출처.**
    fn unbindBuiltinChords(self: *AppSession, entry: command_catalog.Entry, except: ?config_mod.KeyChord) void {
        const a = self.loaded_config.arena.allocator();
        var ub: std.ArrayList(config_mod.KeyChord) = .empty;
        ub.appendSlice(a, self.loaded_config.unbinds) catch return;
        var added_any = false;
        for (config_mod.keybinding.default_app_bindings) |db| {
            if (!std.meta.eql(db.action, entry.action)) continue;
            if (except) |x| if (x.eql(db.chord)) continue; // 새 chord(=빌트인)는 안 죽임
            var dup = false;
            for (ub.items) |u| if (u.eql(db.chord)) {
                dup = true;
                break;
            };
            if (dup) continue;
            ub.append(a, db.chord) catch return;
            added_any = true;
            var chord_buf: [command_catalog.max_chord_display_len]u8 = undefined;
            self.markKeybindUnbind(a.dupe(u8, db.chord.toConfigString(&chord_buf)) catch return);
        }
        if (added_any) self.loaded_config.unbinds = ub.toOwnedSlice(a) catch return;
    }

    /// chord를 다시 **사용자 바인딩**으로 묶을 때, 옛 `keybind = <chord> = unbind` 지시어가 모순되게 남는 걸 정리한다
    /// (stale unbind). resolver는 사용자 바인딩을 unbinds보다 먼저 봐서 동작은 정상이지만, 파일에 "X = unbind"와 "X = 액션"이
    /// 공존하면 혼란스럽고 다음 unbind/편집에 헷갈린다. ① 라이브 unbinds에서 chord 제거 ② 이번 세션 펜딩 unbind-append 취소
    /// ③ 파일에 있을 옛 줄 제거 예약(removeKeybindUnbindLines). chord가 unbinds에 없으면 무동작(흔한 경우 비용 0).
    fn clearStaleUnbind(self: *AppSession, chord: config_mod.KeyChord) void {
        var present = false;
        for (self.loaded_config.unbinds) |u| if (u.eql(chord)) {
            present = true;
            break;
        };
        if (!present) return;
        const a = self.loaded_config.arena.allocator();
        // ① 라이브 unbinds에서 제거(그 chord를 더는 ignored로 안 본다).
        var keep: std.ArrayList(config_mod.KeyChord) = .empty;
        for (self.loaded_config.unbinds) |u| if (!u.eql(chord)) keep.append(a, u) catch return;
        self.loaded_config.unbinds = keep.toOwnedSlice(a) catch return;
        var chord_buf: [command_catalog.max_chord_display_len]u8 = undefined;
        const cs = chord.toConfigString(&chord_buf);
        // ② 이번 세션에 죽였다 다시 묶는 경우 — 펜딩 unbind-append에서 같은 chord 제거(append 안 되게).
        var i: usize = 0;
        while (i < self.config_keybind_unbinds.items.len) {
            if (std.mem.eql(u8, self.config_keybind_unbinds.items[i], cs)) {
                _ = self.config_keybind_unbinds.orderedRemove(i);
            } else i += 1;
        }
        // ③ 옛 세션이 파일에 쓴 `keybind = cs = unbind` 줄 제거 예약(없으면 removeKeybindUnbindLines가 no-op).
        for (self.config_keybind_unbind_removed.items) |c| if (std.mem.eql(u8, c, cs)) return; // 이미 예약
        const owned = a.dupe(u8, cs) catch return;
        self.config_keybind_unbind_removed.append(self.allocator, owned) catch {};
    }

    fn rebindActionEntry(self: *AppSession, entry: command_catalog.Entry, chord: config_mod.KeyChord) void {
        const a = self.loaded_config.arena.allocator();
        // 충돌 경고: 이 chord가 **다른 액션**에 이미 묶여 있으면 알린다(rebind는 진행 — 사용자 의도, last-wins). 현재 effective
        // chord(사용자/빌트인) 기준으로 카탈로그 액션을 스캔. 메시지는 스택 버퍼 → showNotice가 복사하므로 안전.
        const resolver_pre = self.loaded_config.keyBindingResolver();
        for (command_catalog.entries) |other| {
            if (std.meta.eql(other.action, entry.action)) continue;
            const oc = command_catalog.chordForAction(resolver_pre, other.action) orelse continue;
            if (oc.eql(chord)) {
                var msg_buf: [160]u8 = undefined;
                const msg = std.fmt.bufPrint(&msg_buf, "이 단축키는 '{s}'에 이미 묶여 있습니다 — 덮어씁니다", .{other.title}) catch "이 단축키는 이미 다른 동작에 묶여 있습니다 — 덮어씁니다";
                self.settingsMessageOrNotice(msg); // 세팅 열림이면 배너(모달 유지), 아니면 토스트
                break;
            }
        }
        var list: std.ArrayList(config_mod.AppBinding) = .empty;
        var replaced = false;
        for (self.loaded_config.keybindings) |b| {
            if (std.meta.eql(b.action, entry.action)) {
                list.append(a, .{ .chord = chord, .action = entry.action }) catch return;
                replaced = true;
            } else list.append(a, b) catch return;
        }
        if (!replaced) list.append(a, .{ .chord = chord, .action = entry.action }) catch return;
        self.loaded_config.keybindings = list.toOwnedSlice(a) catch return;
        // **완전 교체**: 새 chord를 묶는 데 더해, 그 액션의 빌트인 chord(새 chord 제외)를 unbind한다 — 안 그러면 빌트인이
        // 살아 있어 옛 키 + 새 키 둘 다 동작한다(추가가 아니라 교체여야 표시=동작·옛 키 되찾기). 새 chord가 빌트인과
        // 같으면(재확인) 그건 살린다(except). 키바인드 완전 교체 — docs/config-gui.md §6.7.
        self.unbindBuiltinChords(entry, chord);
        // stale unbind 정리: 이 새 chord가 옛 `keybind = chord = unbind`로 죽어 있었으면 그 모순 줄을 뺀다(사용자 바인딩으로 부활).
        self.clearStaleUnbind(chord);
        self.rebuildCommandCatalog();

        // 영속 예약 — action 키별 upsert(같은 액션 여러 번 바꾸면 마지막만). chord는 config 표기로 arena에 둔다.
        var chord_buf: [command_catalog.max_chord_display_len]u8 = undefined;
        const chord_str = a.dupe(u8, chord.toConfigString(&chord_buf)) catch return;
        for (self.config_keybind_rebinds.items) |*rb| {
            if (std.mem.eql(u8, rb.action, entry.key)) {
                rb.chord = chord_str;
                self.metal_dirty = true;
                return;
            }
        }
        self.config_keybind_rebinds.append(self.allocator, .{ .action = entry.key, .chord = chord_str }) catch return;
        self.metal_dirty = true;
    }

    /// 액션의 단축키를 **완전히 해제**한다(keybind 행 Backspace). 현재 effective chord Y(resolver — 사용자/빌트인 무관)를
    /// 구해, 사용자 바인딩이면 빼고 + Y를 loaded_config.unbinds에 넣어 빌트인이어도 ignored로 만든다(라이브 즉시 — resolver가
    /// unbinds를 본다). 영속: 사용자 줄 제거 예약 + `keybind = Y = unbind` 지시어 예약. 펜딩 rebind 취소. 해제 후
    /// chordForAction(Y가 unbinds라)이 null → 행은 "(미지정)". 이미 미지정이면 notice.
    fn unbindActionEntry(self: *AppSession, entry: command_catalog.Entry) void {
        const a = self.loaded_config.arena.allocator();
        const resolver = self.loaded_config.keyBindingResolver();
        if (command_catalog.chordForAction(resolver, entry.action) == null) {
            self.settingsMessageOrNotice("이미 지정된 단축키가 없습니다");
            return;
        }
        // ① 사용자 바인딩 제거(사용자 chord는 제거만으로 죽는다 — config 줄 제거 + 라이브 슬라이스에서 드롭).
        var list: std.ArrayList(config_mod.AppBinding) = .empty;
        var found_user = false;
        for (self.loaded_config.keybindings) |b| {
            if (std.meta.eql(b.action, entry.action)) {
                found_user = true; // 드롭
            } else list.append(a, b) catch return;
        }
        if (found_user) self.loaded_config.keybindings = list.toOwnedSlice(a) catch return;
        // ② **빌트인 chord 전부**를 unbind(except=null) — 사용자 chord만 빼면 빌트인이 되살아나므로 모두 죽인다(완전 해제).
        // 다중-chord 빌트인도 전부(리뷰 #840). rebind(완전 교체)와 공유하는 unbindBuiltinChords 단일 출처.
        self.unbindBuiltinChords(entry, null);
        self.rebuildCommandCatalog();
        // 펜딩 rebind 취소(unbind가 우선).
        var i: usize = 0;
        while (i < self.config_keybind_rebinds.items.len) {
            if (std.mem.eql(u8, self.config_keybind_rebinds.items[i].action, entry.key)) {
                _ = self.config_keybind_rebinds.orderedRemove(i);
            } else i += 1;
        }
        if (found_user) self.markKeybindRemoved(entry.key); // 영속: 사용자 줄 제거
        self.metal_dirty = true;
    }

    /// 전역(OS) 액션을 새 chord로 다시 묶는다(rebindActionEntry의 글로벌 미러). chord가 전역 등록 불가(descriptorFor가
    /// null — 가상 키코드 매핑 없음, 예 Plus·Insert)면 notice로 거부하고 중단한다(파일에 못 쓸 chord를 안 받는다). 아니면
    /// loaded_config.global_bindings를 새 슬라이스로 교체(그 액션을 새 chord로, 없으면 추가, 같은 action 중복 제거),
    /// write-back 예약(updateGlobalKeybindLines가 `keybind = global:<chord> = <action>` 줄로 영속). 옛 슬라이스는 미참조로
    /// 남아 reload/deinit에 arena 통째 해제. OS 재등록(라이브)은 PR2 — 이번엔 "재시작 후 적용"이다.
    fn rebindGlobalEntry(self: *AppSession, entry: command_catalog.GlobalEntry, chord: config_mod.KeyChord) void {
        const a = self.loaded_config.arena.allocator();
        // 전역 등록 가능한 chord인지 먼저 확인(가상 키코드 매핑) — 안 되면 파일에 못 쓸 chord라 거부.
        if (global_hotkey.descriptorFor(.{ .chord = chord, .action = entry.action }) == null) {
            self.settingsMessageOrNotice("이 키는 전역 단축키로 등록할 수 없습니다"); // 세팅 열림이면 배너(모달 유지), 아니면 토스트
            return;
        }
        // 충돌 경고(선택): 이 chord가 **다른 전역 액션**에 이미 묶여 있으면 알린다(rebind는 진행 — last-wins).
        for (self.loaded_config.global_bindings) |other| {
            if (other.action == entry.action) continue;
            if (other.chord.eql(chord)) {
                self.settingsMessageOrNotice("이 전역 단축키는 이미 다른 동작에 묶여 있습니다 — 덮어씁니다");
                break;
            }
        }
        // global_bindings를 새 슬라이스로 교체 — 이 액션은 새 chord로 갈고(같은 action 중복은 한 번만), 다른 액션은 보존.
        var list: std.ArrayList(config_mod.GlobalBinding) = .empty;
        var replaced = false;
        for (self.loaded_config.global_bindings) |b| {
            if (b.action == entry.action) {
                if (replaced) continue; // 같은 action 중복 제거(첫 매칭만 새 chord로)
                list.append(a, .{ .chord = chord, .action = entry.action }) catch return;
                replaced = true;
            } else list.append(a, b) catch return;
        }
        if (!replaced) list.append(a, .{ .chord = chord, .action = entry.action }) catch return;
        self.loaded_config.global_bindings = list.toOwnedSlice(a) catch return;

        // 영속 예약 — action 키별 upsert(같은 액션 여러 번 바꾸면 마지막만). chord는 config 표기로 arena에 둔다.
        var chord_buf: [command_catalog.max_chord_display_len]u8 = undefined;
        const chord_str = a.dupe(u8, chord.toConfigString(&chord_buf)) catch return;
        self.markGlobalRebind(entry.key, chord_str);
        // 라이브 OS 재등록(PR2) — global_hotkeys를 새 global_bindings로 다시 빌드하고 dirty를 세운다(Swift가 drain해 재등록).
        self.rebuildGlobalHotkeys() catch {};
        self.global_hotkeys_dirty = true;
        self.metal_dirty = true;
    }

    /// 전역(OS) 액션의 단축키를 해제한다(전역 행 Backspace — unbindActionEntry의 글로벌 미러). 빌트인 기본이 없으므로
    /// global_bindings에서 그 액션 줄을 빼면 끝이다(in-app처럼 unbind 지시어가 필요 없다). 안 묶여 있으면 notice. 펜딩
    /// rebind는 취소하고 줄 제거를 예약(markGlobalRemoved → removeGlobalKeybindLines). OS 반영은 재시작 후.
    fn unbindGlobalEntry(self: *AppSession, entry: command_catalog.GlobalEntry) void {
        const a = self.loaded_config.arena.allocator();
        if (command_catalog.chordForGlobalAction(self.loaded_config.global_bindings, entry.action) == null) {
            self.settingsMessageOrNotice("이미 지정된 전역 단축키가 없습니다");
            return;
        }
        var list: std.ArrayList(config_mod.GlobalBinding) = .empty;
        for (self.loaded_config.global_bindings) |b| {
            if (b.action == entry.action) continue; // 드롭(중복 포함 전부)
            list.append(a, b) catch return;
        }
        self.loaded_config.global_bindings = list.toOwnedSlice(a) catch return;
        self.cancelGlobalRebind(entry.key); // 펜딩 rebind 취소(제거가 우선)
        self.markGlobalRemoved(entry.key); // 영속: 전역 줄 제거
        // 라이브 OS 재등록(PR2) — 그 액션이 빠진 global_bindings로 global_hotkeys를 다시 빌드하고 dirty(Swift drain → 재등록).
        self.rebuildGlobalHotkeys() catch {};
        self.global_hotkeys_dirty = true;
        self.metal_dirty = true;
    }

    /// 전역 keybind 재바인딩 예약(markConfigKeyDirty·rebind upsert의 글로벌 미러 — action 키별 한 건). action은
    /// command_catalog 정적 키, chord는 loaded_config.arena 소유(config 표기). serializeConfig가 updateGlobalKeybindLines로 반영.
    fn markGlobalRebind(self: *AppSession, action_key: []const u8, chord_str: []const u8) void {
        for (self.config_global_rebinds.items) |*rb| {
            if (std.mem.eql(u8, rb.action, action_key)) {
                rb.chord = chord_str;
                return;
            }
        }
        self.config_global_rebinds.append(self.allocator, .{ .action = action_key, .chord = chord_str }) catch {};
    }

    /// 전역 keybind 줄 제거 예약(중복 한 번만). action은 command_catalog 정적 키. serializeConfig가 removeGlobalKeybindLines로 반영.
    fn markGlobalRemoved(self: *AppSession, action_key: []const u8) void {
        for (self.config_global_removed.items) |k| if (std.mem.eql(u8, k, action_key)) return;
        self.config_global_removed.append(self.allocator, action_key) catch {};
    }

    /// 펜딩 전역 rebind를 액션 키로 취소한다(unbind가 rebind보다 우선 — 같은 액션을 바꿨다 지우면 결국 제거).
    fn cancelGlobalRebind(self: *AppSession, action_key: []const u8) void {
        var i: usize = 0;
        while (i < self.config_global_rebinds.items.len) {
            if (std.mem.eql(u8, self.config_global_rebinds.items[i].action, action_key)) {
                _ = self.config_global_rebinds.orderedRemove(i);
            } else i += 1;
        }
    }

    /// keybind 줄 제거 예약(중복 한 번만). action은 command_catalog 정적 키. serializeConfig가 removeKeybindLines로 반영.
    fn markKeybindRemoved(self: *AppSession, action_key: []const u8) void {
        for (self.config_keybind_removed.items) |k| if (std.mem.eql(u8, k, action_key)) return;
        self.config_keybind_removed.append(self.allocator, action_key) catch {};
    }

    /// `keybind = chord = unbind` 지시어 예약(중복 한 번만). chord는 config 표기(loaded_config.arena 소유).
    fn markKeybindUnbind(self: *AppSession, chord_str: []const u8) void {
        for (self.config_keybind_unbinds.items) |c| if (std.mem.eql(u8, c, chord_str)) return;
        self.config_keybind_unbinds.append(self.allocator, chord_str) catch {};
    }

    /// keybind 녹음 중 raw 키 한 개를 처리한다(handleKeyEvent가 가로채 호출). 평범한 Esc(모디파이어 없음)는 취소(rebind
    /// 안 함 — 흔한 recorder 관례). 그 외 키는 KeyChord로 만들어 선택된 keybind 행의 액션에 묶는다. 녹음은 한 키로 끝난다.
    fn captureKeybindRecording(self: *AppSession, event: terminal.KeyEvent) void {
        self.chrome_host.settings.recording = false; // 취소든 캡처든 한 키로 종료
        self.chrome_host.settings.clearMessage(); // 새 녹음 시도 — 직전 안내 배너 정리(아래에서 실패/충돌 시 다시 세운다)
        const m = event.modifiers;
        if (event.key == .escape and !m.shift and !m.control and !m.option and !m.command) return; // 취소
        const chord = config_mod.KeyChord.fromKeyEvent(event) orelse return; // 매핑 불가 키는 무시(녹음만 끝남)
        var scratch = std.heap.ArenaAllocator.init(self.allocator);
        defer scratch.deinit();
        const cf = self.currentSectionFields(scratch.allocator()) catch return;
        const sel = self.chrome_host.settings.selected;
        // in-app keybind 행이면 그 액션에 rebind, 전역 단축키 행이면 글로벌 분기로 rebind(둘은 selected 구간으로 갈린다).
        if (cf.keybindRowStart()) |start| {
            if (sel >= start and sel - start < cf.keybind_entries.len) {
                self.rebindActionEntry(cf.keybind_entries[sel - start], chord);
                return;
            }
        }
        if (cf.globalKeybindRowStart()) |gstart| {
            if (sel >= gstart and sel - gstart < cf.global_entries.len) {
                self.rebindGlobalEntry(cf.global_entries[sel - gstart], chord);
                return;
            }
        }
    }

    /// 커맨드 카탈로그(메뉴바·팝업이 그릴 액션 목록). 세션 동안 불변. owned — destroy까지 유효.
    pub fn commandCatalog(self: *const AppSession) []const CommandEntry {
        return self.command_entries.items;
    }

    /// action_key(= parseAction 문자열) 한 개를 실행한다 — 메뉴/팝업 선택의 디스패치 경로. 파싱되면
    /// dispatchAppAction으로 넘기고 true, 모르는 키면 무동작 true 반환 없이 false(Swift가 무시). 터미널
    /// Action만 받는다(global/UI 동작은 Swift 소유라 별도).
    pub fn runAction(self: *AppSession, action_key: []const u8) bool {
        // 모달/오버레이(세팅·confirm·notice·palette·find·context_menu)가 열린 동안엔 메뉴바 keyEquivalent(Swift가 OS에서
        // 잡아 이 경로로 보낸다)를 무시한다 — 모달 중 단축키(⌘T 등)가 뒤의 터미널을 조작하거나, keybind 녹음할 chord를
        // 가로채면 안 된다. anyOverlayOpen 단일 출처로 판정(settings·context_menu 포함 — 예전엔 일부 모달을 누락해 세팅
        // 중 ⌘T가 샜다). 모달 자신의 키는 chrome_host.handleInput·녹음 캡처가 따로 처리하므로 이 경로를 안 거친다.
        if (self.anyOverlayOpen()) return false;
        const action = config_mod.parseAction(action_key) orelse return false;
        self.dispatchAppAction(action);
        return true;
    }

    /// 이 창(AppSession)의 라이브 상태를 workspace restore 모델(maru.session.workspace.Window)로 캡처한다(R3). 탭→pane
    /// split 트리→Term→surface를 걸어 선언적 상태만 모은다 — live PTY/process/grid는 안 담는다. cwd/title은 OSC
    /// 권위 소스(core.currentCwd/windowTitle), command는 spawn argv[0](surface.command). split 트리는 *Pane leaf를
    /// pane 인덱스로 환원해 preorder TreeNode로 평탄화(직렬화 모델과 같은 형태). 멀티 창 전체 모델은 호출자(R5)가
    /// 각 세션의 Window를 모아 만든다. 모든 슬라이스·문자열은 `arena`가 소유한다(호출자가 deinit).
    pub fn captureWorkspaceWindow(self: *AppSession, arena: std.mem.Allocator) !maru.session.workspace.Window {
        var tabs: std.ArrayList(maru.session.workspace.Tab) = .empty;
        for (self.tabs.items) |tab| try tabs.append(arena, try self.captureWorkspaceTab(arena, tab));
        return .{ .active_tab = self.app_window.active_tab, .tabs = try tabs.toOwnedSlice(arena) };
    }

    fn captureWorkspaceTab(self: *AppSession, arena: std.mem.Allocator, tab: *Tab) !maru.session.workspace.Tab {
        var panes: std.ArrayList(maru.session.workspace.Pane) = .empty;
        for (tab.panes.items) |pane| {
            var surfaces: std.ArrayList(maru.session.workspace.Surface) = .empty;
            for (pane.terms.items) |term| {
                const core = &term.surface.core;
                const agent = self.captureAgentForRestore(arena, term);
                try surfaces.append(arena, .{
                    // custom_name = 사용자 rename(owned, 없으면 ""), title = 자동 제목(OSC). 둘은 별도 필드로 저장한다.
                    .custom_name = try arena.dupe(u8, term.surface.custom_name orelse ""),
                    .title = try arena.dupe(u8, core.windowTitle()),
                    .cwd = try arena.dupe(u8, core.currentCwd()),
                    .command = try arena.dupe(u8, term.surface.command orelse ""),
                    .cols = core.size.cols,
                    .rows = core.size.rows,
                    // claude/codex 세션 자동 resume(opt-in). agent_kind 빈값이면 일반 셸 복원(docs/workspace-restore.md).
                    .agent_kind = agent.kind,
                    .agent_session = agent.session,
                    .agent_argv = agent.argv,
                });
            }
            try panes.append(arena, .{
                .active_term = pane.active_term,
                .custom_name = try arena.dupe(u8, pane.custom_name orelse ""), // pane 사용자 rename(없으면 "")
                .surfaces = try surfaces.toOwnedSlice(arena),
            });
        }
        var tree: std.ArrayList(maru.session.workspace.TreeNode) = .empty;
        try Model.flattenTree(arena, tab, tab.tree, &tree);
        return .{
            .active_pane = tab.active_pane,
            // 워크스페이스(탭)의 사용자 rename(없으면 ""). 예전엔 데이터 출처가 없어 reserved placeholder였으나, 이제
            // tab.custom_name이 출처다(docs/workspace-restore.md "사용자 지정 이름과 자동 제목").
            .custom_name = try arena.dupe(u8, tab.custom_name orelse ""),
            .pinned = tab.pinned,
            .background_color = tab.background_color,
            .tree = try tree.toOwnedSlice(arena),
            .panes = try panes.toOwnedSlice(arena),
        };
    }

    /// (workspace restore) captureAgentForRestore 결과 — claude/codex 세션 자동 resume 정보(빈값이면 일반 셸 복원).
    const AgentRestoreInfo = struct {
        kind: []const u8 = "",
        session: []const u8 = "",
        argv: []const []const u8 = &.{},
    };

    /// 이 Term이 claude/codex이고 해당 토글이 켜졌으면, 종료 시점에 세션을 자동 resume하기 위한 정보(agent_kind·
    /// session_id·보존 argv)를 캡처한다(아니면 빈값=일반 셸 복원). exec_path+argv는 KERN_PROCARGS2(captureAgentArgv —
    /// **틱이 멈춘 종료 시점 호출이라 정적 procargs_buf 공유 안전**), session_id는 트랜스크립트 파일(resolveSessionId).
    /// argv[0]은 exec_path 절대경로로 교체하고 민감 인라인 토큰은 redact한다. 결과는 arena 소유. 단일 출처:
    /// docs/workspace-restore.md "에이전트 세션 자동 resume".
    fn captureAgentForRestore(self: *AppSession, arena: std.mem.Allocator, term: *Term) AgentRestoreInfo {
        const kind: app.agent_resume.Kind = switch (term.agent_kind) {
            .none => return .{},
            .claude => if (self.loaded_config.config.workspace.restore_claude) .claude else return .{},
            .codex => if (self.loaded_config.config.workspace.restore_codex) .codex else return .{},
        };
        if (!term.rt.live_initialized) return .{};

        // 1) exec_path + 전체 argv 캡처(틱이 멈춘 종료 시점이라 정적 procargs_buf 공유 안전).
        var str_buf: [16 * 1024]u8 = undefined;
        var argv_raw: [maru.session.workspace.max_agent_argv][]const u8 = undefined;
        const cap = term.rt.live_pty.session.captureAgentArgv(&str_buf, &argv_raw) orelse return .{};
        if (cap.argv.len == 0) return .{};
        // stale agent_kind 방어: 캡처된 실제 프로그램(node 래퍼면 argv[1] 스크립트, 아니면 exec_path)이 기대 kind와
        // 일치하는지 재확인한다 — agent_kind는 ~0.5s 폴 캐시라, claude 종료 직후 셸이 idle이거나 다른 명령이 뜬
        // 순간 종료하면 셸/그 명령의 argv를 잡을 수 있다(그 경우 classifyAgent=none → 빈값, 일반 셸 복원).
        const prog_path = if (cap.argv.len >= 2 and app.agent_resume.isInterpreterPath(cap.exec_path)) cap.argv[1] else cap.exec_path;
        if (classifyAgent(std.fs.path.basename(prog_path)) != term.agent_kind) return .{};

        // 2) argv[0]을 exec_path(절대경로)로 교체 → 민감 인라인 토큰 redact.
        var combined: [maru.session.workspace.max_agent_argv][]const u8 = undefined;
        var m: usize = 0;
        combined[m] = cap.exec_path;
        m += 1;
        for (cap.argv[1..]) |a| {
            if (m >= combined.len) break;
            combined[m] = a;
            m += 1;
        }
        var redacted_buf: [maru.session.workspace.max_agent_argv][]const u8 = undefined;
        const redacted = app.agent_resume.redactArgv(combined[0..m], &redacted_buf);

        // 3) arena로 소유 이전(str_buf/combined는 지역이라 종료 시점 이후 무효).
        const argv_out = arena.alloc([]const u8, redacted.len) catch return .{};
        for (redacted, 0..) |a, i| argv_out[i] = arena.dupe(u8, a) catch return .{};

        return .{
            .kind = arena.dupe(u8, kind.toString()) catch return .{},
            .session = self.captureAgentSessionId(arena, term, kind),
            .argv = argv_out,
        };
    }

    /// captureAgentForRestore의 session id 부분 — cwd(OSC 7, 락 아래 복사) + HOME으로 트랜스크립트 루트를 만들어
    /// resolveSessionId. 못 구하면 ""(폴백 resume). pollAgentState의 root/cwd 구성과 같은 패턴.
    fn captureAgentSessionId(self: *AppSession, arena: std.mem.Allocator, term: *Term, kind: app.agent_resume.Kind) []const u8 {
        var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
        const cwd = blk: {
            term.surface.lockCore(self.io);
            defer term.surface.unlockCore(self.io);
            const live = term.surface.core.currentCwd();
            if (live.len == 0 or live.len > cwd_buf.len) break :blk "";
            @memcpy(cwd_buf[0..live.len], live);
            break :blk cwd_buf[0..live.len];
        };
        if (cwd.len == 0) return "";
        const home: []const u8 = if (std.c.getenv("HOME")) |h| std.mem.span(h) else return "";
        const subdir: []const u8 = switch (kind) {
            .claude => ".claude/projects",
            .codex => ".codex/sessions",
        };
        var root_buf: [4096]u8 = undefined;
        const root = std.fmt.bufPrint(&root_buf, "{s}/{s}", .{ home, subdir }) catch return "";
        // agent_session.Kind는 app.agent_resume.Kind와 같은 타입이라(#6 통합) 변환 없이 그대로 넘긴다.
        var id_buf: [256]u8 = undefined;
        const id = agent_session.resolveSessionId(self.io, self.allocator, kind, root, cwd, &id_buf) orelse return "";
        return arena.dupe(u8, id) catch "";
    }

    /// PaneTree 노드를 preorder로 평탄화한다 — leaf(*Pane)는 그 Pane의 tab.panes 인덱스로, split은 방향+ratio(천분율)
    /// 로. 직렬화 모델(self-delimiting preorder)과 같은 순서·형태.
    // flattenPaneTree·paneIndexOf(PaneTree → workspace.TreeNode 평탄화)는 session core로 이동(§3.1) —
    // Model.flattenTree(내부에 paneIndexOf). 단일 출처: src/session/session_model.zig.

    /// 이 창의 workspace 블록(헤더 없는 `window …` 텍스트)을 직렬화해 세션-소유 버퍼로 돌려준다(R5 저장 ABI).
    /// 캡처는 임시 arena로 하고, 결과 텍스트만 self.allocator로 보관한다(다음 호출/deinit까지 유효 — cwd ABI와
    /// 같은 소유 규칙). Swift가 멀티 창 저장에서 세션마다 호출해 `maru.workspace.v1` 헤더 아래로 모은다.
    pub fn serializeWorkspaceWindow(self: *AppSession) ![]const u8 {
        if (self.workspace_buffer) |b| {
            self.allocator.free(b);
            self.workspace_buffer = null;
        }
        var arena = std.heap.ArenaAllocator.init(self.allocator);
        defer arena.deinit();
        const win = try self.captureWorkspaceWindow(arena.allocator());
        const text = try maru.session.workspace.serializeWindow(self.allocator, win);
        self.workspace_buffer = text;
        return text;
    }

    /// 현재 sidebar 토글(show_branch/show_folder)을 config 파일에 반영할 새 텍스트를 직렬화한다(owned, 다음
    /// 호출/deinit까지 유효 — workspace_buffer 패턴). 원본 config를 읽어 updateConfigText로 부분 갱신하므로
    /// 주석·미파싱 키를 보존한다. Swift가 받아 config 경로에 atomic write한다(앱→config 방향). 원본이 없거나
    /// 읽기 실패면 빈 텍스트로 두 키를 append한다(forgiving — config가 없어도 토글이 새 파일을 만든다).
    pub fn serializeConfig(self: *AppSession) ![]const u8 {
        if (self.sidebar_config_buffer) |b| {
            self.allocator.free(b);
            self.sidebar_config_buffer = null;
        }
        const path = self.configPath();
        const owned: ?[]u8 = if (path.len == 0)
            null
        else
            std.Io.Dir.cwd().readFileAlloc(self.io, path, self.allocator, .limited(1 << 20)) catch null;
        defer if (owned) |o| self.allocator.free(o);
        const original: []const u8 = owned orelse &.{};

        // 바뀐 키만 현재값으로 부분 갱신(override-only write-back, S0-1b 일반화 — 사이드바 view options·세팅 화면
        // 공용). 값은 스키마 직렬화(configKeyValues)가 단일 출처라 타입별 손코드 중복이 없다. 성공 시 dirty 집합을
        // 비운다(아래) — updateConfigForKeys가 실패하면 try가 빠져나가 키가 남아 다음 tick 재시도된다.
        var text = try config_mod.updateConfigForKeys(self.allocator, original, self.loaded_config.config, self.config_dirty_keys.items);
        errdefer self.allocator.free(text); // 이후 체이닝 패스(theme.preset·keybind 등) 중 try 실패 시 현재 text 버퍼 누수 방지 —
        // text는 패스마다 reassign되므로 errdefer는 항상 최신 버퍼를 free하고, 성공 경로(sidebar_config_buffer 보관·return)에선 미발화.
        // 테마 프리셋 영속(팔레트 포함): `theme.preset = <name>` 줄을 set/update한다 — configKeyValues가 derive 키
        // theme.preset을 emit하지 않으므로(round-trip 대칭 유지) 전용 패스로 쓴다. 충돌할 개별 theme.* override는
        // config_removed_keys(아래 제거 패스)가 빼므로 base 프리셋 색이 온전히 산다. 성공해야 비운다(실패 시 재시도).
        if (self.theme_preset_persist) |name| {
            const kv = [_]config_mod.ConfigKeyValue{.{ .key = "theme.preset", .value = name }};
            const chained = try config_mod.updateConfigText(self.allocator, text, &kv);
            self.allocator.free(text);
            text = chained;
            self.theme_preset_persist = null;
        }
        // keybind 재바인딩은 `keybind = chord = action` 줄이라 key=value 패스로 못 다룬다 — 전용 패스로 체이닝한다
        // (앞 단계 결과 텍스트 위에 keybind 줄을 action 기준 갱신/추가). 성공해야 양쪽 dirty를 비운다.
        if (self.config_keybind_rebinds.items.len > 0) {
            const chained = try config_mod.updateKeybindLines(self.allocator, text, self.config_keybind_rebinds.items);
            self.allocator.free(text);
            text = chained;
            self.config_keybind_rebinds.clearRetainingCapacity();
        }
        // 삭제 예약된 키(env 변수 삭제 등)는 줄을 제거한다 — 갱신 패스 뒤에 체이닝(삭제 우선). 같은 키를 갱신+삭제 둘 다면
        // 갱신이 먼저 줄을 남겨도 여기서 빠진다.
        if (self.config_removed_keys.items.len > 0) {
            const chained = try config_mod.removeConfigLines(self.allocator, text, self.config_removed_keys.items);
            self.allocator.free(text);
            text = chained;
            self.config_removed_keys.clearRetainingCapacity();
        }
        // keybind unbind — `keybind = chord = action` 줄을 action 기준으로 제거(keybind 갱신 패스 뒤, 제거 우선).
        if (self.config_keybind_removed.items.len > 0) {
            const chained = try config_mod.removeKeybindLines(self.allocator, text, self.config_keybind_removed.items);
            self.allocator.free(text);
            text = chained;
            self.config_keybind_removed.clearRetainingCapacity();
        }
        // 터미널 매크로 upsert — `keybind = <chord> = text:/esc:/ctrl:` 줄을 chord 기준 갱신/추가(전용 패스).
        if (self.config_terminal_macros.items.len > 0) {
            const chained = try config_mod.updateTerminalMacroLines(self.allocator, text, self.config_terminal_macros.items);
            self.allocator.free(text);
            text = chained;
            self.config_terminal_macros.clearRetainingCapacity();
        }
        // 터미널 매크로 삭제 — `keybind = <chord> = <매크로 rhs>` 줄을 chord 기준 제거(갱신 패스 뒤, 제거 우선).
        if (self.config_terminal_macro_removes.items.len > 0) {
            const chained = try config_mod.removeTerminalMacroLines(self.allocator, text, self.config_terminal_macro_removes.items);
            self.allocator.free(text);
            text = chained;
            self.config_terminal_macro_removes.clearRetainingCapacity();
        }
        // 빌트인 죽이기 — `keybind = chord = unbind` 지시어 append(사용자 줄 제거 뒤, 마지막).
        if (self.config_keybind_unbinds.items.len > 0) {
            const chained = try config_mod.appendKeybindUnbinds(self.allocator, text, self.config_keybind_unbinds.items);
            self.allocator.free(text);
            text = chained;
            self.config_keybind_unbinds.clearRetainingCapacity();
        }
        // stale unbind 정리 — 재바인딩으로 부활한 chord의 옛 `keybind = chord = unbind` 줄을 제거(append 패스 뒤 — append가 안
        // 쓴 chord를 여기서 빼 정리; 같은 chord를 죽임+부활 둘 다면 append는 펜딩에서 빠져 안 쓰고 여기서 옛 줄만 뺀다).
        if (self.config_keybind_unbind_removed.items.len > 0) {
            const chained = try config_mod.removeKeybindUnbindLines(self.allocator, text, self.config_keybind_unbind_removed.items);
            self.allocator.free(text);
            text = chained;
            self.config_keybind_unbind_removed.clearRetainingCapacity();
        }
        // 전역(OS) 단축키 재바인딩 — `keybind = global:<chord> = <action>` 줄을 action 기준 갱신/추가(in-app keybind 줄과
        // 별도 패스, global: 좌측만 매칭). 기존 keybind 체이닝 뒤에 둔다.
        if (self.config_global_rebinds.items.len > 0) {
            const chained = try config_mod.updateGlobalKeybindLines(self.allocator, text, self.config_global_rebinds.items);
            self.allocator.free(text);
            text = chained;
            self.config_global_rebinds.clearRetainingCapacity();
        }
        // 전역 단축키 해제 — `keybind = global:<chord> = <action>` 줄을 action 기준 제거(전역 갱신 패스 뒤, 제거 우선).
        if (self.config_global_removed.items.len > 0) {
            const chained = try config_mod.removeGlobalKeybindLines(self.allocator, text, self.config_global_removed.items);
            self.allocator.free(text);
            text = chained;
            self.config_global_removed.clearRetainingCapacity();
        }
        self.sidebar_config_buffer = text;
        self.config_dirty_keys.clearRetainingCapacity();
        return text;
    }

    /// 저장된 workspace 모델(한 창)을 이 세션에 적용해 탭/pane split 트리/Term을 재생성한다(R4 복원). init이 만든
    /// 기본 탭을 모델대로 교체한다 — 각 Term은 저장된 cwd에서 새 셸을 spawn한다(셸 상태가 아니라 cwd·레이아웃 복원).
    /// title/command는 정적 기본(셸이 OSC 0/2로 곧 재설정)·size는 모델값(이후 resize가 창에 맞게 보정). 새 탭들을
    /// 먼저 다 빌드한 뒤 기존 탭을 teardown하고 swap한다 — 빌드 실패면 새 것만 정리하고 기존 세션을 보존한다.
    /// 빈 모델이면 무동작(기본 유지). 빈 cwd면 기본 cwd로 spawn(저장 안 됐거나 셸 통합 없음).
    pub fn applyWorkspaceWindow(self: *AppSession, win: maru.session.workspace.Window) !void {
        if (win.tabs.len == 0) return;

        // 1) 새 탭들을 먼저 다 빌드한다(아직 self.tabs에 안 넣음 — 실패하면 기존 세션 그대로 유지).
        var new_tabs: std.ArrayList(*Tab) = .empty;
        defer new_tabs.deinit(self.allocator);
        errdefer for (new_tabs.items) |t| self.destroyTabStandalone(t);
        try new_tabs.ensureTotalCapacity(self.allocator, win.tabs.len);
        for (win.tabs) |tab_model| {
            new_tabs.appendAssumeCapacity(try self.buildWorkspaceTab(tab_model));
        }

        // 2) swap이 실패하지 않게 컬렉션 capacity를 미리 잡는다(teardown 뒤 append가 무실패여야 half-state가 없다).
        try self.tabs.ensureTotalCapacity(self.allocator, new_tabs.items.len);
        try self.surface_ptrs.ensureTotalCapacity(self.allocator, new_tabs.items.len);

        // 3) 기존 탭 teardown(closeTab의 teardown과 같은 순서 — 마지막-탭 latch는 안 탄다) 후 새 탭 설치.
        for (self.tabs.items) |tab| self.destroyTabStandalone(tab);
        self.tabs.clearRetainingCapacity();
        self.surface_ptrs.clearRetainingCapacity();
        for (new_tabs.items) |tab| {
            self.tabs.appendAssumeCapacity(tab);
            self.surface_ptrs.appendAssumeCapacity(&tab.activePane().activeTerm().surface);
        }
        self.app_window.tabs = self.surface_ptrs.items;
        self.app_window.active_tab = @min(win.active_tab, self.tabs.items.len - 1);
        // 고정-prefix 불변식 강제(복원): clampMoveToGroup/countPinnedTabs는 "고정 탭이 앞쪽 [0, pinned_count)에
        // 연속"을 가정한다. 저장 순서를 그대로 복원하면(재정렬 안 함) #685 이전 빌드가 만든 [P,u,P,u]처럼 섞인
        // workspace가 들어와 드래그/토글 clamp가 엉뚱한 슬롯에 떨어진다. 여기서 stable-partition으로 고정을 전부
        // 앞으로 모은다(고정끼리·비고정끼리 상대 순서 유지). 불변식을 모든 진입 경로(토글·드래그·복원)에서 성립시킨다.
        self.stablePartitionPinned();
        // 트리·탭을 통째로 교체했으니 해제된 옛 트리를 가리키던 상호작용 포인터를 비워야 하는데, 위 destroyTabStandalone
        // 루프의 destroyPane이 invalidateForFreedPane(S1 chokepoint)으로 옛 Pane을 가리키던 호버·드래그 포인터를 이미
        // 비웠다(표적 무효화라 옛 Pane을 가리키던 tab_drag_pane도 포함). 지금은 시작 전용이라 드래그가 없지만,
        // mid-session 재적용(repo별 workspace 후속)에서도 같은 chokepoint가 UAF를 막는다 — 따로 리셋하지 않는다.
        // 복원된 모든 탭을 현재 창 grid로 맞춘다. apply는 resize를 안 부르고 각 surface는 저장 grid로 spawn되며,
        // caller의 resizeAppSessionFromWindow→resize()는 (활성 탭만 + last_resize_size dedup) 배경 탭과 primary
        // 활성 탭을 빠뜨린다. 여기서 전 탭을 명시적으로 맞춰 dedup·활성탭-한정을 둘 다 우회한다(best-effort).
        for (self.tabs.items) |tab| self.resizeTabPanes(tab);
        // 활성 탭의 대표 surface는 위 swap 루프가 이미 surface_ptrs[*]에 바인딩했고 active_pane도 빌드 때
        // 세팅됐다(focusPane(active==active)는 early-return no-op이라 호출하지 않는다). 좌표·사이드바만 갱신.
        self.recomputeActivePaneRect();
        self.rebuildSidebar() catch {};
        self.metal_dirty = true;
        if (builtin.mode == .Debug) assertPinnedPrefixRuntime(self); // 복원 후 불변식 확인(디버그)
    }

    /// 컬렉션에 안 든 Tab을 teardown·해제한다(closeTab의 teardown 부분 — 단, tabs/surface_ptrs는 호출자가 관리).
    /// 트리(tab.tree)가 세팅된 '완성된' 탭에만 쓴다(buildWorkspaceTab은 자기 granular errdefer로 미완성을 정리).
    fn destroyTabStandalone(self: *AppSession, tab: *Tab) void {
        // rename 대상이 이 워크스페이스(또는 그 안 pane/Term)면 비운다 — pane/Term은 아래 destroyPane/destroyTerm
        // 가드가 처리하지만, 워크스페이스 자체 rename은 여기서. teardown 중이라 직접 null(부수효과 없이).
        if (self.renamingWorkspace(tab)) {
            self.rename = null;
            self.rename_input.clear();
        }
        // 컨텍스트 메뉴 대상이 이 워크스페이스면 메뉴를 닫고 대상을 비운다(stale 포인터 방지). pane/Term은 아래
        // destroyPane/destroyTerm가 처리.
        if (self.context_menu_target) |t| if (std.meta.activeTag(t) == .workspace and t.workspace == tab) {
            self.context_menu_target = null;
            self.chrome_host.context_menu.hide();
        };
        for (tab.panes.items) |pane| self.destroyPane(pane);
        // 트리를 통째 해제하기 전에, divider_drag가 이 트리 소속 split이면 표적 null(다른 탭 트리를 가리키면 유지 —
        // 무관한 탭 close가 진행 중 divider 드래그를 안 끊는다). collapse 경로의 invalidateForFreedSplit과 같은 규율.
        if (self.divider_drag) |dd| {
            if (PaneTree.containsSplit(tab.tree, dd)) self.divider_drag = null;
        }
        if (tab.custom_name) |n| self.allocator.free(n); // 워크스페이스 사용자 rename(owned) 해제
        PaneTree.deinit(self.allocator, tab.tree); // heap split 노드 해제(leaf surface는 destroyPane가 이미)
        tab.panes.deinit(self.allocator);
        self.allocator.destroy(tab);
    }

    /// 모델 Tab → 완성된 *Tab(panes + split 트리). pane들을 먼저 만들고(각 첫 surface로 spawn + 나머지 Term 추가),
    /// 트리를 모델 preorder대로 직접 짓는다(leaf 인덱스 → 그 pane, split → 새 PaneTree.Split). 부분 실패는 granular
    /// errdefer로 정리(트리는 아직 미세팅이라 destroyTabStandalone 안 씀). capacity 예약으로 append를 무실패화.
    fn buildWorkspaceTab(self: *AppSession, m: maru.session.workspace.Tab) !*Tab {
        if (m.panes.len == 0) return error.EmptyTab;
        const tab = try self.allocator.create(Tab);
        errdefer self.allocator.destroy(tab);
        tab.* = .{};
        errdefer tab.panes.deinit(self.allocator);
        errdefer for (tab.panes.items) |p| self.destroyPane(p);

        try tab.panes.ensureTotalCapacity(self.allocator, m.panes.len);
        for (m.panes) |pm| tab.panes.appendAssumeCapacity(try self.buildWorkspacePane(pm));

        // 트리 빌드 — 새로 만든 split 노드를 추적해 에러 시 전부 해제(트리 미완성이라 PaneTree.deinit 못 씀).
        // capacity를 split 노드 수만큼 미리 잡아 추적 append를 무실패화한다: create 직후 append가 OOM이면 그
        // split이 추적되지 않아 누수되므로, 예약된 무실패 append로 create↔추적 사이의 빈틈을 없앤다.
        var split_count: usize = 0;
        for (m.tree) |n| switch (n) {
            .split => split_count += 1,
            .leaf => {},
        };
        var splits: std.ArrayList(*PaneTree.Split) = .empty;
        defer splits.deinit(self.allocator);
        try splits.ensureTotalCapacity(self.allocator, split_count);
        errdefer for (splits.items) |s| self.allocator.destroy(s);
        // 트리 leaf↔pane 1:1 검증용(corruption graceful). 손상 파일이 같은 pane을 두 leaf로 참조하면 같은 *Pane이
        // 트리에 두 번 들어가 close 시 removeLeaf가 첫 매치만 접고 destroyPane이 free → 두 번째 leaf가 dangling(UAF).
        // 미참조 pane은 보이지 않는 라이브 셸(고아)이 된다. 각 pane이 정확히 1회 참조되는지 확인해 둘 다 막는다.
        const used = try self.allocator.alloc(bool, tab.panes.items.len);
        defer self.allocator.free(used);
        @memset(used, false);
        var idx: usize = 0;
        const root = try Model.buildTreeNode(self.allocator, tab.panes.items, m.tree, &idx, &splits, used);
        if (idx != m.tree.len) return error.MalformedTree; // preorder를 다 안 소비했다(노드 수 불일치)
        for (used) |u| if (!u) return error.MalformedTree; // 트리가 참조 안 한 고아 pane(보이지 않는 라이브 셸) 차단
        tab.tree = root;
        tab.active_pane = @min(m.active_pane, tab.panes.items.len - 1);
        // 워크스페이스 사용자 rename 복원 — 마지막 fallible 단계로 둬, OOM 시 위 errdefer(panes·tab)가 정리하고
        // custom_name은 아직 미할당이라 누수가 없다.
        tab.custom_name = try self.dupeCustomName(m.custom_name);
        tab.pinned = m.pinned; // 위치 고정 복원
        tab.background_color = m.background_color; // 카드 배경 tint 복원
        return tab;
    }

    /// 모델 preorder TreeNode 한 subtree를 소비해 PaneTree.Node를 만든다. leaf는 panes[idx]를, split은 새 Split
    /// (dir/ratio)을 할당하고 뒤따르는 두 subtree(a,b)를 재귀로 짓는다. 할당한 split은 splits에 추적(에러 해제용).
    // buildWorkspaceTreeNode(workspace.TreeNode → PaneTree.Node 복원)는 session core로 이동(§3.1) —
    // Model.buildTreeNode(self.allocator 대신 allocator 인자로 pure화). 단일 출처: src/session/session_model.zig.

    /// 모델 Pane → 완성된 *Pane. 첫 surface로 createPane(=1 Term)하고 나머지 surface를 Term으로 추가한다.
    fn buildWorkspacePane(self: *AppSession, m: maru.session.workspace.Pane) !*Pane {
        if (m.surfaces.len == 0) return error.EmptyPane;
        const pane = try self.createPaneFromSurface(m.surfaces[0]);
        errdefer self.destroyPane(pane);
        pane.custom_name = try self.dupeCustomName(m.custom_name); // pane 사용자 rename 복원(errdefer destroyPane이 정리)
        try pane.terms.ensureTotalCapacity(self.allocator, m.surfaces.len);
        for (m.surfaces[1..]) |sm| pane.terms.appendAssumeCapacity(try self.createTermFromSurface(sm));
        pane.active_term = @min(m.active_term, pane.terms.items.len - 1);
        return pane;
    }

    /// 복원 surface 하나로 spawn 준비(createPane/createTerm 공통). new_tab_config에 저장 grid를 얹고, 사용 가능한
    /// (존재하는 디렉터리) cwd면 그걸 쓴다 — 마지막 create 호출만 두 함수가 다르다. 모델의 command(argv[0])·title은
    /// v1 복원에선 쓰지 않는다(기본 셸·"Maru"로 spawn; 정확한 argv·제목 복원은 후속) — 저장은 향후 복원용으로만.
    fn restoreSpawn(self: *AppSession, sm: maru.session.workspace.Surface, args_buf: [][]const u8) struct { req: maru.pty.SpawnRequest, size: terminal.Size } {
        var cfg = self.new_tab_config;
        const size = restoreSurfaceSize(sm);
        cfg.size = size;
        // claude/codex 세션 자동 resume(opt-in) — agent 정보가 있고 토글이 켜졌으면 기본 셸 대신 resume 명령으로 띄운다.
        if (self.agentResumeRequest(sm, size, args_buf)) |req| return .{ .req = req, .size = size };
        var req = spawnRequest(cfg, self.loaded_config.config.term, self.loaded_config.config.shell, self.loaded_config.config.env, self.new_tab_zdotdir, self.new_tab_ssh_bin);
        if (usableRestoreCwd(sm.cwd)) |c| req.cwd = c; // 존재하는 디렉터리면 거기서, 아니면 기본 cwd(surface 안 잃음)
        return .{ .req = req, .size = size };
    }

    /// (workspace restore) sm이 claude/codex 에이전트이고 해당 토글이 켜졌으면 resume SpawnRequest를 만든다(아니면
    /// null → 기본 셸). command=보존 argv[0](exec_path 절대경로), args=정확한 session_id로 재구성한 argv(session_id가
    /// 없으면 --continue/resume --last 폴백). 셸이 아니라 바이너리 직접 exec이라 login=false다 — exec_path 절대경로라
    /// 에이전트 바이너리 자체는 PATH 무관하게 뜨지만, 에이전트가 spawn하는 하위 도구(git·rg 등)의 PATH는 login 셸이
    /// 아니라 maru 프로세스 env 기준이라 다를 수 있다(behavioral 한계 — 후속). args 슬라이스는 호출자 스택의 args_buf를
    /// 가리킨다 — createTermFromSurface가 동기 spawn하므로 spawn까지 유효. 단일 출처: docs/workspace-restore.md "에이전트 세션 자동 resume".
    fn agentResumeRequest(self: *AppSession, sm: maru.session.workspace.Surface, size: terminal.Size, args_buf: [][]const u8) ?maru.pty.SpawnRequest {
        const kind = app.agent_resume.Kind.fromString(sm.agent_kind) orelse return null;
        const enabled = switch (kind) {
            .claude => self.loaded_config.config.workspace.restore_claude,
            .codex => self.loaded_config.config.workspace.restore_codex,
        };
        if (!enabled or sm.agent_argv.len == 0 or sm.agent_argv[0].len == 0) return null;
        const args = app.agent_resume.rebuildAgentArgv(kind, sm.agent_argv, sm.agent_session, args_buf);
        var req: maru.pty.SpawnRequest = .{
            .command = sm.agent_argv[0], // exec_path 절대경로(PATH 의존 제거)
            .args = args,
            .login = false, // 셸 아닌 에이전트 바이너리 직접 exec
            .size = size,
        };
        req.term = self.loaded_config.config.term;
        req.env_overrides = self.loaded_config.config.env;
        req.zdotdir = self.new_tab_zdotdir;
        req.ssh_integration_bin = self.new_tab_ssh_bin;
        if (usableRestoreCwd(sm.cwd)) |c| req.cwd = c;
        return req;
    }

    /// 직렬화 모델의 custom_name(""=없음)을 라이브 owned `?[]const u8`(null=없음)로 변환한다 — 비면 null,
    /// 아니면 세션 allocator로 dupe. 복원과 rename commit(PR3)이 공유하는 ""→null 단일 변환점이라 규칙이 한 곳뿐이다.
    fn dupeCustomName(self: *AppSession, name: []const u8) !?[]const u8 {
        if (name.len == 0) return null;
        return try self.allocator.dupe(u8, name);
    }

    fn createPaneFromSurface(self: *AppSession, sm: maru.session.workspace.Surface) !*Pane {
        var args_buf: [maru.session.workspace.max_agent_argv + 4][]const u8 = undefined;
        const rs = self.restoreSpawn(sm, &args_buf);
        const cfg = self.new_tab_config;
        const pane = try self.createPane(rs.req, rs.size, cfg.queue_capacity, "Maru", commandName(cfg.command_kind));
        errdefer self.destroyPane(pane);
        // 첫 Term(=이 surface)의 사용자 rename 복원. 실패 시 errdefer destroyPane이 정리한다.
        pane.activeTerm().surface.custom_name = try self.dupeCustomName(sm.custom_name);
        return pane;
    }

    fn createTermFromSurface(self: *AppSession, sm: maru.session.workspace.Surface) !*Term {
        var args_buf: [maru.session.workspace.max_agent_argv + 4][]const u8 = undefined;
        const rs = self.restoreSpawn(sm, &args_buf);
        const cfg = self.new_tab_config;
        const term = try self.createTerm(rs.req, rs.size, cfg.queue_capacity, "Maru", commandName(cfg.command_kind));
        errdefer self.destroyTerm(term);
        term.surface.custom_name = try self.dupeCustomName(sm.custom_name);
        return term;
    }

    /// quick terminal 표시 옵션(config에서 파싱). Swift가 패널 크기·화면·자동 숨김에 쓴다. 세션 동안 불변.
    pub fn quickTerminalConfig(self: *const AppSession) QuickTerminalConfig {
        const qt = self.loaded_config.config.quick_terminal;
        return .{
            .height_milli = @intFromFloat(@round(qt.height_fraction * 1000.0)),
            .auto_hide = if (qt.auto_hide) 1 else 0,
            .screen = @intFromEnum(qt.screen),
            .position = @intFromEnum(qt.position),
            .chrome = @intFromEnum(qt.chrome),
            .minimal_tabs = if (qt.minimal_tabs) 1 else 0,
            .width_milli = @intFromFloat(@round(qt.width_fraction * 1000.0)),
        };
    }

    /// 한 화면씩 스크롤(Shift+PageUp/Down). delta_pages>0=위(과거). 한 화면은 rows-1줄(한 줄 겹침)이고,
    /// rows는 app session이 권위 있게 알고 있어 Swift가 stale 값으로 계산하지 않게 여기서 구한다.
    // pageScrollDelta는 session core로 추출됐다(위 file-scope alias=input_math.pageScrollDelta로 호출).
    // 정의·단위 테스트는 src/session/input_math.zig.

    pub fn scrollPage(self: *AppSession, delta_pages: i32) void {
        if (!self.surface_initialized) return;
        const rows = self.activeSurface().core.size.rows;
        const page: i32 = @max(@as(i32, 1), @as(i32, rows) - 1);
        self.scrollLines(delta_pages *| page);
    }

    /// 이전(dir<0)/다음(dir>0) 프롬프트 블록으로 뷰포트를 점프한다(OSC 133 셸 통합 필요 — Cmd+↑/↓).
    /// 분류·이동 로직은 core가 소유하고, 여기선 스크롤됐으면 다음 tick이 다시 그리도록 metal_dirty만
    /// 세운다(Swift는 방향만 넘기는 얇은 글루 — scrollPage와 같은 규율).
    pub fn jumpToPrompt(self: *AppSession, dir: i8) void {
        if (!self.surface_initialized) return;
        // view_offset mutate라 reader로 위임(full (a), docs/io-render-threading.md §9 P3-4) — 위임된 scroll과 같은
        // 큐를 타 순서 보존(메인 직접 mutate면 reader scroll과 view_offset race). "스크롤됨" 최적화는 reader 렌더 트리거로 대체.
        self.runtime.enqueueCoreCommand(self.activeSurface().id, .{ .jump_to_prompt = dir }, self.io) catch {};
        self.metal_dirty = true;
    }

    pub fn resize(self: *AppSession, width_px: u32, height_px: u32, scale_milli: u32) !FrameSummary {
        // resize는 terminal grid와 PTY winsize가 함께 바뀌어야 한다. FrameLoop API를
        // 통해 SurfaceRuntime action으로 내려보내면 Swift가 두 책임을 다시 구현하지 않는다.
        // total_resize_events는 아래 dedup early-return 뒤(실제 변화가 있는 resize)에서만 센다.
        // Swift가 콜백마다 backing 픽셀을 보내므로, 같은 size+scale 중복은 카운트에 넣지 않는다.
        // scale_milli를 [250,8000]로 막아 손상된 값에서도 곱이 비정상으로 커지지 않게 한다.
        const next_scale = std.math.clamp(scale_milli, 250, 8000);
        const scale_changed = next_scale != self.scale_milli;
        // backing scale이 바뀌면(다른 DPI 디스플레이로 이동 등) cell 메트릭을 분수 scale로 먼저
        // 다시 뽑는다. grid 계산이 placeholder가 아니라 실제 cell 크기를 쓰도록 순서가 중요하다.
        if (scale_changed) {
            self.scale_milli = next_scale;
            self.refreshCellMetrics();
        }
        // grid(cols/rows)를 Swift가 아니라 app session이 backing 픽셀 + 자기 cell 메트릭에서 직접
        // 계산한다. init이 메트릭을 미리 뽑으므로 cell 크기는 항상 준비돼 있어, Swift가 첫 resize에서
        // placeholder 크기로 cols/rows를 잘못 잡던(창과 grid가 어긋나던) 문제가 사라진다.
        const size = layout_math.gridFromBacking(width_px, height_px, self.cell_width_px, self.cell_height_px, self.sidebar_width_px, self.gridPadding());
        const size_changed = self.last_resize_size == null or
            self.last_resize_size.?.cols != size.cols or self.last_resize_size.?.rows != size.rows;
        // 같은 size+scale이면 비싼 재작업(TerminalCore.resize alloc/memcpy + PTY winsize/SIGWINCH)을
        // 건너뛴다. Swift의 windowDidResize·backing 콜백·tick 폴링이 한 변화에 여러 번 부를 수
        // 있는데, 매번 적용하면 셸이 SIGWINCH storm으로 다시 그린다(중복방지를 Swift가 아니라
        // 여기서 한 곳에서 처리).
        if (!scale_changed and !size_changed) {
            self.writeSummaryFromState();
            self.last_summary.last_event_kind = @intFromEnum(EventKind.resize);
            return self.last_summary;
        }
        // dedup을 통과한(실제 size/scale 변화가 있는) resize만 센다.
        self.total_resize_events += 1;
        // 종료된 세션의 resize도 live surface가 없어 실패한다. 닫히는 창의 late resize는
        // 치명적 오류가 아니므로 무시하고 정상으로 닫는다(key와 같은 정책).
        if (self.ended_seen) {
            self.writeSummaryFromState();
            self.last_summary.last_event_kind = @intFromEnum(EventKind.resize);
            return self.last_summary;
        }
        // backing 크기를 갱신하고(split leaf rect 계산의 입력) 활성 탭의 각 panel을 자기 leaf rect grid로
        // 재배치한다. 단일 leaf면 활성 surface 하나를 full term grid로 — 기존 resizeActiveSurface와 동일.
        self.backing_width_px = width_px;
        self.backing_height_px = height_px;
        try self.resizeActiveTabPanes();
        self.recomputeActivePaneRect(); // backing/grid가 바뀌었으니 활성 panel rect(좌표 origin)도 갱신
        self.last_resize_size = size;
        // grid가 reflow됐으므로 다음 tick이 Metal frame을 재투영하게 dirty로 표시한다.
        self.metal_dirty = true;
        self.writeSummaryFromState();
        self.last_summary.last_event_kind = @intFromEnum(EventKind.resize);
        return self.last_summary;
    }

    /// MARU_DEBUG일 때 활성 surface의 cell 격자를 찍는다. CJK 등 비-ASCII는 텍스트 줄에서
    /// 공백으로 보이지만 배경 줄(b...)의 'B'로 영역을 알 수 있어, 파란 배경 줄과 프롬프트 줄이
    /// 같은 row에 겹치는지(개행 안 됨) 다른 row인지 데이터로 구분한다.
    fn logScreenIfDebug(self: *AppSession) void {
        if (!diag_gate.maruDebugEnabled() or !self.surface_initialized) return;
        const core = &self.activeSurface().core;
        const cols = @min(@as(usize, core.size.cols), 240);
        // 헤더에 OSC 133 마지막 명령 종료코드도 찍는다(셸 통합이 emit하면 채워진다).
        if (core.last_command_exit) |code| {
            screen_diag.info("=== screen {d}x{d} cursor=({d},{d}) last_exit={d} ===", .{
                core.size.cols, core.size.rows, core.screen.cursor.row, core.screen.cursor.col, code,
            });
        } else {
            screen_diag.info("=== screen {d}x{d} cursor=({d},{d}) ===", .{
                core.size.cols, core.size.rows, core.screen.cursor.row, core.screen.cursor.col,
            });
        }
        // OSC 7로 셸이 보고한 cwd(셸 통합이 emit하면 채워진다). 창 제목이 읽는 값을 데이터로 확인.
        const cwd = core.currentCwd();
        if (cwd.len > 0) screen_diag.info("cwd={s}", .{cwd});
        var text: [240]u8 = undefined;
        var bg: [240]u8 = undefined;
        const grid_cols: usize = core.size.cols;
        for (0..core.size.rows) |row| {
            var any = false;
            for (0..cols) |col| {
                const cell = core.screen.cells[row * grid_cols + col];
                const cp = cell.codepoint;
                text[col] = if (cp >= 0x20 and cp < 0x7f) @intCast(cp) else ' ';
                const has_bg = switch (cell.style.background) {
                    .default => false,
                    else => true,
                };
                bg[col] = if (has_bg) 'B' else '.';
                if ((cp != 0 and cp != ' ') or has_bg) any = true;
            }
            // soft-wrap 플래그를 함께 찍는다(w=다음 줄로 이어짐, .=hard 줄끝). reflow 피드백 루프
            // 회귀는 hard 줄(프롬프트)이 w로 잘못 찍히는 것으로 드러나므로, wrapped인 빈 줄도 보인다.
            const w_mark: u8 = if (row < core.screen.wrapped.len and core.screen.wrapped[row]) 'w' else '.';
            // OSC 133 semantic 분류(P=프롬프트 I=입력 C=명령출력 ·=미분류). 셸 통합이 마커를 emit하면
            // 채워진다 — 프롬프트/입력/출력이 어떤 행으로 잡히는지 데이터로 본다(거터 PR 전 조기 확인).
            const p_mark: u8 = if (row < core.screen.prompt_marks.len) switch (core.screen.prompt_marks[row].kind) {
                .unknown => '.',
                .prompt => 'P',
                .input => 'I',
                .command => 'C',
            } else '.';
            if (!any and w_mark != 'w' and p_mark == '.') continue;
            screen_diag.info("r{d:0>2} {c}{c} t|{s}|", .{ row, w_mark, p_mark, text[0..cols] });
            screen_diag.info("r{d:0>2} {c}{c} b|{s}|", .{ row, w_mark, p_mark, bg[0..cols] });
        }
    }

    /// 프레임마다 셸 의미 이벤트(OSC 133/7)를 소비한다 — MARU_DEBUG면 명령 경계를 구조화 한 줄씩
    /// 찍고, 항상 비워 core의 이벤트 버퍼를 bounded하게 유지한다(누구도 drain 안 하면 cap에서 드롭).
    /// 같은 도메인 데이터를 후속 trace writer도 바로 이 자리에서 drain하면 된다(관측 가능성 원칙).
    fn drainShellEventsForFrame(self: *AppSession) void {
        if (!self.surface_initialized) return;
        const core = &self.activeSurface().core;
        if (core.shellEvents().len == 0 and !core.shellEventsOverflowed()) return;
        if (diag_gate.maruDebugEnabled()) {
            for (core.shellEvents()) |ev| switch (ev) {
                .prompt_start => |r| shell_diag.info("shell.prompt-start row={d}", .{r}),
                .input_start => |r| shell_diag.info("shell.input-start row={d}", .{r}),
                .command_start => |r| shell_diag.info("shell.command-start row={d}", .{r}),
                .command_end => |ce| if (ce.exit) |code|
                    shell_diag.info("shell.command-end row={d} exit={d}", .{ ce.row, code })
                else
                    shell_diag.info("shell.command-end row={d} exit=?", .{ce.row}),
                .cwd_changed => shell_diag.info("shell.cwd-changed cwd={s}", .{core.currentCwd()}),
            };
            // 조용한 손실 방지: cap을 넘어 드롭된 이벤트가 있으면 보고한다.
            if (core.shellEventsOverflowed()) shell_diag.info("shell.events OVERFLOW: cap 초과로 일부 이벤트 드롭", .{});
        }
        core.clearShellEvents();
    }

    /// 각 Term의 포그라운드 프로세스(claude/codex)를 throttled로 polling해 agent_kind를 갱신한다. 매 tick
    /// syscall은 비싸므로 agent_poll_interval_ms(≈0.5s)마다. 변화가 있으면 metal_dirty로 재렌더(심볼 표시 갱신).
    fn pollAgentKinds(self: *AppSession) void {
        self.agent_poll_ticks += 1;
        if (self.agent_poll_ticks < self.agentPollIntervalTicks()) return;
        self.agent_poll_ticks = 0;
        if (!self.surface_initialized) return;
        // **모든 pane × 모든 Term**을 poll한다 — background split pane·가로탭(Term)에서 끝난 에이전트도 완료 알림을
        // 내고, 클릭이 그 Term으로 점프하려면(activateSurfaceById) 발신 Term의 surface_id가 필요하기 때문이다. 예전엔
        // 탭당 활성 pane의 활성 Term 하나만 poll해(사이드바가 그 Term만 보여줘서), 비활성 pane/Term에서 끝난 에이전트는
        // 완료 알림 자체가 안 났고 docs/notifications.md "split panel+가로탭까지 포커스" 능력이 사실상 트리거되지 않았다.
        // 비용 가드: foregroundProcessName syscall은 agent_poll_interval_ms(≈0.5s)로 throttle되고, metal_dirty(재렌더)는
        // **사이드바에 보이는** Term(워크스페이스별 활성 pane의 활성 Term)의 변화에만 올린다 — 안 보이는 Term의 agent_kind/
        // 상태 변화로 동일 프레임을 헛 재렌더하지 않게(예전 code-review 지적 보존; 안 보이는 Term은 표시될 때 switch가 dirty).
        // is_current(완료 알림 억제 게이트)는 **Term 단위**다 — 사용자가 지금 실제로 그 안에 있는 Term 하나(포커스 창의
        // 활성 탭·활성 pane·활성 Term)뿐 억제하고, 그 외 모든 Term(비활성 탭·활성 탭의 background split·background 가로탭)은
        // 완료 시 알림한다. 탭 단위로 묶으면 같은 탭의 다른 pane에서 끝난 에이전트를 알림으로 열람·점프할 길이 막혀 직관에
        // 어긋난다(사용자 피드백). 창이 비포커스면 어떤 Term도 "지금 보는" 게 아니라(null) 전부 알림한다.
        var buf: [256]u8 = undefined;
        const focused_term: ?*Term = if (self.window_focused) self.activeTab().activePane().activeTerm() else null;
        for (self.tabs.items) |tab| {
            const shown_term = tab.activePane().activeTerm(); // 이 워크스페이스 사이드바 행이 보여주는 Term
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (!term.rt.live_initialized or term.rt.terminated) continue; // 종료(미reap) Term은 건너뜀(dispatchBell과 동형)
                    const displayed = term == shown_term; // 사이드바에 이 Term이 보이는가(재렌더 게이트)
                    const prev = term.agent_kind;
                    term.agent_kind = classifyAgent(term.rt.live_pty.session.foregroundProcessName(&buf));
                    if (term.agent_kind != prev) {
                        if (displayed) self.metal_dirty = true; // 보이는 Term의 에이전트 변화만 재렌더
                        if (diag_gate.maruDebugEnabled()) std.log.scoped(.agent).info("agent: {s}", .{@tagName(term.agent_kind)});
                        // kind가 바뀌면(새 에이전트 시작/종료/claude↔codex 직접 전환) 상태 캐시를 **전부** 리셋한다 —
                        // 옛 세션의 mtime/상태/답변이 새 에이전트로 새지 않게. 특히 agent_state를 unknown으로 되돌려야
                        // 직접 전환(claude .running → codex) 때 stale한 prev_state로 가짜 running→idle 알림이 안 뜬다.
                        term.agent_session_mtime = 0;
                        term.agent_state = .unknown;
                        term.agent_answer_len = 0;
                    }
                    const is_current = focused_term != null and term == focused_term.?; // 지금 그 안에 있는 그 Term만 억제
                    if (term.agent_kind != .none) self.pollAgentState(term, tab, is_current, displayed);
                }
            }
        }
    }

    /// 에이전트 포그라운드인 Term의 진행 상태(running/idle)를 세션 JSONL tail로 갱신한다. 세션 파일 위치 I/O는
    /// agent_session(L4)이, 바이트→상태 판정은 session core가 한다. cwd(OSC 7)를 모르면(아직 미보고) 보류한다 —
    /// 잘못된 cwd로 엉뚱한 세션을 읽지 않게. mtime이 직전과 같으면 agent_session.poll이 재파싱을 건너뛴다.
    /// `is_current`=사용자가 지금 그 안에 있는 그 Term(포커스 창의 활성 탭·활성 pane·활성 Term) — 그게 아닌데(비활성 탭·
    /// background split·background 가로탭) running→idle로 끝나면 완료 알림을 큐에 넣는다(Term 단위 — 같은 탭 다른 pane도 알림).
    /// `displayed`=이 Term이 사이드바에 보이는가(워크스페이스별 활성 pane의 활성 Term) — 상태/답변 변화 시 metal_dirty는
    /// 보이는 Term에만 올린다(안 보이는 background Term까지 poll하면서 헛 재렌더하지 않게 — pollAgentKinds 게이트와 짝).
    fn pollAgentState(self: *AppSession, term: *Term, tab: *Tab, is_current: bool, displayed: bool) void {
        const kind: agent_session.Kind = switch (term.agent_kind) {
            .none => return,
            .claude => .claude,
            .codex => .codex,
        };
        // cwd는 reader 스레드가 core_mutex 아래 OSC 7로 free·재할당하므로(dispatchOscCwd), 락 없이 들고 있으면
        // use-after-free/torn read가 난다(focusedTermCwd와 같은 함정). 락 아래에서 읽어 즉시 로컬 버퍼로 복사해 끊는다 —
        // 이후 세션 파일 I/O는 코어 수명과 무관한 cwd_buf 슬라이스로 한다(background Term까지 poll하며 노출이 늘어 필수).
        var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
        const cwd = blk: {
            term.surface.lockCore(self.io);
            defer term.surface.unlockCore(self.io);
            const live = term.surface.core.currentCwd();
            if (live.len == 0 or live.len > cwd_buf.len) break :blk "";
            @memcpy(cwd_buf[0..live.len], live);
            break :blk cwd_buf[0..live.len];
        };
        if (cwd.len == 0) return; // OSC 7 cwd 아직 없음 — 다음 poll에.
        const home: []const u8 = if (std.c.getenv("HOME")) |h| std.mem.span(h) else return;
        const subdir: []const u8 = switch (kind) {
            .claude => ".claude/projects",
            .codex => ".codex/sessions",
        };
        var root_buf: [4096]u8 = undefined;
        const root = std.fmt.bufPrint(&root_buf, "{s}/{s}", .{ home, subdir }) catch return;

        const prev_state = term.agent_state;
        const r = agent_session.poll(self.io, self.allocator, kind, root, cwd, term.agent_session_mtime, &term.agent_answer_buf);
        const new_state = r.state orelse {
            term.agent_session_mtime = r.mtime; // null = mtime 동일 — 갱신 무해, 직전 상태 유지(재파싱 skip)
            return;
        };
        // unknown(세션 못 찾음 / tail에 완전한 엔트리 없음)은 **직전 상태를 보존**한다(AgentState.unknown 계약).
        // running을 unknown으로 덮으면 사이드바가 깜빡이고, running→idle 전환 edge를 놓쳐 완료 알림이 누락된다.
        // mtime을 갱신하지 않아 다음 poll에 다시 시도한다(거대 단일 줄/쓰는 중이던 경우 곧 완전한 줄이 보임).
        if (new_state == .unknown) return;
        term.agent_session_mtime = r.mtime;
        const new_answer_len: usize = if (new_state == .idle) r.answer_len else 0;
        if (new_state != term.agent_state or new_answer_len != term.agent_answer_len) {
            if (displayed) self.metal_dirty = true; // 보이는 Term의 상태/답변 변화만 사이드바 재렌더(pollAgentKinds 게이트와 짝)
            if (diag_gate.maruDebugEnabled()) std.log.scoped(.agent).info("agent state: {s}", .{@tagName(new_state)});
        }
        term.agent_state = new_state;
        term.agent_answer_len = new_answer_len;
        // 완료 알림: running→idle 전환을 처음 관측했고(전환 edge가 자연 디바운스 — idle 유지 중엔 mtime-skip으로
        // 재진입 안 함), "보고 있는" 탭이 아니며, config가 켜졌을 때만. unknown→idle(원래 idle이던 세션)은 알림 안 함.
        if (prev_state == .running and new_state == .idle and !is_current and self.loaded_config.config.notifications.agent_complete) {
            self.enqueueAgentCompletion(tab, term);
        }
    }

    /// 완료 알림 한 건을 큐에 넣는다 — title=`{✶|◆} {Claude|Codex} · {끝난 Term 라벨}`(아래), body=마지막 답변
    /// 평탄화 미리보기 또는 "완료". owned dup 실패는 조용히 버린다(best-effort — 알림은 부가 기능). 큐가 상한이면
    /// 가장 오래된 걸 버려 폭주를 막는다.
    fn enqueueAgentCompletion(self: *AppSession, tab: *Tab, term: *Term) void {
        // 제목 = **에이전트 심볼 + 종류(Claude/Codex)** + **끝난 그 Term(세션) 라벨** — 어느 대화가 끝났는지 식별
        // (사용자 요청). 심볼은 사이드바 에이전트 아이콘과 **의미가 같은** 종류 표시(✶ claude=선버스트, ◆ codex)로
        // 알림에서도 종류가 한눈에 구분된다(macOS 알림 왼쪽 큰 아이콘은 앱 아이콘 고정이라 제목 prefix로 구분).
        // 알림 제목은 OS 폰트라 **실제 유니코드 `agentSymbolCodepoint`**(✶◆)를 쓴다 — 사이드바는 maru 합성
        // `agentIconCodepoint`(PUA sparkle/diamond)로, 둘은 의미 1:1이되 OS vs maru 렌더 차이로 codepoint가 갈린다.
        // 옛 제목은 workspaceLabel(tab)=tab.activeTerm 라벨이라 background split/가로탭 Term 완료 시 활성 Term 이름이
        // 떠 어긋났다 — 끝난 term의 termLabel을 직접 써 그 세션을 가리킨다. 종류 없음(이론상 미발생)이면 워크스페이스 폴백.
        const agent_name: []const u8 = switch (term.agent_kind) {
            .claude => "Claude",
            .codex => "Codex",
            .none => "",
        };
        const session_label = termLabel(term);
        const title = if (agent_name.len > 0)
            // {u}=심볼 codepoint를 UTF-8로(agentSymbolCodepoint 단일 출처) + 종류명 + 세션 라벨.
            std.fmt.allocPrint(self.allocator, "{u} {s} · {s}", .{ agentSymbolCodepoint(term.agent_kind), agent_name, session_label }) catch return
        else
            self.allocator.dupe(u8, workspaceLabel(tab)) catch return;
        const body_src: []const u8 = if (term.agent_answer_len > 0) term.agent_answer_buf[0..term.agent_answer_len] else "완료";
        const body = self.allocator.dupe(u8, body_src) catch {
            self.allocator.free(title);
            return;
        };
        if (self.agent_notifications.items.len >= agent_notification_cap) {
            const dropped = self.agent_notifications.orderedRemove(0);
            self.allocator.free(dropped.title);
            self.allocator.free(dropped.body);
        }
        // surface_id는 알림 클릭 시 그 Term으로 점프하기 위한 식별자다(term은 heap-pin이라 닫히기 전까지 유효하지만
        // 여기선 id 값만 복사하므로 수명 의존이 없다 — 클릭 시점에 id로 재조회한다).
        self.agent_notifications.append(self.allocator, .{ .title = title, .body = body, .surface_id = term.surface.id }) catch {
            self.allocator.free(title);
            self.allocator.free(body);
        };
    }

    /// 모든 Term의 자동 제목 캐시(auto_title)를 core_mutex 하에 갱신한다 — termLabel(렌더 스레드)이 reader 스레드의
    /// core.title/cwd free(OSC 0/2/7)와 경합하지 않게 owned 복사본을 만든다(io-render-threading PR3). 매 tick 호출.
    /// 라이브 windowTitle(OSC 제목 > cwd basename)이 비면 캐시를 비워 termLabel이 정적 surface.title로 폴백한다.
    /// OOM이면 append만 무시(라벨이 잠깐 비어 surface.title 폴백 — 안전). live_pty 미초기화 Term은 건너뛴다.
    fn syncAutoTitles(self: *AppSession) void {
        for (self.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (!term.rt.live_initialized) continue;
                    term.surface.lockCore(self.io);
                    defer term.surface.unlockCore(self.io);
                    const live = term.surface.core.windowTitle();
                    term.auto_title.clearRetainingCapacity();
                    if (live.len > 0) term.auto_title.appendSlice(self.allocator, live) catch {};
                }
            }
        }
    }

    pub fn tick(self: *AppSession) !FrameSummary {
        // macOS 제품 실행은 실제 CoreText shaper/rasterizer로 frame을 만든다(fake backend
        // 아님). 그래야 summary의 glyph/atlas 통계가 실제 rasterized glyph를 반영하고, 이후
        // 제품 Metal view가 같은 RenderFrame을 그대로 그릴 수 있다. CoreText는 platform
        // 경계라 builder가 소유한다.
        //
        // 비-macOS(주로 Linux CI의 ABI 계약 테스트)에는 CoreText 브리지 심볼이 없다. OS
        // 게이트는 comptime이라 Linux 빌드는 macOS 분기를 codegen에서 제외하므로 extern
        // 참조가 생기지 않고, frame loop 계약만 fake backend로 유지한다.
        // PTY queue를 non-blocking으로 비운다(output/exit 감지). 이 drain은 매 tick 필요하지만
        // 싸다. 생명주기 회계(이벤트 합산, 종료 reap)도 build 여부와 무관하게 매 tick 한다 —
        // Metal 투영이나 비싼 build가 실패/생략돼도 drained 이벤트나 finishAfterTermination
        // (reader join/child reap)을 건너뛰지 않게 한다.
        if (!self.update_started) { // 첫 tick에서 인앱 새 버전 안내 백그라운드 체크를 1회 띄운다(config로 끔)
            self.update_started = true;
            self.startUpdateCheck();
        }
        self.applyDragAutoscroll(); // 드래그가 grid 밖에 머무는 동안 frame-loop tick마다 한 줄씩 스크롤+확장
        self.flushPendingPaste(); // 큰 붙여넣기의 잔여를 자식이 읽는 속도에 맞춰 흘려보낸다
        self.drainUploadResults(); // 완료된 드롭 업로드의 원격 경로를 paste 큐로(백그라운드 스레드 → 메인)
        self.drainUpdateCheck(); // 인앱 새 버전 안내: 백그라운드 체크 결과를 알림으로(백그라운드 스레드 → 메인)
        self.pollAgentKinds(); // 포그라운드 프로세스(claude/codex) polling — throttled, 각 Term agent_kind 갱신
        self.syncAutoTitles(); // 라벨용 자동 제목 캐시 갱신(core_mutex 하 owned 복사 — termLabel use-after-free 회피)
        // 모든 탭의 모든 panel의 모든 Term PTY를 drain한다 — 백그라운드 탭/panel/탭(Term)도 출력을 받게
        // (routing은 surface_id로 각 surface에 가고, frame은 아래에서 활성 탭만 빌드한다). summary는 보고용.
        var drain_summary: app.RuntimePumpDrainSummary = .{};
        for (self.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (!term.rt.live_initialized) continue;
                    const ds = try term.rt.pump.drainAvailable();
                    drain_summary.output_events += ds.output_events;
                    drain_summary.exit_events += ds.exit_events;
                    // Term별로 종료를 한 번만 finish(reader join + child reap). 세션 종료는 '모든' Term이 끝났을 때.
                    if (ds.ended != null and !term.rt.terminated) {
                        term.rt.live_pty.finishAfterTermination();
                        term.rt.terminated = true;
                        drain_summary.ended = ds.ended; // 마지막 관측 종료를 frame 보고에 싣는다
                    }
                }
            }
        }
        self.total_output_events += drain_summary.output_events;
        self.total_exit_events += drain_summary.exit_events;
        // 개별 Term이 exit하면(전부는 아닌) 그 Term을 자동으로 닫는다(계층 cascade: Term→pane→워크스페이스,
        // PR5b). 이번 tick에 새 종료가 관측됐을 때만 — 살아있는 Term이 있으면 같은 tick에 reap되고, 전부 죽으면
        // 아래 세션 종료 latch가 마지막을 맡는다(그래서 reap이 빈 세션을 만들지 않는다).
        if (drain_summary.ended != null) self.reapTerminatedTerms();
        // 세션(창) 종료: live 탭이 전부 terminated면. 단일 탭이면 그 탭이 끝나는 즉시(기존 동작 보존).
        if (!self.termination_finished and self.allTabsTerminated()) {
            self.ended_seen = true;
            self.termination_finished = true;
        }

        // 새 output이 있을 때만 frame이 바뀐다(resize는 resize()가 dirty를 세운다). idle tick은
        // 비싼 부분(buildDrawList + 전체 grid CoreText shape + atlas/raster 준비)을 통째로
        // 건너뛴다 — 출력 없는 셸이 매 frame-loop tick마다 grid를 다시 shape하느라 CPU를 태우거나
        // 머신이 idle/sleep으로 못 들어가게 하지 않는다. generation도 그대로라 재드로우도 생략된다.
        // 가정: 모든 시각 변화는 PTY output(또는 resize)에서 온다. cursor blink나 주기적 redraw
        // 같은 PTY와 무관한 변화를 넣게 되면, 그 트리거에서도 metal_dirty를 세워야 한다.
        if (drain_summary.output_events > 0) self.metal_dirty = true;
        // 깜빡임: 출력이 흐르면 보이는 위상으로 리셋(커서가 움직이는 동안 항상 보이게), idle이면 500ms마다 토글.
        // steady/숨김 커서 + 오버레이 닫힘이면 updateCursorBlink가 무토글로 고정한다. 오버레이 caret도 같은 위상으로
        // 깜빡이고, suffix-trim(setCursorVisible)이라 재빌드 없이 토글된다(터미널 커서와 같은 메커니즘 재활용).
        if (drain_summary.output_events > 0) self.resetCursorBlink() else self.updateCursorBlink();
        self.dispatchBell(); // BEL 1회 drain → audible/visual/dock-badge 분배(아래 frame이 flash·페이드 그림)
        self.updateScrollbarFade(); // 스크롤바 fade: view_offset 변화/hover/드래그로 full↔faint(appendScrollbar 전에 갱신)
        // synchronized output(DECSET 2026): sync 중이면 frame 투영을 멈춘다(metal_dirty는 쌓인 채 유지) — ESU(2026
        // reset)로 sync가 꺼지면 다음 tick에 누적 출력을 한 frame으로 투영한다(render skip과 동형). 단 ESU가
        // 영영 안 오면 freeze되므로 hold가 sync_timeout_ms를 넘으면 강제 해제한다(아래 sync_blocks).
        const sync_view = blk: {
            // sync_output(DECSET 2026)·view_offset은 리더 core.write/scroll이 set/clear — 같은 락 아래 읽는다
            // (docs/io-render-threading.md PR3). view_offset은 스크롤 리페인트를 sync hold에서 빼는 데 쓴다.
            const s = self.activeSurface();
            s.lockCore(self.io);
            defer s.unlockCore(self.io);
            break :blk .{ .sync = s.core.sync_output, .view_offset = s.core.view_offset };
        };
        const sync_active = sync_view.sync;
        const active_view_offset = sync_view.view_offset;
        if (sync_active) {
            self.sync_hold_ticks +|= 1;
        } else {
            self.sync_hold_ticks = 0;
        }
        // 투영 게이트(shouldProjectFrame): sync hold는 라이브 화면 tearing만 막고, 스크롤백 탐색(view_offset 변화)
        // 리페인트는 막지 않는다 — rapid 스크롤 시 sync에 막혀 viewport가 stale로 멈추던 버그 수정. view_offset
        // 변화는 metal_dirty 누락(스크롤 reader 위임 race)에도 투영을 강제한다. timeout 넘긴 sync hold는 강제 해제.
        if (shouldProjectFrame(self.metal_dirty, sync_active, self.sync_hold_ticks, self.syncTimeoutTicks(), active_view_offset, self.last_rendered_view_offset)) {
            // 멀티 페인 통합 수집: atlas-쓰는 빌드를 shapeOnly로 모아, replace 전 placeAndDistribute가 한 번의
            // placeMultiPane(한 atlas 세대)으로 배치+분배한다 — 개별 buildFromDrawList가 invalidate로 앞 페인을
            // 무효화하는 cross-pane 깨짐을 차단한다. defer는 place 전 에러로 빠질 때만 남은 ShapedPane을 정리한다
            // (정상 경로에선 placeAndDistribute가 collected를 비운다).
            var collected: std.ArrayList(CollectedPane) = .empty;
            defer {
                for (collected.items) |*c| c.pane.deinit(self.allocator);
                collected.deinit(self.allocator);
            }
            // 활성 panel: macOS면 shapeOnly까지만(atlas 무접촉) — 아래 멀티 페인 collect(.active)로 합류해 다른
            // 페인과 한 placeMultiPane(한 atlas 세대)에 배치한다(활성이 atlas에 가장 먼저·크게 쓰므로 합류해야
            // cross-pane 깨짐이 사라진다). 비-macOS는 fake backend로 RenderFrame까지(단일 leaf라 cross-pane 무관).
            // active_shaped는 collect로 소유 이전되면 null로 비운다(중복 deinit 방지). active_result는 placeAndDistribute가
            // 채우고 built_frames가 소유(view라 따로 deinit 안 함).
            var active_shaped: ?coretext_frame_builder.ShapedPane = null;
            defer if (active_shaped) |*ap| ap.deinit(self.allocator);
            // 이번 tick에 활성 프레임이 실제로 그린 view_offset(shapeOnlyBuild가 채움). null=빌드 실패/비-macOS.
            // 아래서 last_rendered_view_offset에 기록한다(성공=render-time, 실패=gate-time 폴백).
            var rendered_view_offset: ?usize = null;
            var active_result: ?ActiveResult = null;
            var active_index: usize = 0;
            var tick_result: ?app.AppFrameLoopTick = null;
            defer if (tick_result) |*t| t.deinit(self.allocator);
            if (builtin.os.tag == .macos) {
                const frame_builder = coretext_frame_builder.CoreTextFrameBuilder{
                    .appearance = self.appearance,
                    .shape_draw_list = coretext_bridge.maru_macos_coretext_shape_draw_list,
                    .rasterize_glyph = coretext_bridge.maru_macos_coretext_smoke_rasterize_glyph,
                    .scale_milli = self.scale_milli,
                    .cell_width_px = @intCast(self.cell_width_px),
                    .glyph_cell_width_px = @intCast(self.glyph_cell_width_px),
                    .cell_height_px = @intCast(self.cell_height_px),
                    // 활성 surface 커서: 창이 포커스를 잃었으면 cursor.unfocused(block/hollow/hidden) 적용(F1-4b-2).
                    .cursor_unfocused = self.unfocusedCursorMode(),
                };
                // shapeOnly 실패(드문 OOM)면 active_shaped=null → 아래 active_failed 가드가 이 frame을 통째로 포기한다
                // (chrome만 그려 blank/stale terminal을 합성하지 않게 — 기존 build-실패 동형). frame 카운터
                // (advanceFrameIndex)는 활성이 실제 그려질 때만 올린다(placeAndDistribute 후) — 실패 frame은 기존처럼
                // frame_loop_ticks를 안 올린다.
                active_shaped = frame_builder.shapeOnlyBuild(self.allocator, &self.app_window, &self.renderer_state.font_registry, self.io) catch null;
                // 이 프레임이 실제로 그린 스크롤 위치(shapeOnlyBuild가 같은 락 아래 캡처). null=빌드 실패.
                if (active_shaped) |sp| rendered_view_offset = sp.view_offset;
            } else {
                tick_result = try self.frame_loop.tickAfterDrain(drain_summary, renderer.FakeFontBackend{});
                // 비-macOS(단일 leaf·fake backend)는 활성 멀티 페인 통합을 쓰지 않는다. active_*는 macOS 통합 경로
                // 전용이라 여기서 명시 초기화해 비-macOS 빌드의 never-mutated 진단을 피한다(macOS 빌드에선 이 else가
                // comptime dead라 무영향).
                active_shaped = null;
                active_result = null;
                active_index = 0;
            }
            // 이번 tick에 투영하는 스크롤 위치를 기록한다 — 빌드 성공/실패와 무관하게 여기서 한 번(아래 replace
            // 성공 분기가 아님). 성공이면 render-time offset(shapeOnlyBuild가 같은 락에서 캡처)이라 read/render
            // TOCTOU로 stale이 안 생기고, shapeOnlyBuild 실패(active_failed)면 gate-time으로 폴백해 view_scrolled를
            // 풀어 sync hold 중 매-tick 재시도(OOM 스핀)를 막는다(metal_dirty 재시도는 sync가 throttle).
            self.last_rendered_view_offset = rendered_view_offset orelse active_view_offset;

            // Find 열린 채(또는 ⌘G 닫힘-네비 중) 새 출력이 들어오면 매치 절대 좌표가 어긋날 수 있다(스크롤백
            // eviction). 재검색해 하이라이트를 최신으로 유지하되 현재 인덱스만 clamp하고 스크롤은 하지 않는다.
            const find_active = self.chrome_host.find.open or self.find_nav;
            // 스크롤백 Find 재검색·뷰포트 클립은 활성 surface 코어를 읽고(findMatches는 ensureScrollbackRewrapped로
            // 스크롤백을 mutate) 리더 core.write와 경합하므로 락 아래(docs/io-render-threading.md PR3). matchViewportSpan
            // 루프까지 한 락으로 — find_view_spans/setMatchCount는 app 상태라 락 보유 중 안전.
            self.find_view_spans.clearRetainingCapacity();
            var find_current_span: ?terminal.SelectionSpan = null;
            {
                const fa_surface = self.activeSurface();
                fa_surface.lockCore(self.io);
                defer fa_surface.unlockCore(self.io);
                if (find_active and drain_summary.output_events > 0) {
                    const now_alt = fa_surface.core.alt_active;
                    fa_surface.core.findMatches(self.allocator, self.chrome_host.find.input.query.items, &self.find_matches) catch self.find_matches.clearRetainingCapacity();
                    self.chrome_host.find.setMatchCount(self.find_matches.items.len); // 매치 수 동기화 + current clamp(스크롤은 안 함)
                    // primary<->alt 화면 전환이면 매치 셋의 좌표 도메인이 통째로 바뀌어 이전 current가 무의미하다
                    // (setMatchCount는 clamp만). 첫 매치로 리셋한다 — 같은 화면 내 출력(스크롤백 eviction)이면 유지.
                    if (now_alt != self.find_was_alt) self.chrome_host.find.current = 0;
                    self.find_was_alt = now_alt;
                }
                // 활성 surface 매치를 뷰포트 span으로 클립(Find 활성일 때만). 현재 매치는 별도 강조색(current_match),
                // 나머지는 find_view_spans. 닫힌 채 ⌘G 네비(find_nav,!open)면 현재 매치만.
                if (find_active) {
                    for (self.find_matches.items, 0..) |m, mi| {
                        const span = fa_surface.core.matchViewportSpan(m) orelse continue;
                        if (mi == self.chrome_host.find.current) {
                            find_current_span = span;
                        } else if (self.chrome_host.find.open) {
                            self.find_view_spans.append(self.allocator, span) catch {};
                        }
                    }
                }
            }
            // Metal view 데이터 투영 실패(OOM 등)는 터미널 코어 동작과 무관하다. 마지막
            // frame을 유지하고 dirty를 남겨 다음 tick에 재시도한다(세션을 죽이지 않는다).
            // 활성 surface 코어 색/선택 상태(palette 복사·fg/bg·reverse·selection·hover)를 하나의 락 아래
            // 읽는다(docs/io-render-threading.md PR3 — 리더 core.write와 경합 방지). palette는 소유 버퍼로 복사해
            // CellColors가 코어 포인터를 안 들게 한다(복사본은 이 tick 동안 유효, replace가 소비). 리터럴은
            // shaping/GPU 없이 값만 모으므로 락 보유가 짧다(.cursor 등 app state는 코어 무관).
            const cc_surface = self.activeSurface();
            cc_surface.lockCore(self.io);
            self.active_palette_copy = cc_surface.core.paletteOverride().*;
            const cell_colors: metal_frame.CellColors = .{
                // OSC 10/11 색 설정이 있으면 그 색, 없으면 theme 기본. SGR reverse의 default 색 스왑·OSC 11 배경에도 반영.
                .default_fg = self.activeSurface().core.defaultFgOverride() orelse self.appearance.theme.foreground,
                .default_bg = self.activeSurface().core.defaultBgOverride() orelse self.appearance.theme.background,
                .palette = &self.active_palette_copy, // 코어 alias 대신 소유 복사본(OSC 4 .indexed 색 풀이)
                // ANSI 16색 config base(theme.palette). OSC4 override가 없을 때만 index<16에 적용(OSC4 → config → xterm256).
                // appearance는 세션 동안 불변·소유라 포인터 안전(복사 불필요) — OSC4 복사본과 달리 매 tick 변하지 않는다.
                .config_palette = &self.appearance.theme.palette,
                .screen_reverse = self.activeSurface().core.reverseScreen(), // DECSCNM(?5) 화면 전역 반전(G9)
                // blink(SGR 5): config text.blink가 켜졌을 때만 위상(blink_visible)을 반영해 off 위상에 숨긴다.
                // 꺼져 있으면(기본) 항상 on → 정적(안 깜빡임). 접근성 기본값.
                .blink_on = !self.appearance.blink_text or self.blink_visible,
                // bold-is-bright(theme.bold-is-bright): bold + indexed 0~7 전경을 bright(8~15)로(render-only).
                .bold_is_bright = self.appearance.bold_is_bright,
                .selection_bg = self.appearance.theme.selection,
                .selection = self.activeSurface().core.selectionViewportSpan(),
                .hover_link = self.hoverLinkSpan(),
                // 스크롤백 Find 매치 하이라이트(활성 surface에만 적용 — 비활성 pane은 inactive_colors).
                .search_match_bg = self.appearance.theme.search_match,
                .search_matches = self.find_view_spans.items,
                .current_match_bg = self.appearance.theme.search_match_current,
                .current_match = find_current_span,

                // 커서는 반전 블록으로 그린다: 칸 배경=cursor.color(없으면 theme.cursor), 그 위 glyph=
                // cursor.text(없으면 theme.background). cursor.* override는 테마와 독립적으로 커서만 칠하는
                // opt-in이라 미설정 시 기존 동작(흰 커서 + 배경색 반전 글자)을 그대로 보존한다.
                // blink와 무관하게 항상 투영한다 — off 위상 숨김은 metal_buffer가 커서 suffix 노출
                // 길이로 처리해(setCursorVisible) frame rebuild가 필요 없다.
                .cursor = .{
                    .block = self.appearance.cursor.color orelse self.appearance.theme.cursor,
                    .text = self.appearance.cursor.text orelse self.appearance.theme.background,
                },
            };
            cc_surface.unlockCore(self.io); // cell_colors의 활성 코어 읽기 끝 — 이후 shaping/GPU는 락 밖
            // 사이드바 탭 제목 glyph 패스(macOS만 — buildFromDrawList는 실 CoreText 브리지). 터미널과
            // 같은 frame_builder/renderer_state(atlas)를 써서 제목 glyph도 같은 slot을 재사용한다. 실패는
            // 무시하고 제목 없이 밴드만 그린다(세션을 죽이지 않음). 짧은 제목이라 매 frame 재-shape해도
            // 싸고, atlas dedup이 새 glyph만 업로드한다.
            var sidebar_frame: ?renderer.RenderFrame = null;
            defer if (sidebar_frame) |*sf| sf.deinit(self.allocator);
            if (builtin.os.tag == .macos) {
                // 통합 수집: DrawList만 만들고 collect(.sidebar) — placeAndDistribute가 sidebar_frame을 채운다(한 atlas 세대).
                if (self.buildSidebarTitleDrawList()) |dl| {
                    self.collectShaped(&collected, dl, self.paneFrameBuilder(), .sidebar);
                } else |_| {}
            }
            // 사이드바 상단 헤더 glyph(검색 placeholder + view options ⚙·새 워크스페이스 + 아이콘) — 절대 좌표라
            // 카드(sidebar_frame)와 별도 frame. replace가 origin(0,0) 기반 cells로 헤더 영역 [0,header)에 직접
            // 박는다(카드·밴드만 .m이 header_h 시프트). 실패는 무시(헤더 없이 정상). 같은 atlas라 slot 비충돌.
            var sidebar_header_frame: ?renderer.RenderFrame = null;
            defer if (sidebar_header_frame) |*hf| hf.deinit(self.allocator);
            if (builtin.os.tag == .macos) {
                // 통합 수집: DrawList만 만들고 collect(.sidebar_header) — placeAndDistribute가 sidebar_header_frame을 채운다.
                if (self.buildSidebarHeaderDrawList()) |maybe_dl| {
                    if (maybe_dl) |dl| self.collectShaped(&collected, dl, self.paneFrameBuilder(), .sidebar_header);
                } else |_| {}
            }
            // 최상위 모달 오버레이 frame(열렸을 때만, macOS). Notice·Find·Palette는 배타적이라 하나만 그린다(replace의
            // overlay_frame). 셋 다 chrome 컴포넌트 경로(buildChromeOverlayFrame → collectDraws/collectPaletteDraws →
            // 일반 rasterizer placeText)로 lower한다 — palette도 C1b에서 이주해 같은 EAW-폭 경로를 탄다. 실패는 무시
            // (오버레이 없이 정상). PaneFrame.frame을 deinit해야 하므로 defer로 정리한다.
            self.dropQuadsByLayer(1); // C4b 모달: 이전 프레임 모달 quad(layer1)를 비운다 — 닫혀도 잔존 안 함(아래서 재채움).
            self.dropQuadsByLayer(2); // C4b-5: 탭 밴드 quad(layer2)도 per-frame — 매 프레임 비우고 탭 바 build가 재채운다(미연결 시 no-op).
            self.dropQuadsByLayer(3); // 스크롤바(layer3 over)도 per-frame — drop과 append를 짝지어 깜빡임/누적 방지.
            self.dropQuadsByLayer(4); // 알림 종 배지(layer4 header)도 per-frame — 헤더 frame(흰 숫자)과 같은 주기로 갱신.
            self.appendNotificationBadge(); // 종 우상단 빨강 원형 배지(안 읽음 있을 때만, 펼침 헤더)
            self.appendPaneScrollbars(); // 모든 pane 우측 thumb(스크롤백 있을 때만) — 활성=fade/hover, 비활성=faint
            self.appendSidebarScrollbar(); // 사이드바 우측 thumb(워크스페이스 카드가 뷰포트 넘칠 때만) — 단일 트랙 fade
            self.gpu_shadows.clearRetainingCapacity(); // C4b 모달: 그림자도 per-frame — 매 프레임 비우고 lowering이 재채움.
            var overlay_frame: ?metal_frame.PaneFrame = null;
            defer if (overlay_frame) |*pf| pf.frame.deinit(self.allocator);
            if (builtin.os.tag == .macos) {
                // 단축키 힌트 HUD(key_hints.visible)는 패시브라 anyOverlayOpen이 아니다(커서 blink·keyEquivalent 양보 불변) —
                // 빌드 게이트에만 더해 오버레이 frame을 그린다. 모달이 같이 열리면 collectKeyHintsDraws가 내부에서 억제해 단일 오버레이 유지.
                if (self.anyOverlayOpen() or self.chrome_host.key_hints.visible) {
                    // 통합 수집: prep만 만들고 collect(.overlay) — placeAndDistribute가 overlay_frame(PaneFrame)을 조립한다.
                    if (self.buildChromeOverlayPrep()) |maybe| {
                        if (maybe) |prep| self.collectShaped(&collected, prep.dl, prep.builder, .{ .overlay = prep.placement });
                    } else |_| {}
                }
            }
            // 제목 glyph 투영용 색(전경=테마 글자색). 밴드는 rebuildSidebar가 이미 색을 박아 넘긴다.
            const sidebar_colors: metal_frame.CellColors = .{ .default_fg = self.appearance.theme.foreground };

            // 활성 탭의 leaf별 frame을 N개 합성한다. 단일 leaf(split 전)면 활성 frame 하나가 터미널 영역
            // 전체에 그려진다(origin = leaf rect = (사이드바 폭, 0)) — 기존 동작 보존. split이면 비활성 panel은
            // 각자 surface snapshot으로 frame을 만들어(커서/선택 없는 plain 색) 먼저 넣고, 활성 panel(frame_loop가
            // 만든 tick_result.frame)을 자기 leaf rect origin으로 '맨 뒤'에 둔다(맨 뒤 = 커서 suffix). 비활성
            // frame 빌드는 실 CoreText 브리지라 macOS에서만; 실패한 panel은 건너뛴다(세션 안 죽임).
            var leaf_rects: std.ArrayList(PaneTree.LeafRect) = .empty;
            defer leaf_rects.deinit(self.allocator);
            self.activeTabLeafRects(self.allocator, self.termRect(), &leaf_rects) catch {};
            const active_pane = self.activePane();

            // per-pane 상단 탭 바 chrome: 바 배경(전체) + 활성 Term 탭 하이라이트. 각 panel rect 상단 바에 origin
            // 박은 배경 셀로 만들어 터미널 셀 스트림에 prepend된다(C1). 바 base = chrome 색(sidebarBg). 활성 Term
            // 탭 강조색은 **포커스된 pane을 구분**한다: 활성 pane은 밝은 sidebarActiveBg, 비활성 pane은 dim
            // sidebarHoverBg(중간 톤) — split에서 pane 포커스를 옮기면 어느 bar가 활성인지 시각적으로 갱신된다
            // (세로 분할 등에서 "활성 탭 UI가 안 바뀐다"는 제보 대응). 제목 glyph는 아래 pane_frames에(C2).
            var pane_chrome: std.ArrayList(metal_frame.NativeMetalCell) = .empty;
            defer pane_chrome.deinit(self.allocator);
            // rich(corner>0)면 활성 탭을 VSCode식(평평 약한 배경 + 하단 maru 앰버 언더바) layer 2 quad로, tui(0)면 셀 밴드로.
            const tk = self.buildChromeTokens();
            const tk_space = tk.space;
            const tab_corner = tk_space.corner_radius_px; // rich 판별 게이트(>0이면 quad, 0이면 tui 셀)
            const tab_accent = packOpaqueRgb(tk.palette.get(.accent_bar)); // 활성 탭 하단 언더바(maru 앰버 — 포커스 surface 표시)
            for (leaf_rects.items) |lr| {
                const pb = self.paneBar(lr.rect, lr.leaf) orelse continue;
                const bar = pb.full; // 바 배경·언더바는 전체 바(라벨 영역도 같은 chrome 배경)
                // tui 밴드 강조색: 활성 pane=밝은 sidebarActiveBg, 비활성=dim sidebarHoverBg(포커스 구분). rich는 아래에서
                // 본문색 cutout(U-tab2)으로 override하고 포커스 구분을 언더바 색으로 옮긴다 — tui 보존(이 hl_bg는 tui 셀 밴드 전용).
                const hl_bg = if (lr.leaf == active_pane) self.sidebarActiveBg() else self.sidebarHoverBg();
                const m_opt = barMetrics(pb.tabs, self.cell_width_px, lr.leaf.terms.items.len, tk_space.tab_width_cols, lr.leaf.tab_scroll_cols); // 활성 밴드·‹›는 라벨 뺀 탭 영역
                if (tab_corner > 0) {
                    // rich: 바 배경(직각)·활성 탭(본문색 cutout + 하단 앰버 언더바) 모두 layer 2 quad. 바 배경 먼저(아래),
                    // 활성 탭이 위, 제목 셀(part1)은 그 위 — 불투명 바 배경 셀이 quad를 가리던 z-order 버그 해소(리뷰 #1).
                    self.appendBarBgQuad(bar, self.sidebarBg());
                    self.appendTabBarUnderline(bar, tk.border.line_thickness_px); // 탭바 하단 구분선(터미널 콘텐츠와 경계) — 활성 탭 세그먼트는 본문색 cutout+앰버 언더바가 덮어 "연결"된다
                    // U-tab2 연결형: rich 활성 탭 = 터미널 본문색 cutout(strip에서 도려낸 듯 아래 본문과 이어짐). 포커스 구분은
                    // 배경이 아니라 **언더바 색** — 포커스 pane=maru 앰버(active indicator), 비포커스=muted(흐린 구분만).
                    const tab_cutout_bg = packOpaqueRgb(self.appearance.theme.background);
                    const ub_accent = if (lr.leaf == active_pane) tab_accent else packOpaqueRgb(tk.palette.get(.muted_fg));
                    if (m_opt) |m| self.appendActiveTabHighlight(m, lr.leaf.active_term, tab_cutout_bg, hl_bg, ub_accent, tk_space, tk.border);
                    if (m_opt) |m| if (m.has_scroll) { // #5a/#5b: 우측 ‹·› 사각형 버튼 — hover면 밝게(sidebarActiveBg)로 클릭 가능 표시
                        const lh = if (self.hovered_scroll) |hs| (hs.pane == lr.leaf and !hs.right) else false;
                        const rh = if (self.hovered_scroll) |hs| (hs.pane == lr.leaf and hs.right) else false;
                        self.appendScrollButtonQuad(m, m.tab_cols, if (lh) self.sidebarActiveBg() else self.sidebarHoverBg());
                        self.appendScrollButtonQuad(m, m.tab_cols + 2, if (rh) self.sidebarActiveBg() else self.sidebarHoverBg());
                    };
                } else {
                    // tui: 직각 셀 — 바 배경 후 활성 탭 밴드(셀-셀 append 순서로 밴드가 위).
                    if (paneBarBgCell(bar, self.cell_width_px, self.sidebarBg())) |cell| pane_chrome.append(self.allocator, cell) catch {};
                    if (m_opt) |m| {
                        if (tabbarHighlightCell(m, lr.leaf.active_term, hl_bg)) |cell| pane_chrome.append(self.allocator, cell) catch {};
                    }
                }
                // 활성 pane 강조는 활성 탭 하단 앰버 언더바(appendActiveTabHighlight)로 일원화한다(사용자 요청) — 옛
                // 앰버 사각 ring(pane rect 둘레 border quad)은 제거. chrome_minimal은 아래 appendActivePaneBorder(셀 테두리)가 따로 담당.
            }

            // panel 사이 divider 선(PR6) — split이면 각 경계에 seam 중심 셀 strip을 깐다. chrome(맨 아래)이 아니라
            // overlay로 넘겨 터미널 위·커서 아래에 그린다(seam 위라 터미널에 안 가리게). 단일 panel이면 빈 리스트.
            var pane_overlay: std.ArrayList(metal_frame.NativeMetalCell) = .empty;
            defer pane_overlay.deinit(self.allocator);
            self.appendDropTargetHighlight(&pane_overlay); // ④b 드롭 타겟 반투명 하이라이트(divider보다 먼저 → 아래)
            self.appendActiveTabDividers(&pane_overlay);

            // 활성 panel의 origin(터미널 영역 = 바 아래). 못 구하면(빈 리스트 — OOM) 터미널 영역 전체의 바 아래로 폴백.
            const active_fallback = self.paneTermRect(self.termRect());
            var active_origin_x: u32 = active_fallback.x;
            var active_origin_y: u32 = active_fallback.y;
            var active_term_rect: maru.session.SplitRect = active_fallback;
            for (leaf_rects.items) |lr| {
                if (lr.leaf == active_pane) {
                    const t = self.paneTermRect(lr.rect);
                    active_origin_x = t.x;
                    active_origin_y = t.y;
                    active_term_rect = t;
                    break;
                }
            }
            // minimal split: 활성 pane 둘레 얇은 테두리(full·단일 pane이면 무동작). divider 위에 얹어 focus를 보인다.
            self.appendActivePaneBorder(&pane_overlay, active_term_rect, leaf_rects.items.len);
            // 우상단 탭 점 인디케이터(full·단일이면 무동작) — 테두리 **뒤에** append해 정보 chip이 focus 테두리 위에
            // 올라온다(활성 pane이 우상단일 때 테두리 상/우 선이 점을 가로지르던 코너 겹침 해소; chrome 프레임=아래,
            // 정보 chip=위 z-order).
            self.appendMinimalTabIndicator(&pane_overlay);

            var pane_frames: std.ArrayList(metal_frame.PaneFrame) = .empty;
            defer pane_frames.deinit(self.allocator);
            // 드래그 중 floating 탭 미리보기 frame(맨 위에 둘 것). macOS 블록에서 빌드해 활성 터미널 뒤에 넣는다.
            var floating_pf: ?metal_frame.PaneFrame = null;
            // sticky command 배너 frame(스크롤 시 명령줄 고정) — 활성 터미널 '위', floating 드래그 ghost '아래'.
            var sticky_pf: ?metal_frame.PaneFrame = null;
            // 탭 바 제목·비활성 panel frame은 여기서 소유하고 replace 뒤에 해제한다(pane_frames의 PaneFrame은 같은
            // frame을 가리키는 view일 뿐이라 따로 deinit하지 않는다 — 이중 free 방지). 활성 frame은 macOS면 통합
            // placeMultiPane 결과라 built_frames가 소유(active_result는 view), 비-macOS면 tick_result가 소유한다.
            var built_frames: std.ArrayList(renderer.RenderFrame) = .empty;
            defer {
                for (built_frames.items) |*bf| bf.deinit(self.allocator);
                built_frames.deinit(self.allocator);
            }
            // 비활성 panel 색: 포커스 안 된 panel이라 커서/선택/호버 없음(default 전경/배경만). config_palette는 ANSI 16색
            // base(theme.palette) — 비활성 pane도 자기 OSC4(palette)를 쓰되, OSC4가 없으면 이 config base로 폴백한다
            // (pane_colors가 inactive_colors를 복사해 쓰므로 여기 한 곳에 둔다). appearance는 세션 불변·소유라 포인터 안전.
            const inactive_colors: metal_frame.CellColors = .{
                .default_fg = self.appearance.theme.foreground,
                .default_bg = self.appearance.theme.background,
                .config_palette = &self.appearance.theme.palette,
                .bold_is_bright = self.appearance.bold_is_bright, // pane_colors가 이걸 복사 — 비활성 pane도 동일 규칙
                // 비활성 split pane 디밍(F2-7, window.unfocused-dim): 이 CellColors를 쓰는 pane은 전부 비활성이므로
                // 여기 한 곳에 dim_milli를 세우면 모든 비활성 pane 셀 색이 배경 쪽으로 흐려진다. 활성 pane은
                // CoreTextFrameBuilder(cell_colors, dim_milli=0)라 영향 없다. f32 0~1 → 천분율(클램프).
                .dim_milli = @intFromFloat(@min(@max(self.appearance.unfocused_dim, 0.0), 1.0) * 1000.0),
            };
            // 탭 바 제목 색: 전경=테마 글자색, 배경은 chrome이 이미 깔아 둠(투명).
            const tabbar_colors: metal_frame.CellColors = .{ .default_fg = self.appearance.theme.foreground };
            if (builtin.os.tag == .macos) {
                // grip/label/탭바/비활성/floating/활성 collect가 공유하는 finishPane용 builder(단일 출처 paneFrameBuilder).
                const pane_frame_builder = self.paneFrameBuilder();

                // 1) 각 pane의 탭 바 제목 frame — Term 제목들을 가로 등폭 탭으로(buildPaneTabBarDrawList). 활성 panel
                //    커서 suffix가 합쳐진 cells의 끝에 남도록 '터미널 frame들 앞'에 둔다. 바 없는 작은 pane은 건너뜀.
                for (leaf_rects.items) |lr| {
                    const pb = self.paneBar(lr.rect, lr.leaf) orelse continue;
                    // 제목/라벨을 위 패딩만큼 내려 바 가운데에. tui(pad=0)면 바 상단(full.y).
                    const text_origin_y = pb.full.y + @as(u32, self.buildChromeTokens().space.tab_bar_pad_y_px);

                    // 1a-grip) pane grip 핸들(좌측, 항상 예약·항상 표시) — [full.x, full.x+grip_cols*cw)에 grip 글리프. pane
                    //     통째 드래그 손잡이(아래 마우스 arm과 같은 영역). 라벨·탭은 grip 뒤로 밀려 안 겹친다. muted 색.
                    //     **항상 보인다**(사용자 피드백): pane→워크스페이스 분리 드래그는 Warp에 없는 maru 기능이라, 손잡이를 늘
                    //     보여야 발견성이 유지된다(hover-only로 숨겼다가 되돌림 — Warp 벤치마킹은 grip 없는 모델이라 부적합).
                    if (pb.grip_cols > 0) {
                        const grip_fg: terminal.Color = .{ .rgb = dimRgb(self.appearance.theme.sidebar_foreground) };
                        if (coretext_frame_builder.buildPaneGripDrawList(self.allocator, @intCast(pb.grip_cols), grip_fg)) |gdl| {
                            self.collectShaped(&collected, gdl, pane_frame_builder, .{ .pane = .{ .origin_x = pb.full.x, .origin_y = text_origin_y, .colors = tabbar_colors } });
                        } else |_| {}
                    }

                    // 1a) pane 라벨 세그먼트(좌측) — custom_name이 있으면 [full.x, full.x+label_cols*cw)에 이름 glyph.
                    //     탭 영역(pb.tabs)이 라벨만큼 우측으로 밀려 겹치지 않는다(label_cols=0이면 이 블록 생략 = 기존 동작).
                    if (pb.label_cols > 0) {
                        // 이 pane을 rename 중이면 편집 텍스트(+caret), 아니면 custom_name. 편집 중엔 paneBar가 빈
                        // 이름이어도 세그먼트를 띄워(renameDisplayWidth) caret이 보인다. 편집 텍스트는 owned라 해제.
                        var name_buf: ?[]const u8 = null;
                        defer if (name_buf) |b| self.allocator.free(b);
                        const name = if (self.renamingPane(lr.leaf)) blk: {
                            const e = self.renameEditText(self.allocator) catch break :blk app.pickLabel(lr.leaf.custom_name, "");
                            name_buf = e;
                            break :blk e;
                        } else app.pickLabel(lr.leaf.custom_name, "");
                        const label_fg: terminal.Color = .{ .rgb = self.appearance.theme.sidebar_foreground }; // 밝은 전경(muted 비활성 탭과 구분)
                        if (coretext_frame_builder.buildPaneLabelDrawList(self.allocator, name, @intCast(pb.label_cols), label_fg)) |ldl| {
                            self.collectShaped(&collected, ldl, pane_frame_builder, .{ .pane = .{ .origin_x = pb.full.x + pb.grip_cols * self.cell_width_px, .origin_y = text_origin_y, .colors = tabbar_colors } });
                        } else |_| {}
                    }

                    // 1b) Term 탭 제목 — 라벨 뒤 탭 영역(pb.tabs)에. 바 없을 만큼 좁으면 건너뜀.
                    const bar_cols = @min(pb.tabs.w / self.cell_width_px, @as(u32, std.math.maxInt(u16)));
                    if (bar_cols == 0) continue;
                    // Term 탭 라벨 = 제목만(번호 prefix 없음 — U-tab2; 사이드바 워크스페이스 라벨과 같은 무번호 규약).
                    // dupe 소유 버퍼라 아래 defer로 해제한다(termLabel은 borrowed라 즉시 복사 — termLabel doc).
                    var titles: std.ArrayList([]const u8) = .empty;
                    defer {
                        for (titles.items) |l| self.allocator.free(l);
                        titles.deinit(self.allocator);
                    }
                    for (lr.leaf.terms.items) |term| {
                        // Term 탭 라벨 = surface.custom_name(rename) 우선, 없으면 자동 제목(번호 prefix 없음 — 모던 탭은
                        // 브라우저/VSCode/Warp처럼 제목만; Term 번호는 단축키에 매핑되지 않아 시각 군더더기였다, U-tab2).
                        // 이 Term을 rename 중이면 그 탭에 편집 텍스트(+caret)를 그려 탭에서 바로 편집되게 한다.
                        if (self.renamingTerm(term)) {
                            const edit = self.renameEditText(self.allocator) catch continue;
                            defer self.allocator.free(edit);
                            const label = self.allocator.dupe(u8, edit) catch continue;
                            titles.append(self.allocator, label) catch self.allocator.free(label);
                        } else {
                            const label = self.allocator.dupe(u8, termLabel(term)) catch continue;
                            titles.append(self.allocator, label) catch self.allocator.free(label);
                        }
                    }
                    // 비활성 Term 탭은 흐린 색(muted), 그 pane의 활성 Term 탭은 full sidebar_foreground로 강조한다.
                    const tab_fg: terminal.Color = .{ .rgb = self.mutedForeground() };
                    const active_tab_fg: terminal.Color = .{ .rgb = self.appearance.theme.sidebar_foreground };
                    // 이 pane의 탭이 호버 중이면 그 탭에 ✕를 그린다(다른 pane이면 null).
                    const close_tab: ?usize = if (self.hovered_tab) |h| (if (h.pane == lr.leaf) h.tab else null) else null;
                    const dl = coretext_frame_builder.buildPaneTabBarDrawList(self.allocator, titles.items, @intCast(bar_cols), tab_fg, close_tab, lr.leaf.active_term, active_tab_fg, self.buildChromeTokens().space.tab_width_cols, lr.leaf.tab_scroll_cols) catch continue;
                    self.collectShaped(&collected, dl, pane_frame_builder, .{ .pane = .{ .origin_x = pb.tabs.x, .origin_y = text_origin_y, .colors = tabbar_colors } });
                }

                // 2) 비활성 panel 터미널 frame(자기 활성 Term surface, 바 아래 origin). split일 때만 여럿이다.
                if (leaf_rects.items.len > 1) {
                    // 비활성 pane palette 복사 버퍼를 leaf 수만큼 예약(루프 중 realloc 없이 → 포인터 안정).
                    self.pane_palette_copies.clearRetainingCapacity();
                    self.pane_palette_copies.ensureTotalCapacity(self.allocator, leaf_rects.items.len) catch {};
                    for (leaf_rects.items) |lr| {
                        if (lr.leaf == active_pane) continue; // 활성은 맨 뒤에 따로 넣는다
                        const pane_surface = &lr.leaf.activeTerm().surface;
                        const pane_core = &pane_surface.core;
                        // 코어 읽기(snapshot→DrawList 복사 + per-pane 색 상태)는 락 아래, CoreText shaping
                        // (buildFromDrawList — DrawList 복사본만 봄)은 락 밖(docs/io-render-threading.md PR3).
                        pane_surface.lockCore(self.io);
                        // 창이 포커스를 잃었으면 config.cursor.unfocused(block/hollow/hidden)를 커서에 반영한다 — 포커스
                        // 있으면(또는 block) 현행(normal). renderer가 이 모드로 cursor overlay의 hollow/visible를 정한다(F1-4b-2).
                        const dl_or = renderer.buildDrawListWithUnfocused(self.allocator, pane_core.renderSnapshot(), self.unfocusedCursorMode());
                        // palette를 소유 버퍼로 복사(코어 alias 제거). 예약 capacity 부족(OOM)이면 코어 포인터 폴백.
                        const pane_palette_ptr = if (self.pane_palette_copies.items.len < self.pane_palette_copies.capacity) blk: {
                            self.pane_palette_copies.appendAssumeCapacity(pane_core.paletteOverride().*);
                            break :blk &self.pane_palette_copies.items[self.pane_palette_copies.items.len - 1];
                        } else pane_core.paletteOverride();
                        const pane_rev = pane_core.reverseScreen(); // DECSCNM(G9) per-pane
                        const pane_fg = pane_core.defaultFgOverride();
                        const pane_bg = pane_core.defaultBgOverride();
                        pane_surface.unlockCore(self.io);
                        const dl = dl_or catch continue;
                        // 비활성 pane도 자기 core의 OSC 4 팔레트·OSC 10/11 색 설정을 쓴다(둘 다 per-터미널 상태). collect는
                        // place를 미루므로 색을 먼저 모은다 — palette 포인터는 pane_palette_copies(루프 전 예약, 포인터 안정)라
                        // frame 끝까지 유효하다.
                        var pane_colors = inactive_colors;
                        pane_colors.palette = pane_palette_ptr;
                        pane_colors.screen_reverse = pane_rev;
                        pane_colors.blink_on = !self.appearance.blink_text or self.blink_visible; // blink 위상(전역, config 게이트)
                        if (pane_fg) |fg| pane_colors.default_fg = fg;
                        if (pane_bg) |bg| pane_colors.default_bg = bg;
                        const t = self.paneTermRect(lr.rect); // 바 아래 영역 origin
                        self.collectShaped(&collected, dl, pane_frame_builder, .{ .pane = .{ .origin_x = t.x, .origin_y = t.y, .colors = pane_colors } });
                    }
                }

                // 3) 드래그 중 floating 탭 미리보기 — 커서 위치에 박스+제목. 활성 터미널 '뒤'(맨 위)에 넣어야 하므로
                //    여기선 빌드만 하고 아래에서 append한다(built_frames가 소유).
                // floating 탭 미리보기(드래그 중일 때만) collect — placeAndDistribute가 .floating으로 floating_pf를 채운다.
                if (self.buildFloatingTabDrawListAndPlacement()) |dp| {
                    self.collectShaped(&collected, dp.dl, pane_frame_builder, .{ .floating = dp.placement });
                }

                // 3b) sticky command 배너 — 활성 pane이 스크롤됐고(config 켜짐 + OSC133 마커) 명령줄이 뷰포트 위로
                //     밀려났을 때만. 활성 터미널 '위'(.sticky)에 한 줄 배너로 collect한다. 배너 하단 구분선은
                //     아래 append 직후 GpuQuad로(텍스트와 안 겹치게 배너 아래 행에).
                if (self.buildStickyDrawListAndPlacement(active_term_rect)) |sp| {
                    self.collectShaped(&collected, sp.dl, pane_frame_builder, .{ .sticky = sp.placement });
                }

                // 활성 panel(위에서 shapeOnly됨)을 collect(.active)로 합류 — 다른 모든 페인과 한 placeMultiPane 세대.
                // 소유권을 collected로 넘기고 active_shaped를 비운다(바깥 defer 중복 deinit 방지). cell_colors/active_origin은
                // 이미 준비됨. builder는 finishPane(place/raster)용이라 cursor_unfocused 없는 pane_frame_builder로 충분하다
                // (커서는 shapeOnly 단계의 DrawList에 이미 반영됨).
                if (active_shaped) |ap| {
                    self.collectShapedPane(&collected, ap, pane_frame_builder, .active);
                    active_shaped = null;
                }

                // 수집된 모든 페인(sidebar/header/overlay/grip/label/탭바/비활성/floating + 활성)을 한 번에 placeMultiPane으로
                // 배치+분배한다 — cross-pane 정합(한 atlas 세대). 활성은 active_result로 받아 아래에서 pane_frames 맨 뒤(커서
                // suffix·floating 맨 위 직전)에 넣는다.
                self.placeAndDistribute(&collected, &pane_frames, &built_frames, &sidebar_frame, &sidebar_header_frame, &overlay_frame, &floating_pf, &sticky_pf, &active_result);
            }
            // 활성 terminal frame 성공 여부를 확정한다. macOS에서 surface가 있는데 active_result==null이면 활성
            // shapeOnly/place가 실패한 것(드문 OOM) — 기존 build-실패와 동형으로 이 frame을 통째로 포기해야 한다(chrome만
            // 그려 blank/stale terminal을 합성하면 metal_dirty가 내려가 self-heal이 막히므로). 활성이 실제 그려질 때만
            // frame 카운터를 올린다(실패 frame은 frame_loop_ticks를 안 올림 — 기존 build-실패 동형).
            const active_failed = builtin.os.tag == .macos and self.surface_initialized and active_result == null;
            if (builtin.os.tag == .macos and active_result != null) {
                active_index = self.frame_loop.advanceFrameIndex();
            }
            // 활성 panel 터미널을 맨 뒤에(커서 suffix). macOS면 통합 placeMultiPane 결과(active_result.rf — built_frames
            // 소유, pane_frames엔 view로), 비-macOS면 fake backend의 tick_result. 단일 leaf면 이게 유일한 터미널 frame이다
            // (기존 동작). 활성 frame이 없으면(active_failed) 아래 replace/summary를 스킵해 frame을 통째로 포기한다.
            if (active_result) |ar| {
                pane_frames.append(self.allocator, .{
                    .frame = ar.rf,
                    .origin_x = active_origin_x,
                    .origin_y = active_origin_y,
                    .colors = cell_colors,
                }) catch {};
            } else if (tick_result) |*t| {
                pane_frames.append(self.allocator, .{
                    .frame = t.frame.render_frame,
                    .origin_x = active_origin_x,
                    .origin_y = active_origin_y,
                    .colors = cell_colors,
                }) catch {};
            }
            // sticky 배너는 활성 터미널 '위'(스크롤된 콘텐츠를 가린다)이되 floating 드래그 ghost '아래'에 둔다.
            if (sticky_pf) |pf| {
                pane_frames.append(self.allocator, pf) catch {};
                // 배너 하단 구분선(스크롤된 콘텐츠와 시각 분리) — 배너 한 줄 '아래' 경계(origin_y+ch)에 그어 배너
                // 텍스트(active_term_rect.y..+ch)와 y가 겹치지 않는다. layer 3(over)라 셀 위에 또렷이.
                const dch = self.cell_height_px;
                const dthick: u32 = @max(@as(u32, 1), self.buildChromeTokens().border.line_thickness_px);
                self.appendSolidQuad(@floatFromInt(pf.origin_x), @floatFromInt(pf.origin_y + dch), @floatFromInt(active_term_rect.w), @floatFromInt(dthick), self.dividerColor(), 3);
            }
            // floating 탭은 활성 터미널·커서보다 위(맨 마지막 frame)에 그린다 — 드래그 ghost가 가장 위에 보이게.
            if (floating_pf) |pf| pane_frames.append(self.allocator, pf) catch {};

            // active_failed면 replace를 스킵한다 — chrome panes만으로 blank/stale terminal을 합성하면 metal_dirty가
            // 내려가 다음 tick에 재빌드되지 않아 깨진 frame이 화면에 고정된다. 스킵하면 metal_dirty가 유지돼 다음 tick에
            // 재시도한다(기존 build-실패 frame 스킵 동형).
            if (pane_frames.items.len > 0 and !active_failed) {
                // kitty graphics(K2d): 활성 surface(이 frame을 만든 surface)의 placement를 GpuImage로 환산하고,
                // generation이 바뀐 이미지만 업로드 채널로 만든다. dest origin은 활성 panel의 픽셀 origin(사이드바
                // 폭·탭 바 아래)으로 박아 터미널 sub-rect에 그려지게 한다. 비활성 panel 이미지는 후속(단일 활성 기준).
                var kg_images: []metal_frame.GpuImage = &.{};
                var kg_uploads: []metal_frame.GpuImageUpload = &.{};
                var kg_pixels: []u8 = &.{};
                var kg_live_ids: std.ArrayList(u32) = .empty;
                defer self.allocator.free(kg_images);
                defer self.allocator.free(kg_uploads);
                defer self.allocator.free(kg_pixels);
                defer kg_live_ids.deinit(self.allocator);
                if (self.surface_initialized) {
                    // 코어 변경(setCellMetrics·setDefaultColors)과 kitty 이미지 읽기(snap.placements/images는
                    // 코어 alias)는 모두 락 아래(docs/io-render-threading.md PR3 — 리더 core.write와 경합 방지).
                    // buildGpuImages/planImageUploads가 이미지 데이터를 owned 버퍼로 복사하므로(planImageUploads는
                    // img.pixels를 appendSlice로 복사), 락 밖 replace()는 코어를 안 본다.
                    const active_surface = self.activeSurface();
                    active_surface.lockCore(self.io);
                    defer active_surface.unlockCore(self.io);
                    // kitty 자동 크기 이미지의 커서 advance용 셀 메트릭을 활성 surface 코어에 주입한다(매 tick 최신).
                    active_surface.core.setCellMetrics(self.cell_width_px, self.cell_height_px);
                    // OSC 10/11 색 질의 응답용 theme 전경/배경 RGB도 주입(코어는 Color.default 추상만 알아 실제 색 필요).
                    active_surface.core.setDefaultColors(self.appearance.theme.foreground, self.appearance.theme.background);
                    const snap = active_surface.core.renderSnapshot();
                    // K4c: 살아있는 이미지 id 집합(활성 surface 저장소). Swift가 이 집합에 없는 텍스처를 evict.
                    for (snap.images) |img| kg_live_ids.append(self.allocator, img.image_id) catch {};
                    // kitty_uploaded를 같은 집합으로 prune — 텍스처가 evict된(=live 아님) 이미지는 dedup 상태에서도
                    // 빼, 다시 활성화되면 재업로드되게(Swift 캐시와 동기). 멀티 surface 전환 시 정합.
                    self.pruneKittyUploaded(kg_live_ids.items);
                    if (snap.placements.len > 0) {
                        kg_images = metal_frame.buildGpuImages(self.allocator, snap.placements, snap.images, snap.size, self.cell_width_px, self.cell_height_px) catch &.{};
                        for (kg_images) |*gi| {
                            gi.origin_x = active_origin_x;
                            gi.origin_y = active_origin_y;
                        }
                        if (kg_images.len > 0) {
                            if (metal_frame.planImageUploads(self.allocator, kg_images, snap.images, &self.kitty_uploaded)) |plan| {
                                kg_uploads = plan.uploads;
                                kg_pixels = plan.pixels;
                            } else |_| {}
                        }
                    }
                }
                // F2-1 배경 이미지(window.background-image): 풀-윈도 pass-0 GpuImage를 kitty 채널 앞에 끼운다
                // (렌더러 변경 없이 텍스처 캐시·image quad 인프라 재사용). pass 0이라 (pass,z) 정렬 partition을
                // 유지하려 kg_images **앞**에 prepend한다(below-text 먼저·above-text 뒤 split 불변).
                self.ensureBackgroundImage();
                if (self.buildBackgroundGpuImage()) |bg_gi| {
                    if (self.allocator.alloc(metal_frame.GpuImage, kg_images.len + 1) catch null) |new_images| {
                        new_images[0] = bg_gi;
                        @memcpy(new_images[1..], kg_images);
                        self.allocator.free(kg_images);
                        kg_images = new_images;
                        // live 집합에 bg id 추가 — eviction(live 아닌 텍스처 회수)에서 살아남게.
                        kg_live_ids.append(self.allocator, background_image_id) catch {};
                        // 픽셀 업로드는 generation이 바뀐(경로 변경 후 첫 frame) 때만 — 렌더러 텍스처 1회 캐시
                        // (upload-once, kitty와 동일 모델; 렌더러 재생성 시 desync는 kitty_uploaded 캐비엇과 같음).
                        if (self.bg_image_generation != self.bg_image_uploaded_gen and self.bg_image_pixels.len > 0) {
                            const bg_upload = metal_frame.GpuImageUpload{
                                .image_id = background_image_id,
                                .width = self.bg_image_width,
                                .height = self.bg_image_height,
                                .bpp = self.bg_image_bpp,
                                .generation = self.bg_image_generation,
                                .pixels_offset = kg_pixels.len, // 합친 픽셀 버퍼 끝에 bg 픽셀을 잇는다
                                .pixels_len = self.bg_image_pixels.len,
                            };
                            const new_uploads = self.allocator.alloc(metal_frame.GpuImageUpload, kg_uploads.len + 1) catch null;
                            const new_pixels = std.mem.concat(self.allocator, u8, &.{ kg_pixels, self.bg_image_pixels }) catch null;
                            if (new_uploads != null and new_pixels != null) {
                                @memcpy(new_uploads.?[0..kg_uploads.len], kg_uploads);
                                new_uploads.?[kg_uploads.len] = bg_upload;
                                self.allocator.free(kg_uploads);
                                self.allocator.free(kg_pixels);
                                kg_uploads = new_uploads.?;
                                kg_pixels = new_pixels.?;
                                self.bg_image_uploaded_gen = self.bg_image_generation;
                            } else {
                                // 부분 할당 실패 — 누수 방지로 새 버퍼만 해제(이번 frame 업로드 생략, 다음 frame 재시도).
                                if (new_uploads) |nu| self.allocator.free(nu);
                                if (new_pixels) |np| self.allocator.free(np);
                            }
                        }
                    }
                }
                self.appendBellFlashQuad(); // 시각 벨(bell.visual): flash 중이면 전경색 반투명 full-screen quad를 맨 위에(F2-4)
                if (self.metal_buffer.replace(self.allocator, pane_frames.items, self.renderer_state.atlas.config, self.cell_width_px, self.cell_height_px, sidebar_frame, sidebar_header_frame, self.sidebar_cells.items, sidebar_colors, pane_chrome.items, pane_overlay.items, overlay_frame, self.gpu_quads.items, self.gpu_shadows.items, kg_images, kg_uploads, kg_pixels, kg_live_ids.items)) |_| {
                    self.metal_dirty = false;
                    // last_rendered_view_offset은 위(os-tag 블록 직후)에서 빌드 성공/실패 무관하게 이미 기록했다
                    // (성공=render-time, 실패=gate-time 폴백). 여기서 다시 쓰지 않는다.
                } else |_| {}
            }

            // per-frame render 통계와 tick index를 summary에 덧씌운다. macOS면 통합 활성 frame(active_result.rf)로 직접
            // 산출(finishTick을 안 거쳐서 — atlas entry는 통합 place 후 최종값), 비-macOS면 tick_result. active_failed(드문
            // shapeOnly/place 실패)면 이 frame을 포기했으므로 마지막 frame 통계를 유지한다(idle 동형 — writeSummaryFromState만,
            // frame_loop_ticks는 advanceFrameIndex를 안 했으므로 자동으로 그대로다).
            if (active_failed) {
                self.writeSummaryFromState();
            } else if (active_result) |ar| {
                self.writeSummaryFromRenderStats(active_index, renderer.renderFrameStats(ar.rf, self.renderer_state.atlas.entryCount()));
            } else if (tick_result) |t| {
                self.writeSummaryFromTick(t);
            } else {
                self.writeSummaryFromState();
            }
            self.logScreenIfDebug();
            self.drainShellEventsForFrame();
        } else {
            // idle: build/project를 건너뛰므로 summary는 마지막 frame render 통계를 그대로 둔다.
            self.writeSummaryFromState();
        }
        // 세션이 종료되면 host가 frame loop를 멈추고 우아하게 내려가도록 app_should_terminate를
        // 싣는다. ABI의 tick export는 이 ended를 SessionEnded status로 올려준다.
        self.last_summary.last_event_kind = @intFromEnum(
            if (self.ended_seen) EventKind.app_should_terminate else EventKind.frame_tick,
        );
        // Cmd+Q 종료 확인의 결정을 host로 한 번 전달하고 비운다(one-shot). writeSummaryFrom*가 매 tick
        // last_summary를 덮어쓰므로 여기 epilogue가 단일 출처 — 모든 tick 경로(render/tick/idle)를 거친다.
        self.last_summary.quit_decision = @intFromEnum(self.quit_decision);
        self.quit_decision = .none;
        return self.last_summary;
    }

    pub fn close(self: *AppSession) FrameSummary {
        self.total_close_events += 1;
        // 창 close — 모든 탭의 모든 panel PTY를 정리한다(활성만이 아니라). runtime이 살아 있으면 detach까지,
        // 아니면 close만.
        for (self.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (term.rt.live_initialized and self.runtime_initialized) {
                        term.rt.live_pty.closeAndDetach(&self.runtime);
                    } else if (term.rt.live_initialized) {
                        term.rt.live_pty.close();
                    }
                }
            }
        }
        if (self.surface_initialized) {
            // App/window close는 더 이상 이 surface가 live input/output을 받을 수 없다는
            // 뜻이다. exit event를 기다리지 않고 close가 child를 정리한 경우에도 summary가
            // running으로 남으면 close lifecycle을 오해하므로 app session summary에서는
            // 종료 상태로 latch한다.
            self.activeSurface().process_state = .exited;
            self.ended_seen = true;
        }
        self.writeSummaryFromState();
        self.last_summary.last_event_kind = @intFromEnum(EventKind.close_requested);
        return self.last_summary;
    }

    /// 사이드바 strip 배경색(0xAARRGGBB). resolved 테마의 `sidebar_background`를 읽기만 한다 — 색 파생
    /// (명시 없으면 배경 +24)은 config resolver(resolveTheme)가 단일 출처로 소유한다. 테마가 명시하면 그 색.
    fn sidebarBg(self: *const AppSession) u32 {
        return packOpaqueRgb(self.appearance.theme.sidebar_background);
    }

    /// 활성 탭 하이라이트 밴드 배경색(0xAARRGGBB). resolved 테마의 `sidebar_active`를 읽기만 한다 — 명시
    /// 없으면 배경 +48(사이드바 배경보다 한 단계 밝게)로 resolveTheme가 파생한다. 테마가 명시하면 그 색.
    fn sidebarActiveBg(self: *const AppSession) u32 {
        return packOpaqueRgb(self.appearance.theme.sidebar_active);
    }

    /// 호버 슬롯 하이라이트 배경색(0xAARRGGBB) — 사이드바 배경(+24)과 활성(+48)의 중간으로 파생한다.
    /// 별도 테마 필드 없이 두 resolved 색의 채널 평균을 써서, 사용자가 사이드바 색을 커스텀해도 호버가
    /// 그 사이 톤을 따라간다(활성보다 약하고 배경보다 또렷한 호버 피드백).
    fn sidebarHoverBg(self: *const AppSession) u32 {
        const a = self.appearance.theme.sidebar_background;
        const b = self.appearance.theme.sidebar_active;
        const r: u32 = (@as(u32, a.r) + b.r) / 2;
        const g: u32 = (@as(u32, a.g) + b.g) / 2;
        const bch: u32 = (@as(u32, a.b) + b.b) / 2;
        return 0xFF00_0000 | (r << 16) | (g << 8) | bch;
    }

    /// 비활성 탭 제목용 흐린 전경색 — sidebar_foreground(테마화된 사이드바 글자색, 기본=foreground)를 background
    /// 쪽으로 45% 섞어 muted한다. 활성 탭은 full sidebar_foreground라 대비로 글자가 도드라진다. 사이드바·pane 탭 바 공유.
    fn mutedForeground(self: *const AppSession) maru.color.Rgb {
        const f = self.appearance.theme.sidebar_foreground;
        const b = self.appearance.theme.background;
        return .{
            .r = @intCast((@as(u32, f.r) * 55 + @as(u32, b.r) * 45) / 100),
            .g = @intCast((@as(u32, f.g) * 55 + @as(u32, b.g) * 45) / 100),
            .b = @intCast((@as(u32, f.b) * 55 + @as(u32, b.b) * 45) / 100),
        };
    }

    /// 스크린 x가 세로 사이드바 영역 안인가(순수 `xInSidebar` 래퍼).
    fn inSidebar(self: *const AppSession, x_px: f64) bool {
        return chrome.components.sidebar.inSidebar(x_px, self.sidebar_width_px);
    }

    /// (x,y backing px)가 창 chrome의 '빈' 영역(아이콘·검색·접힘 버튼이 아닌 곳)인가. Swift가 1이면 네이티브 타이틀바처럼
    /// 창 이동(performDrag)·더블클릭 확대(zoom)를 한다. MaruMetalTerminalView는 mouseDownCanMoveWindow=false라(터미널/
    /// 사이드바가 자체 마우스 사용) 콘텐츠 자동 드래그가 없고, 여기만 창 드래그 영역이다. 두 부분:
    ///   ① 사이드바 헤더(펼침, 좌측)의 빈 영역 — headerHit==.none(아이콘·검색 제외, 신호등 옆 빈 공간 포함).
    ///   ② 상단 타이틀바 띠(터미널 위·접힘 시 전체)의 빈 영역 — y<titlebar_strip_px, 접힘 ◧ 펼치기 버튼은 제외(클릭).
    /// quick terminal(chrome_minimal — 신호등 없는 borderless)이면 항상 false.
    pub fn isWindowDragRegion(self: *const AppSession, x_px: f64, y_px: f64) bool {
        if (self.chrome_minimal) return false;
        if (!std.math.isFinite(x_px) or !std.math.isFinite(y_px) or y_px < 0) return false;
        // ① 사이드바 헤더(펼침): 3줄 헤더의 빈 영역.
        if (self.sidebar_width_px > 0 and self.sidebar_header_height_px > 0 and self.inSidebar(x_px)) {
            if (y_px >= @as(f64, @floatFromInt(self.sidebar_header_height_px))) return false;
            return chrome.components.sidebar.headerHit(x_px, y_px, self.sidebar_width_px, self.cell_width_px, self.cell_height_px, self.sidebar_header_height_px) == .none;
        }
        // ② 상단 타이틀바 띠(터미널 위, 또는 접힘 시 전체 폭): 한 줄. 접힘 ◧ 펼치기 버튼·알림 종 위면 드래그 아님(클릭).
        if (self.titlebar_strip_px > 0 and y_px < @as(f64, @floatFromInt(self.titlebar_strip_px))) {
            if (self.collapsedToggleRect()) |r| {
                const rx: f64 = @floatFromInt(r.x);
                if (x_px >= rx and x_px < rx + @as(f64, @floatFromInt(r.w))) return false;
            }
            if (self.collapsedNotificationRect()) |r| {
                const rx: f64 = @floatFromInt(r.x);
                if (x_px >= rx and x_px < rx + @as(f64, @floatFromInt(r.w))) return false; // 접힘 종 클릭 영역 — 창 드래그 아님
            }
            return true;
        }
        return false;
    }

    /// 사이드바 y → 탭 슬롯 인덱스(순수 `sidebarSlot` 래퍼 — 슬롯 높이·탭 수·스크롤로 판정).
    fn sidebarSlotAt(self: *const AppSession, y_px: f64) ?usize {
        return chrome.components.sidebar.slotAt(y_px, self.sidebar_header_height_px, self.sidebar_slot_height_px, self.sidebar_scroll_offset_px, self.sidebar_visible_tabs.items.len);
    }

    /// 사이드바 콘텐츠(표시 카드 전체 높이)가 헤더 아래 뷰포트를 넘는 양(backing px). 0이면 스크롤 불필요.
    /// 순수 산술은 sidebarMaxScrollPx에 둬(헤드리스 단위 테스트) self는 필드만 떠 넘긴다.
    fn sidebarMaxScroll(self: *const AppSession) u32 {
        return sidebarMaxScrollPx(self.sidebar_slot_height_px, self.sidebar_visible_tabs.items.len, self.backing_height_px, self.sidebar_header_height_px);
    }

    /// 사이드바 스크롤 오프셋을 [0, sidebarMaxScroll]로 잡는다. 탭 추가/삭제·검색 필터·resize·휠로 콘텐츠/뷰포트가
    /// 바뀌면 stale 오프셋이 자동 정정된다(tab_scroll_cols 재clamp 선례). rebuildSidebar가 표시 탭 재계산 직후 호출.
    fn clampSidebarScroll(self: *AppSession) void {
        const max = self.sidebarMaxScroll();
        if (self.sidebar_scroll_offset_px > max) self.sidebar_scroll_offset_px = max;
    }

    /// 호버 중인 사이드바 슬롯을 갱신한다. 바뀌면 호버 밴드를 다시 만들고(rebuildSidebar) 재드로우한다.
    /// 같은 슬롯이면 무동작 — 한 슬롯 안에서의 마우스 이동이 매번 재드로우를 유발하지 않게 한다.
    fn setHoveredSlot(self: *AppSession, slot: ?usize) void {
        if (usizeOptEql(self.hovered_slot, slot)) return;
        self.hovered_slot = slot;
        self.rebuildSidebar() catch {};
        self.metal_dirty = true;
    }

    /// 호버 중인 알림 카드를 갱신한다(알림 패널 열림 시 hoverCursor가 hitTest 결과로 호출). 바뀌면 재드로우만 — 카드
    /// 데이터는 매 프레임 platform이 주입하므로 사이드바처럼 rebuild는 필요 없다. 같은 카드면 무동작(한 카드 안 이동 dedup).
    fn setHoveredNotification(self: *AppSession, idx: ?usize) void {
        if (usizeOptEql(self.chrome_host.notifications.hovered, idx)) return;
        self.chrome_host.notifications.hovered = idx;
        self.metal_dirty = true;
    }

    /// 알림 패널 hit-test 단일 출처(클릭 라우팅 mouse()와 호버 라우팅 hoverCursor가 공유). 임시 arena로 동적 Item을
    /// 빌드(buildNotificationItems — 역순)해 컴포넌트 hitTest에 넘기고 결과 Hit만 돌려준다(Item은 함수 안에서만 살고
    /// Hit은 인덱스/태그라 escape하지 않는다). 빌드 실패(OOM)면 null. 클릭/호버가 같은 좌표→Hit 매핑을 쓰게 해 둘이 어긋나지 않는다.
    fn notificationHitAt(self: *AppSession, x_px: f64, y_px: f64) ?chrome.components.notifications.Hit {
        var arena_state = std.heap.ArenaAllocator.init(self.allocator);
        defer arena_state.deinit();
        const items = self.buildNotificationItems(arena_state.allocator()) catch return null;
        return chrome.components.notifications.hitTest(&self.chrome_host.notifications, items, self.buildChromeProps(), x_px, y_px);
    }

    /// 호버 중인 per-pane 탭을 갱신한다. 바뀌면 재드로우한다(호버 ✕가 생기거나 사라진다). 같은 탭이면 무동작.
    fn setHoveredTab(self: *AppSession, tab: ?TabRef) void {
        if (tabRefEql(self.hovered_tab, tab)) return;
        self.hovered_tab = tab;
        self.metal_dirty = true;
    }

    /// #5b: 호버 중인 ‹/› 스크롤 버튼을 갱신한다. 바뀌면 재드로우(버튼이 밝아져 클릭 가능 표시). 같으면 무동작.
    fn setHoveredScroll(self: *AppSession, s: ?ScrollRef) void {
        const same = (self.hovered_scroll == null and s == null) or
            (self.hovered_scroll != null and s != null and self.hovered_scroll.?.pane == s.?.pane and self.hovered_scroll.?.right == s.?.right);
        if (same) return;
        self.hovered_scroll = s;
        self.metal_dirty = true;
    }

    /// 호버 중인 헤더 아이콘 영역을 갱신한다. 아이콘(◧/⚙/+)이면 그 region, 그 외(검색·none)는 null로 정규화한다.
    /// 바뀌면 사이드바를 재빌드해(retained layer 0 quad) 아이콘 뒤 호버 배경을 그리거나 지운다. 같으면 무동작
    /// (재빌드 churn 방지 — 아이콘 경계를 넘을 때만 1회). 검색 줄은 caret만 있고 호버 배경 없음(텍스트 입력 영역).
    fn setHoveredHeaderRegion(self: *AppSession, region: chrome.components.sidebar.HeaderRegion) void {
        const next: ?chrome.components.sidebar.HeaderRegion = switch (region) {
            .toggle_sidebar, .view_options, .new_workspace, .notifications => region,
            .search, .none => null,
        };
        if (self.hovered_header_region == next) return;
        self.hovered_header_region = next;
        self.rebuildSidebar() catch {};
        self.metal_dirty = true;
    }

    /// 접힘 펼치기 토글(◧) 호버 상태를 갱신한다 — 바뀔 때만 rebuildSidebar(호버 quad 추가/제거)+재렌더. 접힘이
    /// 아니면 항상 false로 둔다(펼치며 stale 호버 방지). setHoveredHeaderRegion의 접힘 버전.
    fn setHoveredCollapsedToggle(self: *AppSession, hovered: bool) void {
        const next = hovered and self.sidebar_collapsed;
        if (self.hovered_collapsed_toggle == next) return;
        self.hovered_collapsed_toggle = next;
        self.rebuildSidebar() catch {};
        self.metal_dirty = true;
    }

    /// 모든 마우스 호버 강조(슬롯 밴드·탭 ✕·헤더 아이콘·◧·스크롤바·Cmd+hover URL 밑줄)를 한 번에 끈다 — 닫기 확인
    /// 모달을 열 때 호출한다. hoverCursor가 모달 중엔 호버를 재계산하지 않으므로(.default early-return), 열기 직전에
    /// 비워야 중앙 패널 '밖'(사이드바·탭 바·좌상단 ◧·우측 스크롤바)에 켜져 있던 강조가 얼어붙어 보이지 않는다(키보드로
    /// 닫으면 마우스 이동이 없어 영구 잔존하던 회귀 — code-review). 각 setter는 무변화면 no-op이라 중복 rebuild 없음.
    fn clearAllHover(self: *AppSession) void {
        self.setHoveredSlot(null);
        self.setHoveredTab(null);
        self.setHoveredHeaderRegion(.none);
        self.setHoveredCollapsedToggle(false);
        self.setScrollbarHovered(false);
        self.clearHoverUrlAnchor();
    }

    /// pane 탭 바 호버 영역 — none(바 밖), tabs(탭/‹›/+/pane 포커스 = 클릭), grip(좌측 grip+라벨 = 드래그 손잡이).
    const BarHover = enum { none, tabs, grip };
    /// 마우스가 어느 pane의 탭 바 위면 (그 pane, 탭 index)으로 호버 탭을 갱신하고, 아니면 null로 비운다. 좌측
    /// grip+라벨 세그먼트면 grip(grab 커서). 활성 탭 leaf rect를 펴 각 pane 바를 hit-test한다. hoverCursor이 호출한다.
    fn updateHoveredTab(self: *AppSession, x_px: f64, y_px: f64) BarHover {
        var next: ?TabRef = null;
        var next_scroll: ?ScrollRef = null;
        var on_bar = false; // 탭 바 위 여부(탭 영역) — hoverCursor가 pointingHand(클릭 가능) 판정에 쓴다
        var on_grip = false; // 좌측 grip+라벨 세그먼트 위 여부 — grab(openHand) 커서
        // 매 이동마다 새 ArrayList를 안 만들고 재사용 scratch에 레이아웃을 다시 깐다(할당 churn 제거, 결과는 최신).
        const leaf_rects = &self.hover_leaf_scratch;
        leaf_rects.clearRetainingCapacity();
        if (self.activeTabLeafRects(self.allocator, self.termRect(), leaf_rects)) |_| {
            for (leaf_rects.items) |lr| {
                const pb = self.paneBar(lr.rect, lr.leaf) orelse continue;
                if (layout_math.pointInRect(x_px, y_px, pb.full)) {
                    on_bar = true; // 탭 바 위 — 탭·‹/›·+·pane 포커스 모두 클릭 가능 영역
                    // 좌측 grip+라벨 영역 = 드래그 손잡이(grab 커서). 탭 호버 아님(탭0 ✕ 오표시 방지) — 그 뒤 탭 영역만 hit-test.
                    if ((pb.grip_cols > 0 or pb.label_cols > 0) and x_px < @as(f64, @floatFromInt(pb.tabs.x))) {
                        on_grip = true;
                        break;
                    }
                    const count = lr.leaf.terms.items.len;
                    const m = barMetrics(pb.tabs, self.cell_width_px, count, self.buildChromeTokens().space.tab_width_cols, lr.leaf.tab_scroll_cols) orelse break; // 메트릭 불가(초소형 바) → 호버 없음
                    if (m.inScrollLeftZone(x_px)) { // #5b: ‹ 버튼 호버 — 탭 호버 아님
                        next_scroll = .{ .pane = lr.leaf, .right = false };
                        break;
                    }
                    if (m.inScrollRightZone(x_px)) { // #5b: › 버튼 호버
                        next_scroll = .{ .pane = lr.leaf, .right = true };
                        break;
                    }
                    if (m.inPlusZone(x_px)) break; // "+" 버튼 위 — 탭 호버 아님(마지막 탭에 ✕ 오표시 방지)
                    next = .{ .pane = lr.leaf, .tab = m.tabIndex(count, x_px) };
                    break;
                }
            }
        } else |_| {}
        self.setHoveredTab(next);
        self.setHoveredScroll(next_scroll);
        return if (on_grip) .grip else if (on_bar) .tabs else .none;
    }

    fn usizeOptEql(a: ?usize, b: ?usize) bool {
        if (a == null and b == null) return true;
        if (a == null or b == null) return false;
        return a.? == b.?;
    }

    /// 세로 사이드바 셀(탭 엔트리 밴드)을 다시 만든다 — 활성 탭 행에 하이라이트 밴드, 그리고 호버 슬롯이
    /// 활성과 다르면 그 행에 (더 약한) 호버 밴드를 emit한다. 탭 i는 행 i에 대응한다(한 탭=한 슬롯). 제목
    /// glyph는 여기서 안 만든다(tick의 제목 패스가 따로 더해 metal_buffer가 밴드와 머지). 사이드바가
    /// 꺼졌거나(폭 0) cell 폭 미상이면 비운다. 탭 추가/전환/메트릭/호버 변경 때 호출한다. 실패(OOM)는
    /// 세션을 죽이지 않고 빈 사이드바로 degrade한다(호출부가 catch).
    fn rebuildSidebar(self: *AppSession) !void {
        self.sidebar_cells.clearRetainingCapacity();
        self.gpu_quads.clearRetainingCapacity();
        self.recomputeVisibleTabs(); // 검색 필터로 표시 카드(sidebar_visible_tabs) 갱신 — 아래는 전부 표시 슬롯 기준
        self.clampSidebarScroll(); // 표시 카드 수/뷰포트가 바뀌었을 수 있으니 stale 스크롤 정정 — 아래 quad가 이 오프셋을 쓴다
        if (self.tabs.items.len == 0) return;
        // 밴드(활성/호버 슬롯·"+" 호버)는 chrome `sidebar.view`가 fill op으로 단일 출처. `lowerSidebar`가 그 fill을
        // sidebarBandCell(행=슬롯)로 lower한다(색·NativeMetalCell은 platform). host가 중립 Tab(활성)을 주입(palette Row 선례).
        var arena_state = std.heap.ArenaAllocator.init(self.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const tabs = self.sidebarTabs(arena) catch return;
        var ops: std.ArrayList(chrome.draw.Op) = .empty;
        chrome.components.sidebar.view(tabs, self.hovered_slot, self.pane_drop_slot, self.buildChromeProps(), arena, &ops) catch return;
        self.lowerSidebar(ops.items);
        // 헤더(검색바) 하단 구분선 — 검색 줄과 카드 목록 사이 경계를 명확히(사용자 요청 "Searchbar에 언더바"). divider
        // 색·border 두께로 사이드바 폭 전체에 가로선(layer 0=사이드바 retained). 검색 줄 바로 아래(=header_h 하단)에 둔다.
        if (self.sidebar_width_px > 0 and self.sidebar_header_height_px > 0) {
            const tk = self.buildChromeTokens();
            const thickness: f32 = @floatFromInt(@max(@as(u32, 1), tk.border.line_thickness_px));
            const uy: f32 = @as(f32, @floatFromInt(self.sidebar_header_height_px)) - thickness;
            self.appendSolidQuad(0, uy, @floatFromInt(self.sidebar_width_px), thickness, self.dividerColor(), 0);
        }
        // 헤더 아이콘 호버 배경(웹 버튼 hover) — hovered_header_region이 아이콘이면 그 아이콘 뒤에 둥근 quad(layer 0,
        // 아이콘 셀 아래). 아이콘 col은 buildSidebarHeaderDrawList과 같은 단일 레이아웃(◧ cols-8·⚙ cols-5·+ cols-2).
        // 아이콘은 .m이 1.7×로 확대+py_nudge 0.30하므로 셀 중심(가로)·~0.8ch(세로)에 앉는다 — quad를 거기에 맞춰 약 2칸×
        // 1.7줄로 덮고 가운데 정렬. 색은 탭 ‹›/슬롯 호버와 같은 sidebarHoverBg(중간 톤).
        if (self.hovered_header_region) |hr| {
            if (self.cell_width_px > 0 and self.cell_height_px > 0 and self.sidebar_width_px / self.cell_width_px >= 10) {
                const cols: u32 = self.sidebar_width_px / self.cell_width_px;
                const icon_col: u32 = switch (hr) {
                    .toggle_sidebar => cols -| 8,
                    .view_options => cols -| 5,
                    .new_workspace => cols -| 2,
                    .notifications => cols -| 12, // 벨 글리프(col cols-12, 2칸 폭)와 hover 정렬 — 2.6칸 폭 quad가 cols-12·cols-11 글리프를 덮는다
                    .search, .none => cols, // 도달 안 함(setHoveredHeaderRegion이 정규화) — 안전값
                };
                const cw: f32 = @floatFromInt(self.cell_width_px);
                const ch: f32 = @floatFromInt(self.cell_height_px);
                // hover quad 중심 = 글리프 중심. 1칸 아이콘(◧⚙+)은 셀 중심 (icon_col+0.5)cw. 종(notifications)은 EAW
                // width 2라 .m(is_bell_icon)이 2칸 footprint 중앙 (icon_col+1)cw에 그리므로 +1.0이라야 한다 — +0.5면 왼쪽
                // 셀(cols-12) 중심에 박스가 떨어져 좁아진 종이 박스 우측으로 치우쳐 보인다(예전 3.4cw 종은 박스보다 커서
                // 0.5cw 어긋남이 안 보였으나, width-2 수정으로 1.7cw가 되며 드러난 기존 버그).
                const center_cells: f32 = if (hr == .notifications) 1.0 else 0.5;
                const center_x: f32 = (@as(f32, @floatFromInt(icon_col)) + center_cells) * cw; // 글리프 중심(=.m gscale/footprint 중심)
                const w: f32 = cw * 2.6; // 좌우 패딩을 더 줘 버튼처럼(아이콘 ~1.7칸 + 양옆 여백) — 사용자 피드백
                const h: f32 = ch * 1.7;
                const radius: f32 = @min(w, h) * 0.28; // 둥근 버튼
                // 호버 배경은 **전경색(밝음) 기반 반투명**으로 둔다. 헤더 아이콘 glyph는 터미널 셀 패스(draw 1b)에,
                // 이 호버 quad는 layer 0(under, draw 3)이라 아이콘 '뒤'가 아니라 '위'에 그려진다(그 사이에 끼울 패스가
                // 없음). 그래서 중간톤/불투명이면 아이콘을 어둡게 덮었다(사용자 피드백). 밝은 전경색을 낮은 알파로 깔면
                // 어두운 사이드바 배경 위엔 밝은 하이라이트로 보이고, 밝은 아이콘 위엔 같은 밝기라 아이콘이 안 어두워진다.
                // GpuQuad는 **straight-alpha**(packRgbAlpha) — SDF quad 셰이더가 rgb*=a로 직접 premultiply한다
                // (스크롤바 quad와 같은 규약). premultipliedRgba를 쓰면 셰이더가 또 곱해 ~4배 흐려진다(코드리뷰 발견).
                const hover_fill = packRgbAlpha(self.appearance.theme.sidebar_foreground, 0x40); // ≈25% 밝은 하이라이트
                self.gpu_quads.append(self.allocator, .{
                    .x = center_x - w / 2.0,
                    .y = 0,
                    .w = w,
                    .h = h,
                    .corner_radii = .{ radius, radius, radius, radius },
                    .border_widths = .{ 0, 0, 0, 0 },
                    .fill_color0 = hover_fill,
                    .fill_color1 = hover_fill,
                    .border_color = 0,
                    .gradient_kind = 0,
                    .layer = 0,
                }) catch {};
            }
        }
        // per-tab 배경 tint(우클릭 메뉴 "배경: …") — background_color 설정된 워크스페이스 슬롯(밴드 없는 idle 슬롯)에
        // 반투명(≈40%) 색 quad를 텍스트 셀 아래(layer 0)에 얹는다. 활성/호버 슬롯은 위 lowerSidebar가 밴드 색에
        // tint를 블렌딩해 보이게 한다(tui 불투명 밴드가 이 quad를 덮으므로). chrome draw op은 role 기반이라 임의 RGB를
        // 못 실어, platform이 명시 색 GpuQuad로 직접 lower(사이드바 명시-색 경로). y는 f32 도메인으로 곱해 i32 overflow 회피.
        const slot_h = self.sidebar_slot_height_px;
        if (slot_h > 0 and self.sidebar_width_px > 0) for (self.sidebar_visible_tabs.items, 0..) |orig, i| {
            const tab = self.tabs.items[orig]; // 표시 슬롯 i → 원본 탭(검색 필터)
            if (tab.background_color == 0) continue;
            // GpuQuad는 straight-alpha(셰이더가 rgb*=a) — premultipliedRgba를 쓰면 이중 premultiply로 틴트가
            // 흐려져 활성/호버 슬롯의 blendRgb(직접 알파) 경로보다 약했다(code-review 발견). straight로 맞춰 일치시킨다.
            const c = (@as(u32, tab_bg_tint_alpha) << 24) | (tab.background_color & 0x00FF_FFFF);
            const abs_y = @as(f32, @floatFromInt(i)) * @as(f32, @floatFromInt(slot_h)) + @as(f32, @floatFromInt(self.sidebar_header_height_px));
            const sr = self.sidebarScrollClipQuad(abs_y, @floatFromInt(slot_h)) orelse continue; // 스크롤+헤더 클립(직각이라 corner 무관)
            self.gpu_quads.append(self.allocator, .{
                .x = 0,
                .y = sr.y,
                .w = @floatFromInt(self.sidebar_width_px),
                .h = sr.h,
                .corner_radii = .{ 0, 0, 0, 0 },
                .border_widths = .{ 0, 0, 0, 0 },
                .fill_color0 = c,
                .fill_color1 = c,
                .border_color = 0,
                .gradient_kind = 0,
                .layer = 0,
            }) catch {};
        };
        // 접힘 펼치기 토글(◧) 호버 배경 — 접힘 시 위 헤더-아이콘 호버 경로(sidebar_width_px>0 가드)가 안 타므로 여기서
        // 별도로 그린다. 토글 글리프는 .m이 titlebar_strip 안 세로 중앙 + 1.7×로 그리므로(metalFrame.titlebar_strip_px),
        // quad도 같은 중심에 맞춘다: 가로=셀 중심(col+0.5), 세로=띠 중앙, 폭≈2.6칸. 색·알파·둥글기는 헤더 아이콘 호버와
        // 동일(밝은 fg 반투명 — straight-alpha packRgbAlpha; premultipliedRgba면 셰이더 이중 premultiply로 흐려짐).
        if (self.sidebar_collapsed and self.hovered_collapsed_toggle and self.cell_width_px > 0 and self.cell_height_px > 0 and self.titlebar_strip_px > 0) {
            const cw: f32 = @floatFromInt(self.cell_width_px);
            const ch: f32 = @floatFromInt(self.cell_height_px);
            const strip: f32 = @floatFromInt(self.titlebar_strip_px);
            const w: f32 = cw * 2.6; // 아이콘(~1.7칸) + 좌우 여백 — 헤더 아이콘 호버와 같은 폭
            const h: f32 = ch * 1.7; // 글리프(1.7× 셀)와 같은 높이 — 헤더 아이콘 호버와 동일. cap하면 큰 폰트(1.7ch>strip)서
            const radius: f32 = @min(w, h) * 0.28; // 글리프가 pill 밖으로 삐져나가므로(code-review) 무cap으로 글리프와 정확히 일치
            const hover_fill = packRgbAlpha(self.appearance.theme.sidebar_foreground, 0x40); // ≈25% 밝은 하이라이트
            self.gpu_quads.append(self.allocator, .{
                .x = (@as(f32, @floatFromInt(self.collapsedToggleCol())) + 0.5) * cw - w / 2.0, // 셀 중심 기준 중앙
                .y = (strip - h) / 2.0, // 글리프와 같은 중심(strip/2). 1.7ch>strip이면 y<0(글리프도 띠 밖으로 나가므로 일치) — 렌더러 clip
                .w = w,
                .h = h,
                .corner_radii = .{ radius, radius, radius, radius },
                .border_widths = .{ 0, 0, 0, 0 },
                .fill_color0 = hover_fill,
                .fill_color1 = hover_fill,
                .border_color = 0,
                .gradient_kind = 0,
                .layer = 0,
            }) catch {};
        }
    }

    /// C4b 모달: self.gpu_quads에서 모달 배경 quad(layer==1)를 제거한다. sidebar 밴드(layer 0)는 retained
    /// (rebuildSidebar 관리)라 남기고, 모달 quad는 per-frame이라 renderFrame이 매 프레임 비운 뒤 build
    /// ChromeOverlayFrame이 다시 채운다 — 모달이 닫힌 프레임엔 안 채워져 유령 모달이 안 남는다(swapRemove,
    /// 순서 무관 — 렌더러가 layer로 재정렬). 리뷰가 지적한 sidebar/모달 clear-타이밍 충돌 해소.
    /// gpu_quads에서 주어진 layer의 quad를 모두 제거한다(per-frame 레이어 청소). 모달(layer 1)·탭 밴드(layer 2)는
    /// 매 프레임 재채워지므로 그 전에 비운다. 사이드바(layer 0)는 retained(rebuildSidebar 관리)라 대상이 아니다.
    fn dropQuadsByLayer(self: *AppSession, layer: u32) void {
        var i: usize = 0;
        while (i < self.gpu_quads.items.len) {
            if (self.gpu_quads.items[i].layer == layer) {
                _ = self.gpu_quads.swapRemove(i);
            } else {
                i += 1;
            }
        }
    }

    /// 활성 탭 강조(rich) — **연결형 cutout**: 활성 탭을 터미널 본문색(bg=theme.background)으로 채워 아래 본문과
    /// 이어져 보이게 하고(strip에서 도려낸 듯), 하단에 굵은 maru 앰버 언더바(active/focus indicator, 탭 seg 폭)를 얹는다.
    /// 옛 "평평한 약한 배경(sidebarActiveBg)"을 본문색으로 바꿔 깊이(strip↔본문)를 만든다(U-tab2). 배경·언더바 둘 다
    /// layer 2(셀 part1 제목 아래)라 본문색 quad가 하단 하이라인(appendTabBarUnderline)을 활성 탭 구간에서 덮어 "연결"이
    /// 끊기지 않는다. segOf 픽셀 경계로 hit-test·제목 glyph와 정합(§6 단일 소스). overflow 탭이면 무동작.
    /// `space.tab_active_style`(chrome.tab-style §7)로 분기: **connected**=본문색 cutout(바 전체) + 앰버 언더바, **underline**=
    /// 앰버 언더바만(bg fill 없음 — strip 그대로), **pill**=둥근 inset 캡슐을 **lifted 회색(`lifted_bg`)으로 채워** 띄우고 옅은 밝은
    /// 테두리만(실제 Warp 벤치마킹 — 밝은 fill로 올린다, 어두운 외곽선 아님). bg=본문색(connected cutout), lifted_bg=strip보다 밝은
    /// 색(pill fill·포커스 밝기), accent=포커스 앰버/비포커스 muted(connected·underline 언더바). 세 스타일 모두 **세그먼트 기하
    /// 불변**이라 hit-test/✕/드래그 공통(스타일은 세그먼트 안 fill만 바꿈, §5.4). 모두 layer 2(per-frame, dropQuadsByLayer(2)가 비움). tui는 tabbarHighlightCell 셀 밴드.
    fn appendActiveTabHighlight(self: *AppSession, m: chrome.components.tabbar.Metrics, tab_index: usize, bg: u32, lifted_bg: u32, accent: u32, space: chrome.tokens.Spacing, border: chrome.tokens.Border) void {
        const seg = m.segOf(tab_index);
        if (seg.end_col <= seg.start_col) return; // overflow(탭 영역 밖, 안 보이는) 탭
        const x: f32 = @floatCast(seg.start_px);
        const w: f32 = @floatCast(seg.end_px - seg.start_px);
        const by: f32 = @floatFromInt(m.bar_y);
        const bh: f32 = @floatFromInt(m.bar_h);
        switch (space.tab_active_style) {
            .connected, .underline => {
                const uw: f32 = @min(@as(f32, @floatFromInt(space.tab_underbar_px)), bh); // 바보다 두꺼우면 바 높이로 clamp(언더바가 바 위로 안 샘 — #496 리뷰)
                if (space.tab_active_style == .connected) self.appendSolidQuad(x, by, w, bh, bg, 2); // 본문색 cutout(strip 하이라인을 덮음). underline은 배경 fill 생략
                self.appendSolidQuad(x, by + bh - uw, w, uw, accent, 2); // 하단 maru 앰버/muted 언더바(active/focus indicator, 탭 폭)
            },
            .pill => {
                // 떠 있는 pill(실제 Warp 벤치마킹): 바 위아래로 inset한 둥근 캡슐을 **strip보다 밝은 lifted 회색**(`lifted_bg`)으로
                // 채워 "올라온 알약"으로 보이게 하고(Warp는 어두운 외곽선이 아니라 밝은 fill로 띄운다), 옅은 더 밝은 hairline 테두리만
                // 얹는다(Warp의 faint 테두리). 포커스 구분은 fill 밝기(focus=sidebarActiveBg / 비포커스=sidebarHoverBg) — 언더바·앰버 테두리 아님.
                const inset: f32 = @min(@as(f32, @floatFromInt(space.tab_pill_inset_px)), bh / 2.0); // inset>바높이/2면 clamp(ph≥0)
                const radius: f32 = @floatFromInt(space.corner_radius_px);
                const bw: f32 = @floatFromInt(border.line_thickness_px);
                const ph: f32 = @max(bh - 2.0 * inset, 1.0);
                self.gpu_quads.append(self.allocator, .{
                    .x = x,
                    .y = by + inset,
                    .w = w,
                    .h = ph,
                    .corner_radii = .{ radius, radius, radius, radius },
                    .border_widths = .{ bw, bw, bw, bw },
                    .fill_color0 = lifted_bg,
                    .fill_color1 = lifted_bg,
                    .border_color = blendRgb(lifted_bg, 0xFFFFFF, 0x28), // lifted_bg를 흰색으로 ~16% 블렌딩 — Warp식 옅은 밝은 테두리(가라앉은 앰버 외곽선 폐기)
                    .gradient_kind = 0,
                    .layer = 2,
                }) catch {};
            },
        }
    }

    /// #5a: 우측 가로 스크롤 ‹/› 버튼의 사각형 배경(GpuQuad layer 2) — col 셀(‹=tab_cols, ›=tab_cols+2) 영역을 약한
    /// 배경으로 채워 "클릭 가능한 버튼"으로 보이게 한다. glyph는 coretext가 같은 col에 그린다(배경 위). hover 색은 #5b, 커서는 #5c.
    fn appendScrollButtonQuad(self: *AppSession, m: chrome.components.tabbar.Metrics, col: u32, bg: u32) void {
        const x: f32 = @floatFromInt(m.bar_x + col * m.cell_width_px);
        self.appendSolidQuad(x, @floatFromInt(m.bar_y), @floatFromInt(m.cell_width_px), @floatFromInt(m.bar_h), bg, 2);
    }

    /// solid 직각 GpuQuad(곡률·테두리·gradient 없음)를 지정 layer에 append하는 공통 헬퍼 — appendBarBgQuad·
    /// appendTabBarUnderline이 공유해 같은 11필드 보일러플레이트 반복을 없앤다(GpuQuad는 extern struct라 필드
    /// default가 없어 필드 추가 시 모든 리터럴을 손봐야 하는데, solid 직각 quad는 이 헬퍼 한 곳으로 모은다). 둥근/
    /// 테두리/gradient quad는 따로 — 각자 모양 파라미터를 받아 일반화하지 않는다.
    fn appendSolidQuad(self: *AppSession, x: f32, y: f32, w: f32, h: f32, color: u32, layer: u32) void {
        self.gpu_quads.append(self.allocator, .{
            .x = x,
            .y = y,
            .w = w,
            .h = h,
            .corner_radii = .{ 0, 0, 0, 0 },
            .border_widths = .{ 0, 0, 0, 0 },
            .fill_color0 = color,
            .fill_color1 = color,
            .border_color = 0,
            .gradient_kind = 0,
            .layer = layer,
        }) catch {};
    }

    /// 사이드바 세로 스크롤의 최대 오프셋(backing px) — 표시 카드 전체 높이가 헤더 아래 뷰포트를 넘는 양. 순수 함수라
    /// 헤드리스 단위 테스트 가능. content = 표시 탭 수 × 슬롯 높이, viewport = backing 높이 − 헤더(카드 아래 "+"는
    /// 헤더로 이동해 콘텐츠에 없음). content ≤ viewport(또는 슬롯 0)면 0(스크롤 불필요). u64로 계산해 곱셈 overflow 회피.
    fn sidebarMaxScrollPx(slot_height_px: u32, visible_count: usize, backing_height_px: u32, header_height_px: u32) u32 {
        if (slot_height_px == 0) return 0;
        const content: u64 = @as(u64, visible_count) * @as(u64, slot_height_px);
        const viewport: u64 = if (backing_height_px > header_height_px) backing_height_px - header_height_px else 0;
        if (content <= viewport) return 0;
        return @intCast(@min(content - viewport, @as(u64, std.math.maxInt(u32))));
    }

    /// 스크롤바 thumb 기하(보이는 영역 내 y offset·높이, backing px) — 순수 함수라 단위 테스트 가능. sb_count==0
    /// (스크롤백 없음)·메트릭 0이면 null(안 그림). thumb 높이=보이는 비율(view/(sb+view)), 최소 높이로 clamp.
    /// y: view_offset 0(바닥)이면 view_h-thumb_h(아래), sb_count(꼭대기)면 0(위) — 위로 스크롤할수록 thumb가 올라간다.
    fn scrollbarThumbGeom(sb_count: usize, view_offset: usize, cell_height_px: u32, view_h_px: u32) ?struct { y: f32, h: f32 } {
        if (sb_count == 0 or cell_height_px == 0 or view_h_px == 0) return null;
        const ch: f32 = @floatFromInt(cell_height_px);
        const sb_px: f32 = @as(f32, @floatFromInt(sb_count)) * ch; // 스크롤백 총 높이(px)
        const view_px: f32 = @floatFromInt(view_h_px); // 보이는 높이
        const min_thumb: f32 = @max(view_px * 0.04, 18.0);
        var thumb_h: f32 = view_px * view_px / (sb_px + view_px);
        if (thumb_h < min_thumb) thumb_h = min_thumb;
        if (thumb_h > view_px) thumb_h = view_px;
        const t: f32 = if (sb_px > 0) @as(f32, @floatFromInt(view_offset)) * ch / sb_px else 0; // 0..1
        return .{ .y = (view_px - thumb_h) * (1.0 - t), .h = thumb_h };
    }

    /// 드래그 위치 t(0=트랙 바닥, 1=꼭대기)를 view_offset으로 매핑 — scrollbarThumbGeom의 `t = view_offset/sb_count`
    /// 역(逆). [0,1]로 clamp 후 round해 [0,sb_count] 정수 offset. 순수 함수라 단위 테스트 가능.
    fn scrollbarTargetOffset(t: f64, sb_count: usize) usize {
        var tt = t;
        if (tt < 0) tt = 0;
        if (tt > 1) tt = 1;
        return @intFromFloat(@round(tt * @as(f64, @floatFromInt(sb_count))));
    }

    /// 스크롤바 thumb 폭(px) — cell_width 비율, 최소 px 보장. emphasized(hover/드래그)면 +emphasize_px로 굵게.
    /// appendScrollbar(그리기)·scrollbarGrabAt(hit-test)가 공유해 폭이 어긋나지 않게 한다(순수 함수 — 테스트 가능).
    fn scrollbarBarWidthPx(cell_width_px: u32, emphasized: bool) f32 {
        const base = @max(@as(f32, @floatFromInt(cell_width_px)) * scrollbar_bar_mul, scrollbar_bar_min_px);
        return if (emphasized) base + scrollbar_bar_emphasize_px else base;
    }

    /// idle 틱에 따른 스크롤바 alpha(0xAARRGGBB의 A). visible_ticks까지 full, 이어 fade_ticks 동안 full→idle로
    /// 선형 감쇠, 이후 idle(faint) 유지(숨기지 않음). 순수 함수 — 테스트 가능. hover/드래그 override는 호출처에서.
    fn computeScrollbarAlpha(idle_ticks: u32) u8 {
        return computeScrollbarAlphaFor(idle_ticks, default_scrollbar_visible_ticks, default_scrollbar_fade_ticks);
    }

    fn computeScrollbarAlphaFor(idle_ticks: u32, visible_ticks: u32, fade_ticks: u32) u8 {
        if (idle_ticks <= visible_ticks) return scrollbar_alpha_full;
        if (idle_ticks >= visible_ticks + fade_ticks) return scrollbar_alpha_idle;
        const into: u32 = idle_ticks - visible_ticks; // 1..fade_ticks-1
        const drop: u32 = @as(u32, scrollbar_alpha_full - scrollbar_alpha_idle) * into / fade_ticks;
        return @intCast(@as(u32, scrollbar_alpha_full) - drop);
    }

    fn scrollbarAlpha(self: *const AppSession, idle_ticks: u32) u8 {
        return computeScrollbarAlphaFor(idle_ticks, self.scrollbarVisibleTicks(), self.scrollbarFadeTicks());
    }

    /// 마우스가 스크롤바 영역에 있는지 갱신(hoverCursor가 매 이동 호출). 바뀌면 redraw 표시 — hover 강조가
    /// 곧바로 나타나거나 사라지게. fade 리셋(idle_ticks=0)은 updateScrollbarFade가 hover를 보고 한다.
    fn setScrollbarHovered(self: *AppSession, on: bool) void {
        if (self.scrollbar_hovered == on) return;
        self.scrollbar_hovered = on;
        self.metal_dirty = true;
    }

    /// 매 tick 스크롤바 fade를 갱신한다(updateCursorBlink와 같은 frame-loop tick). 한 곳에서 활성 surface의 view_offset
    /// 변화를 감지해(스크롤·드래그·page-key·surface 전환) idle_ticks를 0(full)으로 리셋하고, hover/드래그면 full로
    /// 핀, 그 외엔 매 tick 늘려 fade 창에서 alpha가 바뀔 때만 metal_dirty를 세운다(idle 정착 후엔 정적 — 비용 0).
    fn updateScrollbarFade(self: *AppSession) void {
        if (!self.surface_initialized) return;
        const visible_ticks = self.scrollbarVisibleTicks();
        const fade_done_ticks = self.scrollbarFadeCompleteTicks();
        // 활성 탭의 모든 pane을 순회해 각자 fade를 갱신한다(per-pane — pane 목록만 보면 되고 rect/layout 불요라
        // 매 tick 싸다). 활성 pane은 hover/드래그면 full로 핀. 한 pane이라도 alpha가 바뀌면 metal_dirty.
        const active_pane = self.activePane();
        for (self.activeTab().panes.items) |pane| {
            const psurface = &pane.activeTerm().surface;
            // scrollbackLen(리더 core.write가 증가)·viewOffset 스칼라를 락 아래 한 번에 읽는다
            // (docs/io-render-threading.md PR3). 비-const 메서드라 락 가능.
            psurface.lockCore(self.io);
            const sb_len = psurface.core.scrollbackLen();
            const vo = psurface.core.viewOffset();
            psurface.unlockCore(self.io);
            if (sb_len == 0) {
                // 스크롤바 없음 — 다음 등장이 full로 시작하게 타이머 리셋(0→nonzero 전환).
                pane.scrollbar_idle_ticks = 0;
                pane.scrollbar_last_view_offset = 0;
                continue;
            }
            if (vo != pane.scrollbar_last_view_offset) { // 이 pane 스크롤 활동 → full로 복귀
                pane.scrollbar_last_view_offset = vo;
                if (pane.scrollbar_idle_ticks != 0) self.metal_dirty = true;
                pane.scrollbar_idle_ticks = 0;
                continue;
            }
            if (pane == active_pane and (self.scrollbar_hovered or self.scrollbar_drag_grab != null)) { // 활성 pane 상호작용 — full 핀
                if (pane.scrollbar_idle_ticks != 0) {
                    pane.scrollbar_idle_ticks = 0;
                    self.metal_dirty = true;
                }
                continue;
            }
            if (pane.scrollbar_idle_ticks >= fade_done_ticks) continue; // faint 정착 — 정적
            pane.scrollbar_idle_ticks += 1;
            if (pane.scrollbar_idle_ticks > visible_ticks) self.metal_dirty = true; // fade 창 — alpha 변함
        }
        // 사이드바 스크롤바 fade(단일 트랙 — pane과 동형). 스크롤 활동은 offset 변화로 감지(휠/clamp가 바꾼다).
        // 스크롤 불필요(max 0)면 다음 등장이 full로 시작하게 타이머·last를 리셋한다.
        if (self.sidebarMaxScroll() == 0) {
            self.sidebar_scrollbar_idle_ticks = fade_done_ticks; // faint 정착(안 보임)
            self.sidebar_scrollbar_last_offset = self.sidebar_scroll_offset_px;
        } else if (self.sidebar_scroll_offset_px != self.sidebar_scrollbar_last_offset) { // 스크롤 활동 → full 복귀
            self.sidebar_scrollbar_last_offset = self.sidebar_scroll_offset_px;
            if (self.sidebar_scrollbar_idle_ticks != 0) self.metal_dirty = true;
            self.sidebar_scrollbar_idle_ticks = 0;
        } else if (self.sidebar_scrollbar_idle_ticks < fade_done_ticks) {
            self.sidebar_scrollbar_idle_ticks += 1;
            if (self.sidebar_scrollbar_idle_ticks > visible_ticks) self.metal_dirty = true; // fade 창 — alpha 변함
        }
    }

    /// down 좌표가 활성 pane 스크롤바(thumb 또는 트랙)에 있으면 잡은 grab offset(y_px - thumb_top, px)을 돌려준다.
    /// thumb 위면 그 offset(드래그가 thumb 내 상대 위치를 유지), thumb 밖 트랙이면 thumb_h/2(클릭 지점에 thumb
    /// 중앙을 맞춰 점프). 스크롤백 없음·메트릭 0·영역 밖이면 null. x 영역은 thumb 폭 + 좌측 4px 여유(잡기 쉽게),
    /// y는 트랙(pane) 전체. appendScrollbar와 같은 bar_w(cell_width*0.32, 최소 5)·우측 2px 안쪽 배치를 쓴다.
    fn scrollbarGrabAt(self: *const AppSession, x_px: f64, y_px: f64) ?f32 {
        const rect = self.active_pane_rect;
        if (rect.w == 0 or self.cell_width_px == 0) return null;
        const core = &self.activeSurfaceConst().core;
        const geom = scrollbarThumbGeom(core.scrollbackLen(), core.viewOffset(), self.cell_height_px, rect.h) orelse return null;
        // thumb가 트랙을 꽉 채워 스크롤 여지가 없으면(track<=0, degenerate 작은 pane) 잡지 않는다 — 안 그러면
        // 클릭을 캡처하고도 dragScrollbarTo가 무동작이라 선택도 스크롤도 안 되는 dead zone이 된다.
        if (geom.h >= @as(f32, @floatFromInt(rect.h))) return null;
        // hit-test는 base 폭(비-emphasized) + 4px 여유 — hover로 굵어진 폭이 아니라 안정된 base로 잡는다.
        const bar_w: f64 = scrollbarBarWidthPx(self.cell_width_px, false);
        const right: f64 = @floatFromInt(rect.x + rect.w);
        const zone_left: f64 = right - bar_w - 2.0 - 4.0; // thumb 좌단(우측 2px 안쪽) - 4px grab 여유
        if (x_px < zone_left or x_px > right) return null;
        const top: f64 = @floatFromInt(rect.y);
        const bottom: f64 = top + @as(f64, @floatFromInt(rect.h));
        if (y_px < top or y_px > bottom) return null;
        const thumb_top: f64 = top + @as(f64, geom.y);
        const grab: f64 = y_px - thumb_top;
        if (grab >= 0 and grab <= @as(f64, geom.h)) return @floatCast(grab); // thumb 위 — 상대 위치 유지
        return geom.h * 0.5; // 트랙 — thumb 중앙을 클릭에 맞춤(점프)
    }

    /// 드래그/트랙-점프 중 마우스 y로 view_offset을 절대 설정한다. new_thumb_top(view 내) = (y_px - rect.y) - grab을
    /// [0, track]로 clamp(track = view_h - thumb_h), t = 1 - thumb_top/track(0=바닥, 1=꼭대기), target =
    /// scrollbarTargetOffset(t, sb_count). 현재 viewOffset과의 차이만큼 scrollViewport(절대 위치 → 상대 delta).
    fn dragScrollbarTo(self: *AppSession, y_px: f64) void {
        const grab: f64 = self.scrollbar_drag_grab orelse return;
        const rect = self.active_pane_rect;
        if (rect.h == 0 or self.cell_height_px == 0) return;
        // 코어 읽기(scrollbackLen·viewOffset)는 락 아래(§9.1). scrollViewport mutate는 **락 밖에서** reader에 위임
        // (full (a)) — 락을 잡은 채 enqueueCoreCommand하면 non-interactive 폴백이 같은 core_mutex를 재취득해 재진입
        // (panic/deadlock). 그래서 읽기만 락에 가두고, enqueue는 락 해제 후 한다(다른 위임 사이트와 같은 규율).
        const surface = self.activeSurface();
        const snap = blk: {
            surface.lockCore(self.io);
            defer surface.unlockCore(self.io);
            break :blk .{ .total_sb = surface.core.scrollbackLen(), .view_offset = surface.core.viewOffset() };
        };
        const total_sb = snap.total_sb;
        if (total_sb == 0) return;
        // thumb_h는 view_offset과 무관(sb_count·ch·view_h만) — 현재 offset으로 구해도 .h는 안정적.
        const geom = scrollbarThumbGeom(total_sb, snap.view_offset, self.cell_height_px, rect.h) orelse return;
        const view_px: f64 = @floatFromInt(rect.h);
        const track: f64 = view_px - @as(f64, geom.h); // thumb_top 가동 범위
        if (track <= 0) return; // thumb가 트랙을 꽉 채움 — 스크롤 여지 없음
        var thumb_top: f64 = (y_px - @as(f64, @floatFromInt(rect.y))) - grab;
        if (thumb_top < 0) thumb_top = 0;
        if (thumb_top > track) thumb_top = track;
        const t: f64 = 1.0 - thumb_top / track; // 0=바닥(offset 0), 1=꼭대기(offset sb_count)
        const target = scrollbarTargetOffset(t, total_sb);
        // 절대 목표를 reader에 위임(scroll_to_offset) — reader가 적용 시점의 fresh view_offset에서 delta 계산
        // (메인이 delta를 미리 빼면 연속 드래그가 옛 base로 double-count돼 어긋남).
        if (target != snap.view_offset) {
            self.runtime.enqueueCoreCommand(surface.id, .{ .scroll_to_offset = target }, self.io) catch {};
            self.metal_dirty = true;
        }
    }

    /// 활성 탭의 모든 pane 우측에 스크롤바를 그린다 — **각 pane이 자기 idle_ticks로 독립 fade**(per-pane), 활성
    /// pane만 추가로 hover/드래그 강조(세션 상태). 각 pane은 자기 core의 view_offset/scrollback을 반영. leaf rect는
    /// 재사용 scratch로 계산(per-frame 할당 churn 없음), 실패(OOM)면 활성 pane만(폴백). per-frame(layer3)에서 부른다.
    fn appendPaneScrollbars(self: *AppSession) void {
        if (!self.surface_initialized) return;
        self.scrollbar_leaf_scratch.clearRetainingCapacity();
        if (self.activeTabLeafRects(self.allocator, self.termRect(), &self.scrollbar_leaf_scratch)) |_| {
            const active_pane = self.activePane();
            for (self.scrollbar_leaf_scratch.items) |lr| {
                const trect = self.paneTermRect(lr.rect); // 상단 탭 바를 뺀 터미널 영역(active_pane_rect와 같은 식)
                self.appendScrollbar(trect, lr.leaf, lr.leaf == active_pane);
            }
        } else |_| {
            self.appendScrollbar(self.active_pane_rect, self.activePane(), true);
        }
    }

    /// 시각 벨(bell.visual): flash 중(bell_flash_ticks>0)이면 화면 전체(backing px)를 전경색 반투명 GpuQuad로 덮고
    /// 남은 tick 비율로 alpha를 정해 페이드한다. over 패스(layer 1)라 셀·chrome 위에 뜬다. 매 frame 1 감소 —
    /// 0이면 멈춘다. metal_dirty(다음 frame 재빌드)는 dispatchBell이 세운다. dispatchBell 단일 drain 후 build에서 호출(F2-4).
    fn appendBellFlashQuad(self: *AppSession) void {
        if (self.bell_flash_ticks == 0) return;
        // alpha = peak × (남은 tick / 총 tick). 첫 tick=full peak → 마지막 tick=거의 투명.
        const fade_milli: u32 = bell_flash_peak_milli * self.bell_flash_ticks / self.bellFlashTotalTicks();
        const alpha: u8 = @intCast(@min(@as(u32, 255), fade_milli * 255 / 1000));
        const color: u32 = packRgbAlpha(self.appearance.theme.foreground, alpha); // straight-alpha(셰이더가 rgb*=a)
        self.gpu_quads.append(self.allocator, .{
            .x = 0,
            .y = 0,
            .w = @floatFromInt(self.backing_width_px),
            .h = @floatFromInt(self.backing_height_px),
            .corner_radii = .{ 0, 0, 0, 0 },
            .border_widths = .{ 0, 0, 0, 0 },
            .fill_color0 = color,
            .fill_color1 = color,
            .border_color = 0,
            .gradient_kind = 0,
            .layer = 1, // over 패스 — 화면 전체 덮음(scrollbar layer 3·modal layer 1과 같은 over, append 순서로 위)
        }) catch {};
        self.bell_flash_ticks -= 1; // 페이드: 다음 frame은 더 흐리게(0이면 다음 dispatchBell이 metal_dirty 안 세움)
    }

    /// 배경 이미지(window.background-image, F2-1) 디코드 캐시를 config 경로와 동기화한다. 경로가 바뀐 frame에만
    /// 파일을 읽어 PNG를 디코드한다(매 frame 디코드 방지) — 디코드 픽셀은 bg_image_pixels에 owned로 보관하고
    /// generation을 올려 렌더러 텍스처 1회 재업로드를 트리거한다. 빈 경로/읽기·디코드 실패는 배경 없음(width=0)으로
    /// 조용히 폴백하되 path_cache는 갱신해 같은 (잘못된) 경로를 매 frame 다시 읽지 않게 한다.
    /// 베이스: kitty graphics f=100 PNG 디코더(terminal/png.zig) 재사용 — JPEG 등은 후속(maru 내장 디코더 PNG만).
    fn ensureBackgroundImage(self: *AppSession) void {
        const path = self.loaded_config.config.window_background_image;
        // 경로 무변: 이미 이 경로로 디코드(또는 폴백)했다 — 재작업 없음.
        if (std.mem.eql(u8, path, self.bg_image_path_cache)) return;

        // 경로가 바뀌었다(빈→채움·채움→다름·채움→빈 포함). 옛 디코드 픽셀·path_cache를 버리고 새로 시도한다.
        if (self.bg_image_pixels.len > 0) self.allocator.free(self.bg_image_pixels);
        self.bg_image_pixels = &.{};
        self.bg_image_width = 0;
        self.bg_image_height = 0;
        self.allocator.free(self.bg_image_path_cache);
        self.bg_image_path_cache = self.allocator.dupe(u8, path) catch &.{};
        self.bg_image_generation +%= 1; // 경로 변경 → 렌더러가 옛 텍스처를 버리고(빈 경로면 evict) 새로 업로드

        if (path.len == 0) return; // 빈 경로 = 배경 없음

        // 절대경로 PNG 파일을 읽어 디코드한다. 못 읽거나(없음·권한) 미지원 PNG면 width=0 유지(조용한 폴백).
        // 파일 상한 64MiB(디코드 출력 상한은 png.decode 내부 320MB) — 비정상적으로 큰 파일은 거부.
        const bytes = std.Io.Dir.cwd().readFileAlloc(self.io, path, self.allocator, .limited(1 << 26)) catch return;
        defer self.allocator.free(bytes);
        const img = terminal.png.decode(self.allocator, bytes) catch return;
        // decode 성공: img.data(owned)를 그대로 인수받는다(복사 없음). bpp는 3(RGB)/4(RGBA).
        self.bg_image_pixels = img.data;
        self.bg_image_width = img.width;
        self.bg_image_height = img.height;
        self.bg_image_bpp = img.bpp;
    }

    /// 디코드된 배경 이미지(F2-1)를 창 전체를 덮는 pass-0 GpuImage로 환산한다. aspect-fill(cover) — 종횡비를
    /// 유지하며 창을 꽉 채우고, 넘치는 축을 가운데 기준으로 UV crop한다. pass=0·z=minInt이라 kitty 이미지·셀
    /// 배경·텍스트 모두보다 뒤에 그려져 default 배경 셀(빈 영역)로 비친다. 디코드 픽셀/창 크기가 없으면 null.
    fn buildBackgroundGpuImage(self: *AppSession) ?metal_frame.GpuImage {
        if (self.bg_image_width == 0 or self.bg_image_height == 0) return null;
        if (self.backing_width_px == 0 or self.backing_height_px == 0) return null;
        const win_w: f32 = @floatFromInt(self.backing_width_px);
        const win_h: f32 = @floatFromInt(self.backing_height_px);
        const img_w: f32 = @floatFromInt(self.bg_image_width);
        const img_h: f32 = @floatFromInt(self.bg_image_height);
        const win_aspect = win_w / win_h;
        const img_aspect = img_w / img_h;
        var uv_u0: f32 = 0;
        var uv_v0: f32 = 0;
        var uv_u1: f32 = 1;
        var uv_v1: f32 = 1;
        if (win_aspect > img_aspect) {
            // 창이 이미지보다 넓다 → 가로를 꽉 채우고 세로를 crop(visible = 보이는 세로 비율).
            const visible = img_aspect / win_aspect;
            uv_v0 = (1.0 - visible) / 2.0;
            uv_v1 = 1.0 - uv_v0;
        } else {
            // 창이 이미지보다 좁(높)다 → 세로를 꽉 채우고 가로를 crop.
            const visible = win_aspect / img_aspect;
            uv_u0 = (1.0 - visible) / 2.0;
            uv_u1 = 1.0 - uv_u0;
        }
        return metal_frame.GpuImage{
            .image_id = background_image_id,
            .dest_x = 0,
            .dest_y = 0,
            .dest_w = win_w,
            .dest_h = win_h,
            .origin_x = 0,
            .origin_y = 0,
            .src_u0 = uv_u0,
            .src_v0 = uv_v0,
            .src_u1 = uv_u1,
            .src_v1 = uv_v1,
            .z = std.math.minInt(i32), // pass 0 안에서도 맨 뒤(혹시 z<bg_limit인 kitty 이미지보다 더 뒤)
            .pass = 0, // below_bg — 셀 배경·텍스트 모두 앞에 그려져 default 배경 셀로 비침
        };
    }

    /// 한 pane 우측에 스크롤바 thumb(둥근 GpuQuad)를 그린다 — 스크롤백이 있을 때만(sb_count>0). thumb 높이는
    /// 보이는 비율, 위치는 view_offset(0=바닥, sb_count=꼭대기)을 반영한다. 셀 위(layer 3 over)에 뜬다.
    /// alpha는 pane.scrollbar_idle_ticks로 fade(활성·비활성 모두 per-pane 독립). `is_active`면 추가로 hover/드래그
    /// 강조(굵게+full, 세션 상태) — 상호작용(hover/드래그)은 활성 pane만이라 비활성 pane은 fade만(emphasize 없음).
    /// 메모리 'UI는 Zig+GPU 렌더러로' — 네이티브 NSScroller가 아니라 chrome GpuQuad 프리미티브. 좌표는 backing 픽셀.
    fn appendScrollbar(self: *AppSession, rect: maru.session.SplitRect, pane: *Pane, is_active: bool) void {
        if (rect.w == 0) return;
        const core = &pane.activeTerm().surface.core;
        const geom = scrollbarThumbGeom(core.scrollbackLen(), core.viewOffset(), self.cell_height_px, rect.h) orelse return;
        const thumb_y: f32 = @as(f32, @floatFromInt(rect.y)) + geom.y;
        const thumb_h: f32 = geom.h;
        // 활성 pane만 hover/드래그로 굵게+full(세션 상태). alpha는 **per-pane fade**(각 pane scrollbar_idle_ticks) —
        // 활성·비활성 모두 자기 스크롤 활동으로 독립적으로 흐려진다(비활성 pane을 휠로 스크롤하면 그 pane만 full→fade).
        const emphasized = is_active and (self.scrollbar_hovered or self.scrollbar_drag_grab != null);
        const bar_w: f32 = scrollbarBarWidthPx(self.cell_width_px, emphasized);
        const x: f32 = @as(f32, @floatFromInt(rect.x + rect.w)) - bar_w - 2.0; // 우측 가장자리에서 2px 안쪽
        const alpha: u8 = if (emphasized) scrollbar_alpha_full else self.scrollbarAlpha(pane.scrollbar_idle_ticks);
        const rgb = self.mutedForeground(); // muted 전경(사이드바 비활성 탭과 같은 톤)
        const color: u32 = packRgbAlpha(rgb, alpha); // 셰이더가 rgb*=a premultiply
        const r = bar_w * 0.5; // pill 모양(반지름 = 폭 절반)
        self.gpu_quads.append(self.allocator, .{
            .x = x,
            .y = thumb_y,
            .w = bar_w,
            .h = thumb_h,
            .corner_radii = .{ r, r, r, r },
            .border_widths = .{ 0, 0, 0, 0 },
            .fill_color0 = color,
            .fill_color1 = color,
            .border_color = 0,
            .gradient_kind = 0,
            .layer = 3, // over 패스(셀·사이드바 위) per-frame. layer 1(모달)이 gpu_quads에서 뒤에 append돼 위로 — 모달이 스크롤바를 가린다.
        }) catch {};
    }

    /// 사이드바 우측에 세로 스크롤바 thumb(layer 3 over)를 그린다 — 워크스페이스 카드가 헤더 아래 뷰포트를 넘을 때만.
    /// pane 스크롤바와 같은 pill 모양·muted 색·fade(sidebar_scrollbar_idle_ticks)를 쓰되, 단일 트랙이라 per-frame
    /// (appendPaneScrollbars 옆에서) 호출한다. 트랙 = [헤더 하단, backing 하단], thumb 위치는 offset/maxScroll.
    /// 접힘(폭 0)·헤더 없음·스크롤 불필요면 무동작. dropQuadsByLayer(3)가 매 프레임 비우므로 누적 안 됨.
    fn appendSidebarScrollbar(self: *AppSession) void {
        if (self.sidebar_width_px == 0 or self.cell_width_px == 0) return;
        const slot_h = self.sidebar_slot_height_px;
        if (slot_h == 0) return;
        const header = self.sidebar_header_height_px;
        if (self.backing_height_px <= header) return;
        const viewport_h: u32 = self.backing_height_px - header;
        const max_scroll = self.sidebarMaxScroll();
        if (max_scroll == 0) return; // 안 넘침 — 스크롤바 없음
        const view_px: f32 = @floatFromInt(viewport_h);
        const content_px: f32 = @as(f32, @floatFromInt(self.sidebar_visible_tabs.items.len)) * @as(f32, @floatFromInt(slot_h));
        const min_thumb: f32 = @max(view_px * 0.04, 18.0);
        var thumb_h: f32 = if (content_px > 0) view_px * view_px / content_px else view_px;
        if (thumb_h < min_thumb) thumb_h = min_thumb;
        if (thumb_h > view_px) thumb_h = view_px;
        const t: f32 = @as(f32, @floatFromInt(self.sidebar_scroll_offset_px)) / @as(f32, @floatFromInt(max_scroll)); // 0(맨 위)..1(맨 아래)
        const thumb_y: f32 = @as(f32, @floatFromInt(header)) + (view_px - thumb_h) * t;
        const bar_w: f32 = scrollbarBarWidthPx(self.cell_width_px, false);
        const x: f32 = @as(f32, @floatFromInt(self.sidebar_width_px)) - bar_w - 2.0; // 사이드바 우측 가장자리에서 2px 안쪽
        const alpha: u8 = self.scrollbarAlpha(self.sidebar_scrollbar_idle_ticks); // pane과 같은 fade 곡선
        const color: u32 = packRgbAlpha(self.mutedForeground(), alpha); // muted 전경(비활성 탭과 같은 톤), 셰이더 rgb*=a
        const r = bar_w * 0.5; // pill(반지름 = 폭 절반)
        self.gpu_quads.append(self.allocator, .{
            .x = x,
            .y = thumb_y,
            .w = bar_w,
            .h = thumb_h,
            .corner_radii = .{ r, r, r, r },
            .border_widths = .{ 0, 0, 0, 0 },
            .fill_color0 = color,
            .fill_color1 = color,
            .border_color = 0,
            .gradient_kind = 0,
            .layer = 3, // over — 셀·밴드 위. dropQuadsByLayer(3)가 per-frame 비움(pane 스크롤바와 짝).
        }) catch {};
    }

    /// C4b-5: rich 탭 바 배경(직각)을 layer 2 GpuQuad로 그린다 — 활성 탭 밴드 quad(같은 layer, 뒤에 append되어 위로)가
    /// 불투명 셀 배경(paneBarBgCell)에 가리지 않게(리뷰 z-order #1, #451과 동형). tui는 셀. 둘 다 part1 제목 셀 아래(layer 2).
    fn appendBarBgQuad(self: *AppSession, bar: maru.session.SplitRect, bg: u32) void {
        self.appendSolidQuad(@floatFromInt(bar.x), @floatFromInt(bar.y), @floatFromInt(bar.w), @floatFromInt(bar.h), bg, 2);
    }

    /// 탭바 하단 구분선(divider 색)을 layer 2 GpuQuad로 — 탭바를 터미널 콘텐츠와 시각 분리(rich). 활성 탭 영역은
    /// 활성 밴드(나중 append)가 위에 덮어 자연히 밴드 색이 되고, 비활성 영역엔 divider 구분선이 보인다.
    /// 두께는 `border.line_thickness_px` 토큰(rich 2px)을 받는다 — 1px GpuQuad는 SDF AA(maru_quad_fragment
    /// 78행 `cov=1-smoothstep(-aa,aa,d)`)가 1px-tall(half_size.y=0.5)에서 cov≈0.84로 옅게 그려 선이 흐리고
    /// HiDPI 분수 스케일에서 떨린다. 형제 선 헬퍼(appendHorizontalLine)가 셀+reserved ~2px를 쓰는 것과 같은
    /// 이유로 토큰 두께(≥2px)면 중심 행이 cov≈1로 선명하다. 두께만큼 바 하단 안쪽에 둔다(바 위로 안 새게).
    fn appendTabBarUnderline(self: *AppSession, bar: maru.session.SplitRect, thickness: u32) void {
        self.appendSolidQuad(@floatFromInt(bar.x), @floatFromInt(bar.y + bar.h -| thickness), @floatFromInt(bar.w), @floatFromInt(thickness), self.dividerColor(), 2);
    }

    /// app `*Tab`에서 chrome 중립 `sidebar.Tab`(라벨·활성)을 빌드한다 — chrome은 app 트리를 모르므로 host가 떼어 준다
    /// (palette Row 선례). 라벨 = 활성 panel surface 제목(제목 glyph는 buildSidebarTitleFrame이 이 라벨로 그린다).
    fn sidebarTabs(self: *AppSession, arena: std.mem.Allocator) ![]chrome.components.sidebar.Tab {
        const out = try arena.alloc(chrome.components.sidebar.Tab, self.sidebar_visible_tabs.items.len);
        for (self.sidebar_visible_tabs.items, 0..) |orig, i| {
            const tab = self.tabs.items[orig]; // 표시 슬롯 i → 원본 탭(검색 필터)
            out[i] = .{ .label = workspaceLabel(tab), .active = (orig == self.app_window.active_tab) };
        }
        return out;
    }

    /// chrome `sidebar.view`가 낸 밴드 fill op을 sidebar 셀(NativeMetalCell)로 lower한다 — fill rect.y / slot_h = 슬롯 행,
    /// role(tab_active_bg/tab_hover_bg) → sidebarActiveBg/HoverBg. sidebarBandCell이 폭을 cell로 floor해 한 칸 밴드로.
    /// (옛 rebuildSidebar의 밴드 emit을 view 경로로 — 색 해석·NativeMetalCell은 platform 책임, divider lowerDividerRules와 동형.)
    /// 슬롯 콘텐츠 GpuQuad(밴드·accent 막대·배경 tint)의 절대 y(슬롯 상대 y + 헤더 시프트는 호출자가 더해 넘김)와
    /// 높이에 사이드바 세로 스크롤을 적용하고 헤더 아래로 클립한다. 헤더 quad(검색 underline·아이콘 호버·배지)는 고정이라
    /// 이걸 안 거친다. 반환 null = 완전히 헤더 위(스킵). clipped=true면 위쪽이 잘려(상단이 헤더 경계에 abut) 호출자가 둥근
    /// 상단 모서리를 죽인다(라운드 quad가 헤더 경계에서 어색하지 않게). 셀(밴드 sentinel·glyph)은 .m이 frame 오프셋으로
    /// 따로 스크롤+scissor하므로 이 경로는 GpuQuad 전용이다(둘 다 같은 sidebar_scroll_offset_px를 쓴다 — 단일 출처).
    fn sidebarScrollClipQuad(self: *const AppSession, abs_y: f32, h: f32) ?struct { y: f32, h: f32, clipped: bool } {
        const header: f32 = @floatFromInt(self.sidebar_header_height_px);
        const off: f32 = @floatFromInt(self.sidebar_scroll_offset_px);
        var y = abs_y - off;
        var hh = h;
        if (y + hh <= header) return null; // 헤더 위로 완전히 스크롤됨 — 안 그림
        var clipped = false;
        if (y < header) { // 상단 일부가 헤더에 걸침 — 헤더 경계에서 자른다
            hh -= (header - y);
            y = header;
            clipped = true;
        }
        return .{ .y = y, .h = hh, .clipped = clipped };
    }

    fn lowerSidebar(self: *AppSession, ops: []const chrome.draw.Op) void {
        const slot_h = self.sidebar_slot_height_px;
        if (slot_h == 0) return;
        // gpu_quad(accent bar·rich 밴드)는 슬롯 상대 y를 절대 좌표로 박으므로 상단 헤더만큼 내려야 한다 — .m이
        // header_h 시프트하는 건 sidebar_cells(텍스트·tui 밴드)뿐이라 gpu_quad는 여기서 header_h를 더한다(위치 정합).
        const header_f: f32 = @floatFromInt(self.sidebar_header_height_px);
        for (ops) |op| switch (op) {
            .quad => |q| {
                if (q.fill_role == .accent_bar) {
                    // U1: 얇은 좌측 maru-accent 막대 — 셀 폭 floor를 피해 항상 GpuQuad(직각, layer 0=under). 색은 palette.accent_bar(앰버).
                    const sr = self.sidebarScrollClipQuad(@as(f32, @floatFromInt(q.rect.y)) + header_f, @floatFromInt(q.rect.h)) orelse continue;
                    const ac = packOpaqueRgb(self.buildChromeTokens().palette.get(.accent_bar));
                    self.gpu_quads.append(self.allocator, .{
                        .x = @floatFromInt(q.rect.x),
                        .y = sr.y,
                        .w = @floatFromInt(q.rect.w),
                        .h = sr.h,
                        .corner_radii = .{ 0, 0, 0, 0 },
                        .border_widths = .{ 0, 0, 0, 0 },
                        .fill_color0 = ac,
                        .fill_color1 = ac,
                        .border_color = 0,
                        .gradient_kind = 0,
                        .layer = 0,
                    }) catch {};
                    continue;
                }
                var color = switch (q.fill_role) {
                    .tab_active_bg => self.sidebarActiveBg(),
                    .drop_zone => packOpaqueRgb(self.buildChromeTokens().palette.get(.drop_zone)), // pane 드롭 타겟(rich=밝게)
                    else => self.sidebarHoverBg(),
                };
                // 이 슬롯 탭에 배경 tint가 있으면 밴드 색에 섞는다 — tui 활성/호버 슬롯은 불투명 밴드(셀)가 tint quad를
                // 덮으므로, 밴드 색 자체를 tint로 당겨 활성/호버 슬롯에서도 색이 보이게 한다(idle 슬롯은 밴드가 없어 quad가 그대로).
                const band_row_i = @divTrunc(q.rect.y, @as(i32, @intCast(slot_h)));
                if (band_row_i >= 0) {
                    const ri: usize = @intCast(band_row_i);
                    if (self.visibleTab(ri)) |orig| { // 표시 슬롯 ri → 원본(검색 필터)
                        if (self.tabs.items[orig].background_color != 0)
                            color = blendRgb(color, self.tabs.items[orig].background_color & 0x00FF_FFFF, tab_bg_tint_alpha);
                    }
                }
                const has_radius = q.corner_radii[0] != 0 or q.corner_radii[1] != 0 or q.corner_radii[2] != 0 or q.corner_radii[3] != 0;
                if (!has_radius) {
                    // tui: 직각 → 셀 밴드(기존 경로). rect.y/slot_h = 슬롯 행.
                    const row_i = @divTrunc(q.rect.y, @as(i32, @intCast(slot_h)));
                    if (row_i < 0) continue;
                    const row: u16 = @intCast(@min(@as(usize, @intCast(row_i)), @as(usize, std.math.maxInt(u16))));
                    if (sidebarBandCell(self.sidebar_width_px, self.cell_width_px, row, color)) |cell| {
                        self.sidebar_cells.append(self.allocator, cell) catch {};
                    }
                } else {
                    // rich: GPU quad 프리미티브(둥근 밴드) — 셀 그리드와 별개 파이프라인으로 렌더된다.
                    const sr = self.sidebarScrollClipQuad(@as(f32, @floatFromInt(q.rect.y)) + header_f, @floatFromInt(q.rect.h)) orelse continue;
                    // 상단이 헤더에 걸려 잘리면 둥근 모서리를 죽인다(헤더 경계에 abut한 라운드 상단이 어색하지 않게).
                    const radii: [4]f32 = if (sr.clipped) .{ 0, 0, 0, 0 } else .{ @floatFromInt(q.corner_radii[0]), @floatFromInt(q.corner_radii[1]), @floatFromInt(q.corner_radii[2]), @floatFromInt(q.corner_radii[3]) };
                    self.gpu_quads.append(self.allocator, .{
                        .x = @floatFromInt(q.rect.x),
                        .y = sr.y,
                        .w = @floatFromInt(q.rect.w),
                        .h = sr.h,
                        .corner_radii = radii,
                        .border_widths = .{ 0, 0, 0, 0 },
                        .fill_color0 = color,
                        .fill_color1 = color,
                        .border_color = 0,
                        .gradient_kind = 0,
                        .layer = 0, // under — 사이드바 밴드(셀 위·제목 아래)
                    }) catch {};
                }
            },
            else => {},
        };
    }

    /// 사이드바 카드 4번째 줄(상태줄) 텍스트를 owned 슬라이스로 만든다. 에이전트 포그라운드가 아니면(none) "" —
    /// 그 줄은 생략된다. running이면 "● 진행중", idle이면 "✓ {답변 미리보기}"(답변이 없으면 "✓ 완료"). 답변은 Term의
    /// inline 버퍼(여러 줄을 한 줄로 평탄화한 미리보기 — copyPreviewFlattened, 알림 본문과 공유)에서 가져오고,
    /// 사이드바가 카드 폭으로 다시 말줄임한다(개행이 공백 1칸이라 한 줄로 보인다).
    fn agentStatusLine(self: *AppSession, term: *Term) ![]const u8 {
        if (term.agent_kind == .none) return self.allocator.dupe(u8, "");
        return switch (term.agent_state) {
            .running => blk: { // codex식 4칸 이퀄라이저 파형 + 진행중(바는 색칠 루프가 브랜드색으로). 정적 ● 대신.
                // 각 바 = 현재 프레임 높이의 블록 글리프(최대 3바이트). 4칸을 이어 붙여 파형 한 줄을 만든다.
                var bars: [spinner_bar_count * 3]u8 = undefined;
                var used: usize = 0;
                for (0..spinner_bar_count) |bar| {
                    used += std.unicode.utf8Encode(spinnerBarCp(self.agent_spin_frame, bar), bars[used..]) catch 0;
                }
                break :blk std.fmt.allocPrint(self.allocator, "{s} 진행중", .{bars[0..used]});
            },
            .idle => if (term.agent_answer_len > 0)
                std.fmt.allocPrint(self.allocator, "\u{2713} {s}", .{term.agent_answer_buf[0..term.agent_answer_len]}) // ✓ {답변}
            else
                self.allocator.dupe(u8, "\u{2713} 완료"), // ✓ 완료(답변 텍스트 없음)
            .unknown => self.allocator.dupe(u8, ""), // 트랜스크립트 못 읽음 — 상태줄 생략(아이콘만)
        };
    }

    /// 탭 제목들을 라벨(제목만, 번호 prefix 없음 — U-tab2)로 모아 사이드바 제목 glyph RenderFrame을 만든다(한 줄=한 탭,
    /// row=탭 인덱스). `build`(터미널)와 같은 CoreTextFrameBuilder/renderer_state(atlas)를 써서 제목
    /// glyph도 터미널과 같은 slot을 재사용하고 새 glyph만 추가 업로드된다. macOS 전용(실 CoreText
    /// 브리지) — tick의 `builtin.os.tag == .macos` 가드 안에서만 호출한다. 사이드바가 꺼졌거나(폭 0)
    /// 탭이 없으면 error.NoSidebar로 빠져 호출부가 제목 없이 밴드만 그린다.
    /// 멀티 페인 통합 빌드(cross-pane 정확성)의 수집 항목 목적지. 각 atlas-쓰는 빌드를 shapeOnly로 모아 한 번에
    /// placeMultiPane(한 atlas 세대)한 뒤 dest별로 RenderFrame을 분배한다 — 개별 buildFromDrawList가 invalidate로
    /// 앞 페인을 무효화하는 cross-pane 깨짐을 막는다(docs/font-strategy.md frame epoch).
    const PanePlacement = struct {
        origin_x: u32,
        origin_y: u32,
        colors: metal_frame.CellColors,
        clip_rect: ?metal_frame.ClipPx = null,
    };
    const CollectDest = union(enum) {
        sidebar,
        sidebar_header,
        overlay: PanePlacement,
        pane: PanePlacement,
        floating: PanePlacement,
        // sticky command 배너(스크롤 시 명령줄 고정) — floating처럼 활성 터미널 '위'(맨 위 직전)에 한 frame.
        sticky: PanePlacement,
        // 활성은 배치(origin/colors)를 안 들고 있는다 — 호출자가 active_origin_x/y·cell_colors locals로 직접 박는다.
        active,
    };

    /// 활성 panel의 placeMultiPane 결과 RenderFrame. placeAndDistribute가 out param으로 돌려주면 호출자가 pane_frames
    /// 맨 뒤(커서 suffix)에 view로 넣고 render_stats를 산출한다(배치 origin/colors는 호출자가 locals로 박으므로 placement는
    /// 안 들고 있는다). 활성 frame은 built_frames가 소유(view라 따로 deinit 안 함 — built_frames 규율과 동형).
    const ActiveResult = struct { rf: renderer.RenderFrame };
    const CollectedPane = struct {
        pane: coretext_frame_builder.ShapedPane,
        dest: CollectDest,
        builder: coretext_frame_builder.CoreTextFrameBuilder,
    };

    /// chrome 오버레이의 shape 전 준비 — DrawList + 배치(origin/colors/cursor/clip) + builder(오버레이는 호출자
    /// appearance/cell_w/h를 쓴다). 단발(buildChromeOverlayFrame)·통합(collect)이 공유한다.
    const OverlayPrep = struct {
        dl: renderer.DrawList,
        placement: PanePlacement,
        builder: coretext_frame_builder.CoreTextFrameBuilder,
    };

    /// 사이드바/탭바/비활성/오버레이/floating 공용 frame builder(cursor_unfocused 없음 — 활성 panel만 cursor 모드를
    /// 쓴다). macOS 전용 coretext bridge라 호출은 `if (builtin.os.tag == .macos)` 안에서만 한다(비-macOS는 lazy 미분석).
    fn paneFrameBuilder(self: *const AppSession) coretext_frame_builder.CoreTextFrameBuilder {
        return .{
            .appearance = self.appearance,
            .shape_draw_list = coretext_bridge.maru_macos_coretext_shape_draw_list,
            .rasterize_glyph = coretext_bridge.maru_macos_coretext_smoke_rasterize_glyph,
            .scale_milli = self.scale_milli,
            .cell_width_px = @intCast(self.cell_width_px),
            .glyph_cell_width_px = @intCast(self.glyph_cell_width_px),
            .cell_height_px = @intCast(self.cell_height_px),
        };
    }

    /// DrawList(소유권 이전)를 shapeOnly로 만들어 collected에 추가한다. shapeOnly 실패면 dl은 shapeOnly가 정리하고
    /// 그 페인만 skip(기존 per-pane `catch continue/null`과 동형), append 실패면 pane.deinit.
    fn collectShaped(self: *AppSession, collected: *std.ArrayList(CollectedPane), dl: renderer.DrawList, builder: coretext_frame_builder.CoreTextFrameBuilder, dest: CollectDest) void {
        const pane = builder.shapeOnly(self.allocator, dl, &self.renderer_state.font_registry) catch return;
        // 헤더 아이콘 ◧(U+25E7)는 .m이 hscale 1.7로 quad를 키워 셀보다 ~1.7칸 넓게 그린다. 셀 크기로 굽고 GPU에서
        // 확대하면 anti-alias가 번져 흐리므로(slot-stretch; partial-alpha 비율 ≈0.69 — coretext_smoke 측정 test), atlas
        // slot을 목표 px(셀×1.7)로 키워 그 크기로 직접 래스터한다 — 1.7× 텍스처가 1.7× quad에 1:1로 들어가 선명(≈0.33).
        // raster_*_px>0이면 estimateGlyphBitmapSize가 셀 배수 대신 이 크기로 slot을 잡는다(.m·레이아웃 불변). 터미널
        // 콘텐츠(.pane)의 ◧는 키우지 않도록 헤더 dest로 한정한다(펼침·접힘 토글 모두 .sidebar_header).
        if (std.meta.activeTag(dest) == .sidebar_header and self.cell_width_px > 0 and self.cell_height_px > 0) {
            const rw: u16 = @intCast(@min(@as(u32, self.cell_width_px) * 17 / 10, @as(u32, std.math.maxInt(u16))));
            const rh: u16 = @intCast(@min(@as(u32, self.cell_height_px) * 17 / 10, @as(u32, std.math.maxInt(u16))));
            for (pane.shaped.runs.glyphs) |*g| {
                // ◧(접기)·⚙(view options)는 헤더 전용 심볼이라 coretext_smoke.m의 cover-fit(center_symbol)
                // 경로를 이미 타므로, slot만 1.7×로 키우면 1.7× quad에 1:1로 들어가 선명해진다. '+'(U+002B)는
                // 터미널 콘텐츠에도 흔해 center_symbol에 넣으면 전역 '+'가 슬롯을 꽉 채워 굵어지는 회귀라,
                // 헤더 전용 cover-fit 신호가 필요한 별도 작업으로 둔다.
                if (g.codepoint == 0xF0002 or g.codepoint == 0xF0003 or g.codepoint == 0xF0005 or g.codepoint == 0xF0006) {
                    g.cache_key.raster_width_px = rw;
                    g.cache_key.raster_height_px = rh;
                }
            }
        }
        self.collectShapedPane(collected, pane, builder, dest);
    }

    /// 이미 shapeOnly된 ShapedPane을 collected에 추가한다 — append-or-deinit 꼬리의 단일 출처다(collectShaped는 DrawList를
    /// shapeOnly한 뒤 이걸 부르고, 활성 panel은 frame_builder가 미리 shape한 ShapedPane을 바로 넘긴다). append 실패면 그
    /// 페인만 deinit. 소유권은 collected로 이전되므로 호출자는 넘긴 ShapedPane을 더는 deinit하지 않는다(호출자가 보관
    /// 변수를 null로 비운다).
    fn collectShapedPane(self: *AppSession, collected: *std.ArrayList(CollectedPane), pane: coretext_frame_builder.ShapedPane, builder: coretext_frame_builder.CoreTextFrameBuilder, dest: CollectDest) void {
        var p = pane;
        collected.append(self.allocator, .{ .pane = p, .dest = dest, .builder = builder }) catch {
            p.deinit(self.allocator);
        };
    }

    /// 수집된 모든 페인을 한 placeMultiPane(한 atlas 세대)으로 배치하고 dest별로 RenderFrame을 분배한다. finishPane이
    /// ShapedPane을 consume하므로 이 함수가 collected를 비우며(clearRetainingCapacity) 모든 정리를 흡수한다 — 바깥 defer는
    /// 빈 배열만 deinit(double-free 없음). place 실패면 전 페인 deinit + 이번 통합 생략(metal_dirty 유지로 다음 tick 재시도).
    /// 분배: sidebar/header는 RenderFrame, overlay/floating은 PaneFrame, pane은 built_frames 소유 + pane_frames view.
    fn placeAndDistribute(
        self: *AppSession,
        collected: *std.ArrayList(CollectedPane),
        pane_frames: *std.ArrayList(metal_frame.PaneFrame),
        built_frames: *std.ArrayList(renderer.RenderFrame),
        sidebar_frame: *?renderer.RenderFrame,
        sidebar_header_frame: *?renderer.RenderFrame,
        overlay_frame: *?metal_frame.PaneFrame,
        floating_pf: *?metal_frame.PaneFrame,
        sticky_pf: *?metal_frame.PaneFrame,
        active_out: *?ActiveResult,
    ) void {
        defer collected.clearRetainingCapacity();
        if (collected.items.len == 0) return;

        const lists = self.allocator.alloc(renderer.glyph_layout.GlyphRunList, collected.items.len) catch {
            for (collected.items) |*c| c.pane.deinit(self.allocator);
            return;
        };
        defer self.allocator.free(lists);
        for (collected.items, lists) |c, *l| l.* = c.pane.shaped.runs;

        const frames = self.renderer_state.placeMultiPane(self.allocator, lists) catch {
            for (collected.items) |*c| c.pane.deinit(self.allocator);
            return;
        };
        defer self.allocator.free(frames);

        for (collected.items, frames) |*c, frame| {
            const rf = c.builder.finishPane(self.allocator, &c.pane, frame, &self.renderer_state) catch {
                // finishPane 실패: frame은 buildQuadRaster가 정리, pane은 미consume → deinit. 그 페인만 skip.
                c.pane.deinit(self.allocator);
                continue;
            };
            switch (c.dest) {
                .sidebar => sidebar_frame.* = rf,
                .sidebar_header => sidebar_header_frame.* = rf,
                .overlay => |p| overlay_frame.* = .{ .frame = rf, .origin_x = p.origin_x, .origin_y = p.origin_y, .colors = p.colors, .clip_rect = p.clip_rect },
                .pane => |p| {
                    if (built_frames.append(self.allocator, rf)) |_| {
                        pane_frames.append(self.allocator, .{ .frame = rf, .origin_x = p.origin_x, .origin_y = p.origin_y, .colors = p.colors, .clip_rect = p.clip_rect }) catch {};
                    } else |_| {
                        var v = rf;
                        v.deinit(self.allocator);
                    }
                },
                .floating => |p| {
                    if (built_frames.append(self.allocator, rf)) |_| {
                        floating_pf.* = .{ .frame = rf, .origin_x = p.origin_x, .origin_y = p.origin_y, .colors = p.colors, .clip_rect = p.clip_rect };
                    } else |_| {
                        var v = rf;
                        v.deinit(self.allocator);
                    }
                },
                .sticky => |p| {
                    if (built_frames.append(self.allocator, rf)) |_| {
                        sticky_pf.* = .{ .frame = rf, .origin_x = p.origin_x, .origin_y = p.origin_y, .colors = p.colors, .clip_rect = p.clip_rect };
                    } else |_| {
                        var v = rf;
                        v.deinit(self.allocator);
                    }
                },
                // 활성 panel: 다른 pane과 동형으로 built_frames가 소유(pane_frames·active_out은 view라 deinit 안 함).
                // 호출자가 active_out.rf를 pane_frames 맨 뒤(커서 suffix, floating 앞)에 넣고 그 rf로 render_stats를 산출한다.
                .active => {
                    if (built_frames.append(self.allocator, rf)) |_| {
                        active_out.* = .{ .rf = rf };
                    } else |_| {
                        var v = rf;
                        v.deinit(self.allocator);
                    }
                },
            }
        }
    }

    fn buildSidebarTitleDrawList(self: *AppSession) !renderer.DrawList {
        const cw = self.cell_width_px;
        if (cw == 0 or self.tabs.items.len == 0) return error.NoSidebar;
        // U2/B2: 제목 영역 = 슬롯 폭에서 좌측(카드 패딩 + accent 막대)·우측(카드 패딩)을 inset한 content rect(선언적
        // 패딩, Rect.inset). 그 좌단을 셀 col로 ceil 환산(indent_cols)해 제목을 좌측 막대 우측·카드 안에 둔다(rich).
        // tui(0)면 left=right=0이라 전체 폭·indent 0(기존과 동일).
        const sp = self.buildChromeTokens().space;
        const row = chrome.draw.Rect{ .x = 0, .y = 0, .w = self.sidebar_width_px, .h = cw }; // h는 가로 환산에 무관
        const text_area = row.inset(.{ .left = sp.card_gap_px + sp.accent_bar_width_px, .right = sp.card_gap_px });
        const indent_px: u32 = @intCast(text_area.x);
        const indent_cols: u16 = if (indent_px > 0) @intCast(@min((indent_px + cw - 1) / cw, @as(u32, std.math.maxInt(u16)))) else 0;
        // B2 리뷰(e): indent_cols=ceil(left/cw)와 text_area.w/cw=floor의 합이 full_cols를 1 넘어 제목 우단이 터미널 영역을
        // 침범할 수 있어, sidebar_cols를 full_cols-indent_cols로도 clamp한다 → indent_cols+sidebar_cols <= full_cols 보장.
        const full_cols: u32 = self.sidebar_width_px / cw;
        const sidebar_cols: u16 = @intCast(@min(@min(text_area.w / cw, full_cols -| indent_cols), @as(u32, std.math.maxInt(u16))));
        if (sidebar_cols == 0) return error.NoSidebar;

        // 탭 카드를 소유 버퍼로 모은다(buildSidebarDrawList가 코드포인트로 디코드): names=이름줄(동작/활성 마커 ·/* prefix,
        // 번호 없음), branch_lines=octocat() 브랜치줄, path_lines=경로줄, status_lines=상태줄(빈 보조줄은 생략 → 1~4줄).
        // agents=에이전트 아이콘 코드포인트(0=없음) — 이름과 분리해 슬롯 세로 중앙에 독립 배치. pins=고정 핀(📌) 표시 여부
        // (buildSidebarDrawList가 이름줄 **우측 끝**에 그림 — 선두가 아니라, 마커가 가려지지 않게).
        var names: std.ArrayList([]const u8) = .empty;
        defer {
            for (names.items) |l| self.allocator.free(l);
            names.deinit(self.allocator);
        }
        var branch_lines: std.ArrayList([]const u8) = .empty;
        defer {
            for (branch_lines.items) |l| self.allocator.free(l);
            branch_lines.deinit(self.allocator);
        }
        var path_lines: std.ArrayList([]const u8) = .empty;
        defer {
            for (path_lines.items) |l| self.allocator.free(l);
            path_lines.deinit(self.allocator);
        }
        // 상태줄(4번째 줄): 에이전트 포그라운드일 때만 — running이면 "● 진행중", idle이면 "✓ {답변}"(완료 답변
        // 미리보기). none/unknown이면 ""(그 줄 생략). 아이콘 펄스와 함께 진행 상태를 보여준다(docs/agent-session.md).
        var status_lines: std.ArrayList([]const u8) = .empty;
        defer {
            for (status_lines.items) |l| self.allocator.free(l);
            status_lines.deinit(self.allocator);
        }
        var agents: std.ArrayList(u21) = .empty;
        defer agents.deinit(self.allocator);
        var pins: std.ArrayList(bool) = .empty;
        defer pins.deinit(self.allocator);
        for (self.sidebar_visible_tabs.items) |orig| {
            const tab = self.tabs.items[orig]; // 표시 슬롯 순서 → 원본 탭(검색 필터)
            const term = tab.activePane().activeTerm();
            const renaming = self.renamingWorkspace(tab);
            // 에이전트 아이콘은 슬롯 중앙에 독립 배치. 단 rename 중엔 숨긴다(0) — 안 그러면 편집 텍스트가 icon_cols
            // 만큼 우측으로 밀려 renameCaretRect(아이콘 오프셋 미반영)의 caret/IME 후보창과 어긋난다.
            try agents.append(self.allocator, if (renaming) 0 else agentIconCodepoint(term.agent_kind));
            // 이름줄 = custom_name(rename) 우선, 없으면 활성 Term 라벨. rename 중이면 편집 텍스트로 대체하고 보조줄은 숨긴다.
            if (renaming) {
                // rename 중엔 마커·핀을 안 붙인다 — 마커 prefix를 붙이면 편집 텍스트가 2칸 밀려 renameCaretRect(이름줄
                // 좌단=indent 가정)의 caret/IME 후보창과 어긋나고, 핀은 편집 폭을 잡아먹는다. 편집 동안만 전체 폭 사용.
                try names.append(self.allocator, try self.renameEditText(self.allocator)); // owned → names가 소유
                try branch_lines.append(self.allocator, try self.allocator.dupe(u8, ""));
                try path_lines.append(self.allocator, try self.allocator.dupe(u8, ""));
                try status_lines.append(self.allocator, try self.allocator.dupe(u8, "")); // rename 중엔 상태줄 숨김
                try pins.append(self.allocator, false);
            } else {
                const base = workspaceLabel(tab);
                // 이름줄 선두 = 동작/활성 마커: 활성 워크스페이스='*', 그 외='·'(U+00B7). 핀(📌)은 옛 설계처럼 선두에 박지
                // 않고 buildSidebarDrawList가 이름줄 우측 끝에 따로 그린다 — 선두 칼럼을 마커 전용으로 비워 핀이 "동작/활성"
                // 표시를 가리지 않게 한다(사용자 요청). 마커는 이름줄(line 0) 색을 따라간다(활성=강조, 그 외=흐림).
                const marker: []const u8 = if (orig == self.app_window.active_tab) "* " else "\u{00B7} ";
                try names.append(self.allocator, try std.fmt.allocPrint(self.allocator, "{s}{s}", .{ marker, base }));
                try pins.append(self.allocator, tab.pinned);
                // 브랜치줄·경로줄: cwd가 git repo 안일 때만(branch != null) + view options 토글로 표시 여부 결정.
                // 이름줄은 항상 표시(사용자 요청). show-branch=false면 브랜치줄 생략, show-folder=false면 경로줄 생략.
                // 토글은 독립적이다 — 둘 다 "git repo 안"을 전제로 하되(maru는 repo 밖 cwd 줄을 안 그림) 서로 안 묶인다.
                const branch = self.termGitBranch(term); // cwd 변경 시에만 .git/HEAD 재읽기(캐시) — repo 판정에도 씀
                const show_branch = self.loaded_config.config.sidebar.show_branch;
                const show_folder = self.loaded_config.config.sidebar.show_folder;
                // 브랜치줄 prefix = GitHub octocat(0xF0009). 예전 git-branch(0xF0001)는 얇은 선+링 3개라 카드 셀 크기
                // (~8~12px)로 area-average 다운스케일되면 내부 구조가 뭉개져 ├(U+251C)처럼 보였다(사용자 피드백). octocat은
                // 꽉 찬 단색 실루엣이라 작은 크기에서도 외곽이 살아 GitHub 마크로 읽힌다(icon_glyph fillCoverage 경로 동일).
                // 폭은 titleCellWidth가 PUA를 **2칸(~16px)** 렌더해 width-1(~8px)일 때 동그란 링처럼 뭉개지던 걸 키웠다 —
                // 폴더줄(0xF000A)·에이전트 gutter 아이콘과 같은 크기로 통일(사용자 피드백 "깃 아이콘이 너무 작다").
                try branch_lines.append(self.allocator, if (show_branch) (if (branch) |b| try std.fmt.allocPrint(self.allocator, "\u{F0009} {s}", .{b}) else try self.allocator.dupe(u8, "")) else try self.allocator.dupe(u8, ""));
                try path_lines.append(self.allocator, if (show_folder and branch != null) try sidebarFolderLine(self.allocator, term) else try self.allocator.dupe(u8, ""));
                try status_lines.append(self.allocator, try self.agentStatusLine(term));
            }
        }

        // 비활성 워크스페이스 제목은 흐린 색(muted), 활성 워크스페이스(active_tab 행)는 full sidebar_foreground로 강조한다.
        const fg: terminal.Color = .{ .rgb = self.mutedForeground() };
        const active_fg: terminal.Color = .{ .rgb = self.appearance.theme.sidebar_foreground };
        // 호버 슬롯엔 닫기 ✕(없으면 null). plus_row = 탭 개수 → 목록 아래 행에 "+"(새 워크스페이스) 버튼.
        // plus_row=null — 하단 "+" 버튼은 헤더 우측 아이콘으로 이동·폐기(P2). 호버 슬롯엔 닫기 ✕(없으면 null).
        var draw_list = try coretext_frame_builder.buildSidebarDrawList(self.allocator, names.items, branch_lines.items, path_lines.items, status_lines.items, agents.items, pins.items, sidebar_cols, fg, self.hovered_slot, null, self.displaySlotOf(self.app_window.active_tab), active_fg);
        // 에이전트 아이콘(✶ claude / ◆ codex)과 상태줄 running 스피너(이퀄라이저 바 ▁~█)에 **브랜드색**을 입힌다 — claude=Anthropic 코랄,
        // codex=OpenAI 청록. 종류를 색으로 구분하고, **진행/완료는 상태줄**(running=이퀄라이저 파형[브랜드색]·idle=✓)이 담당한다
        // (옛 아이콘 밝기 펄스는 폐기 — 아래 루프는 아이콘·스피너 모두 솔리드 브랜드색). 색은 `term.agent_kind` 단일 출처로 고른다.
        // **오염 방지**: 아이콘은 gutter `col 0` + 합성 codepoint로 좁히고, 스피너는 **상태줄(카드 마지막 줄)**에만 색칠한다 —
        // 워크스페이스 이름/브랜치/경로 줄(line_index<line_count-1)에 블록 글자가 들어가도 안 오염(code-review high #2).
        for (draw_list.cells) |*c| {
            const is_icon = c.col == 0 and (c.codepoint == 0xF0007 or c.codepoint == 0xF0008); // ✶ claude / ◆ codex
            // 상태줄(카드 마지막 줄)의 이퀄라이저 바(블록 ▁~█)만 스피너로 본다. row=slot*base + line_count*4 + line_index라
            // within=row%base, line_count=within/4, line_index=within%4; 상태줄=line_index==line_count-1(에이전트 카드의 마지막 줄).
            const within = c.row % coretext_frame_builder.sidebar_line_base;
            const on_status_line = (within / 4) >= 1 and (within % 4) == (within / 4) - 1;
            const is_spinner = on_status_line and isAgentSpinnerCp(c.codepoint);
            if (!is_icon and !is_spinner) continue;
            // 셀 row에서 슬롯(탭) 인덱스를 디코드(row=slot*sidebar_line_base+줄offset, 줄offset<base라 아이콘/스피너 같은 슬롯)해 그 Term을 얻는다.
            const slot = c.row / coretext_frame_builder.sidebar_line_base; // 표시 슬롯
            const orig = self.visibleTab(slot) orelse continue; // 표시 슬롯 → 원본 탭(검색 필터)
            const t = self.tabs.items[orig].activePane().activeTerm();
            const brand: maru.color.Rgb = switch (t.agent_kind) {
                .claude => .{ .r = 0xCC, .g = 0x78, .b = 0x5C }, // Anthropic 공식 코랄 #CC785C
                .codex => .{ .r = 0x10, .g = 0xA3, .b = 0x7F }, // OpenAI 청록(#10A37F)
                .none => continue, // 아이콘/braille codepoint인데 kind=none(이름 글자 등) — 색칠 안 함.
            };
            // 아이콘·스피너 모두 **솔리드 브랜드색**(running 펄스 폐기 — 작은 밝기 변조가 안 보인다는 피드백). 작업 중
            // 애니메이션은 상태줄 스피너 회전이 담당하고, 아이콘은 큰 솔리드 색으로 종류/presence를 또렷이 보인다.
            c.style.foreground = .{ .rgb = brand };
        }
        // U2/B2: 제목·✕·+ 셀을 content rect 좌단(indent_cols)만큼 우측으로 민다 — 좌측 maru-accent 막대 + 카드 패딩 안 가리게(rich만; tui indent=0 no-op).
        if (indent_cols > 0) {
            for (draw_list.cells) |*c| c.col += indent_cols;
            // 시프트로 셀이 [indent_cols, sidebar_cols+indent_cols)로 가므로 surface 폭도 full_cols로 넓힌다 — 안 그러면
            // 폭을 꽉 채운 긴 경로줄이 size.cols(=sidebar_cols)를 넘어 ShapedRecordOutsideSurface로 프레임이 통째로 실패
            // (짧은 이름은 안 걸리던 잠재 버그를 경로줄이 깨움). full_cols ≥ sidebar_cols+indent_cols라 항상 수용한다.
            draw_list.size.cols = @intCast(@min(full_cols, @as(u32, std.math.maxInt(u16))));
        }
        return draw_list;
    }

    /// 사이드바 상단 헤더 glyph(검색 placeholder + view options ⚙·새 워크스페이스 + 아이콘) frame을 만든다.
    /// 카드(buildSidebarTitleFrame)와 달리 절대 좌표라 .m 헤더 시프트 대상이 아니다 — replace가 origin(0,0)
    /// 기반 cells로 헤더 영역 [0, header)에 직접 박는다(카드·밴드는 .m이 header_h만큼 아래로 시프트). 폭이 너무
    /// 좁거나 헤더 없으면 null(헤더 안 그림). 아이콘 우측 정렬(⚙=cols-4, +=cols-2)은 sidebar.headerHit과 같은
    /// 레이아웃 — 그려진 아이콘과 클릭 영역이 일치한다(§5.4 단일 레이아웃 소스). 검색 입력 텍스트·caret은 P3.
    /// 알림 종(🔔) + 안 읽은 개수 배지를 row 0의 `bell_col`에 추가한다 — 펼침 헤더(buildSidebarHeaderDrawList)와 접힘 토글
    /// (buildCollapsedToggleDrawList)의 **단일 출처**라 글리프(U+1F514, EAW 2칸)·배지 색(coral)·"9+" 규칙이 두 곳에서
    /// 드리프트하지 않는다. 배지는 안 읽은 알림이 있을 때만 종 한 칸 왼쪽부터: 1~9는 숫자 1칸(`bell_col-1`), 10개 이상은
    /// "9+" 2칸(`bell_col-2`·`bell_col-1`). 종 색은 fg(sidebar_foreground), 배지는 coral. 호출처가 폭을 보장해
    /// (펼침 cols≥13 → bell_col=cols-11≥2, 접힘 bell_col≥5) `bell_col-2` saturating은 실제로 안 닿는다(방어).
    fn appendBellAndBadge(self: *AppSession, cells: *std.ArrayList(renderer.DrawCell), bell_col: u16, fg: terminal.Color, round_badge: bool) !void {
        try cells.append(self.allocator, .{ .row = 0, .col = bell_col, .codepoint = 0xF0005, .width = 2, .style = .{ .foreground = fg } });
        if (self.notification_unread == 0) return;
        if (round_badge) {
            // 펼침 헤더: 종 **우상단** 빨강 원형 배지(iOS/macOS식). 빨강 원은 GPU quad(appendNotificationBadge, layer 4 —
            // 헤더 글리프 '뒤')가 그리고, 여기선 그 원 위에 올라갈 **흰 숫자**만 셀로 둔다(같은 col=bell_col+2 단일 출처 —
            // notificationBadgeCol). 원형 1칸 제약상 1~9는 숫자, 10개 이상은 '9'로 cap한다(2칸 "9+"는 종 우측에 ◧가 붙어
            // 자리가 없다 — docs/notifications.md §3). 배경은 default(투명)라 원 quad가 비친다.
            const white: terminal.Color = .{ .rgb = .{ .r = 0xFF, .g = 0xFF, .b = 0xFF } };
            const digit: u21 = '0' + @as(u21, @intCast(@min(self.notification_unread, 9)));
            try cells.append(self.allocator, .{ .row = 0, .col = notificationBadgeCol(bell_col), .codepoint = digit, .style = .{ .foreground = white } });
        } else {
            // 접힘 타이틀바: 종 **좌측** 빨강 텍스트 배지(기존 유지). 접힘 헤더는 터미널 위에 그려져 layer 4 quad가 터미널
            // 셀에 가리므로(원형 quad 부적합) 텍스트 배지로 둔다. 1~9는 숫자 1칸, 10개 이상은 "9+" 2칸.
            const badge_rgb: terminal.Color = .{ .rgb = .{ .r = 0xE0, .g = 0x5A, .b = 0x4A } };
            if (self.notification_unread > 9) {
                try cells.append(self.allocator, .{ .row = 0, .col = bell_col -| 2, .codepoint = '9', .style = .{ .foreground = badge_rgb } });
                try cells.append(self.allocator, .{ .row = 0, .col = bell_col -| 1, .codepoint = '+', .style = .{ .foreground = badge_rgb } });
            } else {
                try cells.append(self.allocator, .{ .row = 0, .col = bell_col -| 1, .codepoint = '0' + @as(u21, @intCast(self.notification_unread)), .style = .{ .foreground = badge_rgb } });
            }
        }
    }

    /// 펼침 헤더 알림 배지(흰 숫자 cell·빨강 원 quad)가 올라갈 col — 종(2칸, bell_col·bell_col+1) **우측 한 칸**.
    /// 종 글리프는 .m이 1.7cw×1.7ch(코너 아이콘과 동일 크기·2칸 footprint 중앙)로 그려 우상단 모서리가
    /// ≈(bell_col+1.85)·cw인데, 배지 원 반지름이 0.41ch≈0.85cw(ch≈2cw)라 bell_col+2(중심 (bell_col+2.5)·cw)의
    /// 배지 좌단(≈(bell_col+1.65)·cw)이 종 우측 모서리에 ~0.2cw만 겹쳐 iOS식 코너 배지가 된다(실측: 종 우측끝 95px,
    /// 배지 93..107px). 종을 코너 크기로 줄여도 이 값이 그대로 맞다(좁아진 종 = 모서리가 안쪽으로 0.85cw 와도 반지름이 흡수).
    /// appendBellAndBadge(셀)와 appendNotificationBadge(quad)의 단일 출처라 둘이 어긋나지 않는다.
    fn notificationBadgeCol(bell_col: u16) u16 {
        return bell_col + 2;
    }

    /// 펼침 헤더 종 우상단 알림 배지의 **빨강 원형 quad**(layer 4 — 사이드바 bg strip 뒤·헤더 글리프 앞)를 self.gpu_quads에
    /// 1개 append한다. 그 원 위에 올라갈 흰 숫자는 appendBellAndBadge가 헤더 frame 셀(col=notificationBadgeCol)로 둔다 —
    /// cell↔quad가 같은 col에서 만나 어긋나지 않는다. 안 읽은 알림이 없거나 헤더가 안 그려지는 폭/상태면 무동작.
    /// **접힘은 제외**한다(접힘 헤더는 터미널 위에 그려져 layer 4 quad가 터미널 셀에 가려 안 보임 — 접힘은 텍스트 배지 유지).
    /// per-frame: renderFrame이 dropQuadsByLayer(4) 직후 호출(헤더 frame의 흰 숫자와 같은 주기로 갱신).
    fn appendNotificationBadge(self: *AppSession) void {
        if (self.notification_unread == 0 or self.sidebar_collapsed) return;
        const cw = self.cell_width_px;
        const ch = self.cell_height_px;
        if (cw == 0 or ch == 0 or self.tabs.items.len == 0) return;
        if (self.sidebar_width_px == 0 or self.sidebar_header_height_px == 0) return;
        const cols = self.sidebar_width_px / cw;
        if (cols < 13) return; // 헤더가 안 그려지는 폭(buildSidebarHeaderDrawList cols<13과 정합) — 배지도 생략
        const cw_f: f32 = @floatFromInt(cw);
        const ch_f: f32 = @floatFromInt(ch);
        const badge_col = notificationBadgeCol(@intCast(cols - 12)); // 종(cols-12, 2칸) 우측 한 칸 = cols-10 (코너 크기 종의 우상단 모서리에 원 좌단이 ~0.2cw 겹침)
        // 배지 셀 중심(가로)·헤더 row 0 세로 중심(backing px). 흰 숫자가 원 가운데 오게 셀 중심에 맞춘다. center_y는 digit
        // 글리프 시각 중심(셀 중앙보다 약간 위)에 맞춰 0.46ch로 둔다(검증). 원이 너무 크면 옆 ◧ 아이콘에 닿으므로 0.82ch.
        const center_x: f32 = (@as(f32, @floatFromInt(badge_col)) + 0.5) * cw_f;
        const center_y: f32 = ch_f * 0.46;
        const d: f32 = ch_f * 0.82; // 원 지름(또렷하면서 ◧ 아이콘과 안 닿게)
        const red = packRgbAlpha(.{ .r = 0xE5, .g = 0x48, .b = 0x4D }, 0xFF); // 알림 배지 빨강(흰 숫자 대비). straight-alpha(셰이더 rgb*=a)
        self.gpu_quads.append(self.allocator, .{
            .x = center_x - d / 2.0,
            .y = center_y - d / 2.0,
            .w = d,
            .h = d,
            .corner_radii = .{ d / 2.0, d / 2.0, d / 2.0, d / 2.0 }, // 원형
            .border_widths = .{ 0, 0, 0, 0 },
            .fill_color0 = red,
            .fill_color1 = red,
            .border_color = 0,
            .gradient_kind = 0,
            .layer = 4, // 사이드바 bg strip 뒤·헤더 글리프 앞(흰 숫자가 위에 보이게)
        }) catch {};
    }

    /// 사이드바 헤더 glyph의 DrawList(접힘이면 좌상단 토글 — buildCollapsedToggleDrawList 위임; 조건 미달이면 null).
    /// 멀티 페인 통합(collectShaped)이 직접 써 통합 placeMultiPane으로 한 atlas 세대에 묶는다.
    fn buildSidebarHeaderDrawList(self: *AppSession) !?renderer.DrawList {
        const cw = self.cell_width_px;
        if (cw == 0 or self.cell_height_px == 0 or self.tabs.items.len == 0) return null;
        // 접힘이면 헤더 대신 좌상단 펼치기 버튼만 — 사이드바 폭 0이라 터미널 좌상단에 겹쳐 그린다(replace가 커서 suffix
        // '앞'에 끼워 터미널 위에 보임). 헤더 높이·검색·카드는 없다(완전히 숨김 + 좌상단 버튼).
        if (self.sidebar_collapsed) return self.buildCollapsedToggleDrawList();
        if (self.sidebar_header_height_px == 0) return null;
        const cols: u16 = @intCast(@min(self.sidebar_width_px / cw, @as(u32, std.math.maxInt(u16))));
        if (cols < 13) return null; // 검색 줄 + 우측 아이콘 4개(종/◧/⚙/+, 각 3칸 간격)가 들어갈 최소 폭(headerHit cols<13과 정합)

        var cells: std.ArrayList(renderer.DrawCell) = .empty;
        errdefer cells.deinit(self.allocator);
        const muted: terminal.Color = .{ .rgb = self.mutedForeground() };
        const fg: terminal.Color = .{ .rgb = self.appearance.theme.sidebar_foreground };
        // 헤더: 줄0(신호등 줄)은 좌측 네이티브 신호등(닫기·최소화·확대) 영역을 비우고 우측에 사이드바 접기(◧)·view
        // options(⚙)·새 워크스페이스(+) 아이콘. 검색은 신호등 아래 줄(search_row)에 🔍 + 입력/placeholder로 둔다(headerHit과
        // 같은 줄/우측 정렬 — view↔hitTest 단일 레이아웃). 줄 수는 headerRows 단일 소스(headerHit·caretRect과 동일).
        const header_rows: u16 = @intCast(chrome.components.sidebar.headerRows(self.sidebar_header_height_px, self.cell_height_px));
        const search_row: u16 = header_rows - 1; // 헤더 마지막 줄(신호등 아래)
        // 줄0: 우측 아이콘 3개 — 사이드바 접기(◧ cols-8)·view options(⚙ cols-5)·새 워크스페이스(+ cols-2). 3칸 간격,
        // 우측 1칸 패딩(cols-1 비움). 아이콘이 ~1.7칸 폭이라 2칸 간격이면 서로 붙어 보여(사용자 피드백) 3칸으로 띄운다.
        // headerHit의 toggle/view_options/new_workspace zone과 같은 col(단일 레이아웃 소스).
        // 아이콘 색은 호버 여부와 무관하게 항상 sidebar_foreground다 — hover 강조는 아래 호버 배경 quad(밝은 반투명)가
        // 맡는다. 예전엔 호버 아이콘을 sidebar_active로 재색칠했는데, Ghostty 테마에선 sidebar_active가 밝은 전경색이
        // 아니라 어두운 밴드색이라 아이콘이 오히려 어두워졌다(사용자 피드백) — 재색칠을 제거한다.
        // 알림 종(글리프 좌단 col cols-12, EAW 2칸이라 cols-12·cols-11 점유, 렌더 -0.5 nudge로 중심 (cols-11.5)*cw) + 종 우상단
        // 원형 배지(흰 숫자 cols-10 + 빨강 원 quad는 appendNotificationBadge). 종을 cols-12에 둬 배지(cols-10)와 ◧(cols-8)
        // 사이에 cols-9 한 칸 간격을 둔다 — ◧가 1.7×라 cols-9로 번져, 배지를 cols-9에 두면 ◧에 닿던 것을 떼기 위함(사용자 피드백).
        // headerHit의 notifications zone(cols-12..cols-9)이 종 글리프(cols-12·cols-11)와 배지(cols-10)를 모두 포함한다(클릭→패널).
        // 종 글리프는 🔔(U+1F514) — 🔍(검색)과 같은 이모지 경로(CoreText fallback). 글리프·색·배지 규칙은 appendBellAndBadge가
        // 접힘 토글과 공유(접힘은 좌측 텍스트 배지 — round_badge=false). 1~9 숫자·10+ "9" cap은 원형 1칸 제약(docs §3).
        // 아이콘 glyph col은 sidebar.headerIconCol 단일 출처(배지·hit-test와 공유 — 종은 2칸 이모지라 별도 cols-12).
        const sb_icon = chrome.components.sidebar;
        try self.appendBellAndBadge(&cells, cols - 12, fg, true); // 펼침: 종(cols-12) 우상단 원형 배지(흰 숫자 cols-10 + 빨강 원 quad)
        try cells.append(self.allocator, .{ .row = 0, .col = @intCast(sb_icon.headerIconCol(.toggle_sidebar, cols)), .codepoint = sidebar_toggle_codepoint, .style = .{ .foreground = fg } });
        try cells.append(self.allocator, .{ .row = 0, .col = @intCast(sb_icon.headerIconCol(.view_options, cols)), .codepoint = 0xF0002, .style = .{ .foreground = fg } });
        try cells.append(self.allocator, .{ .row = 0, .col = @intCast(sb_icon.headerIconCol(.new_workspace, cols)), .codepoint = 0xF0003, .style = .{ .foreground = fg } });
        // 검색 줄: 🔍(EAW 2칸) + 입력 텍스트(query+preedit, EAW 한글 2칸), 비면 placeholder "Search"(muted).
        // 검색어는 blur(비활성)돼도 보존해 그대로 그린다 — 다시 클릭해 이어서 편집·필터(초안 보존). preedit은 활성일
        // 때만 존재. caret/IME 후보창은 sidebarSearchCaretRect가 잡는다(활성일 때만).
        try cells.append(self.allocator, .{ .row = search_row, .col = sidebar_search_icon_col, .codepoint = 0xF0004, .width = 2, .style = .{ .foreground = muted } });
        const max_col = cols -| 4; // 우측 아이콘 영역 침범 방지
        const has_text = self.sidebar_search_input.query.items.len > 0 or self.sidebar_search_input.preedit.items.len > 0;
        var col: u16 = sidebar_search_text_col;
        if (has_text) {
            const texts = [_][]const u8{ self.sidebar_search_input.query.items, self.sidebar_search_input.preedit.items };
            for (texts) |text| {
                var view = std.unicode.Utf8View.init(text) catch continue;
                var iter = view.iterator();
                while (iter.nextCodepoint()) |cp| {
                    if (col >= max_col) break;
                    const w: u2 = @intCast(@max(@as(u8, 1), @min(@as(u8, 2), terminal.width.cellWidth(cp))));
                    try cells.append(self.allocator, .{ .row = search_row, .col = col, .codepoint = cp, .width = w, .style = .{ .foreground = fg } });
                    col += w;
                }
            }
        } else if (!self.sidebar_search_active) {
            // placeholder "Search"는 비활성+빈 검색일 때만(활성+빈 검색은 caret만 — Find/팔레트처럼 빈 입력칸에 커서).
            const placeholder = "Search";
            for (placeholder, 0..) |ch, i| {
                const c: u16 = @intCast(sidebar_search_text_col + i);
                if (c >= max_col) break;
                try cells.append(self.allocator, .{ .row = search_row, .col = c, .codepoint = ch, .style = .{ .foreground = muted } });
            }
        }
        // 검색 caret — 활성일 때 입력 텍스트 끝(빈 검색은 col 3)에 깜빡이는 '|'(rename in-place caret과 동형, Find/팔레트
        // 처럼 커서 표시). blink_visible로 토글(off 위상엔 생략). IME 조합 중엔 blink 핸들러가 위상을 고정해 항상 보인다.
        if (self.sidebar_search_active and self.blink_visible and col < max_col) {
            try cells.append(self.allocator, .{ .row = search_row, .col = col, .codepoint = '|', .style = .{ .foreground = fg } });
        }

        return renderer.DrawList{
            .size = .{ .cols = cols, .rows = header_rows },
            .cursor = .{ .row = 0, .col = 0 },
            .dirty = null,
            .cells = try cells.toOwnedSlice(self.allocator),
            .overlays = try self.allocator.alloc(renderer.DrawOverlay, 0),
        };
    }

    /// 사이드바 접힘 시 좌상단 알림 종(🔔) 글리프 col — 신호등 클리어런스 오른쪽 **첫(가장 왼쪽)** 아이콘. 펼침 헤더처럼
    /// 종이 ◧ '왼쪽'에 와 접힘↔펼침을 토글해도 종/◧ 순서가 안 바뀐다(사용자 피드백 "◧ 누르면 알림이랑 위치가 바뀜").
    /// render(buildCollapsedToggleDrawList)·hit-test(collapsedNotificationRect)·패널 anchor(openNotificationPanel)가 같은 값을
    /// 쓴다(단일 출처). cell_width 0이면 0.
    fn collapsedBellCol(self: *const AppSession) u16 {
        if (self.cell_width_px == 0) return 0;
        const clearance_px = layout_math.ptToPx(traffic_light_clearance_pt, self.scale_milli); // 신호등 클리어런스(backing px, pt→px 단일 출처)
        // 신호등 오른쪽 + 여백 + 배지폭. 종 왼쪽으로 "9+" 배지가 collapsed_badge_max_cells칸 뻗으므로, 종 base에 그 폭을
        // 더 보태 배지 좌단(=종−배지폭)이 클리어런스 + 여백 칸 안에 들어오게 한다 — 안 그러면 10+ 배지가 신호등에 닿는다.
        return @intCast(@min(clearance_px / self.cell_width_px + collapsed_toggle_gap_cells + collapsed_badge_max_cells, @as(u32, std.math.maxInt(u16))));
    }

    /// 접힘 시 ◧ 펼치기 토글 글리프 col — 종 오른쪽 collapsed_bell_gap_cells칸(펼침 헤더의 종↔◧ 3칸 간격과 같은 리듬).
    /// render(buildCollapsedToggleDrawList)·hit-test(collapsedToggleRect)가 같은 값을 써 그려진 버튼과 클릭 영역이 일치한다(단일 출처).
    fn collapsedToggleCol(self: *const AppSession) u16 {
        return self.collapsedBellCol() + @as(u16, @intCast(collapsed_bell_gap_cells));
    }

    /// 접힘 상태 좌상단 펼치기 버튼(◧)만 그린 frame — 사이드바 폭 0이라 터미널 좌상단에 겹쳐 그린다(replace가 커서
    /// suffix 앞에 끼워 터미널 '위'에). 신호등 오른쪽 col(collapsedToggleCol) 줄0에 1글자. 헤더 frame과 같은 절대 좌표 경로.
    fn buildCollapsedToggleDrawList(self: *AppSession) !?renderer.DrawList {
        const cw = self.cell_width_px;
        if (cw == 0 or self.cell_height_px == 0 or self.tabs.items.len == 0) return null;
        const fg: terminal.Color = .{ .rgb = self.appearance.theme.sidebar_foreground };
        const btn_col = self.collapsedToggleCol();
        const bell_col = self.collapsedBellCol();
        var cells: std.ArrayList(renderer.DrawCell) = .empty;
        errdefer cells.deinit(self.allocator);
        // 좌→우: 종+배지(가장 왼쪽, 펼침 헤더와 같은 순서) → ◧ 펼치기 토글. 알림 종은 접힘에도 유지 — 펼침 헤더와 같은
        // 글리프/색/"9+" 규칙(appendBellAndBadge 단일 출처). 렌더러가 접힘 헤더 줄0 글리프(종·배지·◧)를 타이틀바 띠
        // 세로 중앙에 함께 정렬한다(terminal_origin_x_px==0 분기).
        try self.appendBellAndBadge(&cells, bell_col, fg, false); // 접힘: 종 좌측 텍스트 배지(터미널 위라 quad 부적합)
        try cells.append(self.allocator, .{ .row = 0, .col = btn_col, .codepoint = sidebar_toggle_codepoint, .style = .{ .foreground = fg } });
        return renderer.DrawList{
            .size = .{ .cols = btn_col + 2, .rows = 1 }, // ◧(가장 오른쪽, 1칸) + 여유 1칸
            .cursor = .{ .row = 0, .col = 0 },
            .dirty = null,
            .cells = try cells.toOwnedSlice(self.allocator),
            .overlays = try self.allocator.alloc(renderer.DrawOverlay, 0),
        };
    }

    /// 접힘 상태 좌상단 펼치기 버튼의 backing-px rect(클릭 hit-test) — render(collapsedToggleCol)와 같은 col. 펼침/접힘
    /// 아니거나 탭이 없으면(글리프 frame도 안 그려짐 — buildCollapsedToggleDrawList과 같은 전제) null. mouse 핸들러가 이
    /// rect 안 클릭이면 toggleSidebarCollapsed(펼치기)한다(사이드바가 없어 inSidebar=false라 별도 체크). 높이는
    /// **타이틀바 띠 전체**(cell_h가 아님) — 접힘 띠는 max(cell_h, 30pt)라 1.7× 버튼이 cell_h 밖으로 삐져나가는데
    /// cell_h로 잡으면 그 부분이 데드존(클릭·드래그 둘 다 안 됨)이 된다. 가로는 **글리프 중심에 맞춘다**: .m이 ◧를
    /// 셀 중심((col+0.5)·cw) 기준 1.7×로 키우므로(maru_fill_cell_quad가 중심 기준 확대) 글리프는 ≈[(col-0.35),
    /// (col+1.35)]·cw에 그려진다. rect를 col·cw부터 잡으면 클릭 영역이 글리프보다 0.5칸 오른쪽으로 치우쳐 글리프
    /// 좌측 일부가 안 눌리므로(code-review), 셀 중심에 2칸 폭을 중앙 정렬한다([(col-0.5),(col+1.5)]·cw — 호버 quad·
    /// 글리프와 동심).
    fn collapsedToggleRect(self: *const AppSession) ?chrome.draw.Rect {
        // 글리프 중심 (col+0.5)·cw에 2칸 폭 rect를 중앙 정렬(◧는 .m이 셀 중심 기준 1.7×로 키워 ≈[(col-0.35),(col+1.35)]·cw에
        // 그려지므로, col·cw부터 잡으면 0.5칸 우측으로 치우쳐 글리프 좌측이 안 눌린다 — code-review). collapsedIconRect 단일 출처.
        return self.collapsedIconRect(self.collapsedToggleCol(), 2 * self.cell_width_px);
    }

    /// 접힘 시 알림 종(🔔)의 backing-px rect(클릭 hit-test) — collapsedBellCol()과 같은 col(단일 출처). 마우스 핸들러가 이
    /// rect 클릭이면 openNotificationPanel한다(◧ 토글과 별개 영역). 종 글리프 중심((bell_col+0.5)·cw, 렌더러 가로 −0.5칸
    /// nudge 반영)에 3칸 폭(배지+종)을 중앙 정렬. (3cw)/2 == cw + cw/2라 collapsedIconRect 중앙 정렬이 그대로 종 중심에 온다.
    fn collapsedNotificationRect(self: *const AppSession) ?chrome.draw.Rect {
        return self.collapsedIconRect(self.collapsedBellCol(), 3 * self.cell_width_px);
    }

    /// 접힘 좌상단 띠 아이콘의 클릭 rect — 글리프 중심 (col+0.5)·cw에 width_px(backing) 폭을 중앙 정렬, 높이=타이틀바 띠
    /// 전체(1.7× 글리프가 cell_h 밖으로 삐져나가는 데드존 방지). collapsedToggleRect(◧, 2cw)·collapsedNotificationRect(종, 3cw)
    /// 단일 출처 — 접힘/cell/띠/탭 전제와 중앙-정렬 수학을 한 곳에 둬 둘이 드리프트하지 않는다.
    fn collapsedIconRect(self: *const AppSession, col: u16, width_px: u32) ?chrome.draw.Rect {
        if (!self.sidebar_collapsed or self.cell_width_px == 0 or self.titlebar_strip_px == 0 or self.tabs.items.len == 0) return null;
        const cw = self.cell_width_px;
        const center_x = @as(i32, col) * @as(i32, @intCast(cw)) + @as(i32, @intCast(cw / 2)); // 글리프 중심 (col+0.5)·cw
        return .{ .x = center_x - @as(i32, @intCast(width_px / 2)), .y = 0, .w = width_px, .h = self.titlebar_strip_px };
    }

    /// 오버레이(커맨드 팝업·Find·Notice) frame의 공통 마무리. 채워진 cells(소유권 인계) + 격자 크기(cols×rows) +
    /// backing-px origin을 받아 DrawList → CoreTextFrameBuilder → PaneFrame으로 굳힌다. 세 빌더가 같은 frame 계약
    /// (DrawList 리터럴·frame_builder 6필드·PaneFrame 반환)을 복제하던 boilerplate를 단일화한다 — frame 계약이
    /// 바뀌면 여기 한 곳만 고친다. cells는 toOwnedSlice로 가져가고, 실패 시 호출자 errdefer가 정리한다(아직 유효).
    fn finishOverlayPrep(
        self: *AppSession,
        cells: *std.ArrayList(renderer.DrawCell),
        cols: u16,
        rows: u16,
        origin_x: u32,
        origin_y: u32,
        appearance: config_mod.ResolvedAppearance,
        cell_w: u32,
        cell_h: u32,
        cursor: ?terminal.Cursor,
        clip_rect: ?chrome.draw.Rect,
    ) !OverlayPrep {
        // caret(cursor-role fill에서 lower)이 있으면 **cursor 오버레이**(DrawOverlay.cursor)로 낸다 — buildNativeCellsSplit이
        // frame.overlays에서 .cursor를 찾아 반전-블록으로 그리고(메인 터미널 커서와 같은 경로) suffix-trim으로 깜빡인다.
        // draw_list.cursor 필드만으론 안 그려진다(렌더는 overlays를 본다 — 메인 buildDrawList도 cursor를 overlays에 넣는다).
        const overlays: []renderer.DrawOverlay = if (cursor) |cur| blk: {
            const o = try self.allocator.alloc(renderer.DrawOverlay, 1);
            o[0] = .{ .cursor = .{ .row = cur.row, .col = cur.col, .visible = true, .shape = .block } };
            break :blk o;
        } else try self.allocator.alloc(renderer.DrawOverlay, 0);
        // draw_list 완성 전(toOwnedSlice OOM 등)에 실패하면 overlays를 직접 해제한다. 완성되면 draw_list가
        // overlays·cells를 소유하므로 **disarm**한다 — 안 그러면 buildFromDrawList의 실패 정리(owned_list.deinit가
        // overlays까지 free)와 겹쳐 **이중 해제**된다(coretext_frame_builder의 draw_list_owned 패턴과 동형).
        var overlays_owned = true;
        errdefer if (overlays_owned) self.allocator.free(overlays);
        const draw_list: renderer.DrawList = .{
            .size = .{ .cols = cols, .rows = rows },
            .cursor = cursor orelse .{ .row = 0, .col = 0, .visible = false },
            .dirty = .{ .start_row = 0, .end_row = if (rows == 0) 0 else rows - 1 },
            .cells = try cells.toOwnedSlice(self.allocator),
            .overlays = overlays,
        };
        overlays_owned = false; // 소유권이 draw_list로 — 이후 실패는 buildFromDrawList가 draw_list.deinit로 정리
        // appearance·cell_w/h를 호출자가 준다 — 오버레이는 터미널과 같은 셀·폰트(1×)를 쓴다(buildChromeOverlayFrame가
        // self.cell_width_px·self.appearance를 넘김). 글리프 픽셀(font.size×scale)과 atlas slot(cell)이 같은 메트릭에서
        // 나와 정확히 맞는다 — 1.3× 확대 시절의 스케일 불일치(글자 약간 잘림)가 없다.
        const frame_builder = coretext_frame_builder.CoreTextFrameBuilder{
            .appearance = appearance,
            .shape_draw_list = coretext_bridge.maru_macos_coretext_shape_draw_list,
            .rasterize_glyph = coretext_bridge.maru_macos_coretext_smoke_rasterize_glyph,
            .scale_milli = self.scale_milli,
            .cell_width_px = @intCast(cell_w),
            // 오버레이(커맨드 팔레트·Find·IME preedit)도 터미널과 같은 1× 셀(cell_w==self.cell_width_px)을 쓰므로 폰트
            // 글리프 자연폭도 self.glyph_cell_width_px로 넘긴다 — 안 넘기면 음수 자간에서 오버레이 텍스트만 좁은 slot으로
            // 세로 흔들림 버그가 남는다(code-review). 합성 글리프는 slotCellWidthPx가 glyph_id==0으로 셀폭 유지.
            .glyph_cell_width_px = @intCast(self.glyph_cell_width_px),
            .cell_height_px = @intCast(cell_h),
        };
        // caret이 있으면 cursor 색을 싣는다 — 컴포지터(metal_frame)가 colors.cursor가 있을 때만 반전 블록을 그린다.
        // block=cursor.color(없으면 theme.cursor)=caret 색, text=cursor.text(없으면 패널 bg=sidebar_background —
        // caret 아래 글자가 있으면 가독, 입력 끝 빈칸이라 보통 무관). cursor.* override는 메인 터미널 커서와 같은 색을 쓴다.
        const cursor_colors: ?metal_frame.CursorColors = if (cursor != null) .{
            .block = self.appearance.cursor.color orelse self.appearance.theme.cursor,
            .text = self.appearance.cursor.text orelse self.appearance.theme.sidebar_background,
        } else null;
        // DrawList 소유권을 prep로 넘긴다 — 단발(buildChromeOverlayFrame)·통합(collect)이 buildFromDrawList/shapeOnly로 소비.
        return .{
            .dl = draw_list,
            .placement = .{
                .origin_x = origin_x,
                .origin_y = origin_y,
                .colors = .{ .default_fg = self.appearance.theme.foreground, .cursor = cursor_colors },
                .clip_rect = if (clip_rect) |c| .{ .x = @intCast(@max(0, c.x)), .y = @intCast(@max(0, c.y)), .w = c.w, .h = c.h } else null,
            },
            .builder = frame_builder,
        };
    }

    // 커맨드 팝업·스크롤백 Find 오버레이는 chrome 컴포넌트로 이주했다(palette=C1b, find=C1a). 각 컴포넌트 view가
    // ChromeDraw를 내고 buildChromeOverlayFrame이 일반 rasterizer(placeText, EAW-폭)로 lower한다 — buildPaletteFrame/
    // buildFindFrame은 제거. 팝업은 IME 조합 표시·한글 2칸 폭을 find와 같은 경로로 공짜로 얻는다. 오버레이는 터미널과
    // 같은 셀 크기(1×)로 그린다 — 1.3× 확대는 사용자 요청으로 제거(스케일 불일치로 글자가 약간 잘리던 문제도 함께 사라짐).

    /// chrome 컴포넌트가 읽는 불변 메트릭(props seam). 매 frame 세션 실측값에서 빌드한다 — chrome은 terminal/
    /// config 타입을 모르므로 plain u32만 넘긴다. 오버레이는 터미널과 같은 셀(self.cell_width_px — CoreText 실측)을
    /// 쓴다. sidebar/backing은 실 px 그대로. sidebar_width_px는 런타임 가변(드래그)이라 토큰이 아닌 여기로.
    /// 셀/화면 메트릭만(토큰·shape 없이) — 휠/키 스크롤처럼 metrics만 필요한 경로가 buildChromeProps의 토큰 빌드를
    /// 피하게 한다. buildChromeProps도 이걸 재사용해 metrics를 단일 출처로 둔다.
    fn buildCellMetrics(self: *const AppSession) chrome.props.CellMetrics {
        return .{
            .cell_width_px = self.cell_width_px,
            .cell_height_px = self.cell_height_px,
            .sidebar_width_px = self.sidebar_width_px,
            .sidebar_slot_height_px = self.sidebar_slot_height_px,
            .backing_width_px = self.backing_width_px,
            .backing_height_px = self.backing_height_px,
            .chrome_minimal = self.chrome_minimal,
        };
    }

    fn buildChromeProps(self: *const AppSession) chrome.ChromeProps {
        const tk = self.buildChromeTokens();
        return .{
            .metrics = self.buildCellMetrics(),
            // C4b: 박스 모양 토큰을 tokens.space에서(단일 출처). tui=0(직각·셀 밴드), rich>0(둥근 GPU quad).
            .shape = .{ .corner_radius_px = tk.space.corner_radius_px, .border_width_px = tk.space.border_width_px, .modal_padding_px = tk.space.modal_padding_px, .accent_bar_width_px = tk.space.accent_bar_width_px, .card_gap_px = tk.space.card_gap_px },
            // 활성 pane rect(셀 그리드 영역) — find 오버레이가 활성 pane 우상단에 붙도록(findLayout 단일 출처).
            // palette는 안 쓴다(창 중앙 유지). active_pane_rect는 recomputeActivePaneRect가 포커스·resize마다 갱신.
            .active_pane = .{ .x = self.active_pane_rect.x, .y = self.active_pane_rect.y, .w = self.active_pane_rect.w, .h = self.active_pane_rect.h },
        };
    }

    /// ResolvedTheme(config) → chrome 토큰. chrome은 ResolvedTheme를 import하지 않으므로(경계) 여기서 resolved
    /// Rgb만 뽑아 넘기고, **역할→색 매핑은 chrome.tokens.Tokens.tui가 단일 출처로 소유**한다(2nd 백엔드·rich도
    /// 같은 매핑 재사용). 이 함수는 ResolvedTheme→ThemeColors 투영(필드 추림)만 한다.
    fn buildChromeTokens(self: *const AppSession) chrome.Tokens {
        const t = self.appearance.theme;
        const tc = chrome.tokens.ThemeColors{
            .foreground = t.foreground,
            .sidebar_background = t.sidebar_background,
            .sidebar_foreground = t.sidebar_foreground,
            .sidebar_active = t.sidebar_active,
            .search_match = t.search_match,
            .search_match_current = t.search_match_current,
            .selection = t.selection,
            .cursor = t.cursor,
        };
        // chrome theme = 토큰셋 교체(컴포넌트 불변). rich는 sidebar_active-공유 role(divider/focus_accent 등)을 분리 색으로(C4a).
        var tk = switch (self.appearance.chrome_theme) {
            .tui => chrome.tokens.Tokens.tui(tc),
            .rich => chrome.tokens.Tokens.rich(tc),
        };
        // TS1: 활성 탭 룩 축(chrome.tab-style) — config enum을 chrome 중립 토큰으로 매핑(색이 ThemeColors로 흐르는 것과 동형, §7).
        tk.space.tab_active_style = switch (self.appearance.chrome_tab_style) {
            .connected => .connected,
            .underline => .underline,
            .pill => .pill,
        };
        return tk;
    }

    /// 일반 오버레이 lowering: chrome 컴포넌트가 낸 ChromeDraw ops(fill/border/text)를 셀 그리드로 rasterize한다
    /// (painter order). bounding box = 모든 fill/border rect 합집합(패널 외곽), origin = 그 좌상단(backing px 절대).
    /// 각 셀 bg = 그 셀을 덮는 마지막 fill의 role 색(+켜진 변이면 border 색), codepoint·fg = text op이 origin부터
    /// 놓은 글리프. notice(박스 1개)·find(1행 다중 텍스트)·palette(N행 리스트)가 같은 lowering을 공유한다 —
    /// buildNoticeFrame의 "첫 fill+text" 특수형을 일반화(C1). rule op은 컴포넌트가 아직 안 내므로 무시한다.
    /// **순수**(CoreText 무관) — 셀·격자만 산출해 단위 테스트로 고정한다. 빈 box/0칸이면 에러(호출자가 무시).
    /// 반환된 cells는 allocator 소유(호출자가 finishOverlayPrep에 넘겨 frame으로 이전하거나 실패 시 deinit).
    const OverlayRaster = struct {
        cells: std.ArrayList(renderer.DrawCell),
        // C4b 모달: rich 모달 배경 quad(둥근+테두리). buildChromeOverlayFrame이 self.gpu_quads(layer=1 over)에
        // 머지한다. tui(radius=0)면 빈 — 배경은 셀 fill(paintRectBg)로 기존 경로.
        gpu_quads: std.ArrayList(metal_frame.GpuQuad),
        gpu_shadows: std.ArrayList(metal_frame.GpuShadow),
        cols: u16,
        rows: u16,
        origin_x: u32,
        origin_y: u32,
        // cursor-role fill을 PaneFrame.cursor(반전 블록)로 lower한 caret 위치(없으면 null). finishOverlayPrep이
        // draw_list.cursor·colors.cursor에 싣고, 컴포지터가 터미널 커서와 같은 경로로 그리고 suffix-trim으로 깜빡인다.
        cursor: ?terminal.Cursor = null,
        // C4b 모달 클리핑: draw.Op.clip의 px 영역(없으면 null). buildChromeOverlayFrame이 MetalFrame.modal_clip_*로
        // 흘려 renderer가 모달 셀 draw에 scissor를 건다. 인프라 — 컴포넌트 적용은 후속.
        clip_rect: ?chrome.draw.Rect = null,
    };

    fn rasterizeOverlayCells(
        allocator: std.mem.Allocator,
        draws: []const chrome.ChromeDraw,
        tk: *const chrome.Tokens,
        cw: u32,
        ch: u32,
        // transparent_default=true면 패널 배경(quad) 없이도 빈 surface_bg 셀을 투명(.default)으로 둔다 — 단축키 배지처럼
        // 요소 위 흩어진 곳에만 칠하고 나머지는 chrome/터미널이 비치게(modal_bg_quad와 같은 skip을 패널 없이 켜는 플래그).
        transparent_default: bool,
    ) !OverlayRaster {
        if (cw == 0 or ch == 0) return error.NoMetrics;
        // C4b 모달: rich 모달 배경 quad 수집(painter의 .quad가 radius>0면 append). buildChromeOverlayFrame이
        // self.gpu_quads(layer=1 over)에 머지한다. tui(radius=0)면 비어 셀 fill 경로(무변화).
        var gpu_quads: std.ArrayList(metal_frame.GpuQuad) = .empty;
        errdefer gpu_quads.deinit(allocator);
        var gpu_shadows: std.ArrayList(metal_frame.GpuShadow) = .empty;
        errdefer gpu_shadows.deinit(allocator);
        // C4b 모달: rich 배경 quad(아래 painter .quad)가 있으면 true. 그땐 빈 셀(공백)을 평탄화에서 skip해
        // 불투명 surface_bg 셀이 둥근 quad를 사각으로 덮지 않게 한다(리뷰 #1 — quad가 비치게).
        var modal_bg_quad = false;
        // 1) bounding box = fill/border rect 합집합(backing px). text origin은 box 안이라 박스 산정에 안 쓴다.
        var min_x: i32 = std.math.maxInt(i32);
        var min_y: i32 = std.math.maxInt(i32);
        var max_x: i32 = std.math.minInt(i32);
        var max_y: i32 = std.math.minInt(i32);
        var have_box = false;
        for (draws) |d| for (d.ops) |op| {
            const rect: ?chrome.draw.Rect = switch (op) {
                .fill => |f| f.rect,
                .border => |b| b.rect,
                .quad => |q| q.rect, // C4b 모달: 박스가 모달 배경 quad를 포함해야 셀 그리드가 그 위 텍스트를 담는다
                else => null,
            };
            if (rect) |rr| {
                have_box = true;
                min_x = @min(min_x, rr.x);
                min_y = @min(min_y, rr.y);
                max_x = @max(max_x, rr.x + @as(i32, @intCast(rr.w)));
                max_y = @max(max_y, rr.y + @as(i32, @intCast(rr.h)));
            }
        };
        if (!have_box) return error.NoBox;
        const origin_x: u32 = if (min_x < 0) 0 else @intCast(min_x);
        const origin_y: u32 = if (min_y < 0) 0 else @intCast(min_y);
        const cols_u = @as(u32, @intCast(@max(max_x - min_x, 0))) / cw;
        const rows_u = @as(u32, @intCast(@max(max_y - min_y, 0))) / ch;
        if (cols_u == 0 or rows_u == 0) return error.TooSmall;
        const cols: u16 = @intCast(@min(cols_u, @as(u32, std.math.maxInt(u16))));
        const rows: u16 = @intCast(@min(rows_u, @as(u32, std.math.maxInt(u16))));

        // 2) bg/fg/cp 스크래치 그리드. 기본 bg=surface_bg·fg=surface_fg·cp=공백(패널 fill이 곧 덮는다).
        const n = @as(usize, cols) * @as(usize, rows);
        const bg = try allocator.alloc(terminal.Color, n);
        defer allocator.free(bg);
        const fg = try allocator.alloc(terminal.Color, n);
        defer allocator.free(fg);
        const cp = try allocator.alloc(u21, n);
        defer allocator.free(cp);
        const cwid = try allocator.alloc(u2, n); // 셀별 표시폭(EAW): wide 문자(한글/CJK)=2, 나머지=1
        defer allocator.free(cwid);
        const surface_bg_col = terminal.Color{ .rgb = tk.get(.surface_bg) };
        @memset(bg, surface_bg_col);
        @memset(fg, terminal.Color{ .rgb = tk.get(.surface_fg) });
        @memset(cp, ' ');
        @memset(cwid, 1);

        // 3) painter order로 ops 적용. 좌표는 origin 기준 셀로 환산(음수/범위 밖은 clamp/skip).
        // cursor role fill은 bg로 안 칠하고 caret 셀로 기록한다 — finishOverlayPrep이 PaneFrame.cursor로 lower해
        // 터미널 커서와 같은 반전-블록 렌더·suffix-trim 깜빡임을 재활용한다(컴포넌트는 깜빡임 위상을 모른다).
        var cursor: ?terminal.Cursor = null;
        var overlay_clip: ?chrome.draw.Rect = null; // 모달 클리핑 영역(draw.Op.clip) — 여러 개면 마지막이 이김
        for (draws) |d| for (d.ops) |op| switch (op) {
            .fill => |f| {
                if (f.role == .cursor) {
                    const col_i = @divTrunc(f.rect.x - @as(i32, @intCast(origin_x)), @as(i32, @intCast(cw)));
                    const row_i = @divTrunc(f.rect.y - @as(i32, @intCast(origin_y)), @as(i32, @intCast(ch)));
                    if (col_i >= 0 and col_i < cols and row_i >= 0 and row_i < rows) {
                        cursor = .{ .row = @intCast(row_i), .col = @intCast(col_i), .visible = true };
                    }
                } else {
                    paintRectBg(bg, cols, rows, origin_x, origin_y, cw, ch, f.rect, .{ .rgb = tk.get(f.role) }, null);
                }
            },
            .border => |b| {
                // C4b 모달: rich(quad 배경 — modal_bg_quad)면 테두리는 quad의 border_widths가 둥글게 그린다.
                // 셀 직각 테두리를 skip해 둥근 quad에 직각 테두리가 겹치지 않게 한다(리뷰 — notice 테두리 정합).
                if (!modal_bg_quad) paintRectBg(bg, cols, rows, origin_x, origin_y, cw, ch, b.rect, .{ .rgb = tk.get(b.role) }, b.sides);
            },
            .text => |t| placeText(cp, fg, cwid, cols, rows, origin_x, origin_y, cw, ch, t, .{ .rgb = tk.get(t.role) }),
            .swatch => |sw| {
                // color 스와치 — corner_radii 0이면 셀 bg(tui, 직각), >0이면 둥근 GPU quad(rich 칩). .quad의 위젯 분기와
                // 동형이되 색은 **literal RGB**(role 아님). 위젯이라 layer=3(셀·선택 하이라이트 위), 테두리/그림자 없음.
                const sw_radius = sw.corner_radii[0] != 0 or sw.corner_radii[1] != 0 or sw.corner_radii[2] != 0 or sw.corner_radii[3] != 0;
                if (!sw_radius) {
                    paintRectBg(bg, cols, rows, origin_x, origin_y, cw, ch, sw.rect, .{ .rgb = sw.rgb }, null); // color picker 견본 — literal RGB 셀 bg
                } else {
                    const fill = packOpaqueRgb(sw.rgb); // 불투명 색 패킹 단일 출처(0xFFRRGGBB)
                    gpu_quads.append(allocator, .{
                        .x = @floatFromInt(sw.rect.x),
                        .y = @floatFromInt(sw.rect.y),
                        .w = @floatFromInt(sw.rect.w),
                        .h = @floatFromInt(sw.rect.h),
                        .corner_radii = .{ @floatFromInt(sw.corner_radii[0]), @floatFromInt(sw.corner_radii[1]), @floatFromInt(sw.corner_radii[2]), @floatFromInt(sw.corner_radii[3]) },
                        .border_widths = .{ 0, 0, 0, 0 },
                        .fill_color0 = fill,
                        .fill_color1 = fill,
                        .border_color = 0,
                        .gradient_kind = 0,
                        .layer = 3,
                    }) catch {};
                }
            },
            .rule => {}, // 컴포넌트가 아직 안 냄 — 필요해질 때(C2 divider) 셀 라인으로 lower
            .clip => |r| overlay_clip = r, // 모달 클리핑 px 영역 — OverlayRaster.clip_rect로 전달(렌더러가 scissor). 안 그림
            .quad => |q| {
                const has_radius = q.corner_radii[0] != 0 or q.corner_radii[1] != 0 or q.corner_radii[2] != 0 or q.corner_radii[3] != 0;
                if (!has_radius) {
                    // tui: 직각 → 셀 배경(기존 fill 경로와 동일).
                    paintRectBg(bg, cols, rows, origin_x, origin_y, cw, ch, q.rect, .{ .rgb = tk.get(q.fill_role) }, null);
                } else if (modal_bg_quad) {
                    // 모달 배경 **다음**의 rich quad = 위젯(slider track/filled/thumb·toggle pill/knob 등). 이걸 배경처럼
                    // outset(pad)+shadow+layer=1로 처리하면 (a) pad만큼 커지고 (b) layer 1이 셀 그리드(선택 행 하이라이트
                    // bg)보다 아래라 하이라이트에 가려진다(활성 행 위젯 가림 버그). 위젯은 q.rect 그대로 + **layer 3**(셀 위)으로
                    // 올려 하이라이트 위에 보이게 한다. shadow 없음(위젯은 그림자 불필요). tui(직각)는 위 분기라 영향 없음.
                    const fr = tk.get(q.fill_role);
                    const fill: u32 = 0xFF000000 | (@as(u32, fr.r) << 16) | (@as(u32, fr.g) << 8) | @as(u32, fr.b);
                    var border: u32 = 0;
                    if (q.border_role) |brole| {
                        const bc = tk.get(brole);
                        border = 0xFF000000 | (@as(u32, bc.r) << 16) | (@as(u32, bc.g) << 8) | @as(u32, bc.b);
                    }
                    gpu_quads.append(allocator, .{
                        .x = @floatFromInt(q.rect.x),
                        .y = @floatFromInt(q.rect.y),
                        .w = @floatFromInt(q.rect.w),
                        .h = @floatFromInt(q.rect.h),
                        .corner_radii = .{ @floatFromInt(q.corner_radii[0]), @floatFromInt(q.corner_radii[1]), @floatFromInt(q.corner_radii[2]), @floatFromInt(q.corner_radii[3]) },
                        .border_widths = .{ @floatFromInt(q.border_widths[0]), @floatFromInt(q.border_widths[1]), @floatFromInt(q.border_widths[2]), @floatFromInt(q.border_widths[3]) },
                        .fill_color0 = fill,
                        .fill_color1 = fill,
                        .border_color = border,
                        .gradient_kind = 0,
                        .layer = 3,
                    }) catch {};
                } else {
                    // rich: GPU quad(layer=1 over — 모달 배경, 둥근+테두리). 색 0xAARRGGBB 불투명.
                    // C4b 모달 패딩: 배경 quad/shadow를 텍스트 영역(q.rect)보다 사방 pad만큼 확장한다 — 텍스트 셀은
                    // q.rect 그대로라 텍스트가 박스 안쪽으로 들어가 여백이 생긴다(tui=0이면 확장 0 = 기존과 동일).
                    // C4b 모달 패딩: 배경 박스를 텍스트 영역(q.rect)보다 사방 modal_padding_px만큼 키운다(Rect.outset —
                    // inset의 대칭, 선언적 역패딩). quad·shadow가 같은 box를 공유한다(좌우 중복 산술 제거). tui=0이면 outset 0 = q.rect.
                    const mp = tk.space.modal_padding_px;
                    const box = q.rect.outset(.{ .left = mp, .right = mp, .top = mp, .bottom = mp });
                    const bx: f32 = @floatFromInt(box.x);
                    const by: f32 = @floatFromInt(box.y);
                    const bw: f32 = @floatFromInt(box.w);
                    const bh: f32 = @floatFromInt(box.h);
                    const fr = tk.get(q.fill_role);
                    const fill: u32 = 0xFF000000 | (@as(u32, fr.r) << 16) | (@as(u32, fr.g) << 8) | @as(u32, fr.b);
                    var border: u32 = 0;
                    if (q.border_role) |brole| {
                        const bc = tk.get(brole);
                        border = 0xFF000000 | (@as(u32, bc.r) << 16) | (@as(u32, bc.g) << 8) | @as(u32, bc.b);
                    }
                    gpu_quads.append(allocator, .{
                        .x = bx,
                        .y = by,
                        .w = bw,
                        .h = bh,
                        .corner_radii = .{ @floatFromInt(q.corner_radii[0]), @floatFromInt(q.corner_radii[1]), @floatFromInt(q.corner_radii[2]), @floatFromInt(q.corner_radii[3]) },
                        .border_widths = .{ @floatFromInt(q.border_widths[0]), @floatFromInt(q.border_widths[1]), @floatFromInt(q.border_widths[2]), @floatFromInt(q.border_widths[3]) },
                        .fill_color0 = fill,
                        .fill_color1 = fill,
                        .border_color = border,
                        .gradient_kind = 0,
                        .layer = 1,
                    }) catch {};
                    modal_bg_quad = true;
                    // C4b 모달: 배경 quad에 그림자 동반(gpu_shadows 별 배열, quad·셀보다 아래). 같은 box + 약간 아래 offset + blur.
                    gpu_shadows.append(allocator, .{
                        .x = bx,
                        .y = by + @as(f32, @floatFromInt(tk.space.shadow_offset_y_px)),
                        .w = bw,
                        .h = bh,
                        .corner_radii = .{ @floatFromInt(q.corner_radii[0]), @floatFromInt(q.corner_radii[1]), @floatFromInt(q.corner_radii[2]), @floatFromInt(q.corner_radii[3]) },
                        .blur_radius = @floatFromInt(tk.space.shadow_blur_px),
                        .color = @as(u32, tk.space.shadow_alpha) << 24, // 토큰 alpha + RGB 0(검정). tui=0이면 무관(append 안 됨)
                    }) catch {};
                }
            },
        };

        // 4) 그리드를 DrawCell 배열로 평탄화(allocator 소유). wide 문자(한글/CJK)면 width=2 — frame builder가 그 폭으로
        // 글리프를 그린다. **wide 셀의 continuation 칸(c+1)은 emit하지 않는다** — emit하면 그 칸의 배경 quad가 합성 때
        // wide 글리프의 오른쪽 절반을 surface_bg로 덮어 잘려 보였다(터미널도 cell.continuation을 같은 이유로 스킵한다).
        // wide 셀의 2칸 배경이 그 칸을 덮으므로 패널 bg는 유지된다.
        var cells: std.ArrayList(renderer.DrawCell) = .empty;
        errdefer cells.deinit(allocator);
        try cells.ensureTotalCapacity(allocator, n);
        var r: u16 = 0;
        while (r < rows) : (r += 1) {
            var c: u16 = 0;
            while (c < cols) {
                const idx = @as(usize, r) * @as(usize, cols) + c;
                const w = cwid[idx];
                // C4b 모달: rich 모달은 배경이 GPU quad(layer=1)라, 빈 셀(공백)의 불투명 surface_bg가 둥근
                // quad를 사각으로 덮는다(리뷰 #1) — 빈 셀은 skip해 quad가 비치게 한다(글자 칸만 emit).
                // C4b 모달: 빈 셀 skip은 **기본 배경(surface_bg)인 빈 칸만** — 선택 행 강조(tab_active_bg) 등
                // 다른 배경의 빈 칸은 emit해야 그 칸도 하이라이트된다(빈 칸까지 skip하면 글자만 강조돼 보였던 버그).
                if ((modal_bg_quad or transparent_default) and cp[idx] == ' ' and std.meta.eql(bg[idx], surface_bg_col)) {
                    c += if (w == 2) @as(u16, 2) else 1;
                    continue;
                }
                // rich 모달: surface_bg 글자 셀은 배경을 칠하지 않고(default=투명, A0) GPU 배경 quad가 그대로 비치게
                // 한다 — 셀 배경 사각형이 quad와 미세하게 어긋나 '글자 뒤에만 배경색이 떠' 부자연스럽던 문제 제거
                // (사용자 피드백). 빈 surface_bg 셀은 위에서 skip, accent/보조 버튼 등 비-surface_bg 배경은 그대로 칠해
                // 버튼이 보인다. tui(modal_bg_quad=false)는 박스가 셀 배경이라 그대로 surface_bg를 유지한다.
                const cell_bg: terminal.Color = if ((modal_bg_quad or transparent_default) and std.meta.eql(bg[idx], surface_bg_col)) .default else bg[idx];
                cells.appendAssumeCapacity(.{ .row = r, .col = c, .codepoint = cp[idx], .width = w, .style = .{ .foreground = fg[idx], .background = cell_bg } });
                c += if (w == 2) @as(u16, 2) else 1; // wide면 continuation 칸 스킵
            }
        }
        return .{ .cells = cells, .cols = cols, .rows = rows, .origin_x = origin_x, .origin_y = origin_y, .cursor = cursor, .gpu_quads = gpu_quads, .gpu_shadows = gpu_shadows, .clip_rect = overlay_clip };
    }

    /// rect(backing px)를 origin 기준 셀 span으로 환산해 bg를 칠한다. sides==null이면 채움(fill), 아니면 켜진 변의
    /// 가장자리 셀만(border). 범위 밖은 clamp. rasterizeOverlayCells 전용 헬퍼.
    fn paintRectBg(bg: []terminal.Color, cols: u16, rows: u16, origin_x: u32, origin_y: u32, cw: u32, ch: u32, rect: chrome.draw.Rect, color: terminal.Color, sides: ?chrome.draw.Sides) void {
        const ox: i32 = @intCast(origin_x);
        const oy: i32 = @intCast(origin_y);
        const c0 = std.math.clamp(@divTrunc(rect.x - ox, @as(i32, @intCast(cw))), 0, @as(i32, cols));
        const r0 = std.math.clamp(@divTrunc(rect.y - oy, @as(i32, @intCast(ch))), 0, @as(i32, rows));
        const c1 = std.math.clamp(@divTrunc(rect.x + @as(i32, @intCast(rect.w)) - ox, @as(i32, @intCast(cw))), 0, @as(i32, cols));
        const r1 = std.math.clamp(@divTrunc(rect.y + @as(i32, @intCast(rect.h)) - oy, @as(i32, @intCast(ch))), 0, @as(i32, rows));
        var r: i32 = r0;
        while (r < r1) : (r += 1) {
            var c: i32 = c0;
            while (c < c1) : (c += 1) {
                const on_edge = if (sides) |s|
                    (s.top and r == r0) or (s.bottom and r == r1 - 1) or (s.left and c == c0) or (s.right and c == c1 - 1)
                else
                    true; // fill = 모든 셀
                if (on_edge) bg[@as(usize, @intCast(r)) * @as(usize, cols) + @as(usize, @intCast(c))] = color;
            }
        }
    }

    /// text op의 runs를 origin 셀부터 가로로 놓는다(EAW 폭만큼 전진, 범위 밖 skip). cp·fg·cwid 그리드에 쓴다.
    /// 표시 폭은 EAW(terminal.width.cellWidth)로 — 한글/CJK는 2칸을 전진하며 시작 칸의 DrawCell.width=2로
    /// 표시한다(coretext_frame_builder line 121/158과 같은 `@max(1, cellWidth)` 캐논 패턴). 그래야 wide 글리프가
    /// 2칸 폭으로 그려지고 다음 글자가 겹치지 않는다(한글이 잘려 보이던 회귀의 루트커즈). continuation 칸은 빈칸
    /// (codepoint ' ')으로 남고, 평탄화(위 4단계)가 그 칸을 emit하지 않는다(배경 quad가 wide 글리프를 덮지 않게).
    /// rasterizeOverlayCells 전용.
    fn placeText(cp: []u21, fg: []terminal.Color, cwid: []u2, cols: u16, rows: u16, origin_x: u32, origin_y: u32, cw: u32, ch: u32, t: chrome.draw.Op.Text, color: terminal.Color) void {
        const row_i = @divTrunc(t.origin.y - @as(i32, @intCast(origin_y)), @as(i32, @intCast(ch)));
        if (row_i < 0 or row_i >= rows) return;
        const row: usize = @intCast(row_i);
        var col_i = @divTrunc(t.origin.x - @as(i32, @intCast(origin_x)), @as(i32, @intCast(cw)));
        for (t.runs) |run| {
            const view = std.unicode.Utf8View.init(run.text) catch continue; // 잘못된 UTF-8 run은 건너뜀
            var it = view.iterator();
            while (it.nextCodepoint()) |c| {
                const w = @max(1, terminal.width.cellWidth(c)); // 결합 문자(0)는 1칸으로 — frame builder와 동일
                if (col_i >= 0 and col_i < cols) {
                    const idx = row * @as(usize, cols) + @as(usize, @intCast(col_i));
                    cp[idx] = c;
                    fg[idx] = color;
                    cwid[idx] = @intCast(@min(w, 2));
                }
                col_i += w;
            }
        }
    }

    /// 팝업의 가시 행(필터된·윈도우잉된 Row)을 arena에 빌드한다 — 카탈로그(command_catalog.entries.title)와 바인딩
    /// 표시(command_key_displays)는 platform 소유라 여기서 Row{title,binding,selected}로 만들어 neutral 컴포넌트에
    /// 주입한다(컴포넌트는 카탈로그를 안 본다). 선택이 보이도록 max_visible 윈도우로 스크롤한다(레거시 buildPaletteFrame
    /// 윈도우 로직 보존). 선택 행만 selected=true. palette_filtered가 비면 빈 슬라이스.
    fn buildPaletteRows(self: *AppSession, arena: std.mem.Allocator) ![]chrome.components.palette.Row {
        const Row = chrome.components.palette.Row;
        const max_visible = chrome.components.palette.max_visible;
        const total = self.palette_filtered.items.len;
        const selected = self.chrome_host.palette.selected;
        const visible_count = @min(total, max_visible);
        // 공유 윈도잉(prev=0 재파생) — selected가 창 아래로 나가면 끝맞춤 + clamp. settings·notifications와 단일 출처.
        const win_start = chrome.components.overlay_input.windowStart(total, max_visible, selected, 0);
        const rows = try arena.alloc(Row, visible_count);
        var i: usize = 0;
        while (i < visible_count) : (i += 1) {
            const fi = win_start + i; // palette_filtered 안에서의 인덱스
            const entry_idx = self.palette_filtered.items[fi];
            const binding: []const u8 = if (entry_idx < self.command_key_displays.items.len)
                self.command_key_displays.items[entry_idx]
            else
                "";
            rows[i] = .{
                .title = command_catalog.entries[entry_idx].title,
                .binding = binding,
                .selected = (fi == selected),
            };
        }
        return rows;
    }

    /// 단축키 힌트 배지(요소 rect + chord)를 요소 레이아웃에서 빌드해 host.collectKeyHintsDraws에 넘긴다 — 모디파이어
    /// 홀드 시 각 chrome 요소 **우상단**에 그 단축키를 띄운다. 위치가 있는 요소만(요소 없는 ⌘F/⌘K/⌘A/폰트는 생략 —
    /// 사용자 결정). chord는 command_catalog가 사용자 리바인드/unbind를 반영(없으면 그 요소 배지 생략). chord 문자열·배지
    /// 배열은 arena 소유(rasterize까지 유효). macOS 전용. 단일 출처: docs/keybind-hints.md.
    fn buildKeyHintBadges(self: *AppSession, props: chrome.ChromeProps, tokens: *const chrome.Tokens, arena: std.mem.Allocator, draws: *std.ArrayList(chrome.ChromeDraw)) !void {
        const Badge = chrome.components.shortcut_hints.Badge;
        const Action = config_mod.Action;
        const resolver = self.loaded_config.keyBindingResolver();
        var badges: std.ArrayList(Badge) = .empty;

        // 한 액션의 현재 chord를 표시 문자열로(arena dupe). 안 묶였으면 null(그 요소 배지 생략).
        const Local = struct {
            fn chordStr(res: anytype, action: Action, a: std.mem.Allocator) !?[]const u8 {
                const chord = command_catalog.chordForAction(res, action) orelse return null;
                var buf: [command_catalog.max_chord_display_len]u8 = undefined;
                return try a.dupe(u8, command_catalog.formatChord(chord, &buf));
            }
        };

        // 사이드바 워크스페이스 카드 → ⌘1~⌘9(select_tab). 접힘이면 카드가 없어 생략. 카드는 **검색-필터된 표시 목록**
        // (sidebar_visible_tabs) 순으로 그려지므로, 배지도 **표시 슬롯 s**(slotTop, slotAt의 역) 기준에 두고 chord는 그
        // 슬롯이 가리키는 **절대 워크스페이스 abs**의 ⌘(abs+1)을 쓴다 — 필터 활성 시 표시/절대 인덱스가 갈라지는 버그 방지.
        const sidebar = chrome.components.sidebar;
        if (!self.sidebar_collapsed and self.sidebar_width_px > 0 and self.sidebar_slot_height_px > 0) {
            const header_h: i64 = @intCast(self.sidebar_header_height_px);
            const slot_h: i64 = @intCast(self.sidebar_slot_height_px);
            const vp_bottom: i64 = @intCast(self.backing_height_px);
            for (self.sidebar_visible_tabs.items, 0..) |abs, s| {
                if (abs >= 9) continue; // select_tab 0..8 → ⌘1~9만 바인딩이 있다
                const cs = (try Local.chordStr(resolver, Action{ .select_tab = abs }, arena)) orelse continue;
                const y = sidebar.slotTop(s, self.sidebar_header_height_px, self.sidebar_slot_height_px, self.sidebar_scroll_offset_px);
                if (y + slot_h <= header_h or y >= vp_bottom) continue; // 헤더 위로 스크롤·뷰포트 아래로 벗어난 카드 생략(render scissor와 정합)
                try badges.append(arena, .{ .rect = .{ .x = 0, .y = @intCast(@max(y, header_h)), .w = self.sidebar_width_px, .h = self.sidebar_slot_height_px }, .chord = cs });
            }
            // 새 워크스페이스 + 버튼(헤더 줄0) → ⌘⇧T(new_tab). **헤더 아이콘 render 가드(cols<13이면 아이콘 안 그림)와 같게**
            // cols>=13에서만. 배지 rect 우단을 + 글리프 우단((cols-1)*cw, headerIconCol=cols-2의 셀 우단)에 맞춰 사이드바 밖으로 안 샌다.
            const cw = @max(self.cell_width_px, 1);
            const cols = self.sidebar_width_px / cw;
            if (cols >= 13) {
                if (try Local.chordStr(resolver, Action.new_tab, arena)) |cs| {
                    try badges.append(arena, .{ .rect = .{ .x = 0, .y = 0, .w = (cols - 1) * cw, .h = self.cell_height_px }, .chord = cs });
                }
            }
        }

        // 활성 pane → ⌘D(split_horizontal). 활성 pane rect 우상단.
        if (self.active_pane_rect.w > 0) {
            if (try Local.chordStr(resolver, Action.split_horizontal, arena)) |cs| {
                try badges.append(arena, .{ .rect = .{ .x = @intCast(self.active_pane_rect.x), .y = @intCast(self.active_pane_rect.y), .w = @intCast(self.active_pane_rect.w), .h = @intCast(self.active_pane_rect.h) }, .chord = cs });
            }
        }

        // 활성 pane 탭바: + 버튼(plus zone) → ⌘T(new_term), 활성 탭(seg) → ⌘W(close_term). barMetrics(렌더·hit-test와
        // 같은 메트릭)로 위치 단일 출처 — +/탭 seg를 인라인 재계산하지 않는다.
        {
            const pane = self.activePane();
            if (self.paneBarForLeaf(pane)) |pb| {
                const cw2 = self.cell_width_px;
                if (barMetrics(pb.tabs, cw2, pane.terms.items.len, tokens.space.tab_width_cols, pane.tab_scroll_cols)) |m| {
                    if (try Local.chordStr(resolver, Action.new_term, arena)) |cs| {
                        // + 글리프 col = plusZoneStart + (has_scroll? 0 : 1) (coretext buildPaneTabBarDrawList plus_start+1과 정합).
                        // 배지 rect 우단을 그 글리프 우단((plus_glyph+1)*cw)에 맞춰 ⌘T가 + 위에 오게(바 우단 패딩 아님).
                        const plus_glyph: u32 = m.plusZoneStart() + (if (m.has_scroll) @as(u32, 0) else 1);
                        if (plus_glyph < m.cols) try badges.append(arena, .{ .rect = .{ .x = @intCast(pb.tabs.x), .y = @intCast(pb.tabs.y), .w = (plus_glyph + 1) * cw2, .h = pb.tabs.h }, .chord = cs });
                    }
                    if (try Local.chordStr(resolver, Action.close_term, arena)) |cs| {
                        const seg = m.segOf(pane.active_term);
                        if (seg.end_col > seg.start_col) try badges.append(arena, .{ .rect = .{ .x = @intCast(pb.tabs.x + seg.start_col * cw2), .y = @intCast(pb.tabs.y), .w = (seg.end_col - seg.start_col) * cw2, .h = pb.tabs.h }, .chord = cs });
                    }
                }
            }
        }

        try self.chrome_host.collectKeyHintsDraws(badges.items, props, tokens, arena, draws);
    }

    /// chrome 오버레이 frame(최상위). chrome_host에서 열린 컴포넌트(Notice·Find·Palette)의 ChromeDraw를 수집해(실제
    /// view 계약을 탄다) 일반 rasterizer로 lower한다(fill·border·text, EAW-폭 placeText). 오버레이는 라우팅상 배타적
    /// 이라 최대 1개만 ops를 낸다(rasterizer가 단일 오버레이 가정). palette는 카탈로그 행을 주입해야 해 collectDraws가
    /// 아니라 collectPaletteDraws로 따로 모은다. 닫혀 있거나 메트릭/박스 미상이면 에러(호출자가 무시). macOS 전용.
    fn buildChromeOverlayPrep(self: *AppSession) !?OverlayPrep {
        // 오버레이는 터미널과 같은 셀·폰트(1×)로 그린다 — buildChromeProps도 같은 셀을 컴포넌트에 준다. 1.3× 확대는
        // 사용자 요청으로 제거(스케일 불일치로 한글이 약간 잘리던 문제도 함께 사라짐 — 셀=글리프 font size 일치).
        const cw = self.cell_width_px;
        const ch = self.cell_height_px;
        if (cw == 0 or ch == 0) return error.NoMetrics;
        const appearance = self.appearance;

        // 컴포넌트 view 경로를 실제로 타서 열린 오버레이의 ChromeDraw를 모은다(arena가 ops·runs 소유, lower까지 유효).
        var arena_state = std.heap.ArenaAllocator.init(self.allocator);
        defer arena_state.deinit();
        const arena = arena_state.allocator();
        const tokens = self.buildChromeTokens();
        const props = self.buildChromeProps();
        var draws: std.ArrayList(chrome.ChromeDraw) = .empty;
        try self.chrome_host.collectDraws(props, &tokens, arena, &draws); // Notice·Find
        if (self.chrome_host.palette.open) {
            const rows = try self.buildPaletteRows(arena); // 카탈로그 행 주입(platform 소유)
            try self.chrome_host.collectPaletteDraws(rows, props, &tokens, arena, &draws);
        }
        if (self.chrome_host.context_menu.open) {
            try self.chrome_host.collectContextMenuDraws(self.contextMenuItems(), props, &tokens, arena, &draws); // 항목 라벨 주입(platform 소유, 동적)
        }
        var notif_items: []const chrome.components.notifications.Item = &.{}; // caret 배치(append 후)에 재사용 — 같은 패널 rect
        if (self.chrome_host.notifications.open) {
            notif_items = try self.buildNotificationItems(arena); // 히스토리 → 카드(역순) 주입
            self.chrome_host.notifications.setItemCount(notif_items.len); // 패널 열린 채 새 알림 도착 시 selected clamp 동기화
            // 다음 프레임들의 hoverCursor coarse 게이트가 쓸 패널 content rect를 캐시한다(이미 빌드한 notif_items 재사용 —
            // 추가 비용 없음). 게이트가 이 rect로 "포인터가 패널 밖이면 빌드 스킵"을 판정한다(notif_panel_rect 주석 참조).
            self.notif_panel_rect = chrome.components.notifications.panelRect(&self.chrome_host.notifications, notif_items, props);
            try self.chrome_host.collectNotificationsDraws(notif_items, props, &tokens, arena, &draws);
        }
        self.settings_search_caret = null; // 세팅 안 열림/검색 아님이면 없음(imeCursorRect가 터미널 커서로 폴백)
        if (self.chrome_host.settings.open) {
            const labels = try self.buildSettingsSectionLabels(arena); // 좌측 네비 라벨(platform 소유)
            const fields = try self.buildSettingsFields(arena); // 현재 섹션의 필드 행 주입(platform 소유)
            try self.chrome_host.collectSettingsDraws(labels, fields, props, &tokens, arena, &draws);
            // 검색줄 caret을 캐시한다(sections/rows/props가 여기 있으니 추가 비용 없음) — imeCursorRect가 IME 후보창을
            // 검색줄 옆에 띄우는 데 쓴다(검색 중이 아니면 searchCaretRect가 null). notif_panel_rect 캐시 선례.
            self.settings_search_caret = chrome.components.settings.searchCaretRect(&self.chrome_host.settings, labels, fields, props, &tokens);
        }
        // 단축키 힌트(재설계): 모달이 안 열렸고 key_hints.visible면 **각 chrome 요소 우상단에 단축키 배지**를 빌드한다
        // (한 박스 HUD가 아니라 요소별 배지 — 사용자 요청). 모달이 열렸으면(위에서 draws 채워짐) 배지는 억제(모달 우선).
        // 배지는 요소 위 흩어진 곳만 칠하므로 아래 rasterize를 transparent_default로 해 나머지가 chrome/터미널이 비치게 한다.
        const key_hint_badges = draws.items.len == 0 and self.chrome_host.key_hints.visible;
        if (key_hint_badges) try self.buildKeyHintBadges(props, &tokens, arena, &draws);
        if (draws.items.len == 0) return null; // 열린 오버레이/배지 없음 — prep 없음(래퍼가 error.NotOpen으로 환산)

        var raster = try rasterizeOverlayCells(self.allocator, draws.items, &tokens, cw, ch, key_hint_badges);
        // C4b 모달-2b: 모달 배경 quad(layer=1)를 self.gpu_quads(over 패스)에 머지. renderFrame이 매 프레임
        // dropQuadsByLayer(1)로 layer1을 비운 직후라 누적되지 않는다. cells 소유권은 finishOverlayPrep이.
        self.gpu_quads.appendSlice(self.allocator, raster.gpu_quads.items) catch {};
        raster.gpu_quads.deinit(self.allocator);
        self.gpu_shadows.appendSlice(self.allocator, raster.gpu_shadows.items) catch {};
        raster.gpu_shadows.deinit(self.allocator);
        // 말풍선 caret(GPU 삼각형, gradient_kind=3) — 패널 배경 quad '뒤'에 append해 패널 상단 테두리를 caret 폭만큼
        // 덮어 'bubble을 연다'. 벨 바로 아래(빈 버퍼 행)에서 위로 뾰족. 패널이 세로 clamp로 밀렸거나 벨이 가로 밖이면 생략.
        if (self.chrome_host.notifications.open) self.appendNotificationCaret(notif_items, props, &tokens);
        // finishOverlayPrep이 cells 소유권을 toOwnedSlice로 가져가기 **전에** 실패하면(예: overlays alloc OOM)
        // raster.cells가 미해제로 남는다 — 그 경로만 정리한다(성공/이전 후엔 cells가 비어 no-op).
        errdefer raster.cells.deinit(self.allocator);
        return try self.finishOverlayPrep(&raster.cells, raster.cols, raster.rows, raster.origin_x, raster.origin_y, appearance, cw, ch, raster.cursor, raster.clip_rect);
    }

    /// 알림 센터 패널을 종(🔔) 아이콘 아래에 연다 — 종 클릭과 디버그 훅(MARU_OPEN_NOTIFICATIONS)의 단일 출처.
    /// 패널 좌단을 알림 그룹 좌단(배지 col cols-12)에 맞추고, 상단(body)은 줄2(=2ch)부터 둔다: 벨 글리프가 py_nudge
    /// (0.30ch)로 줄0에서 [0.30ch, 1.30ch]에 그려지므로 줄1(빈 버퍼 행)을 벨↔팝업 간격으로 비워 벨을 안 가린다(말풍선
    /// caret이 들어갈 자리). 항목은 collect 시점에 히스토리에서 빌드(buildNotificationItems) — show엔 개수만 준다(키 nav clamp).
    fn openNotificationPanel(self: *AppSession) void {
        if (self.cell_width_px == 0) return;
        // rich 모달 배경 quad는 lowering(rasterizeOverlayCells)이 content rect를 사방 modal_padding_px만큼 outset하므로
        // **보이는** 패널 상단 = content_top − mp. mp를 더해 보이는 상단을 원하는 줄에 맞춘다(안 더하면 패널이 벨/띠에 붙음).
        const mp: u32 = self.buildChromeTokens().space.modal_padding_px;
        var anchor_x: i32 = undefined;
        var anchor_y: i32 = undefined;
        if (self.sidebar_collapsed) {
            // 접힘: 종은 타이틀바 띠 안 collapsedBellCol(). 패널 좌단을 종 묶음(배지) 좌단에, 보이는 상단을 띠 하단에 둔다.
            // (접힘은 사이드바 폭 0이라 말풍선 caret은 appendNotificationCaret의 cols<13 가드로 자동 생략 — 띠 아래 드롭다운.)
            // 배지/종 묶음 좌단: 안 읽음 개수별 배지 폭(10+ 2칸, 1~9 1칸, 0 없음)만큼 종 왼쪽이 묶음 좌단(collapsed_badge_max_cells 단일 출처).
            const badge_cells: u16 = if (self.notification_unread > 9) collapsed_badge_max_cells else if (self.notification_unread > 0) 1 else 0;
            anchor_x = @intCast(@as(u32, self.collapsedBellCol() -| badge_cells) * self.cell_width_px);
            anchor_y = @intCast(self.titlebar_strip_px + mp); // content_top − mp = titlebar_strip_px(띠 하단)
        } else {
            // 펼침: 패널 좌단을 알림 그룹 좌단(배지 col cols-12)에, 보이는 상단을 줄2에 둔다 — 벨(줄0, py_nudge로 ~1.30ch)을
            // 한 줄 띄우고 그 사이(줄1)가 말풍선 caret 자리. mp를 빼먹으면 보이는 패널이 벨에 붙어(2ch−mp) caret 틈이 없다.
            const hcols = self.sidebar_width_px / self.cell_width_px;
            anchor_x = @intCast((hcols -| 12) * self.cell_width_px);
            anchor_y = @intCast(self.cell_height_px * 2 + mp);
        }
        self.chrome_host.notifications.show(anchor_x, anchor_y, self.notification_history.items.len);
        // 모달을 여는 즉시 배경 호버 강조(탭 ✕·슬롯 밴드·스크롤바·URL)를 끈다 — hoverCursor는 다음 마우스 이동에야
        // 정리하므로, 그 사이 패널 뒤로 stale 호버가 비치는 것을 막는다(close-confirm 모달 showConfirmButtons와 같은 규율).
        self.clearAllHover();
        self.notif_panel_rect = null; // 재오픈 — 직전 오픈의 stale rect로 hover 게이트가 오판하지 않게(첫 프레임이 다시 채운다)
        self.metal_dirty = true;
    }

    /// 알림 패널 말풍선 caret을 GPU 삼각형(gpu_quads gradient_kind=3) **1개**(채움 surface_bg, 패널 배경과 같은 색)로
    /// 그린다. 예전엔 focus_accent 외곽선 삼각형 위에 채움 삼각형을 얹었는데 채움 빗변의 fwidth edge-AA가 내부까지 부분
    /// 커버리지를 줘 외곽선과 블렌딩, 내부가 패널색 아닌 중간톤으로 떴다(사용자 피드백). 벨 글리프 중심(렌더러 가로 nudge 반영: col cols-12·width 2 슬롯이 0.5칸
    /// 왼쪽으로 밀려 중심 (cols-11.5)*cw)에 apex를 두고, 밑변을 패널 상단에 overlap만큼 겹쳐 상단 테두리를 caret
    /// 폭만큼 덮어 'bubble을 연다'. 패널이 세로 clamp로 anchor보다 위로 밀렸거나 벨이 패널 가로 밖이면 생략(벨과
    /// 어긋난 caret 방지). buildChromeOverlayFrame이 패널 배경 quad를 self.gpu_quads에 append한 '뒤'에 부른다(테두리 위로).
    fn appendNotificationCaret(self: *AppSession, items: []const chrome.components.notifications.Item, props: chrome.ChromeProps, tk: *const chrome.Tokens) void {
        const cw = self.cell_width_px;
        const ch = self.cell_height_px;
        if (cw == 0 or ch == 0) return;
        const cols = self.sidebar_width_px / cw;
        if (cols < 13) return; // 벨이 안 그려지는 폭 — caret도 생략(buildSidebarHeaderDrawList cols<13과 정합)
        const panel = chrome.components.notifications.panelRect(&self.chrome_host.notifications, items, props) orelse return;
        if (panel.y < self.chrome_host.notifications.anchor_y) return; // 세로 clamp로 위로 밀림 — 벨과 어긋나니 생략
        const cw_f: f32 = @floatFromInt(cw);
        const ch_f: f32 = @floatFromInt(ch);
        const bell_cx: f32 = (@as(f32, @floatFromInt(cols)) - 11.5) * cw_f; // 벨 중심(cols-12, 2칸, 가로 -0.5 nudge 반영 → cols-11.5)
        // panelRect는 content rect(셀 격자)다. rich 모달 배경 quad는 lowering이 사방 modal_padding_px만큼 outset하므로
        // **보이는** 패널 경계는 content rect를 mp만큼 키운 것 — caret은 그 보이는 경계 기준으로 맞춰야 패널과 닿는다.
        const mp: f32 = @floatFromInt(tk.space.modal_padding_px);
        const px: f32 = @as(f32, @floatFromInt(panel.x)) - mp; // 보이는 패널 좌단
        const pw: f32 = @as(f32, @floatFromInt(panel.w)) + 2 * mp; // 보이는 패널 폭
        if (bell_cx < px or bell_cx > px + pw) return; // 벨이 (보이는) 패널 가로 밖 — 생략
        const panel_top: f32 = @as(f32, @floatFromInt(panel.y)) - mp; // 보이는 패널 상단(content top − outset)
        const caret_w: f32 = cw_f * 1.6; // ~1.6칸 폭(말풍선 꼭지)
        const caret_h: f32 = ch_f * 0.5; // ~반 줄 높이
        const overlap: f32 = 2.0; // 밑변을 패널 안으로 — 상단 테두리 seam 덮기
        const fill = packRgbAlpha(tk.get(.surface_bg), 0xFF); // 채움=패널 배경색(텍스트 박스와 동일)
        // 말풍선 caret = 패널 배경(surface_bg)으로 꽉 찬 **단일** 삼각형. 예전엔 accent 삼각형 위에 더 작은 채움 삼각형을
        // 얹었는데, 작은 삼각형의 fwidth edge-AA가 내부까지 부분 커버리지를 줘 아래 accent와 블렌딩돼 내부가 패널색이
        // 아닌 중간톤으로 떠 보였다(사용자 피드백 "채우기가 텍스트 박스랑 동일하게"). 외곽선 없이 surface_bg로만 채워 패널
        // 상단과 이음새 없이 잇는다(패널 배경 quad '뒤'에 그려 상단 테두리를 caret 폭만큼 덮어 bubble을 연다).
        self.gpu_quads.append(self.allocator, triangleQuad(bell_cx - caret_w / 2, panel_top - caret_h, caret_w, caret_h + overlap, fill)) catch {};
    }

    /// gradient_kind=3(위 삼각형) GpuQuad 한 개(말풍선 caret 헬퍼). 좌상단 (x,y)·크기 (w,h) backing px,
    /// fill_color0=color(0xAARRGGBB), corner/border 0(셰이더가 삼각형 경로에서 무시), layer 1(모달 over).
    fn triangleQuad(x: f32, y: f32, w: f32, h: f32, color: u32) metal_frame.GpuQuad {
        return .{
            .x = x,
            .y = y,
            .w = w,
            .h = h,
            .corner_radii = .{ 0, 0, 0, 0 },
            .border_widths = .{ 0, 0, 0, 0 },
            .fill_color0 = color,
            .fill_color1 = color,
            .border_color = 0,
            .gradient_kind = 3, // 위로 뾰족한 삼각형(셰이더 분기)
            .layer = 1, // 모달 over(패널 배경과 같은 패스)
        };
    }

    /// chrome Notice 모달(손상 알림 등)을 연다. 메시지는 세션 소유 버퍼로 복사한다(copyOverlayMessage — slice
    /// dangling 방지·UTF-8 경계 절단). 다른 오버레이를 닫아 배타성을 지키되(dismissMessageOverlays), confirm은 닫기
    /// 확인이라 보류한 닫기까지 취소한다(cancelPendingClose — showConfirm이 notice를 닫는 것과 대칭, 단일 오버레이
    /// 불변식). 다음 tick이 오버레이로 그린다.
    pub fn showNotice(self: *AppSession, message: []const u8) void {
        self.dismissMessageOverlays();
        self.cancelPendingClose(); // confirm 모달 + 보류 닫기 취소(열려 있을 때만 의미; 닫혀 있으면 무해)
        self.chrome_host.notice.show(copyOverlayMessage(&self.notice_message_buf, message));
        self.metal_dirty = true;
    }

    /// 안내 메시지를 **세팅 모달이 열려 있으면 폼 상단 인라인 배너**(§6.9)로, 아니면 일반 notice 토스트로 보인다.
    /// keybind 녹음(세팅 안)의 검증 실패("등록 불가 키")·충돌 경고가 showNotice로 가면 dismissMessageOverlays가 세팅
    /// 모달까지 닫아(단일-오버레이 불변식) 사용자가 녹음하던 화면이 사라지던 문제를 고친다 — 배너는 세팅 자체 그리드
    /// 안 텍스트라 모달을 닫지 않고 위에 얹힌다. 세팅 밖(메뉴 rebind 등)에서 온 같은 메시지는 기존대로 토스트.
    fn settingsMessageOrNotice(self: *AppSession, message: []const u8) void {
        if (self.chrome_host.settings.open) {
            self.chrome_host.settings.setMessage(message);
            self.metal_dirty = true;
        } else {
            self.showNotice(message);
        }
    }

    pub fn metalFrame(self: *const AppSession) MetalFrame {
        var frame = self.metal_buffer.view();
        // "surface→rect": 터미널을 사이드바 폭만큼 오른쪽에 그리고, 왼쪽 strip에 사이드바 배경을 칠한다.
        // 렌더러가 origin offset + 배경 quad를 처리한다. split(panel)도 같은 origin 방식을 확장한다.
        frame.terminal_origin_x_px = self.sidebar_width_px;
        frame.sidebar_bg = self.sidebarBg();
        // 화면 clear color(빈 영역/기본 배경 셀이 비치는 색): OSC 11(배경 set)이 있으면 그 색, 없으면
        // theme.background. DECSCNM(?5, G9) 화면 반전이면 전경색으로 스왑한다(빈 영역도 반전돼야 함). 활성
        // surface 기준(렌더 pass clearColor — 셀이 default 배경=A0일 때 드러남). surface_initialized 가드는
        // 다른 surface-touch 메서드와 동일 — activeSurfaceConst()의 .? unwrap이 탭이 빈 시점(teardown 등)에
        // 패닉하지 않게 한다(그땐 theme 기본 배경으로 폴백).
        frame.terminal_bg = if (self.surface_initialized) blk: {
            const active_core = &self.activeSurfaceConst().core;
            const eff_bg = active_core.defaultBgOverride() orelse self.appearance.theme.background;
            const eff_fg = active_core.defaultFgOverride() orelse self.appearance.theme.foreground;
            break :blk packOpaqueRgb(if (active_core.reverseScreen()) eff_fg else eff_bg);
        } else packOpaqueRgb(self.appearance.theme.background);
        // 사이드바 셀(밴드 ++ 제목 glyph)은 metal_buffer가 소유한다 — view()가 frame.sidebar_cells를
        // 세팅한다(self.sidebar_cells는 밴드 source라 replace에만 넘긴다). 여기선 슬롯 높이만 더한다:
        // 렌더러가 사이드바 셀을 cell 높이가 아니라 탭 슬롯 높이(≈2.5×)로 세로 배치하게.
        frame.sidebar_slot_height_px = self.sidebar_slot_height_px;
        // 상단 헤더(검색바 + view options·새 워크스페이스 아이콘) 높이 — 렌더러가 사이드바 셀(밴드·카드 glyph)을
        // 이만큼 아래로 민다(밴드 view는 슬롯 상대 좌표라 .m이 시프트 단일 책임). 헤더 glyph는 절대 좌표 별도 frame.
        frame.sidebar_header_height_px = self.sidebar_header_height_px;
        // 사이드바 세로 스크롤량 — 렌더러가 사이드바 셀(밴드·카드 glyph) py_top에서 빼고, scroll>0이면 헤더 아래로
        // scissor 클리핑한다(GPU quad 밴드·tint는 lowering이 이미 뺐다 — 같은 sidebar_scroll_offset_px 단일 출처).
        frame.sidebar_scroll_offset_px = self.sidebar_scroll_offset_px;
        // 상단 타이틀바 띠 높이 — 렌더러가 접힘 펼치기 토글(◧) 글리프를 이 띠 안에 세로 중앙 배치해 신호등과
        // 정렬시키는 데만 쓴다(펼침 헤더 아이콘은 terminal_origin_x_px>0이라 0.3ch nudge 유지). hit-test
        // (collapsedToggleRect)는 이미 이 띠 전체 높이를 클릭 영역으로 쓴다.
        frame.titlebar_strip_px = self.titlebar_strip_px;
        // 창 배경 투명도 → clear color alpha(렌더러가 /1000). opacity는 loader가 0~1로 검증하므로 *1000은 0~1000.
        frame.window_opacity_milli = @intFromFloat(@round(self.appearance.window_opacity * 1000.0));
        return frame;
    }

    pub fn deinit(self: *AppSession) void {
        if (self.copy_buffer.len > 0) self.allocator.free(self.copy_buffer);
        if (self.clipboard_out_buffer.len > 0) self.allocator.free(self.clipboard_out_buffer);
        self.clipboard_read_target_buf.deinit(self.allocator);
        if (self.notification_title_out.len > 0) self.allocator.free(self.notification_title_out);
        if (self.notification_body_out.len > 0) self.allocator.free(self.notification_body_out);
        for (self.agent_notifications.items) |n| {
            self.allocator.free(n.title);
            self.allocator.free(n.body);
        }
        self.agent_notifications.deinit(self.allocator);
        for (self.notification_history.items) |n| {
            self.allocator.free(n.title);
            self.allocator.free(n.body);
        }
        self.notification_history.deinit(self.allocator);
        self.pane_palette_copies.deinit(self.allocator);
        if (self.url_buffer.len > 0) self.allocator.free(self.url_buffer);
        if (self.config_path_buffer) |b| self.allocator.free(b);
        self.pending_paste.deinit(self.allocator);
        // 진행 중 업로드 스레드 완료 대기(detach 스레드가 self.upload_*를 건드리므로 self 해제 전 0까지).
        while (true) {
            self.upload_mutex.lockUncancelable(self.io);
            const n = self.upload_inflight;
            self.upload_mutex.unlock(self.io);
            if (n == 0) break;
            std.atomic.spinLoopHint(); // 미완 업로드 완료 대기 — 보통 inflight=0이라 즉시 break(드물고 짧다)
        }
        for (self.upload_results.items) |p| self.allocator.free(p);
        self.upload_results.deinit(self.allocator);
        // 인앱 업데이트 체크 스레드를 join한다(이전 busy-spin 대신 — CPU를 안 쓰고 OS가 대기). 이 스레드가
        // self.update_*·self.allocator를 건드리므로 self 해제 전에 반드시 끝나야 한다. CLOEXEC으로 curl pipe가
        // 다른 fork에 새지 않아 readAllFd가 매달리지 않으므로, join은 curl -m 타임아웃 안에 수렴한다.
        if (self.update_thread) |t| t.join();
        self.ime_inserted.deinit(self.allocator);

        self.metal_buffer.deinit(self.allocator);
        self.sidebar_cells.deinit(self.allocator);
        self.gpu_quads.deinit(self.allocator);
        self.gpu_shadows.deinit(self.allocator);
        self.kitty_uploaded.deinit(self.allocator);
        // F2-1 배경 이미지 디코드 캐시 — owned 픽셀·경로 문자열(빈 경로면 empty라 무해).
        if (self.bg_image_pixels.len > 0) self.allocator.free(self.bg_image_pixels);
        self.allocator.free(self.bg_image_path_cache);
        self.global_hotkeys.deinit(self.allocator);
        // 커맨드 카탈로그: owned 문자열(key_display·key_equivalent)을 먼저 해제하고 목록들을 deinit(빌드 전이면 empty라 무해).
        for (self.command_key_displays.items) |s| self.allocator.free(s);
        self.command_key_displays.deinit(self.allocator);
        for (self.command_key_equivalents.items) |s| self.allocator.free(s);
        self.command_key_equivalents.deinit(self.allocator);
        self.command_entries.deinit(self.allocator);
        self.palette_filtered.deinit(self.allocator);
        self.chrome_host.deinit(self.allocator); // chrome 컴포넌트 heap(find.query) 해제
        self.rename_input.deinit(self.allocator); // 인라인 rename 입력(query/preedit) heap 해제
        self.sidebar_search_input.deinit(self.allocator); // 사이드바 검색바 입력 heap 해제
        self.sidebar_visible_tabs.deinit(self.allocator); // 검색 필터 표시 슬롯 매핑 heap 해제
        self.find_matches.deinit(self.allocator);
        self.find_view_spans.deinit(self.allocator);
        if (self.workspace_buffer) |b| self.allocator.free(b);
        if (self.sidebar_config_buffer) |b| self.allocator.free(b);
        inline for (pending_writeback_lists) |n| @field(self, n).deinit(self.allocator); // config write-back pending registry(단일 출처)
        self.hover_leaf_scratch.deinit(self.allocator);
        self.scrollbar_leaf_scratch.deinit(self.allocator);
        self.hover_divider_scratch.deinit(self.allocator);
        self.divider_seg_scratch.deinit(self.allocator);
        // 1) 각 탭의 각 panel의 각 Term live PTY 정리 — closeAndDetach는 runtime을 쓰므로 runtime.deinit '전에'.
        //    detach 후 deinit이 reader thread join + fd/queue 해제(이동 금지 계약이라 in-place로 정리).
        for (self.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    if (term.rt.live_initialized) {
                        if (self.runtime_initialized) term.rt.live_pty.closeAndDetach(&self.runtime);
                        term.rt.live_pty.deinit();
                        term.rt.live_initialized = false;
                    }
                }
            }
        }
        if (self.renderer_initialized) {
            self.renderer_state.deinit();
            self.renderer_initialized = false;
        }
        if (self.runtime_initialized) {
            self.runtime.deinit();
            self.runtime_initialized = false;
        }
        // 2) 각 panel의 각 Term surface 정리 + Term/Pane/Tab heap 해제(runtime.deinit 뒤 — surface는 runtime 불요).
        //    appearance가 surface family를 빌리므로 surface 정리는 아래 config/appearance 해제보다 앞이어야
        //    한다(원래 순서 보존).
        for (self.tabs.items) |tab| {
            for (tab.panes.items) |pane| {
                for (pane.terms.items) |term| {
                    // custom_name(사용자 rename) + git_branch 캐시 + auto_title 캐시(owned) 해제 — destroyTerm과 같은
                    // 규율(deinit은 runtime.deinit 순서 때문에 teardown을 직접 풀어 써서 destroyTerm을 못 부르므로 여기서도
                    // 해제한다). destroyTerm의 owned 필드 목록과 동기 유지할 것.
                    if (term.surface.custom_name) |n| self.allocator.free(n);
                    if (term.git_branch) |b| self.allocator.free(b);
                    if (term.git_branch_cwd) |c| self.allocator.free(c);
                    term.auto_title.deinit(self.allocator);
                    term.surface.deinit();
                    self.allocator.destroy(term);
                }
                if (pane.custom_name) |n| self.allocator.free(n);
                pane.terms.deinit(self.allocator);
                self.allocator.destroy(pane);
            }
            if (tab.custom_name) |n| self.allocator.free(n);
            PaneTree.deinit(self.allocator, tab.tree); // heap split 노드 해제(split.deinit은 leaf 미접근)
            tab.panes.deinit(self.allocator);
            self.allocator.destroy(tab);
        }
        self.tabs.deinit(self.allocator);
        self.surface_ptrs.deinit(self.allocator);
        self.surface_initialized = false;
        // appearance가 family를 빌리므로 surface 정리 뒤에 해제. 가드로 init 초반 실패 시 undefined
        // arena를 free하지 않게(다른 자원과 같은 패턴).
        if (self.config_loaded) {
            self.loaded_config.deinit();
            self.config_loaded = false;
        }
        // 새 탭 spawn용으로 보관했던 ZDOTDIR 셸 통합 디렉터리(init에서 안 풀고 들고 있던 것).
        if (self.new_tab_zdotdir) |d| {
            self.allocator.free(d);
            self.new_tab_zdotdir = null;
        }
        // 보관했던 maru 실행 파일 경로(opt-in ssh 라우팅용 — executablePathAlloc owned).
        if (self.new_tab_ssh_bin) |b| {
            self.allocator.free(b);
            self.new_tab_ssh_bin = null;
        }
        self.* = undefined;
    }

    fn writeSummaryFromTick(self: *AppSession, tick_result: app.AppFrameLoopTick) void {
        self.writeSummaryFromRenderStats(tick_result.index, tick_result.render_stats);
    }

    /// FrameLoopTick 없이도(멀티 페인 통합으로 활성 panel을 app_session이 직접 place한 macOS 경로) tick index와
    /// per-frame render 통계만 summary에 덧씌운다. 공유 counter/size/state는 writeSummaryFromState가 단일 출처로
    /// 채운다 — 이렇게 해야 두 writer가 필드별로 어긋나지 않고, 새 counter가 추가돼도 한 곳만 고치면 된다.
    /// key/resize/close summary의 render 필드는 "마지막으로 그려진 frame" 값(화면의 현재 상태)을 그대로 유지한다.
    fn writeSummaryFromRenderStats(self: *AppSession, index: usize, stats: renderer.RenderFrameStats) void {
        self.writeSummaryFromState();
        self.last_summary.last_tick_index = @intCast(index);
        self.last_summary.glyph_count = @intCast(stats.glyph_count);
        self.last_summary.draw_cells = @intCast(stats.draw_cells);
        self.last_summary.atlas_entries = @intCast(stats.atlas_entries);
        self.last_summary.frame_prepared = boolCode(stats.prepared());
        self.last_summary.frame_consistent = boolCode(stats.consistent);
        self.last_summary.glyph_uv_ready = boolCode(stats.glyph_uv_ready);
        self.last_summary.glyph_raster_ready = boolCode(stats.glyph_raster_ready);
    }

    fn writeSummaryFromState(self: *AppSession) void {
        self.last_summary.abi_version = abi_version;
        self.last_summary.terminal_surface = boolCode(self.surface_initialized);
        self.last_summary.frame_loop_ticks = if (self.renderer_initialized) @intCast(self.frame_loop.frame_index) else 0;
        self.last_summary.output_events = self.total_output_events;
        self.last_summary.exit_events = self.total_exit_events;
        self.last_summary.key_events = self.total_key_events;
        self.last_summary.terminal_input_events = self.total_terminal_input_events;
        self.last_summary.terminal_input_bytes = self.total_terminal_input_bytes;
        self.last_summary.app_key_events = self.total_app_key_events;
        self.last_summary.ignored_key_events = self.total_ignored_key_events;
        self.last_summary.resize_events = self.total_resize_events;
        self.last_summary.close_events = self.total_close_events;
        self.last_summary.ended = boolCode(self.ended_seen);
        self.last_summary.metal_generation = @truncate(self.metal_buffer.generation);
        if (self.surface_initialized) {
            self.last_summary.surface_id = self.activeSurface().id;
            self.last_summary.cols = self.activeSurface().core.size.cols;
            self.last_summary.rows = self.activeSurface().core.size.rows;
            self.last_summary.process_state = processStateCode(self.activeSurface().process_state);
        }
    }
};

pub fn normalizeConfig(config: SessionConfig) !NormalizedConfig {
    if (config.abi_version != abi_version) return error.UnsupportedAbi;
    if (config.cols == 0 or config.rows == 0) return error.InvalidConfig;
    if (config.cols > std.math.maxInt(u16) or config.rows > std.math.maxInt(u16)) return error.InvalidConfig;

    const command_kind = std.enums.fromInt(CommandKind, config.command_kind) orelse return error.InvalidConfig;

    return .{
        // PTY spawn winsize와 Surface의 TerminalCore grid가 같은 최소 크기를 쓰도록 clamp한다
        // (cols>=2). 안 그러면 cols=1 config에서 grid는 2칸(core가 clamp)인데 PTY winsize는 1칸이
        // 되어 셸과 어긋난다.
        .size = terminal.clampGridSize(.{ .cols = @intCast(config.cols), .rows = @intCast(config.rows) }),
        .queue_capacity = if (config.queue_capacity == 0) default_queue_capacity else config.queue_capacity,
        .command_kind = command_kind,
        .chrome_minimal = config.chrome_minimal != 0,
        .minimal_tabs = config.minimal_tabs != 0,
        .width_px = config.width_px,
        .height_px = config.height_px,
        .scale_milli = config.scale_milli,
    };
}

fn spawnRequest(config: NormalizedConfig, term: []const u8, shell: config_mod.ShellConfig, env_overrides: []const []const u8, zdotdir: ?[]const u8, ssh_bin: ?[]const u8) maru.pty.SpawnRequest {
    var request: maru.pty.SpawnRequest = switch (config.command_kind) {
        .controlled_smoke => .{
            .command = "/bin/sh",
            .args = &.{
                "-c",
                "printf 'Maru app shell\\r\\n'; IFS= read -r line; printf 'Maru app input:%s\\r\\n' \"$line\"; printf 'Maru app frame loop\\r\\n'",
            },
            .size = config.size,
        },
        .interactive_shell => .{
            // 사용자 config shell.command가 있으면 그 셸을, 없으면 resolveInteractiveShell 폴백(현행).
            // args도 config shell.args(기본 -i). login 래퍼는 이 command/args를 `exec -l`로 감싼다(변경 없음).
            .command = if (shell.command.len > 0) shell.command else maru.pty.resolveInteractiveShell(),
            .args = shell.args,
            // login shell로 띄운다(macOS backend가 login(1)으로 감싼다 — Terminal.app·Ghostty와
            // 동일하게 전체 로그인 세션 셋업). PATH·EDITOR·키바인딩 등 사용자 환경이 완전히 잡힌다.
            // controlled_smoke(/bin/sh -c)는 login이 아니다.
            .login = true,
            .size = config.size,
        },
    };
    // 사용자 config의 TERM을 셸에 준다(기본 xterm-256color). env는 빈 채로 둬 부모 상속 +
    // TERM/COLORTERM override 경로를 타게 한다. zdotdir이 있으면 셸 통합용 ZDOTDIR을 주입한다.
    request.term = term;
    // 사용자 config env.<KEY> 주입(부모 상속 + maru override 위에 upsert). 빈 슬라이스면 EnvStorage가 무동작.
    request.env_overrides = env_overrides;
    request.zdotdir = zdotdir;
    // opt-in ssh 라우팅이 켜졌으면 maru 실행 파일 경로를 실어 EnvStorage가 MARU_BIN/MARU_SSH_INTEGRATION을
    // 주입하게 한다(null이면 주입 안 함 — 평범한 ssh 그대로).
    request.ssh_integration_bin = ssh_bin;
    return request;
}

fn commandName(kind: CommandKind) []const u8 {
    return switch (kind) {
        .controlled_smoke => "/bin/sh -c maru-app-smoke",
        .interactive_shell => maru.pty.resolveInteractiveShell(),
    };
}

fn processStateCode(state: maru.session.ProcessState) u32 {
    return switch (state) {
        .starting => 0,
        .running => 1,
        .exited => 2,
    };
}

fn boolCode(value: bool) u32 {
    return if (value) 1 else 0;
}

test "macOS app session config rejects unsafe fixed-width ABI input" {
    // Swift가 넘긴 config는 Zig allocator나 slice를 포함하지 않는 fixed-width record다.
    // 이 검증이 있어야 잘못된 window size나 오래된 ABI가 PTY spawn까지 내려가지 않는다.
    try std.testing.expectError(error.UnsupportedAbi, normalizeConfig(.{
        .abi_version = abi_version - 1,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    }));
    try std.testing.expectError(error.InvalidConfig, normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 0,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    }));
    try std.testing.expectError(error.InvalidConfig, normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = 999,
    }));
}

test "macOS app session config defaults queue capacity without changing command intent" {
    const normalized = try normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 0,
        .command_kind = @intFromEnum(CommandKind.interactive_shell),
    });
    try std.testing.expectEqual(terminal.Size{ .cols = 80, .rows = 24 }, normalized.size);
    try std.testing.expectEqual(@as(usize, default_queue_capacity), normalized.queue_capacity);
    try std.testing.expectEqual(CommandKind.interactive_shell, normalized.command_kind);
    try std.testing.expectEqual(false, normalized.chrome_minimal); // 기본 full(0)
    try std.testing.expectEqual(false, normalized.minimal_tabs); // 기본 스크래치(0)
}

test "macOS app session normalizeConfig carries chrome_minimal and minimal_tabs flags" {
    const full = try normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        .chrome_minimal = 0,
    });
    try std.testing.expectEqual(false, full.chrome_minimal);
    try std.testing.expectEqual(false, full.minimal_tabs);

    const minimal = try normalizeConfig(.{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        .chrome_minimal = 1,
        .minimal_tabs = 1,
    });
    try std.testing.expectEqual(true, minimal.chrome_minimal);
    try std.testing.expectEqual(true, minimal.minimal_tabs);
}

// gridFromBacking·pointInRect·paneDropZone·halfRect 단위 test는 session/layout_math.zig로 이동(b1, 순수 기하).

// refreshCellMetrics의 단일 적용점이 호출하는 line-height·letter-spacing 산술을 못박는다(OS·CoreText 없이 곱/가산
// 검증 — 비-macOS CI에서도 돈다). 이 두 px가 grid·atlas·hit-test의 진실 소스라, 여기 곱/가산이 맞으면 나머지가 자동 정합.
test "applyFontSpacing: line-height multiplies height, letter-spacing adds to advance (scaled, saturating)" {
    // 기본값(1.0/0.0)은 base 그대로 — advance·glyph 폭 모두 base.
    {
        const r = applyFontSpacing(8, 18, 1.0, 0.0, 1000);
        try std.testing.expectEqual(@as(u32, 8), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 8), r.glyph_width_px);
        try std.testing.expectEqual(@as(u32, 18), r.height_px);
    }
    // line-height 2.0 → 높이 2배(18→36), 폭은 letter-spacing 0이라 불변.
    {
        const r = applyFontSpacing(8, 18, 2.0, 0.0, 1000);
        try std.testing.expectEqual(@as(u32, 8), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 36), r.height_px);
    }
    // line-height 1.5 → 18×1.5=27(round). letter-spacing 4pt @1x → advance +4px(8→12).
    {
        const r = applyFontSpacing(8, 18, 1.5, 4.0, 1000);
        try std.testing.expectEqual(@as(u32, 12), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 27), r.height_px);
    }
    // letter-spacing은 논리 pt × 분수 scale로 환산 — 2x(scale 2000)에서 4pt는 advance +8px(8→16). 높이는 1.0이라 불변.
    {
        const r = applyFontSpacing(8, 18, 1.0, 4.0, 2000);
        try std.testing.expectEqual(@as(u32, 16), r.advance_width_px);
        try std.testing.expectEqual(@as(u32, 18), r.height_px);
    }
    // 음수 letter-spacing → advance 좁힘(8 + (-3) = 5). round(half-away): -3.
    {
        const r = applyFontSpacing(8, 18, 1.0, -3.0, 1000);
        try std.testing.expectEqual(@as(u32, 5), r.advance_width_px);
    }
    // 큰 음수 letter-spacing이 advance를 1 미만으로 끌어내려도 1px로 saturate(0폭 grid div 폭주 방지).
    {
        const r = applyFontSpacing(8, 18, 1.0, -100.0, 1000);
        try std.testing.expectEqual(@as(u32, 1), r.advance_width_px);
    }
    // 정확히 base를 0으로 만드는 음수도 1로 saturate(8 + (-8) = 0 → 1).
    {
        const r = applyFontSpacing(8, 18, 1.0, -8.0, 1000);
        try std.testing.expectEqual(@as(u32, 1), r.advance_width_px);
    }
    // **핵심(슬롯 분리)**: 자간은 advance만 바꾸고 **글리프 비트맵 폭(glyph_width_px)은 자연폭 base 불변**이다 —
    // 음수든 양수든 큰 음수든. 이 불변식이 깨지면 음수 자간에서 slot이 좁아져 글자가 세로로 흔들리는 버그가 재발한다.
    {
        try std.testing.expectEqual(@as(u32, 8), applyFontSpacing(8, 18, 1.0, -3.0, 1000).glyph_width_px);
        try std.testing.expectEqual(@as(u32, 8), applyFontSpacing(8, 18, 1.0, 4.0, 1000).glyph_width_px);
        try std.testing.expectEqual(@as(u32, 8), applyFontSpacing(8, 18, 1.0, -100.0, 1000).glyph_width_px); // saturate 무관: 자연폭 유지
        try std.testing.expectEqual(@as(u32, 8), applyFontSpacing(8, 18, 2.0, 4.0, 2000).glyph_width_px); // line-height·scale 무관
    }
}

test "chromePointerFromMouse: kind→phase, xterm button→PointerButton, mods 비트→Mods" {
    // kind: 1=down, 2=drag→move, 3=up, 4/5=더블/트리플→down. 좌표는 그대로 통과.
    const down = AppSession.chromePointerFromMouse(1, 12.5, 34.0, 0, 0);
    try std.testing.expectEqual(chrome.input.PointerPhase.down, down.phase);
    try std.testing.expectEqual(@as(f64, 12.5), down.x_px);
    try std.testing.expectEqual(@as(f64, 34.0), down.y_px);
    try std.testing.expectEqual(chrome.input.PointerButton.left, down.button);
    try std.testing.expectEqual(chrome.input.Mods{}, down.mods);
    try std.testing.expectEqual(chrome.input.PointerPhase.move, AppSession.chromePointerFromMouse(2, 0, 0, 0, 0).phase);
    try std.testing.expectEqual(chrome.input.PointerPhase.up, AppSession.chromePointerFromMouse(3, 0, 0, 0, 0).phase);
    try std.testing.expectEqual(chrome.input.PointerPhase.down, AppSession.chromePointerFromMouse(4, 0, 0, 0, 0).phase); // 더블클릭도 down

    // button(xterm): 0=L, 2=R, 1(middle)/그 외=other.
    try std.testing.expectEqual(chrome.input.PointerButton.right, AppSession.chromePointerFromMouse(1, 0, 0, 2, 0).button);
    try std.testing.expectEqual(chrome.input.PointerButton.other, AppSession.chromePointerFromMouse(1, 0, 0, 1, 0).button);

    // mods 비트: 4=shift, 8=option, 16=control(modsBits). command는 마우스 ABI에 없어 항상 false.
    const m = AppSession.chromePointerFromMouse(1, 0, 0, 0, 4 | 8 | 16).mods;
    try std.testing.expect(m.shift and m.option and m.control and !m.command);
}

// window padding이 터미널 영역 rect(termRect)를 좌상으로 들이고 폭/높이를 2배만큼 줄이는지 고정한다 — 이 rect가
// 렌더 origin·마우스 hit-test(pxToCell)·IME·split leaf의 단일 출처라, 여기서 inset이 맞으면 그 전부가 정합한다.
test "classifyAgent: claude/codex 부분일치(대소문자 무시), 그 외·null=none" {
    try std.testing.expectEqual(AgentKind.claude, classifyAgent("claude"));
    try std.testing.expectEqual(AgentKind.claude, classifyAgent("Claude")); // 대소문자 무시
    try std.testing.expectEqual(AgentKind.codex, classifyAgent("codex"));
    try std.testing.expectEqual(AgentKind.codex, classifyAgent("codex-cli")); // 부분일치
    try std.testing.expectEqual(AgentKind.none, classifyAgent("zsh"));
    try std.testing.expectEqual(AgentKind.none, classifyAgent("node")); // "node"는 에이전트명 아님 — foregroundProcessName이 argv[1]("codex")로 먼저 해소
    try std.testing.expectEqual(AgentKind.none, classifyAgent(null));
    try std.testing.expectEqual(AgentKind.none, classifyAgent(""));
    // 아이콘 코드포인트 매핑(독립 아이콘 셀에 쓰임).
    try std.testing.expectEqual(@as(u21, 0), agentSymbolCodepoint(.none));
    try std.testing.expectEqual(@as(u21, 0x2736), agentSymbolCodepoint(.claude)); // 알림용 실제 ✶
    try std.testing.expectEqual(@as(u21, 0x25C6), agentSymbolCodepoint(.codex)); // 알림용 실제 ◆
    try std.testing.expectEqual(@as(u21, 0xF0007), agentIconCodepoint(.claude)); // 사이드바 PUA sparkle
    try std.testing.expectEqual(@as(u21, 0xF0008), agentIconCodepoint(.codex)); // 사이드바 PUA diamond
}

test "dimRgb: 색을 45%로 낮춘다(0 아님 — 글자 안 사라짐; 현재 pane grip muted에 쓰임)" {
    // 밝기 변조라 0이 아니다(깜빡임 아님). 200×45/100=90. (옛 에이전트 아이콘 펄스는 폐기 — 스피너로 대체.)
    try std.testing.expectEqual(maru.color.Rgb{ .r = 90, .g = 90, .b = 90 }, dimRgb(.{ .r = 200, .g = 200, .b = 200 }));
    try std.testing.expectEqual(maru.color.Rgb{ .r = 0, .g = 0, .b = 0 }, dimRgb(.{ .r = 0, .g = 0, .b = 0 }));
}

// running 스피너 = codex식 4칸 이퀄라이저 파형(옛 브라유 회전 dot 대체). 이 테스트가 증명하는 것:
// (1) 모든 프레임의 모든 바가 블록 글리프(▁~█)라 색칠 게이트(isAgentSpinnerCp)에 잡히고 renderer/block_glyph 합성 경로로 또렷하게 그려진다.
// (2) 위상 offset 덕에 한 프레임 안에서 바 높이가 획일적이지 않다(파도처럼 보이는 근거) — 최소 한 프레임은 서로 다른 높이를 갖는다.
// (3) advance가 파형 길이(14)로 wrap하므로 프레임이 그 범위를 넘지 않는다(u8 자연 wrap 시 파형 튐 회피).
test "spinner: 4칸 이퀄라이저 바가 전부 블록 글리프이고 위상차로 파도친다" {
    var any_varied = false;
    for (0..spinner_wave.len) |f| {
        const frame: u8 = @intCast(f);
        var prev: ?u21 = null;
        for (0..spinner_bar_count) |bar| {
            const cp = spinnerBarCp(frame, bar);
            try std.testing.expect(cp >= 0x2581 and cp <= 0x2588); // ▁~█ 범위
            try std.testing.expect(isAgentSpinnerCp(cp)); // 색칠 게이트가 잡는다
            if (prev) |p| {
                if (p != cp) any_varied = true;
            }
            prev = cp;
        }
    }
    try std.testing.expect(any_varied); // 획일적이지 않다(파형)
    // 브라유(U+280B 등)는 더 이상 스피너로 취급되지 않는다 — 게이트가 블록 전용.
    try std.testing.expect(!isAgentSpinnerCp(0x280B));
    // 프레임 0 = 사용자가 승인한 모양 "▁▅▇▃"(wave[0,4,8,12]=1,5,7,3). 시각 계약을 고정한다.
    try std.testing.expectEqual(@as(u21, 0x2581), spinnerBarCp(0, 0)); // ▁
    try std.testing.expectEqual(@as(u21, 0x2585), spinnerBarCp(0, 1)); // ▅
    try std.testing.expectEqual(@as(u21, 0x2587), spinnerBarCp(0, 2)); // ▇
    try std.testing.expectEqual(@as(u21, 0x2583), spinnerBarCp(0, 3)); // ▃
}

// anyAgentRunning(스피너 위상 게이트)은 **사이드바에 실제로 보이는** running 에이전트만 본다 — 접힘·필터아웃이면 스피너가
// 화면에 없어 false(매 130ms full-grid 재투영 낭비 회피, code-review high #1). 검색 없으면 visible_tabs=전체라 평소 동작.
test "anyAgentRunning: 접힘·필터아웃이면 false (보이는 running만 — 재투영 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    session.activeTab().activePane().activeTerm().agent_state = .running; // 활성 Term을 running으로
    session.recomputeVisibleTabs(); // 검색 없음 → visible_tabs = 전체(1개)
    try std.testing.expect(session.sidebar_visible_tabs.items.len >= 1);

    session.sidebar_collapsed = false;
    try std.testing.expect(session.anyAgentRunning()); // 펼침 + 보이는 running → true

    session.sidebar_collapsed = true;
    try std.testing.expect(!session.anyAgentRunning()); // 접힘 → 스피너 안 보임 → false

    session.sidebar_collapsed = false;
    session.sidebar_visible_tabs.clearRetainingCapacity(); // 검색 필터로 그 카드가 숨음(표시 목록 비움)
    try std.testing.expect(!session.anyAgentRunning()); // 필터아웃 → false (running이어도 카드 없음)
}

test "에이전트 완료 알림: enqueue 후 pendingNotification이 OSC보다 먼저 큐를 드레인" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const tab = session.tabs.items[0];
    const term = tab.activePane().activeTerm();
    term.agent_kind = .claude; // 배지 제목 경로(✶ Claude · …)를 실제로 검증
    // 완료 답변을 채우고 비활성 탭 완료를 모사해 enqueue(실제 경로 함수 사용).
    const ans = "PR 머지 완료";
    @memcpy(term.agent_answer_buf[0..ans.len], ans);
    term.agent_answer_len = ans.len;
    session.enqueueAgentCompletion(tab, term);
    try std.testing.expectEqual(@as(usize, 1), session.agent_notifications.items.len);

    // pendingNotification이 OSC 9/777보다 먼저 에이전트 큐를 드레인하고, body=답변. 큐가 비워진다.
    const n = session.pendingNotification() orelse return error.TestExpectedNotification;
    try std.testing.expectEqualStrings(ans, n.body);
    // title = "{✶ agentSymbolCodepoint} Claude · {끝난 Term 세션 라벨}" — 배지 글리프·종류·세션 식별.
    try std.testing.expect(std.mem.startsWith(u8, n.title, "\u{2736} Claude")); // ✶ + 종류
    try std.testing.expect(std.mem.indexOf(u8, n.title, "\u{B7}") != null); // " · " 구분자 + 세션 라벨이 붙음
    try std.testing.expectEqual(@as(usize, 0), session.agent_notifications.items.len);
    // 큐가 비면 OSC 경로로 떨어지고, controlled_smoke엔 OSC 알림이 없어 null.
    try std.testing.expect(session.pendingNotification() == null);

    // 답변이 비면 body="완료"로 폴백.
    term.agent_answer_len = 0;
    session.enqueueAgentCompletion(tab, term);
    const n2 = session.pendingNotification() orelse return error.TestExpectedNotification;
    try std.testing.expectEqualStrings("완료", n2.body);
    // 알림에 surface_id가 실린다(클릭 라우팅용) — 활성 탭의 활성 Term surface.id와 일치.
    try std.testing.expectEqual(session.activeSurface().id, n2.surface_id);
    // 에이전트 완료는 "안 보는 탭"이 대상이라 앱 전면에서도 배너로 띄운다(foreground_banner=true).
    try std.testing.expect(n2.foreground_banner);
}

test "activateSurfaceById: surface.id로 (탭·split panel·가로탭)을 역조회해 그 자리로 활성화한다" {
    // 데스크톱 알림(OSC 9/777·에이전트 완료) 클릭이 발신 터미널로 점프하는 경로의 핵심이다. Swift는 창 토큰으로
    // '어느 창(세션)'까지만 고르고, 그 세션 안에서 surface_id로 '어느 탭/split panel/가로탭'인지 찾아 포커스하는 건
    // Zig가 소유한다. 순서(switchTab→focusPaneByPtr→focusTerm)가 틀리면 비활성 탭의 panel/term을 못 찾으므로,
    // 비활성 탭의 둘째 panel 둘째 가로탭을 표적으로 삼아 세 단계 모두 정확히 들어가는지 검증한다. 터미널에서
    // 중요한 이유: 알림은 "지금 안 보는 터미널"이 보내므로, 클릭이 정확히 그 화면을 되살리지 못하면 기능이 무의미하다.
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane/newTab/newTermInActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800; // split/resize가 의미 있으려면 backing 필요
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    // 표적: 비활성 탭(t1)의 둘째 panel(우측 split)의 둘째 가로탭. 만든 직후 활성이라 activeSurface로 id를 잡는다.
    _ = try session.newTab(); // tabs [t0, t1], 활성 t1
    try session.splitActivePane(.horizontal); // t1: pane [p0, p1], 활성 p1
    try session.newTermInActivePane(); // p1: term [tm0, tm1], 활성 tm1
    const target_id = session.activeSurface().id;
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().active_pane);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);

    // 활성을 다른 워크스페이스(t0)로 옮겨, 활성화가 탭 경계를 넘는지(단순 no-op이 아닌지) 본다.
    try std.testing.expect(session.switchTab(0));
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);

    // 알림 클릭 모사: id로 끝까지(탭→panel→가로탭) 정확히 점프.
    try std.testing.expect(session.activateSurfaceById(target_id));
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().active_pane);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);
    try std.testing.expectEqual(target_id, session.activeSurface().id);

    // 없는 id(알림 후 그 Term이 닫힌 경우 모사)는 false + 활성 상태 불변 — stale 알림이 엉뚱한 surface를 깨우지 않는다.
    try std.testing.expect(!session.activateSurfaceById(0xFFFF_FFFF));
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);
}

test "pendingNotification: 비활성 pane/Term의 OSC 9 알림도 그 surface_id로 drain한다" {
    // 예전엔 activeSurface().core만 drain해 background split pane·가로탭이 보낸 OSC 9/777 알림이 영영 안 나왔다 —
    // 클릭이 발신 Term으로 점프하려면(activateSurfaceById) 발신 Term의 surface_id가 알림에 실려야 하는데, 활성
    // surface의 id만 실려 "탭은 맞는데 pane/Term이 어긋나는" 증상이 났다. 이제 모든 Term의 코어를 훑어 발신 Term의
    // surface_id를 싣는다. 비활성 pane Term에 OSC 9를 먹이고(활성 surface엔 알림 없음), 그 비활성 Term의 알림을
    // surface_id까지 정확히 돌려주는지 + 그 id로 점프가 비활성 pane을 포커스하는지 본다(알림→점프 전제 폐곡선).
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane/newTermInActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800; // split이 의미 있으려면 backing 필요
    session.backing_height_px = 600;
    session.window_padding_px = .{};
    session.loaded_config.config.notifications.osc = true; // OSC 게이트 명시(기본값 의존 안 함)
    session.window_focused = true; // 포커스 창 — 활성 Term이 "지금 보는" Term이 되게(전면 배너 억제 대상)

    // 활성 탭에 split을 만들어 비활성 pane을 둔다: panes [p0, p1], 활성 p1. 발신원 = 비활성 p0의 Term.
    try session.splitActivePane(.horizontal);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().active_pane); // p1 활성
    const bg_term = session.activeTab().panes.items[0].terms.items[0]; // 비활성 p0의 Term(*Term)
    const bg_id = bg_term.surface.id;
    const active_id = session.activeSurface().id; // 활성 p1의 Term(지금 보는 Term)
    try std.testing.expect(bg_id != active_id); // 활성과 다른 surface여야 의미 있음

    // 두 Term 모두 OSC 9(iTerm2: ESC ] 9 ; <body> BEL)를 먹인다 — title 없음, body=메시지.
    try bg_term.surface.core.write("\x1b]9;배경 pane 빌드 완료\x07");
    try session.activeSurface().core.write("\x1b]9;활성 pane 알림\x07");

    // 루프는 p0(배경)→p1(활성) 순. 첫 drain = 배경 Term: surface_id=bg_id, 안 보는 곳이라 **전면 배너 뜸**(=1).
    const n1 = session.pendingNotification() orelse return error.TestExpectedNotification;
    try std.testing.expectEqualStrings("배경 pane 빌드 완료", n1.body);
    try std.testing.expectEqual(bg_id, n1.surface_id);
    try std.testing.expect(n1.foreground_banner); // 배경 pane OSC → 전면에서도 배너(사용자가 안 보는 곳)

    // 둘째 drain = 활성(지금 보는) Term: 자기 화면 노이즈라 전면 배너 억제(=0, 목록만).
    const n2 = session.pendingNotification() orelse return error.TestExpectedNotification;
    try std.testing.expectEqual(active_id, n2.surface_id);
    try std.testing.expect(!n2.foreground_banner); // 지금 보는 Term OSC → 전면 배너 억제

    // 모두 소비됐으니 다음 호출은 null(clearNotification으로 코어 pending 비움 — 다음 tick 재발화 방지).
    try std.testing.expect(session.pendingNotification() == null);

    // 배경 Term의 surface_id로 점프하면 비활성 p0로 정확히 활성화된다(알림→점프 전제가 닫힌다).
    try std.testing.expect(session.activateSurfaceById(bg_id));
    try std.testing.expectEqual(@as(usize, 0), session.activeTab().active_pane);
}

test "알림 히스토리: push 상한 ring + unread 증감 + markRead + formatRelativeTime 경계" {
    // 인앱 알림 센터의 토대 — 드레인되면 사라지는 OS 배너와 달리 히스토리는 보관·열람된다. 상한(ring) 초과 시 가장
    // 오래된 걸 버리고, unread 캐시는 push/markRead/cap-drop 3곳에서만 정확히 증감해야 종 배지 수가 맞는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest; // AppSession.init = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // push 2건(에이전트/OSC) → len 2, unread 2, owned dupe.
    _ = session.pushNotificationHistory("ws1", "done", 1, true);
    _ = session.pushNotificationHistory("ws2", "fail", 2, false);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.notification_unread);
    try std.testing.expect(session.notification_history.items[0].is_agent);
    try std.testing.expect(!session.notification_history.items[1].is_agent);
    try std.testing.expectEqual(@as(u64, 2), session.notification_history.items[1].surface_id);

    // markRead(0) → unread 1, 다시 호출은 무동작(이미 읽음).
    session.markNotificationRead(0);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
    session.markNotificationRead(0);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
    session.markNotificationRead(999); // 범위 밖 — 무동작
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);

    // 상한 초과: cap+5건 더 push → len은 cap(config notifications.history-limit) 유지(ring), 누수 없이 오래된 것 free.
    const cap: usize = @intCast(session.loaded_config.config.notifications.history_limit);
    var i: usize = 0;
    while (i < cap + 5) : (i += 1) _ = session.pushNotificationHistory("x", "y", 100, false);
    try std.testing.expectEqual(cap, session.notification_history.items.len);

    // formatRelativeTime 경계(arena).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    try std.testing.expectEqualStrings("방금", try session.formatRelativeTime(a, 30 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("5분 전", try session.formatRelativeTime(a, 5 * 60 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("2시간 전", try session.formatRelativeTime(a, 2 * 3600 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("3일 전", try session.formatRelativeTime(a, 3 * 86400 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("방금", try session.formatRelativeTime(a, -100)); // 시계 역행 → 0
}

test "acceptNotification: 목록 역순 매핑(0=최신) + 클릭 surface 전체 읽음(배너와 통일) + 패널 닫기" {
    // 목록은 최신이 위(역순)라 selected 0 = 히스토리 끝. accept는 그 카드의 surface를 봤다는 의미라 같은 surface의
    // 안읽음을 모두 읽음 처리하고(데스크톱 배너 클릭과 동일 정책 — markNotificationsReadBySurface) 패널을 닫는다.
    // 다른 surface 알림은 안읽음 점을 유지한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = session.pushNotificationHistory("old-A", "1", 11, true); // history 0: surface 11
    _ = session.pushNotificationHistory("other", "2", 22, true); // history 1: surface 22(다른 터미널)
    _ = session.pushNotificationHistory("new-A", "3", 11, false); // history 2(최신): surface 11(또 한 번)
    session.chrome_host.notifications.show(0, 0, 3);
    session.chrome_host.notifications.selected = 0; // 목록 0 = 최신("new-A") = surface 11
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    session.acceptNotification();
    try std.testing.expect(!session.chrome_host.notifications.open); // 패널 닫힘
    // 클릭 카드의 surface(11) 안읽음(old-A·new-A) 모두 읽음, 다른 surface(22, "other")는 유지.
    try std.testing.expect(session.notification_history.items[0].is_read); // old-A (surface 11)
    try std.testing.expect(!session.notification_history.items[1].is_read); // other (surface 22)
    try std.testing.expect(session.notification_history.items[2].is_read); // new-A (surface 11)
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread); // other만 안읽음
}

test "알림 액션: deleteNotification(역순) + markAllNotificationsRead + clearNotifications + unread 보정" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = session.pushNotificationHistory("a", "1", 11, true); // 히스토리 idx 0(가장 오래됨)
    _ = session.pushNotificationHistory("b", "2", 22, true); // idx 1
    _ = session.pushNotificationHistory("c", "3", 33, false); // idx 2(최신) — 목록 역순 [c, b, a]
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    // 목록 list_index 0 = 최신("c") = 히스토리 끝. 삭제 → "c" 제거, unread 1 감소.
    session.deleteNotification(0);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.notification_unread);
    try std.testing.expectEqualStrings("b", session.notification_history.items[1].title); // 최신이 이제 "b"

    // 모두 읽음 → unread 0, 항목 유지(목록엔 남음).
    session.markAllNotificationsRead();
    try std.testing.expectEqual(@as(usize, 0), session.notification_unread);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);

    // 모두 지우기 → 히스토리 비움(누수 없이 owned free).
    session.clearNotifications();
    try std.testing.expectEqual(@as(usize, 0), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.notification_unread);
}

test "markNotificationsReadBySurface: 배너 클릭→그 surface 안읽음 모두 읽음(센터 동기화)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
